INSERT INTO activity_events VALUES(4,'Ops & Learning','لوب: Tick','مسح المنافس الدوري التالي: «Hayah — Urepar» — دوره النهارده (منافس واحد في الجولة، كل منافس مرة يومياً). نفّذ المسح من متابعة السوق وسجّله كجولة. بريفات الجمهور: لا مسودات محتوى بعد — التحديث الدوري (كل 6 ساعات) هيلاقيها فاضية لحد ما تتكتب مسودات.',1795034976548);
