INSERT INTO activity_events VALUES(302,'Ops & Learning','لوب: Tick','مسح المنافس الدوري التالي: «Tetavara» — دوره النهارده (منافس واحد في الجولة، كل منافس مرة يومياً). نفّذ المسح من متابعة السوق وسجّله كجولة. بريفات الجمهور وتقويم المحتوى: 3 عنصر مسودة — التحديث الدوري (كل 6 ساعات) بيراجع المسودات بس؛ النشر ممنوع (Draft-only). شغل خلفي: اتحلل تلقائياً 0 كرييتف و1 إعلان منافس كانوا بانتظار التحليل.',1795081256332);
