INSERT INTO activity_events VALUES(571,'النظام','Loop Tick 23:59 EET','تيك لوب 10 دقائق (23:59 EET): لا مهام مستحقة — مهمة بحث السوق (id 1) تغطية اليوم مكتملة من لوب 109 (16:09) والمهام 2–5 خطط معتمدة بلا تاريخ استحقاق. runlooptick: بريفات الجمهور وتقويم المحتوى 3 عناصر مسودة فقط، بلا تحليل جديد وبلا انتهاء صلاحية. الاقتراحات طازجة (آخر مسح كلمات 21:51 EET، TTL 14 يوم) — لا منتهي. اعتماد واحد معلق بانتظار أحمد: حل فخ سلة الـ998 (id 1) — بلا إجراء. بلا نشر وبلا تغيير ميزانيات أو أسعار.',1795125609518);
INSERT INTO activity_events VALUES(572,'المال والنتائج','خطة معمل أب سيل','تصحيح مالك مهم: الموقع عنده أب سيل وكروس سيل و«كمّلي روتينك» شغالين على صفحة المنتج — الغائب هو الكارت وما بعد الطلب والقياس، مش غياب القمع كله (تصحيح لتحليل الثغرات اللي اتبعت الليلة). وبناء عليه اتعملت خطة معمل أب سيل وكروس سيل تنفيذية (صفحة HTML): 10 أنواع في 3 مجموعات (موقع قبل الشراء / كارت ودفع / بعد الطلب)، أولوية قصوى لشريط عتبة الشحن المجاني في الكارت وإضافات العتبة (سبلاش 240 وشيا 250) لعلاج فخ سلة 998، منهجية تجارب بحراس تحويل وتأكيد/تسليم COD، و4 مراحل تنفيذ من قبل إطلاق الأحد لحد ديسمبر، وأول 5 تجارب U1–U5 جاهزة للتسجيل والقياس بعد الإطلاق.',1795125655019);
INSERT INTO activity_events VALUES(573,'Ops & Learning','لوب: Tick','مسح المنافس الدوري التالي: «Hayah — Urepar» — دوره النهارده (منافس واحد في الجولة، كل منافس مرة يومياً). نفّذ المسح من متابعة السوق وسجّله كجولة. بريفات الجمهور وتقويم المحتوى: 3 عنصر مسودة — التحديث الدوري (كل 6 ساعات) بيراجع المسودات بس؛ النشر ممنوع (Draft-only).',1795126197669);
