INSERT INTO activity_events VALUES(575,'النظام — التشغيل','Loop Tick','تيك 00:09 EET 20 نوفمبر: تشغيل اللوب الداخلي سمّى مسح Hayah — Urepar (أول جولة في دورة يوم 20 نوفمبر) — نُفّذ من المصادر العامة وسُجّل كجولة سوق 50: سعر ثابت (Cairo Drop 439 EGP متوفر / Beseha 357 EGP)، بلا منتج أو عرض جديد — ملاحظة: صفحة Cairo Drop المقروءة زحف 12 نوفمبر. بريفات الجمهور/تقويم المحتوى: 3 مسودات، بلا نشر. لا اقتراحات منتهية (آخر مسح كلمات 19 نوفمبر 21:51، ضمن TTL 14 يوم). موافقة واحدة معلقة بلا قرار جديد: فخ سلة الـ998 (هيرو + مخمرية) — بانتظار قرار المالك. لا مهام أخرى مستحقة: Bosta محظورة على المالك، وخطط Ask Zyra عناصرها في متابعة الشغل.',1795126308780);
INSERT INTO activity_events VALUES(576,'Ops & Learning','لوب: Tick','مسح المنافس الدوري التالي: «Skinova Image» — دوره النهارده (منافس واحد في الجولة، كل منافس مرة يومياً). نفّذ المسح من متابعة السوق وسجّله كجولة. بريفات الجمهور وتقويم المحتوى: 3 عنصر مسودة — التحديث الدوري (كل 6 ساعات) بيراجع المسودات بس؛ النشر ممنوع (Draft-only).',1795126836641);
