INSERT INTO activity_events VALUES(1055,'لغة البحث','مسح اقتراحات جوجل مصر','مسح جوجل مصر 23:53 EET — 12 كلمة متتبعة، 0 اقتراحات جديدة مقارنة بمسح 23:32 EET. تغييرات ترتيب فقط داخل القوائم: «علاج جلد الوزة من الصيدلية» تقدّمت، «يورياج سيكا»/«يورياج صن بلوك» تبدّلا، «زبدة الشيا امتنان»/«زبدة الشيا الخام» تبدّلا. لا ملاحظات جديدة ولا فرص منتجات جديدة — اللقطة سُجّلت لكل الكلمات الـ12.',1795211641198);
INSERT INTO activity_events VALUES(1056,'Ops & Learning','لوب: Tick','مسح المنافس الدوري التالي: «Hayah — Urepar» — دوره النهارده (منافس واحد في الجولة، كل منافس مرة يومياً). نفّذ المسح من متابعة السوق وسجّله كجولة. بريفات الجمهور وتقويم المحتوى: 3 عنصر مسودة — التحديث الدوري (كل 6 ساعات) بيراجع المسودات بس؛ النشر ممنوع (Draft-only).',1795212051652);
INSERT INTO activity_events VALUES(1057,'Market Watch','جولة متابعة','Beseha (زحف نصي حي 2026-11-20 ~23:59–00:02 EET) + Jumia — فحص حي: مسح دوري لمنافس واحد: Hayah — Urepar — السعر والتوفر والعرض (كريم الجسم يوريا 10% 200مل + كريم القدم يوريا 10% 75مل؛ تحقق من غياب KP روتين/سيلوليت/يوريا أعلى ومنتجات جديدة)',1795212269864);
INSERT INTO activity_events VALUES(1058,'السوق','Tick 23:59 — جولة 93 Hayah–Urepar + مراجعة مسودات المحتوى','تيك 23:59 EET: تشغيل runlooptick — جولة السوق 93 Hayah — Urepar سُجّلت (كريم الجسم يوريا 10% 200مل بـ357 ومتوفر، بلا تغيير؛ لا روتين KP ولا سيلوليت ولا يوريا أعلى من 10%؛ كريم القدم على Jumia بـ315–380 بزحف قديم)؛ بريفات الجمهور وتقويم المحتوى: 3 عناصر مسودة رُوجعت (لا نشر)؛ لا اقتراحات منتهية الصلاحية (TTL ‏14 يوم — الكلمات مسحها 21:53 EET، والفرص والخطط المقترحة من 18–19 نوفمبر ضمن النافذة)؛ اعتمادان معلقان بلا تغيير (#1 فخ 998، #2 كود 100OFF) — بانتظار قرار المالك، ولم يُنفَّذ أي إجراء خارجي.',1795212291216);
INSERT INTO activity_events VALUES(1059,'Ops & Learning','لوب: Tick','مسح المنافس الدوري التالي: «Skinova Image» — دوره النهارده (منافس واحد في الجولة، كل منافس مرة يومياً). نفّذ المسح من متابعة السوق وسجّله كجولة. بريفات الجمهور وتقويم المحتوى: 3 عنصر مسودة — التحديث الدوري (كل 6 ساعات) بيراجع المسودات بس؛ النشر ممنوع (Draft-only).',1795212603100);
INSERT INTO activity_events VALUES(1060,'Market Watch','جولة متابعة','Pharma Image + بحث عام — فحص حي 2026-11-21 ~00:10 EET: مسح دوري لمنافس واحد: Skinova Image — السعر والتوفر والعرض (لوشن يوريا بلس 20% 200مل + كريم قدم يوريا 10% 75مل؛ تحقق من غياب KP روتين/سيلوليت/يوريا أعلى ومنتجات جديدة)',1795212681708);
INSERT INTO activity_events VALUES(1061,'السوق والمنافسين','Tick','تيك 00:09 EET 21 نوفمبر: runlooptick نفّذ مسح المنافس الدوري — Skinova Image (الجولة 94): لوشن اليوريا بلس 20% ما زال 199 EGP ومتوفر على Pharma Image، بلا منتجات/عروض جديدة ولا روتين KP ولا سيلوليت ولا يوريا أعلى من 20%؛ كريم القدم 160–210 حسب القناة. بريفات الجمهور وتقويم المحتوى: 3 عناصر مسودة — مراجعة دورية فقط، النشر ممنوع. لا اقتراحات منتهية الصلاحية (آخر مسح كلمات 21:53 EET، ضمن TTL 14 يوم؛ الخطتان المقترحتان 1 و2 ما زالتا قيد انتظار المالك ولم تنتهِ صلاحيتهما). الاعتمادات المعلقة بلا تغيير: #1 فخ سلة 998 و#2 كود 100OFF — بانتظار قرار المالك قبل إطلاق الأحد.',1795212717736);
