INSERT INTO organic_posts VALUES(1,'S1 — هوك الريتينول للجسم','','انستجرام','هوك الريتينول للجسم: كريم السيلوليت (ريتينول + كافيين + نياسيناميد) — 350 ج بدل 400','Static',1,'«الريتينول اللي في روتين وشك.. ليه مش في جسمك؟» كريم السيلوليت (ريتينول+كافيين+نياسيناميد) 350/400','منتج','مسودة','','⚠️ ريتينول — التنبيه الإلزامي موجود في الكابشنات','','',1795038210312,1795038210312);
INSERT INTO organic_posts VALUES(2,'S6 — طبقات العطر','','انستجرام','طبقات العطر: 3 طبقات من نفس الريحة (لوف + مخمرية + سبلاش)','Static',1,'طبقات العطر — 3 طبقات من نفس الريحة (صابونة لوف ورد + مخمرية + سبلاش Midnight Bloom). سبلاش 240، مخمرية 199','تعليمي','مسودة','','','','',1795038215494,1795038215494);
INSERT INTO organic_posts VALUES(3,'S5 — روتين جلد الوزة','','انستجرام','روتين جلد الوزة: حبيبات الدراع ونقط الرجل بعد الشيفينج — 799 ج بدل 1,020','Static',1,'روتين جلد الوزة — حبيبات الدراع ونقط الرجل بعد الشيفينج، روتين واحد (سكراب + لوشن يوريا 25% + شيا) 799/1,020','مشكلة وحل','مسودة','','','','',1795038215543,1795038215543);
INSERT INTO organic_posts VALUES(4,'S3 — لوشن جلد الوزة يوريا 25%','','انستجرام','لوشن جلد الوزة: يوريا 25% + لاكتيك أسيد + بانثينول + زبدة شيا — 360 ج بدل 400','Static',1,'لوشن جلد الوزة — يوريا 25% + لاكتيك أسيد + بانثينول + زبدة شيا، 200جم، 360/400','منتج','مسودة','','','','',1795038215573,1795038215573);
INSERT INTO organic_posts VALUES(5,'S4 — روتين السيلوليت في 3 خطوات','','انستجرام','روتين السيلوليت في 3 خطوات — 799 ج بدل 975','Static',1,'روتين السيلوليت في 3 خطوات (صابونة كولاجين ← سكراب كافيين ← كريم ريتينول بالليل) 799/975','تعليمي','مسودة','','⚠️ ريتينول — التنبيه الإلزامي موجود في الكابشنات','','',1795038215594,1795038215594);
INSERT INTO organic_posts VALUES(6,'S2 — روتين السيلوليت قبل/بعد مع الانتظام','','انستجرام','روتين السيلوليت قبل/بعد «مع الانتظام» — الروتين 799 ج بدل 975','Static',1,'روتين السيلوليت قبل/بعد «مع الانتظام». الروتين 799/975','مشكلة وحل','مسودة','','⚠️ ريتينول — التنبيه الإلزامي موجود في الكابشنات','','',1795038215616,1795038215616);
INSERT INTO organic_posts VALUES(7,'C1 — تعريف البراند والعودة إحنا زيرا','','انستجرام','تعريف البراند والعودة: «إحنا زيرا وبنقولك الحقيقة»','Carousel',8,'تعريف البراند والعودة «إحنا زيرا وبنقولك الحقيقة»: بنبدأ من المشكلة، مواد فعالة (شيا غانا، ملح سيوة، يوريا 25%، ريتينول وكافيين)، خطوات مدروسة، من غير وعود بمعجزات، وقفنا البيع بإرادتنا ورجعنا، دفع عند الاستلام + 14 يوم إرجاع','تعريف بالبراند','مسودة','','⚠️ ريتينول — التنبيه الإلزامي موجود في الكابشنات','','📌 بوست مثبت',1795038220393,1795038220393);
INSERT INTO organic_posts VALUES(8,'S7 — عناية الجسم مش تقشير بس','','انستجرام','عناية الجسم مش تقشير بس: سكراب سيوة + لوف + شيا — السكراب 390 ج بدل 450','Static',1,'عناية الجسم مش تقشير بس — تقشير من غير ترطيب = جلد مشدود؛ سكراب ملح سيوة أسبوعي + لوف + شيا. سكراب سيوة 390/450','تعليمي','مسودة','','','','',1795038220421,1795038220421);
INSERT INTO organic_posts VALUES(9,'S10 — سبلاش ولا مخمرية ولا الاتنين','','انستجرام','سبلاش ولا مخمرية ولا الاتنين: سبلاش 240 ج / مخمرية 199 ج','Static',1,'سبلاش ولا مخمرية ولا الاتنين — سبلاش 240 (100مل، 10 روائح، كحول قليل)، مخمرية 199 (شيا، 8 روائح)؛ الثبات الأطول: مخمرية الأول وسبلاش فوقها من نفس الريحة','منتج','مسودة','','','','',1795038220448,1795038220448);
INSERT INTO organic_posts VALUES(10,'S8 — خلي روتين وشك أبسط','','انستجرام','خلي روتين وشك أبسط: تنظيف ألطف + تونر — التونر 350 ج بدل 400','Static',1,'خلي روتين وشك أبسط — تنظيف ألطف صبح وليل + تونر (تونر الورد والخيار 350/400 + صابون فحم وصبار)','تعليمي','مسودة','','','','',1795038220463,1795038220463);
INSERT INTO organic_posts VALUES(11,'S9 — دليل الـ 3 سكرابات بملح سيوة','','انستجرام','دليل الـ 3 سكرابات بملح سيوة: سيوة 390 / جلد الوزة 440 / سيلوليت 450','Static',1,'دليل الـ 3 سكرابات بملح سيوة — سيوة 390 (عناية أسبوعية، 5 روائح، 1-2 مرة/أسبوع)، جلد الوزة 440 (مرة/أسبوع ثم 2-3)، سيلوليت 450 (كافيين، في الشاور وبعده الكريم بالليل). التلاتة للجسم بس ومش بعد الشيفينج مباشرة','تعليمي','مسودة','','','','',1795038220475,1795038220475);
INSERT INTO organic_posts VALUES(12,'C3 — ليه تطلبي من زيرا؟','','انستجرام','«ليه تطلبي من زيرا؟» — الرد على مخاوف أول طلب','Carousel',9,'«ليه تطلبي من زيرا؟» رد على مخاوف أول طلب: إرجاع 14 يوم وفق شروط السياسة، دفع عند الاستلام، مساعدة في اختيار الروتين، المكونات مكتوبة على صفحة كل منتج، طريقة استخدام خطوة بخطوة، توقعات صادقة والنتائج بتختلف','ثقة','مسودة','','🚩 سلايد 8: وعد شحن مجاني من تاني أوردر غير مؤكد — لا يُكرر في الكابشن','','📌 بوست مثبت',1795038224811,1795038224811);
INSERT INTO organic_posts VALUES(13,'C4 — 5 غلطات في روتين السيلوليت','','انستجرام','«5 غلطات في روتين السيلوليت» وتصحيحها — الروتين 799 ج بدل 975','Carousel',10,'«5 غلطات في روتين السيلوليت»: مش عشان التخن، الفرك الجامد بيهيج، الكريم من غير سكراب الأول، الكريم الصبح من غير واقي (ريتينول بالليل + ممنوع في الحمل)، والبطولة بعد أسبوع. الخلاصة: صابونة كولاجين + سكراب كافيين + كريم ريتينول — 799/975','تعليمي','مسودة','','⚠️ ريتينول — التنبيه الإلزامي موجود في الكابشنات','','',1795038224838,1795038224838);
INSERT INTO organic_posts VALUES(14,'C2 — لو عندك المشكلة دي ده روتينك','','انستجرام','«لو عندك المشكلة دي ده روتينك» — 8 روتينات','Carousel',10,'«لو عندك المشكلة دي ده روتينك»: 8 روتينات (سيلوليت 799، جلد الوزة والفراولة 799، بشرة دهنية، بشرة جافة 599، بشرة باهتة، سيوة الأسبوعي 700، Signature Scent، كيت الساحل). ختام: ابعتلنا اللي مضايقك ونرشحلك + COD + 14 يوم','مشكلة وحل','مسودة','','⚠️ ريتينول — التنبيه الإلزامي موجود في الكابشنات | 🚩 سلايد 9 (كيت الساحل): الهيدلاين مكرر ومتلخبط ويحتاج إعادة صياغة قبل النشر','','📌 بوست مثبت',1795038224865,1795038224865);
INSERT INTO organic_posts VALUES(15,'C5 — 4 غلطات بتزود جلد الوزة','','انستجرام','«4 غلطات بتزود جلد الوزة» وتصحيحها — الروتين 799 ج بدل 1,020','Carousel',9,'«4 غلطات بتزود جلد الوزة»: ليفة جامدة كل يوم، مرطب عادي وخلاص (اليوريا بتليّن الخشن)، ترتيب السكراب واللوشن، لوشن بعد الشيفينج على طول (استني 24-48 ساعة). الخلاصة: سكراب جلد الوزة + لوشن يوريا 25% + شيا مكررة — 799/1,020','تعليمي','مسودة','','🚩 سلايد 7: مكتوب «سكراب الكافيين» خطأً — الصح سكراب جلد الوزة | 🚩 سلايد 9 مفقودة في الترقيم (يقفز من 8 إلى 10)','','',1795038224879,1795038224879);
INSERT INTO organic_captions VALUES(1,1,3,'',replace('لو مظهر السيلوليت مضايقك، ابدئي بخطوة واحدة صح: كريم السيلوليت بالريتينول والكافيين والنياسيناميد، 350 ج بدل 400.\nولو عايزة الروتين الكامل (سكراب + كريم + صابونة) هتلاقيه بـ 799 ج بدل 975.\nاطلبي من اللينك في البايو، والدفع عند الاستلام.\nتنبيه: الريتينول لا يُستخدم أثناء الحمل والرضاعة، ويُستخدم بالليل فقط.\n#سيلوليت #عناية_بالجسم #زيرا','\n',char(10)),'مرشّحة',1795038232696,1795144923483);
INSERT INTO organic_captions VALUES(2,1,2,'تفاعلي',replace('سؤال سريع: آخر مرة اهتميتي بجلد جسمك زي وشك كانت إمتى؟\nالريتينول مش للوش بس. كريم السيلوليت بتاعنا بيجمع ريتينول وكافيين ونياسيناميد في خطوة واحدة بالليل، وهدفه مظهر وملمس أنعم تدريجياً.\nاحفظي البوست وارجعيله وإنتي بتظبطي روتينك.\nتنبيه: الريتينول لا يُستخدم أثناء الحمل والرضاعة.\n#سيلوليت #روتين_الجسم #ZyraCare','\n',char(10)),'مسودة',1795038232711,1795038232711);
INSERT INTO organic_captions VALUES(3,1,1,'تعليمي/قيمة',replace('بتحطي ريتينول في روتين وشك عشان ملمسه ونضارته.. طب وجسمك؟\nكريم السيلوليت من زيرا فيه ريتينول + كافيين + نياسيناميد، وبيشتغل على مظهر السيلوليت وملمس الجلد مع الانتظام في الاستخدام بالليل.\nسعره لوحده 350 ج بدل 400.\nتنبيه: الريتينول لا يُستخدم أثناء الحمل والرضاعة، وبيتحط بالليل بس.\n#سيلوليت #عناية_بالجسم #زيرا','\n',char(10)),'مسودة',1795038232730,1795038232730);
INSERT INTO organic_captions VALUES(4,6,3,'بيع ناعم وCTA',replace('روتين السيلوليت الكامل بـ 799 ج بدل 975، ومكوناته لوحدها أغلى من كده.\nسكراب كافيين + كريم ريتينول وكافيين ونياسيناميد + صابونة كولاجين وبذور العنب.\nابدئي النهارده وخلي الانتظام هو سرك. الدفع عند الاستلام ومن حقك ترجعي خلال 14 يوم.\nتنبيه: الريتينول لا يُستخدم أثناء الحمل والرضاعة.\n#سيلوليت #ZyraCare #عناية_بالجسم','\n',char(10)),'مسودة',1795038239805,1795038239805);
INSERT INTO organic_captions VALUES(5,6,2,'تفاعلي',replace('«مع الانتظام» دي أهم كلمتين في أي روتين.\nمفيش منتج بيشتغل من مرة واحدة، بس في روتين خطواته صح: تقشير ناعم، ترطيب، وكريم فعال بالليل.\nقولي لنا في الكومنتات: أكتر حاجة بتوقعك من أي روتين إيه؟\nتنبيه: الريتينول لا يُستخدم أثناء الحمل والرضاعة.\n#سيلوليت #روتين_الجسم #زيرا','\n',char(10)),'مسودة',1795038239820,1795038239820);
INSERT INTO organic_captions VALUES(6,6,1,'',replace('الفرق بين الصورتين مش فلتر.. الفرق انتظام.\nروتين السيلوليت: سكراب الكافيين في الشاور، وكريم الريتينول بالليل، وصابونة الكولاجين للتنضيف. الملمس بيتحسن تدريجياً، والمظهر بياخد أسابيع وبيختلف من واحدة للتانية — دي الحقيقة من غير مبالغة.\nتنبيه: الريتينول لا يُستخدم أثناء الحمل والرضاعة.\n#سيلوليت #قبل_وبعد #عناية_بالجسم','\n',char(10)),'مرشّحة',1795038239833,1795144923462);
INSERT INTO organic_captions VALUES(7,4,2,'تفاعلي',replace('اعملي اختبار سريع: مرري إيدك على دراعك من بره.. حسيتي بحبيبات صغيرة وخشنة؟\nدي علامة جلد الوزة المشهورة، والشتا بيخليها تبان أكتر.\nاكتبي لنا في الكومنتات بيظهر عندك فين أكتر: دراع، فخد، ولا مكان تاني؟ وهنتابع معاكي بالحل.\n#جلد_الوزة #زيرا #روتين_الجسم','\n',char(10)),'مسودة',1795038243505,1795038243505);
INSERT INTO organic_captions VALUES(8,4,1,'',replace('دراعك لما تلمسيه زي الرملة؟ ده جلد الوزة، والتعامل معاه بيبدأ من المكونات الصح.\nلوشن جلد الوزة من زيرا: يوريا 25% بتنعّم الجلد الخشن، ولاكتيك أسيد بيقشر بلطف، وبانثينول وزبدة شيا للترطيب والتهدئة.\nحجمه 200 جم وسعره 360 ج بدل 400.\n#جلد_الوزة #يوريا #عناية_بالجسم','\n',char(10)),'مرشّحة',1795038243521,1795167942162);
INSERT INTO organic_captions VALUES(9,4,3,'بيع ناعم وCTA',replace('لوشن جلد الوزة لوحده 360 ج، ولو عندك الحبيبات في أكتر من مكان خدي الروتين الكامل: سكراب جلد الوزة + اللوشن + زبدة الشيا المكررة بـ 799 ج بدل 1,050.\nاطلبي من اللينك في البايو والدفع عند الاستلام.\n#جلد_الوزة #يوريا25 #عناية_بالجسم','\n',char(10)),'مسودة',1795038243534,1795104515837);
INSERT INTO organic_captions VALUES(10,5,3,'',replace('3 منتجات، روتين واحد، 799 ج بدل 975.\nصابونة الكولاجين وبذور العنب + سكراب الكافيين وملح سيوة + كريم الريتينول والكافيين والنياسيناميد.\nاطلبي الروتين من اللينك في البايو، تدفعي لما يوصلك، ومعاكي 14 يوم للاسترجاع.\nتنبيه: الريتينول لا يُستخدم أثناء الحمل والرضاعة.\n#سيلوليت #زيرا #روتين_الجسم','\n',char(10)),'مرشّحة',1795038247963,1795144923502);
INSERT INTO organic_captions VALUES(11,5,2,'تفاعلي',replace('أكبر غلطة في روتين السيلوليت؟ تحطي الكريم وخلاص.\nالجلد لازم يتجهز الأول: تنضيف، وبعدين تقشير ناعم، وبعدين الكريم بالليل. كده كل منتج بيشتغل في مكانه الصح.\nاحفظي الترتيب ده وابعتيه لصاحبتك اللي بتشتكي من السيلوليت.\nتنبيه: الريتينول لا يُستخدم أثناء الحمل والرضاعة.\n#سيلوليت #عناية_بالجسم #ZyraCare','\n',char(10)),'مسودة',1795038247982,1795038247982);
INSERT INTO organic_captions VALUES(12,5,1,'تعليمي/قيمة',replace('روتين السيلوليت في 3 خطوات، وكل خطوة ليها دور:\n1) صابونة الكولاجين: تنضيف.\n2) سكراب الكافيين: تقشير ناعم في الشاور.\n3) كريم الريتينول: بالليل بس.\nلما الترتيب يبقى صح، النتيجة تبقى أوضح. الروتين كامل 799 ج بدل 975.\nتنبيه: الريتينول لا يُستخدم أثناء الحمل والرضاعة.\n#سيلوليت #روتين_الجسم #زيرا','\n',char(10)),'مسودة',1795038247996,1795038247996);
INSERT INTO organic_captions VALUES(13,3,1,'',replace('حبيبات في دراعك ونقط في رجلك بعد الشيفينج؟ الاتنين اسمهم واحد: جلد الوزة وجلد الفراولة، والاتنين ليهم روتين واحد.\nسكراب جلد الوزة مرة في الأسبوع في الأول، لوشن يوريا 25% يومياً، وزبدة الشيا المكررة للترطيب العميق.\nالروتين كامل 799 ج بدل 1,050.\n#جلد_الوزة #جلد_الفراولة #عناية_بالجسم','\n',char(10)),'مرشّحة',1795038251490,1795144923530);
INSERT INTO organic_captions VALUES(14,3,2,'تفاعلي',replace('مين هنا الحبيبات عندها في الدراع، ومين النقط عندها في الرجل بعد الشيفينج؟\nاكتبي مكانها في الكومنتات وهنقولك تبدئي منين بالظبط في الروتين.\nالمشكلتين دول منتشرين جداً، وليهم خطوات واضحة لو مشيتي عليها بانتظام.\n#جلد_الوزة #شيفينج #زيرا','\n',char(10)),'مسودة',1795038251517,1795038251517);
INSERT INTO organic_captions VALUES(15,3,3,'بيع ناعم وCTA',replace('روتين واحد للاتنين: سكراب جلد الوزة + لوشن يوريا 25% + زبدة شيا مكررة.\nلو خدتيهم لوحدهم هتدفعي 1,050 ج، والروتين بـ 799 ج بس.\nاطلبي من اللينك في البايو والدفع عند الاستلام.\n#جلد_الوزة #يوريا25 #ZyraCare','\n',char(10)),'مسودة',1795038251539,1795038251539);
INSERT INTO organic_captions VALUES(16,2,3,'بيع ناعم وCTA',replace('ابدئي طبقاتك من هنا: مخمرية كريمي بـ 199 ج وبادي سبلاش 100 مل بـ 240 ج، واختاري نفس الريحة من الاتنين.\nوفيه صابونة لوف بنفس العطر تكمل بيها الثلاثية.\nاطلبي من اللينك في البايو والدفع عند الاستلام.\n#عطور_الجسم #MidnightBloom #ZyraCare','\n',char(10)),'مسودة',1795038254735,1795038254735);
INSERT INTO organic_captions VALUES(17,2,2,'تفاعلي',replace('ريحتك بتطير بعد ساعة؟ جربي قاعدة الطبقات:\nنفس الريحة في 3 أشكال مختلفة بتثبت أكتر من أي منتج لوحده.\nقولي لنا في الكومنتات: إنتي فريق سبلاش بس، ولا فريق الطبقات الكاملة؟\n#مخمرية #سبلاش #زيرا','\n',char(10)),'مسودة',1795038254750,1795038254750);
INSERT INTO organic_captions VALUES(18,2,1,'',replace('عايزة الكل يسألك «حاطة إيه؟» السر مش ريحة قوية.. السر طبقات من نفس الريحة.\nصابونة لوف في الشاور، مخمرية كريمي على الجلد، وبادي سبلاش فوقها — وكلهم بنفس العطر زي Midnight Bloom.\nكده الريحة بتثبت وبتفضل معاكي أطول.\n#عطور_الجسم #مخمرية #بادي_سبلاش','\n',char(10)),'مرشّحة',1795038254763,1795144931855);
INSERT INTO organic_captions VALUES(19,8,3,'بيع ناعم وCTA',replace('سكراب ملح سيوة بـ 390 ج بدل 450، وفيه 5 روائح تختاري منها، ومعاه زبدة الشيا المكررة وصابونة اللوف بيكملوا يوم العناية الأسبوعي لجسمك.\nاطلبي من اللينك في البايو والدفع عند الاستلام.\n#ملح_سيوة #سكراب #ZyraCare','\n',char(10)),'مسودة',1795038260605,1795038260605);
INSERT INTO organic_captions VALUES(20,8,2,'تفاعلي',replace('اعترفي: آخر مرة رطبتي جسمك بعد السكراب كانت إمتى؟\nالسكراب بيشيل الجلد الميت، بس لو سبتي الجلد من غير ترطيب هيرجع ينشف أسرع.\nاحفظي البوست: سكراب، لوف، شيا — وده ترتيب يوم العناية الأسبوعي.\n#عناية_بالجسم #روتين_الجسم #زيرا','\n',char(10)),'مسودة',1795038260625,1795038260625);
INSERT INTO organic_captions VALUES(21,8,1,'',replace('تقشير من غير ترطيب = جلد مشدود ومقشر على الفاضي.\nعناية الجسم الصح: سكراب ملح سيوة مرة أو مرتين في الأسبوع، صابونة لوف للتنضيف، وبعدها زبدة شيا تخلي الترطيب يقعد.\nالتقشير خطوة.. مش الروتين كله.\n#عناية_بالجسم #ملح_سيوة #زبدة_شيا','\n',char(10)),'مرشّحة',1795038260639,1795167942178);
INSERT INTO organic_captions VALUES(22,10,1,'تعليمي/قيمة',replace('روتين وشك مش محتاج يبقى معقد عشان يبقى فعال.\nغسيل كتير بمنتجات قوية = جفاف وتهيّج. البديل: تنظيف ألطف صبح وليل بصابونة مناسبة، وبعده تونر الورد والخيار المنعش.\nأبسط.. وأريح لبشرتك.\n#عناية_بالبشرة #روتين_الوجه #زيرا','\n',char(10)),'مسودة',1795038264070,1795038264070);
INSERT INTO organic_captions VALUES(23,10,3,'بيع ناعم وCTA',replace('ابدئي التبسيط من الأساسيات: صابونة فحم نشط أو صابونة ألوفيرا حسب بشرتك، وتونر الورد والخيار بـ 350 ج بدل 400.\nروتين خفيف تقدري تلتزمي بيه كل يوم، وده أهم من أي روتين طويل بيتنسي.\nاطلبي من اللينك في البايو.\n#روتين_الوجه #عناية_بالبشرة #زيرا','\n',char(10)),'مسودة',1795038264084,1795038264084);
INSERT INTO organic_captions VALUES(24,10,2,'',replace('كام منتج في روتين وشك دلوقتي؟ وكام واحد فيهم بشرتك محتاجاه فعلاً؟\nأوقات كتير المشكلة مش في بشرتك، المشكلة في كتر المنتجات القوية ورا بعض.\nاكتبي لنا نوع بشرتك في الكومنتات وهنرشحلك أبسط روتين يبدأ بيه.\n#عناية_بالبشرة #تونر #ZyraCare','\n',char(10)),'مرشّحة',1795038264099,1795144931843);
INSERT INTO organic_captions VALUES(25,11,2,'تفاعلي',replace('دليلك السريع لاختيار سكرابك:\nجسمك خشن عموماً؟ سكراب ملح سيوة مرة أو مرتين أسبوعياً.\nحبيبات في دراعك؟ سكراب جلد الوزة مرة في الأسبوع في الأول وبعدين 2-3.\nسيلوليت؟ سكراب الكافيين في الشاور وبعده الكريم بالليل.\nاحفظي البوست، هتحتاجيه وإنتي بتختاري.\n#جلد_الوزة #سيلوليت #زيرا','\n',char(10)),'مسودة',1795038266664,1795038266664);
INSERT INTO organic_captions VALUES(26,11,3,'بيع ناعم وCTA',replace('اختاري سكراب مشكلتك: ملح سيوة 390 ج، جلد الوزة 440 ج، السيلوليت 450 ج.\nوكلهم بملح سيوة ومكونات مرطبة زي زبدة الشيا والمانجو وزيت الجوجوبا وجوز الهند حسب نوعه.\nاطلبي من اللينك في البايو والدفع عند الاستلام.\n#سكراب #ZyraCare #عناية_بالجسم','\n',char(10)),'مسودة',1795038266679,1795038266679);
INSERT INTO organic_captions VALUES(27,11,1,'',replace('بتستخدمي نفس السكراب لكل جسمك؟ عندنا 3 سكرابات بملح سيوة وكل واحد ليه وظيفة:\nسكراب ملح سيوة: عناية أسبوعية عامة و5 روائح.\nسكراب جلد الوزة: للحبيبات ونقط ما بعد الشيفينج.\nسكراب السيلوليت: بالكافيين لمظهر وملمس الجلد المتموّج.\nوالتلاتة للجسم بس، ومش بعد الشيفينج مباشرة.\n#سكراب #ملح_سيوة #عناية_بالجسم','\n',char(10)),'مرشّحة',1795038266695,1795144931803);
INSERT INTO organic_captions VALUES(28,9,2,'',replace('معركة كل يوم: سبلاش ولا مخمرية؟\nلو بتحبي الإحساس الخفيف والانتعاش السريع هتروحي للسبلاش، ولو عايزة ترطيب وريحة تقعد هتروحي للمخمرية.\nاكتبي فريقك في الكومنتات.. والذكية اللي بتجمع الاتنين تكتب «الاتنين».\n#مخمرية #سبلاش #زيرا','\n',char(10)),'مرشّحة',1795038269607,1795144931830);
INSERT INTO organic_captions VALUES(29,9,1,'تعليمي/قيمة',replace('سبلاش ولا مخمرية؟ الإجابة الصح: على حسب إنتي عايزة إيه.\nالسبلاش: ريحة خفيفة ومنعشة، 100 مل، كحول قليل وزيوت فمش بينشف، و10 روائح.\nالمخمرية الكريمي: ريحة وترطيب في خطوة واحدة بزبدة الشيا، قوام كريمي من غير إحساس دهني، و8 روائح.\nوعايزاها تفضل أطول؟ مخمرية الأول وسبلاش فوقها من نفس الريحة.\n#بادي_سبلاش #مخمرية #عطور_الجسم','\n',char(10)),'مسودة',1795038269649,1795038269649);
INSERT INTO organic_captions VALUES(30,9,3,'بيع ناعم وCTA',replace('خدي الاتنين بسعرين أوضح من بعض: بادي سبلاش 100 مل بـ 240 ج، ومخمرية كريمي بـ 199 ج.\nاختاري نفس الريحة وحطي المخمرية الأول وبعدها السبلاش، وهتلاحظي الفرق في الثبات.\nاطلبي من اللينك في البايو والدفع عند الاستلام.\n#عطور_الجسم #ZyraCare #مخمرية','\n',char(10)),'مسودة',1795038269666,1795038269666);
INSERT INTO organic_captions VALUES(31,7,2,'',replace('رجعنا.. وعايزين نبدأها صح المرة دي: من عندك إنتي.\nاسحبي السلايدات واعرفي إحنا مين وبنشتغل إزاي، وبعدين اكتبي لنا في الكومنتات: إيه أكتر مشكلة مضايقاكي في جسمك أو بشرتك دلوقتي؟\nكل تعليق هيتقرأ، وهنرشح لكل واحدة الروتين اللي يناسبها.\n#زيرا #جلد_الوزة #سيلوليت','\n',char(10)),'مرشّحة',1795038272833,1795144941154);
INSERT INTO organic_captions VALUES(32,7,1,'تعليمي/قيمة',replace('إحنا زيرا.. وبنقولك الحقيقة.\nبراند مصري بيبدأ من المشكلة قبل المنتج: إيه اللي مضايقك بالظبط؟ وبعدين نحلها بمواد فعالة وطبيعية: شيا من غانا، ملح سيوة، يوريا 25%، وريتينول وكافيين — بخطوات مدروسة، ومن غير وعود بمعجزات.\nوقفنا البيع بإرادتنا عشان نطوّر، ورجعنا.\nتنبيه: منتجات الريتينول لا تُستخدم أثناء الحمل والرضاعة.\n#زيرا #ZyraCare #عناية_بالجسم','\n',char(10)),'مسودة',1795038272846,1795038272846);
INSERT INTO organic_captions VALUES(33,7,3,'بيع ناعم وCTA',replace('ليه تبتدي مع زيرا وإنتي مطمنة؟\nلأننا هنقولك المنتج بيعمل إيه ومتعمليش بيه إيه، وهنرشحلك قبل ما تطلبي ونتابع معاكي بعدها.\nتدفعي لما الأوردر يوصلك، وقدامك 14 يوم ترجعيه لو مش مناسبك.\nابدئي من اللي مضايقك: ابعتلنا في الرسايل وهنرشحلك.\n#ZyraCare #عناية_بالجسم #براند_مصري','\n',char(10)),'مسودة',1795038272859,1795038272859);
INSERT INTO organic_captions VALUES(34,14,1,'',replace('لو عندك المشكلة دي.. ده روتينك.\n8 روتينات، وكل روتين بمكوّنه الفعّال وخطواته: سيلوليت، جلد الوزة والفراولة، بشرة دهنية، بشرة جافة، بشرة باهتة، عناية سيوة الأسبوعية، ثبات الريحة، وكيت الساحل.\nاسحبي ووصفي لنفسك المشكلة، وهتلاقي روتينها مستنيكي.\nتنبيه: روتين السيلوليت فيه ريتينول، لا يُستخدم أثناء الحمل والرضاعة.\n#روتين #جلد_الوزة #سيلوليت #زيرا','\n',char(10)),'مرشّحة',1795038275935,1795144941183);
INSERT INTO organic_captions VALUES(35,14,2,'تفاعلي',replace('محتارة بين روتينين؟ ده طبيعي، وعشان كده عملنا البوست ده.\nاسحبي السلايدات وقارني مشكلتك بكل روتين، ولو لسه محتارة اكتبي لنا في الكومنتات إيه اللي مضايقك بالظبط وهنرشحلك الأنسب.\nاحفظي البوست عندك، ده دليلك السريع لروتينات زيرا كلها.\n#عناية_بالجسم #عناية_بالبشرة #ZyraCare','\n',char(10)),'مسودة',1795038275953,1795038275953);
INSERT INTO organic_captions VALUES(36,14,3,'بيع ناعم وCTA',replace('روتينات الأبطال بتوعنا: روتين السيلوليت وروتين جلد الوزة، كل واحد بـ 799 ج بخصم حقيقي عن تمن مكوناته لوحدهم.\nوفيه روتينات تانية تبدأ من 599 ج لروتين البشرة الجافة و700 ج لروتين سيوة الأسبوعي.\nاختاري روتينك من اللينك في البايو، والدفع عند الاستلام و14 يوم للاسترجاع.\nتنبيه: روتين السيلوليت يحتوي على ريتينول، لا يُستخدم أثناء الحمل والرضاعة.\n#سيلوليت #جلد_الوزة #زيرا','\n',char(10)),'مسودة',1795038275967,1795038275967);
INSERT INTO organic_captions VALUES(37,12,3,'بيع ناعم وCTA',replace('أول طلب من زيرا أأسهل مما تتخيلي:\nاختاري روتينك من اللينك في البايو، ولو محتارة ابعتلنا المشكلة ونساعدك تختاري.\nالأوردر بيوصلك وتدفعي عند الاستلام، ولو احتجتي أي مساعدة إحنا هنا عشانك.\n#ZyraCare #جلد_الوزة #سيلوليت','\n',char(10)),'مسودة',1795038280555,1795038280555);
INSERT INTO organic_captions VALUES(38,12,1,'',replace('ليه تطلبي من زيرا؟ خلينا نرد على كل خوف ممكن يمنعك تاخدي أول خطوة.\nهتدفعي بس لما الأوردر يوصلك، وتقدري ترجعي خلال 14 يوم وفق شروط سياسة الاسترجاع، ومكوّنات كل منتج مكتوبة على صفحته، وكل روتين ليه طريقة استخدام واضحة خطوة بخطوة.\nاسحبي السلايدات، واطلبي وإنتي مطمنة.\n#زيرا #ZyraCare #تسوق_أونلاين','\n',char(10)),'مرشّحة',1795038280575,1795144941168);
INSERT INTO organic_captions VALUES(39,12,2,'تفاعلي',replace('إيه أكتر حاجة بتخوفك وإنتي بتطلبي منتجات عناية أونلاين لأول مرة؟\nإنك تدفعي قبل ما تشوفي؟ إن الروتين ميبقاش مناسبك؟ إن محدش يرد عليكي بعدها؟\nاكتبي خوفك في الكومنتات وهنرد عليه بصراحة، زي ما بنرد في السلايدات دي بالظبط.\n#عناية_بالجسم #براند_مصري #زيرا','\n',char(10)),'مسودة',1795038280596,1795038280596);
INSERT INTO organic_captions VALUES(40,13,2,'تفاعلي',replace('أول حقيقة لازم تسمعيها: إنتي مش لوحدك، والسيلوليت عند أغلب الستات حتى الرفيعة — ده شكل طبيعي للجلد.\nالعناية بتفرق في الملمس والمظهر، ومش بتفرق في الوزن، ومفيش كريم بيشيل السيلوليت. دي الحقيقة اللي هنفضل نقولها.\nاحفظي البوست وابعتيه لأي واحدة محتاجة تسمع الكلام ده.\nتنبيه: منتجات الريتينول لا تُستخدم أثناء الحمل والرضاعة.\n#سيلوليت #ZyraCare #روتين_الجسم','\n',char(10)),'مسودة',1795038290784,1795038290784);
INSERT INTO organic_captions VALUES(41,13,1,'',replace('5 غلطات في روتين السيلوليت ممكن يكونوا السبب إنك مش شايفة فرق:\nتفتكري إنه عشان التخن، تفركي جامد، تحطي الكريم من غير تجهيز، تستخدميه الصبح من غير واقي، أو تبطلي بعد أسبوع.\nاسحبي السلايدات واعرفي تصحيح كل غلطة. الروتين الصح: صابونة كولاجين + سكراب كافيين + كريم ريتينول بالليل.\nتنبيه: الريتينول لا يُستخدم أثناء الحمل والرضاعة.\n#سيلوليت #عناية_بالجسم #زيرا','\n',char(10)),'مرشّحة',1795038290801,1795144941209);
INSERT INTO organic_captions VALUES(42,13,3,'بيع ناعم وCTA',replace('جاهزة تعملي الروتين صح المرة دي؟\nروتين السيلوليت الكامل: صابونة الكولاجين وبذور العنب + سكراب الكافيين وملح سيوة + كريم الريتينول والكافيين والنياسيناميد — بـ 799 ج بدل 975.\nاطلبي من اللينك في البايو، والدفع عند الاستلام.\nتنبيه: الريتينول لا يُستخدم أثناء الحمل والرضاعة، وبيتحط بالليل بس.\n#سيلوليت #زيرا #عناية_بالجسم','\n',char(10)),'مسودة',1795038290816,1795038290816);
INSERT INTO organic_captions VALUES(43,15,3,'بيع ناعم وCTA',replace('روتين جلد الوزة والفراولة كامل: سكراب جلد الوزة + لوشن يوريا 25% + زبدة شيا مكررة.\nمكوناته لوحدها بـ 1,050 ج، والروتين بـ 799 ج بدل 1,050.\nاطلبي من اللينك في البايو، والدفع عند الاستلام و14 يوم للاسترجاع.\n#جلد_الوزة #يوريا25 #ZyraCare','\n',char(10)),'مسودة',1795038294980,1795104515799);
INSERT INTO organic_captions VALUES(44,15,1,'',replace('4 غلطات بتزوّد جلد الوزة من غير ما تاخدي بالك:\nليفة جامدة كل يوم، مرطب عادي وخلاص، ترتيب غلط بين السكراب واللوشن، ولوشن بعد الشيفينج على طول.\nالتصحيح: سكراب ناعم مرة في الأسبوع في الأول، لوشن فيه يوريا ينعّم الجلد الخشن، واستني 24 لـ 48 ساعة بعد الشيفينج.\nاسحبي السلايدات للتفاصيل.\n#جلد_الوزة #يوريا #عناية_بالجسم','\n',char(10)),'مرشّحة',1795038294993,1795167942093);
INSERT INTO organic_captions VALUES(45,15,2,'تفاعلي',replace('حبيبات دراعك بتزيد في الشتا؟ إنتي مش لوحدك.\nاسمها جلد الوزة، وعلمياً Keratosis Pilaris: كيراتين بيتراكم حوالين فتحات الشعر، والجو الناشف بيخليها تبان أكتر.\nاكتبي لنا في الكومنتات: بتزيد عندك في الشتا ولا طول السنة؟ وهنقولك تعدلي روتينك إزاي.\n#جلد_الوزة #زيرا #روتين_الجسم','\n',char(10)),'مسودة',1795038295006,1795038295006);
INSERT INTO thinking_entries VALUES(1,'اقتصاديات الـCOD للـDual Hero لسه [EST] — ماينفعش تبني عليها Scale ولا Kill','الملف الأساسي ولقطة Dual Hero المالية المحسوبة [EST] بتاريخ 2026-11-18: سعر كلا الروتينين الهيرو 799 جنيه، وCOGS كل واحد 350 جنيه مؤكد من المالك، وTarget CPP = 160، والحقول الأساسية ممتلئة 3/7، وWhatsApp% = 0 وDelivery% = 0، والمُسلّم الفعلي 0 وBreak-even ROAS = 0. رايات عدم اليقين بنفس التاريخ: رسوم Bosta الفعلية غير مؤكدة، ورقم Break-even 275 ومساهمة 381/مُسلّم محسوبين بافتراضات السكربت الافتراضية (تعبئة 20 / شحن 70 / مرتجع 50 / COD 2%) وعند تسليم صافٍ 72% افتراضي، ونسب WhatsApp/Delivery الفعلية وميزانية الاختبار الأسبوعية لسه على المالك، وCOGS باقي المنتجات غير مدخل، وأهداف الريلونش للهيروين الاتنين مستهدفها 0 ومحققها 0.','لأن كل رقم ربحية هنا مبني على افتراض مش على فعلي، ولأن مفيش تسليم فعلي مسجل (مُسلّم 0) يثبّت النسب ← إذن أي مقارنة بين Target CPP 160 والـBreak-even أو المساهمة هتبقى استنتاج من نموذج تقديري مش من السوق، وأي قرار Kill/Scale دلوقتي هيبقى من غير مرور على Payday ومن غير بيانات فعلية زي ما هو مطلوب.','اقتصاديات الـCOD لسه فرضية [EST] قابلة للتغيير أول ما رسوم Bosta والنسب الفعلية تدخل، ومفيش أساس صادق دلوقتي للحكم على نجاح الهيرو أو فشله.','جمع بيانات فقط — مش Scale ومش Kill: المالك يوثّق في خطوة واحدة رسوم Bosta الفعلية + نسب WhatsApp/Delivery الفعلية + ميزانية الاختبار الأسبوعية، وبعدها بس يتعاد حساب المساهمة والـBreak-even قبل أي صرف. معيار إقفال الخطوة قابل للقياس: التلات بنود موثقة كتابةً والحساب متعاد بيها فعليًا، ولحد ده ما يحصل الصرف والتصعيد يفضلوا موقوفين كمقترح.',25,'بانتظار قرارك','',0,1795045501027);
INSERT INTO thinking_entries VALUES(2,'بوابة امتثال واحدة: خطوات الروتين من غير وعد علاجي ولا تضخيم لادعاء الـ1000 عميلة','تحليلات إعلانات المنافسين الأخيرة المسجلة ضمن معطيات 2026-11-18 (تاريخ منفصل للتحليل غير مذكور في المعطيات): Alejon — «اختبر/تبنَّ: زاوية الاستمرارية كروتين واضح الخطوات والتكرار لزيرا، لكن بصياغة استخدام واقعية وبلا وعد علاجي أو ضمان نتيجة». والملف الأساسي بنفس التاريخ بيذكر «أكتر من 1000 عميلة طلبوا من زيرا (كما هو معلن على الويبسايت)» — وده مذكور كإعلان ويبسايت، ومفيش في المعطيات توثيق مستقل مرفق ليه. وفي نفس المعطيات: تحليلات كرييتف زيرا «لا تحليلات بعد»، والأورجانيك 15 بوست مسجل و0 معتمد.','لأن القيمة المسجلة في زاوية Alejon هي وضوح الخطوات والتكرار مش ادعاء نتيجة، ولأن زيرا لسه معندهاش تحليل كرييتف ولا بوست أورجانيك معتمد واحد يثبت إن عندها صياغة آمنة شغالة، ولأن ادعاء الـ1000+ مذكور كمُعلن على الويبسايت من غير توثيق مستقل في المعطيات ← إذن تبنّي الشكل من غير بوابة صياغة وتوثيق هيحوّل اختبار منافس لمخاطرة وعد علاجي أو ادعاء اجتماعي غير مدعوم بالمعطيات المسجلة.','اللي يتاخد من Alejon هو هيكل «روتين واضح الخطوات والتكرار» بصياغة واقعية بس، وأي نسخة فيها وعد علاجي أو ضمان نتيجة أو استخدام غير موثق لادعاء الـ1000+ تبقى برّه بوابة الامتثال.','قرار مقترح واحد: قبل اعتماد أول نسخة كرييتف بزاوية الاستمرارية، تعدّي على فحص امتثال واحد موثق. معيار القياس: النسخة المعتمدة عدد الوعود العلاجية وضمانات النتيجة فيها صفر، وخطوات الاستخدام والتكرار مكتوبة بصياغة واقعية، وادعاء الـ1000+ عميلة مش مستخدم في الكرييتف لحد ما يتوثق مصدره — ولو الفحص فشل في أي بند، النسخة ما تتعتمدش.',35,'بانتظار قرارك','',0,1795045501043);
INSERT INTO thinking_entries VALUES(3,'AEO «زبدة الشيا الاصلية» ورقم 25%: اختبار مؤجل لحد توثيق المصدر والمرجع','بنود مسجلة بصيغة «غير محدد من التسجيل» ضمن معطيات 2026-11-18، ومصدرها وتاريخها المنفصل غير محددين في التسجيل نفسه: (1) اختبار قسم أسئلة شائعة/محتوى بعنوان يطابق لغة البحث «زبدة الشيا الاصلية» يشرح علامات تحقق قابلة للفحص لمنتج زيرا — والقائمة مقطوعة في النص المسجل؛ (2) بند بيقول «اختبر ولا تتبنَّ نهائيًا بعد» العنوان ده مقابل عنوان عام عن زبدة الشيا؛ (3) اختبار إبراز «الرقم الموثق 25%» في عنوان الإعلان/صفحة المنتج مقابل وصف عام للفئة، من غير ذكر أسماء براندات ومن غير ادعاء طبي — ومرجع الرقم 25% لإيه بالظبط غير موضح في المعطيات اللي وصلت.','لأن المصدر غير محدد والقائمة غير مكتملة ومرجع 25% غير موضح ← إذن نشر العنوان أو الرقم كحقيقة منتج دلوقتي هيبقى تبنّي نهائي لمحتوى التسجيل نفسه بيقول عليه «اختبر ولا تتبنَّ نهائيًا بعد»، وهيبني AEO على معلومة ناقصة ممكن تتفهم غلط.','فرصة الـAEO موجودة كفرضية اختبار بس، مش كمحتوى جاهز للنشر، وحالتها الحالية رسميًا: ناقصة التوثيق.','جمع بيانات فقط قبل أي نشر أو اختبار: توثيق مصدر البنود دي + مرجع الرقم 25% مكتوبًا + قائمة علامات تحقق زبدة الشيا كاملة وقابلة للفحص لمنتج زيرا. معيار الإقفال قابل للقياس: التلات عناصر موثقة، وبعده بس يتنفذ اختبار العنوان المسجل «زبدة الشيا الاصلية» مقابل عنوان عام — ولحد التوثيق مفيش تبنّي نهائي.',20,'بانتظار قرارك','',0,1795045501055);
INSERT INTO thinking_entries VALUES(4,'هوية زيرا في السيلوليت: «روتين متكامل» ضد بيع الكريم بالخصم — والفراغ جزئي مش سوق فاضي','الملف الأساسي بتاريخ 2026-11-18: عرض الهيرو «روتينات متكاملة لكل مشكلة بشرة/جسم — مشكلتك ليها روتين»، وروتين السيلوليت هيرو ريلونش بسعر 799 جنيه. ورصد Mazora الموثق (VERIFIED) من Meta Ads Library، مصر، إعلانات نشطة، بتاريخ 2026-11-18: بروفايله المسجل براند مصري لكريمات شد الجسم والسيلوليت بيبيع بعروض خصم موسمية قوية، ومسجل ليه «اختبار فراغ»: حضور Meta مخصص لزاوية الشد والعناية بمظهر السيلوليت اللي المنافس سابها بلا إعلان وقت الرصد. في المقابل، تنبيهات السوق الأخيرة في سياق 2026-11-18 فيها Hepta Skin — هيبتا بهيمنة إعلانية وTetavara بتوقف إعلاني، وإجمالي المنافسين المسجلين 31.','لأن تمييز زيرا المسجل هو الروتين المتكامل للمشكلة، وتمييز Mazora المسجل هو كريم + خصم موسمي قوي، ولأن فراغ Mazora خاص بزاوية معينة ووقت رصد ومش معناه سوق فاضي — بدليل هيمنة Hepta المسجلة في نفس المعطيات ← إذن الهوية تتقال كروتين عناية بمظهر السيلوليت بخطوات واضحة، مش كدخول حرب خصومات ولا كادعاء إن السوق بلا منافسة.','فيه زاوية هوية قابلة للاختبار لروتين السيلوليت، لكنها مش إذن إطلاق ولا Scale: لسه مربوطة ببوابة الاقتصاديات في المدخل الأول وبفحص الامتثال في المدخل التاني.','قرار مقترح واحد تحضيري وبلا صرف: تجهيز نسخة حضور Meta واحدة بس لزاوية الشد والعناية بمظهر السيلوليت مبنية على فكرة الروتين المتكامل مش الخصم الموسمي، وتفضل في حالة مسودة لحد توثيق بيانات الاقتصاديات وعدّيها فحص الامتثال. معيار القياس: نسخة واحدة جاهزة ومراجعة بالامتثال، وصفر صرف إعلاني عليها قبل ما البوابتين يقفلوا.',30,'بانتظار قرارك','',0,1795045501069);
INSERT INTO thinking_entries VALUES(5,'اقتصاديات COD لسه تقديرية — ممنوع Scale/Kill','الملف الأساسي بتاريخ 2026-11-19: الهيروان سعر 799 وCOGS ‏350 مؤكد من المالك، وTarget CPP ‏160، وحقول أساسية ممتلئة 3/7 بس، وWhatsApp%=0 وDelivery%=0. آخر لقطة مالية Dual Hero محسوبة [EST] بتاريخ 2026-11-18: موضوع 0 ومُسلّم 0 ومساهمة/مُسلّم 381 وBreak-even ROAS ‏0 وRTO ‏0%. نفس الملف بيقول إن Break-even ‏275 والمساهمة 381 محسوبة بافتراضات افتراضية (تعبئة 20 / شحن 70 / مرتجع 50 / COD ‏2%) وتسليم صافي 72% افتراضي، ورسوم Bosta الفعلية غير مؤكدة، ونسب WhatsApp/Delivery الفعلية وميزانية الاختبار الأسبوعية لسه على المالك، وأهداف الريلونش للهيروان مستهدف 0 ومحقق 0.','لأن المساهمة 381 وBreak-even ‏275 مبنيين على تسليم 72% ورسوم افتراضية مش فعلية ← إذن أي مقارنة مع Target CPP ‏160 هتدي قرار وهمي. ولأن الموضوع والمُسلّم فعليًا 0 والـDelivery% ‏0 ← إذن مفيش وحدة اقتصادية حقيقية اتقاست أصلًا.','مفيش أساس فعلي لأي حكم ربحية أو Scale/Kill دلوقتي؛ الرقم الوحيد المؤكد في اقتصاديات الهيرو هو COGS ‏350، والباقي إما صفر أو تقديري [EST].','قرار مقترح للمالك بس — جمع بيانات مش تنفيذ: المالك يسلّم رسوم Bosta الفعلية ونسب WhatsApp/Delivery الفعلية وميزانية الاختبار الأسبوعية ويستكمل الحقول من 3/7 لـ7/7، وبعدها تتعاد اللقطة المالية بموضوع ومُسلّم أكبر من 0 قبل ما أي Kill/Scale يعدي على Payday — وتاريخ Payday نفسه غير مسجل في المعطيات ويتحدد من المالك.',30,'بانتظار قرارك','',0,1795048285912);
INSERT INTO thinking_entries VALUES(6,'بوابة امتثال AEO: ادعاء الـ+1000 وصياغات العلاج ممنوع يعدّوا من غير توثيق','الملف الأساسي بتاريخ 2026-11-19: عرض الهيرو معلن على الويبسايت بعبارة «أكتر من 1000 عميلة طلبوا من زيرا» من غير مصدر تحقق مستقل مسجل في المعطيات. تحليل Alejon المسجل (التاريخ غير مذكور في المعطيات): تبنّي زاوية الاستمرارية كروتين واضح الخطوات بس بصياغة واقعية وبلا وعد علاجي أو ضمان نتيجة. تحليل Centevia ‏VERIFIED من Meta Ads Library — مصر (التاريخ غير مذكور): صياغة المشكلة لغرض تجميلي/مظهر الخشونة وجلد الوزة. الأورجانيك بتاريخ 2026-11-19: 15 بوست مسجل و0 معتمد، واعتمادات معلّقة 0.','لأن «كما هو معلن على الويبسايت» إعلان مش توثيق ← إذن ماينفعش يتحول الادعاء لدليل تسويقي من غير مصدره. ولأن تحليلات المنافسين المسجلة نفسها حاطة حد واضح: تجميلي وبلا وعد علاجي ولا ضمان نتيجة ← إذن الامتثال بوابة قبل الكرييتف مش بعدها.','بوابة الامتثال والـAEO لسه مفتوحة: الادعاء العددي غير موثّق في المعطيات، ومفيش محتوى معتمد أصلًا، فأي نشر قبل التوثيق والمراجعة مخاطرة مش مدعومة بدليل.','قرار مقترح للمالك بس — بوابة اعتماد قابلة للقياس: الـ15 بوست يفضلوا 0 معتمد لحد ما المالك يقدّم مصدر ادعاء «+1000 عميلة» المسجل، وكل نسخة تعدي مراجعة مكتوبة بتمنع الوعد العلاجي وضمان النتيجة وتلتزم بصياغة المظهر التجميلي بس؛ الاعتماد يتحرك من 0 بس بعد اكتمال التوثيق والمراجعة.',45,'بانتظار قرارك','',0,1795048285927);
INSERT INTO thinking_entries VALUES(7,'اختبار كرييتف واحد بمتغير واحد — بس نصه ناقص','تحليل Centevia ‏VERIFIED، المصدر Meta Ads Library — مصر (التاريخ غير مذكور في المعطيات): «اختبر ولا تنسخ: فيديو يفتتح بمشكلة بصرية واحدة محددة — مظهر الخشونة/جلد الوزة لغرض تجميلي — مقابل فيديو ترطيب عام، بنفس» والنص المسجل مقطوع عند «بنفس». تحليل Alejon المسجل (التاريخ غير مذكور): زاوية تانية مختلفة هي الاستمرارية كروتين واضح الخطوات والتكرار. تحليلات كرييتف أخيرة في ملف 2026-11-19: لا تحليلات بعد.','لأن Rule of One بيطلب متغير واحد، والمقارنة المسجلة هي مشكلة بصرية واحدة محددة مقابل ترطيب عام ← إذن إدخال خطوات الاستمرارية في نفس النسخة هيخلي سبب أي نتيجة مجهول. ولأن الشرط الموحّد مقطوع عند «بنفس» ومفيش تحليلات كرييتف سابقة ← إذن المواصفة والقياس ناقصين ولازم يتجمعوا الأول.','فكرة الاختبار موجودة بس مواصفاتها ناقصة، ودمجها مع زاوية Alejon هيبوّظ عزل المتغير؛ فمفيش اختبار جاهز للتنفيذ ولا فائز ممكن إعلانه.','قرار مقترح للمالك بس — جمع بيانات وتكملة مواصفة: يُستكمل النص المقطوع بعد «بنفس» من مصدر تحليل Centevia ويتسجل الشرط الموحّد بين النسختين ومقياس الحكم قبل الإنتاج، مع فصل اختبار المشكلة البصرية الواحدة عن اختبار الاستمرارية بتاع Alejon فصل كامل؛ من غير الاستكمال ده مفيش إنتاج ولا إطلاق للاختبار.',38,'بانتظار قرارك','',0,1795048285941);
INSERT INTO thinking_entries VALUES(8,'فراغ Mazora في السيلوليت فرصة لحظية — لازم إعادة رصد قبل أي صرف','رصد Mazora ‏VERIFIED بتاريخ 2026-11-18، المصدر Meta Ads Library — مصر، إعلانات نشطة: براند مصري لكريمات شدّ الجسم والسيلوليت بيبيع بخصومات موسمية قوية، والتوصية المسجلة «اختبار الفراغ» لزاوية الشدّ والعناية بمظهر السيلوليت اللي تركها المنافس بلا إعلان وقت الرصد، وباقي التوصية مقطوع في المعطيات. تنبيهات السوق الأخيرة في ملف 2026-11-19 في نفس الوقت: Hepta Skin هيمنة إعلانية، وTetavara توقف إعلاني، وكلمة «سيلوليت» في مكتبة الإعلانات مسجلة كفرصة سوق. ميزانية الاختبار الأسبوعية غير مسجلة ولسه على المالك حسب ملف 2026-11-19.','لأن غياب إعلان Mazora كان «وقت» الرصد بتاريخ 2026-11-18 ← إذن ممكن يكون اتغير على تاريخ النهاردة 2026-11-19 أو بعده ومفيش رصد أحدث. ولأن هيمنة Hepta الإعلانية مسجلة جنب الفرصة ← إذن السوق مش فاضي بالكامل. ولأن الميزانية والاقتصاديات الفعلية ناقصة ← إذن القرار الصح تحقق جديد مش صرف.','الفراغ المسجل لحظي ومؤرخ بـ2026-11-18 ومش دليل دائم، وإشارات السوق متعارضة بين فرصة وهيمنة منافس، فماينفعش يتبني عليه دخول مدفوع دلوقتي.','قرار مقترح للمالك بس — جمع بيانات وتحقق جديد: إعادة رصد مؤرخة على Meta Ads Library لمازورا وHepta Skin لتسجيل حضور أو غياب إعلان زاوية الشدّ ومظهر السيلوليت وقت القرار، ونتيجتها تتربط ببوابة اقتصاديات COD في المدخل الأول؛ لحد ما الرصد الجديد والميزانية يتسجلوا، مفيش إطلاق حضور مدفوع ولا Scale.',32,'بانتظار قرارك','',0,1795048285956);
INSERT INTO thinking_entries VALUES(9,'اقتصاديات COD: أرقام الهيرو تقديرية وصفر تشغيل فعلي — ممنوع Scale/Kill دلوقتي','الملف الأساسي بتاريخ 2026-11-19: سعر الهيروين 799 وCOGS الهيروين 350 EGP مؤكد من المالك، وTarget CPP=160، والح fields الأساسية 3/7 بس. آخر لقطة مالية Dual Hero [EST] بتاريخ 2026-11-18: موضوع 0، مُسلّم 0، مساهمة/مُسلّم 381، Break-even ROAS=0، RTO=0%. نفس المعطيات بتقول رسوم Bosta الفعلية غير مؤكدة، ورقم 381 ورقم Break-even 275 محسوبين بافتراضات سكربت افتراضية (تعبئة 20 / شحن 70 / مرتجع 50 / COD 2%) عند تسليم صافي 72% افتراضي، وWhatsApp%=0 وDelivery%=0، ونسب WhatsApp/Delivery الفعلية وميزانية الاختبار الأسبوعية وCOGS باقي المنتجات لسه ناقصين على المالك.','لأن COGS لوحده مؤكد، لكن تكلفة التوصيل والمرتجع والـ COD والتسليم كلها افتراضية ← إذن المساهمة 381 والـ Break-even 275 مش أرقام فعلية. ولأن الموضوع والمُسلّم وDelivery وWhatsApp كلهم صفر في اللقطة ← إذن مفيش سلوك عميلة فعلي نقيس عليه CPP=160 المستهدف ولا نحكم بيه على الهيرو.','مفيش أساس فعلي لأي قرار Scale أو Kill أو اعتماد رقم 381 كربح حقيقي؛ أي تنفيذ دلوقتي هيبقى مبني على تقدير [EST] وصفر مبيعات مسجلة.','قرار مقترح واحد — جمع بيانات بس، لا Scale ولا Kill قبل Payday والبيانات الفعلية: المالك يسلّم رسوم Bosta الفعلية، ونسب WhatsApp/Delivery الفعلية، وميزانية الاختبار الأسبوعية، وCOGS باقي المنتجات، وتتكمل الحقول الأساسية من 3/7 لـ 7/7، وبعدها تتعاد اللقطة المالية من غير افتراضات السكربت ويُقاس النجاح باختفاء وصف [EST] الافتراضي وظهور موضوع ومُسلّم فعليين غير صفريين.',28,'بانتظار قرارك','',0,1795062656366);
INSERT INTO thinking_entries VALUES(10,'بوابة امتثال AEO: سؤال «جلد الوزة في الوجه» فرضية كويسة بس ممنوع نشرها بلا اعتماد','تحليلات إعلانات المنافسين الأخيرة المسجلة بتاريخ غير محدد من التسجيل: اقتراح اختبار محتوى تعليمي سؤال وجواب موجز يطابق لغة البحث «جلد الوزة في الوجه» مع توضيح فرق احتياجات الوجه عن غيره، واقتراح تاني يشرح صلة التقشير/اليوريا بالشعر تحت الجلد بلغة عناية وصفية غير علاجية، واقتراح قياس الظهور والنقر لعبارة البحث كعنوان خاص بالوجه مقابل المحتوى العام. في المقابل، بتاريخ 2026-11-19: تحليلات الكرييتف «لا تحليلات بعد»، والأورجانيك 15 بوست مسجل و0 معتمد، وميزانية الاختبار الأسبوعية لسه ناقصة.','لأن الطلب المسجل نفسه مربوط بلغة بحث محددة وبيشترط ضمنيًا لغة غير علاجية والتمييز بين الوجه وغيره ← إذن المحتوى لازم يعدّي امتثال AEO قبل ما يبقى رسالة بيع. ولأن الاعتماد صفر والكرييتف غير محلل والميزانية ناقصة ← إذن النشر أو الصرف دلوقتي هيطلع نتيجة مش قابلة للحكم ولا آمنة امتثاليًا.','فكرة الـ AEO المسجلة واعدة كفرضية بحث، بس لسه مش جاهزة للنشر أو الصرف: مفيش تحليل كرييتف، ومفيش اعتماد، وصياغة علاجية واحدة غلط هتعدّي بوابة الامتثال.','قرار مقترح واحد — جمع بيانات واعتماد قبل أي نشر: يتحضّر مسودة واحدة بس بصيغة سؤال/جواب بعنوان عبارة البحث المسجلة «جلد الوزة في الوجه» وبلغة عناية وصفية غير علاجية صريحة، وتقف عند بوابة مراجعة الامتثال والاعتماد، ويُقاس التقدم بتحوّل الاعتماد من 0 من 15 بوست لحالة اعتماد موثقة للمسودة دي وتسجيل مقياس الظهور والنقر المطلوب قبل مقارنتها بالمحتوى العام — من غير إطلاق مدفوع قبل ما المالك يحدد ميزانية الاختبار.',34,'بانتظار قرارك','',0,1795062656384);
INSERT INTO thinking_entries VALUES(11,'هوية البراند: «مشكلتك ليها روتين» عامة، والهيرو وAlejon بيقولوا التخصص لمشكلة واحدة','الملف الأساسي بتاريخ 2026-11-19: عرض الهيرو العام «روتينات متكاملة لكل مشكلة بشرة/جسم — مشكلتك ليها روتين» مع ادعاء «أكتر من 1000 عميلة طلبوا من زيرا (كما هو معلن على الويبسايت)»، والمنتجات المسجلة 23، والهيروات اتنين متخصصين بالاسم: روتين السيلوليت وروتين جلد الوزة والفراولة، كل واحد بسعر 799 وCOGS 350. تحليل Alejon — خط اليوريا/جلد الوزة ببيانات موقع موثقة VERIFIED من alejon.com (التاريخ غير محدد من التسجيل): تبنّي/اختبار منتج وصفحة روتين مخصصين بوضوح لمشكلة واحدة بدل خط عام، باختبار A/B لصفحة متخصصة مقابل صفحة منتج عام — ونص مقياس الاختبار مقطوع عند «بقياس» في التسجيل. أهداف الريلونش بتاريخ 2026-11-19 للهيروين الاتنين: مستهدف 0 ومحقق 0.','لأن العرض الحالي بيكلم كل مشاكل البشرة/الجسم في جملة واحدة، بينما الهيروين نفسهم منتجات مشكلة واحدة، وAlejon الموثق بيختبر التخصص ضد العموم ← إذن فرضية «التخصص أوضح للهوية» تستاهل اختبار. لكن لأن مستهدف ومحقق الريلونش صفر ومقياس الـ A/B مقطوع والميزانية على المالك ← إذن تغيير الهوية أو الصفحة دلوقتي هيبقى قرار تنفيذي بلا معيار نجاح.','فيه توتر هوية حقيقي بين رسالة عامة لكل المشاكل وبين هيروات متخصصة بمشكلة واحدة، ودرس Alejon الموثق بيدعم اختبار التخصص — بس الاختبار نفسه لسه بلا هدف ولا مقياس مكتمل ولا ميزانية.','قرار مقترح واحد — جمع بيانات قبل اختبار الهوية: المالك يحدد مستهدف ريلونش غير صفري لأحد الهيروين، ويتكمل مقياس الـ A/B الناقص في تسجيل Alejon، وتتحدد ميزانية الاختبار الأسبوعية الناقصة، ويُقاس الجاهزية باكتمال التلات عناصر دي موثقة قبل إطلاق أي A/B بين صفحة متخصصة لمشكلة واحدة وصفحة عامة.',38,'بانتظار قرارك','',0,1795062656398);
INSERT INTO thinking_entries VALUES(12,'اقتصاديات الـ COD لسه تقديرية [EST] — مفيش Scale/Kill قبل البيانات الفعلية','الملف الأساسي المسجل بتاريخ 2026-11-19: الهيروان بسعر 799 وCOGS ‏350 EGP من المالك (مؤكد)، وTarget CPP ‏160، وحقول أساسية ممتلئة 3/7 فقط، وWhatsApp% ‏= 0 وDelivery% ‏= 0. وآخر لقطة مالية (Dual Hero — اقتصاديات وحدة محسوبة [EST]، 2026-11-18): موضوع 0، مُسلّم 0، مساهمة/مُسلّم 381، وBreak-even ROAS ‏0 وRTO ‏0%. ورايات عدم اليقين في نفس الملف: رسوم Bosta الفعلية غير مؤكدة، ورقم Break-even ‏275 والمساهمة 381/مُسلّم محسوبين بافتراضات افتراضية (تعبئة 20 / شحن 70 / مرتجع 50 / COD ‏2%) عند تسليم صافٍ افتراضي 72%، ونسب WhatsApp/Delivery الفعلية وميزانية الاختبار الأسبوعية لسه على المالك، وCOGS باقي المنتجات غير مُدخل. وأهداف الريلونش للهيروين: مستهدف 0 ومحقق 0.','لأن COGS الهيروين مؤكد لكن باقي تكلفة الـ COD والشحن والمرتجع افتراضية ← إذن رقم المساهمة والـ Break-even مش قابلين للاعتماد في قرار فلوس. ولأن WhatsApp% وDelivery% والموضوع والمُسلّم كلهم 0 في التسجيل ← إذن مفيش سلوك طلب أو تسليم فعلي نقيس عليه. ولأن ميزانية الاختبار الأسبوعية ناقصة وأهداف الريلونش 0/0 ← إذن أي Scale/Kill دلوقتي هيبقى قرار من غير Payday ومن غير بيانات فعلية.','مفيش أساس فعلي لأي قرار Scale أو Kill، وأي قراءة للربحية دلوقتي هتكون مبنية على تقدير [EST] مش على تشغيل حقيقي. إعلان الويبسايت «أكتر من 1000 عميلة طلبوا من زيرا» هو كما هو معلن على الويبسايت فقط، وماينفعش يتحول لدليل أداء للهيروين قصاد لقطة فيها موضوع 0 ومُسلّم 0.','قرار مقترح واحد — جمع بيانات قبل أي إنفاق أو Kill/Scale: المالك يجيب رسوم Bosta الفعلية موثقة، ونسب WhatsApp وDelivery الفعلية، وميزانية الاختبار الأسبوعية، وتتكمل الحقول الأساسية من 3/7 لـ 7/7، وبعدها بس تتعاد حسابات Break-even والمساهمة وتتعرض على Payday والبيانات الفعلية؛ والقياس هنا هو اكتمال 7/7 ووجود أرقام فعلية بدل الافتراضية.',30,'بانتظار قرارك','',0,1795063842521);
INSERT INTO thinking_entries VALUES(13,'بوابة امتثال AEO قبل أي محتوى «جلد الوزة في الوجه» — سؤال وجواب غير علاجي','تحليلات إعلانات منافسين أخيرة (التاريخ غير محدد من التسجيل، كما وردت ضمن معطيات 2026-11-19): اقتراح اختبار محتوى تعليمي بصيغة سؤال وجواب موجز يطابق لغة البحث «جلد الوزة في الوجه» مع توضيح الفرق بين احتياجات الوجه والجسم، واقتراح تاني يشرح صلة التقشير/اليوريا بالشعر تحت الجلد بلغة عناية وصفية غير علاجية، واقتراح قياس الظهور والنقر للمحتوى الخاص بالوجه مقابل المحتوى العام عن جلد الوزة. وفي المقابل، تحليلات كرييتف أخيرة مسجلة بتاريخ المعطيات 2026-11-19: لا تحليلات بعد، والأورجانيك: 15 بوست مسجل و0 معتمد.','لأن الاقتراحات جاية من تحليلات منافسين وتاريخها غير محدد من التسجيل ومفيش تحليلات كرييتف لزيرا نفسها ← إذن هي فرضيات اختبار مش نتائج مثبتة. ولأن نفس الاقتراحات مشترطة لغة غير علاجية وتوضيح فرق الوجه والجسم ← إذن تجاوز البوابة دي في الصياغة يبوّظ الاختبار من أصله. ولأن الأورجانيك 0 معتمد ← إذن النشر قبل الاعتماد هيبقى قفز فوق البوابة مش تنفيذ ليها.','الفكرة القابلة للاختبار موجودة في التسجيل، لكن بوابة الامتثال والاعتماد هي الشرط اللي قبل أي نشر: لغة وصفية غير علاجية، وتفريق واضح بين الوجه والجسم، واعتماد فعلي — وده لسه مش حاصل بدليل 0 معتمد ومفيش تحليلات كرييتف.','قرار مقترح واحد — اختبار محتوى واحد مشروط بالاعتماد: تجهيز قطعة سؤال وجواب واحدة فقط بعنوان/سؤال «جلد الوزة في الوجه» بلغة وصفية غير علاجية توضح فرق الوجه عن الجسم، ومتتنشرش إلا بعد اعتماد موثق، وبعد النشر يتقاس ظهورها ونقرها مقابل قطعة عامة عن جلد الوزة زي ما هو مقترح في التسجيل؛ لو الاعتماد مجاش، القرار بيقف عند جمع البيانات ومفيش نشر.',25,'بانتظار قرارك','',0,1795063842544);
INSERT INTO thinking_entries VALUES(14,'هوية البراند: «مشكلتك ليها روتين» عامة قصاد صفحة متخصصة لمشكلة واحدة','Alejon — خط اليوريا / جلد الوزة (بيانات موقع موثقة VERIFIED من alejon.com، التاريخ غير محدد من التسجيل): تتبنّى/تختبر منتج وصفحة روتين مخصصين بوضوح لمشكلة واحدة بدل خط عام، باختبار A/B لصفحة متخصصة مقابل صفحة منتج عام — ونص التسجيل مقطوع عند «بقياس» فمقياس الاختبار نفسه ناقص. والملف الأساسي بتاريخ 2026-11-19: عرض الهيرو الحالي عام «روتينات متكاملة لكل مشكلة بشرة/جسم — مشكلتك ليها روتين»، والهيروان المسجلان مشكلتين مختلفتين (السيلوليت، وجلد الوزة والفراولة) وكل واحد بسعر 799 وCOGS ‏350، وأهداف الريلونش لكل هيرو مستهدف 0 ومحقق 0.','لأن عرض الهيرو الحالي بيجمع كل المشاكل في وعد واحد، بينما مصدر Alejon الموثق بيقترح العكس (صفحة لمشكلة واحدة) ← إذن دي نقطة تمييز هوية قابلة للاختبار مش حقيقة مؤكدة لزيرا. ولأن التسجيل مقطوع عند مقياس الـ A/B، وأهداف الريلونش 0/0، ومفيش نتائج تشغيل لزيرا ← إذن ماينفعش نحكم إن المتخصصة هتكسب العامة عندنا. ولأن Rule of One بيفرض مشكلة واحدة واختبار واحد ← إذن التوسع لأكتر من صفحة أو مشكلة في نفس الخطوة هيشوّش أي نتيجة.','التعارض المسجل هو: وعد عام لكل المشاكل قصاد درس منافس موثق لصالح التخصص لمشكلة واحدة. التخصص فرضية هوية وصفحة تستحق تصميم اختبار، لكنها مش قرار إطلاق دلوقتي لأن مقياس الـ A/B والميزانية وبيانات الأداء ناقصين.','قرار مقترح واحد — جمع بيانات وتصميم اختبار فقط، من غير إطلاق: تصميم A/B لصفحة روتين متخصصة لمشكلة واحدة مقابل الصفحة العامة، مع تحديد المقياس الناقص من التسجيل وميزانية الاختبار كتابةً قبل أي تشغيل، وربط التشغيل نفسه باكتمال بيانات اقتصاديات الـ COD في المدخل الأول؛ القياس المطلوب قبل الإطلاق هو وجود مقياس واحد مكتوب وميزانية واحدة مكتوبة.',35,'بانتظار قرارك','',0,1795063842556);
INSERT INTO thinking_entries VALUES(15,'الأورجانيك واقف عند الاعتماد: 15 بوست مسجل و0 معتمد','الأورجانيك المسجل ضمن معطيات 2026-11-19: 15 بوست مسجل و0 معتمد. والشغل في نفس المعطيات: 14 عنصر و0 متأخر، واعتمادات معلّقة: 0. وتحليلات كرييتف أخيرة: لا تحليلات بعد. وسبب عدم اعتماد أي بوست مش مسجل في المعطيات.','لأن 15 بوست مسجلين و0 معتمدين، وفي نفس الوقت الشغل 0 متأخر والاعتمادات المعلّقة 0 ← إذن المشكلة مش عبء متأخرات ظاهر في التسجيل، لكن مفيش ولا قطعة عدّت الاعتماد. ولأن سبب الرفض أو التعطيل مش مسجل ← إذن أي تفسير (جودة، امتثال، هوية) هيبقى تخمين ممنوع. ولأن مفيش تحليلات كرييتف ← إذن ماينفعش نبني قرارات محتوى جديدة قبل ما نعرف مصير الموجود أصلاً.','عنق الزجاجة الظاهر في الأرقام المسجلة هو الاعتماد مش التأخير: فيه محتوى مسجل كتير وصفر منه معتمد، وبالتالي صوت البراند مش موجود فعلياً في السوق بأي قطعة معتمدة، ومفيش أي أساس لتحليل أداء كرييتف.','قرار مقترح واحد قابل للقياس: المالك يراجع الـ 15 بوست المسجلين في خطوة اعتماد واحدة ويوثق لكل بوست قرار «معتمد / مرفوض» وسبب الرفض لو وُجد (امتثال أو هوية)، والهدف المقاس هو الخروج بعدد معتمد أكبر من 0 وقائمة أسباب رفض مكتوبة قبل إنتاج أو اختبار أي محتوى جديد.',40,'بانتظار قرارك','',0,1795063842568);
INSERT INTO thinking_entries VALUES(16,'خطة الكرييتف للفترة الجاية — شتاء زيرا: الهيرو المزدوج أولاً','اندمجت فيها: تعليمات مالك نشطة 2 · خطط مالك 0 · منتجات 23 · كرييتفز في المكتبة 0 (بتحليلاتها الأخيرة ودرجاتها البصرية) · تحليلات إعلانات منافسين 12 · رؤى عملاء 0 · ملاحظات تعلّم 0 · كلمات بحث 12 · طلبات توليد مفتوحة 0 · أورجانيك 15 — بتاريخ 2026-11-19 (تلقائي — لوب التشغيل شغال ورا المالك).',replace('المكتبة صفر والأورجانيك 15 بوست بلا أرقام أداء مسجلة ولا صوت عميل، فلا يوجد فائز موثق وكل مقترح اختبار. أقوى إشارة موسمية هي شتاء نوفمبر–فبراير ذروة الجفاف، والهيرو المزدوج روتين جلد الوزة وروتين السيلوليت بسعر 799 جنيه وCOGS مؤكد 350 لكل منهما، مع Target CPP 160 ومساهمة تقديرية 381 للقطعة المُسلّمة مبنية على افتراض تسليم 72% ورسوم غير مؤكدة. لغة البحث المتعقبة تدعم اليوريا وجلد الوزة وزبدة الشيا للبشرة والاستعلام المركّب مع الشعر تحت الجلد، لكنها رصد مسح واحد بلا أداء. المنافسون المسجلون يتركون فراغاً: Alejon يوريا 10% عامة بلا منتج مخصص لجلد الوزة وباقاته نافدة، وUrban Ducks غاب خطاب السيلوليت عن تشكيلته الحالية في Bloom، وKolagra ظهر وحده في Top Ads بفيديو لكن هوكه غير مسجل وغاب آخر 30 يوماً، وNefertari صفر إعلانات نشطة على ميتا في 2026-11-18. الفجوات: لا فيديو ولا كاروسيل مسجل لزيرا، ولا كرييتف مرساة يوريا 25%، ولا محتوى مقسّم حسب المشكلة المركّبة، وCOGS باقي المنتجات غير مدخل.\nترتيب التنفيذ: نبدأ بالهيرو المزدوج أولاً: بريف ستاتيك جلد الوزة وفيديو UGC السيلوليت بالتوازي للمصمم البشري وصانعة المحتوى، ثم كاروسيل اليوريا 25%، ثم اختبار صغير لستاتيك زبدة الشيا، ثم فيديو جلد الوزة والشعر تحت الجلد. قبل كل إطلاق نتحقق من توفر المنتج ونعيد فحص المنافسين، ونقيس كل كرييتف مقابل Target CPP 160 وعتبات الاختبار المعروفة، ولا نصعّد أي كرييتف قبل بيانات التسليم الفعلية.\nنتجنب: هوكات إحراج أو أي لغة تخجل العميلة — تضر الثقة وتخالف قواعد المالك، والهوك البصري للملمس يكفي لرفع الانتباه. ؛ أي وعد طبي أو وعد بنتيجة حتمية — الادعاءات المعتمدة فقط هي النعومة والترطيب من أول أسبوع وتحسّن تدريجي في الملمس والمظهر مع الانتظام 4–8 أسابيع. ؛ تكرار نفس التمبلت والتكوين أو زحمة عناصر أسفل التصميم أو نص كثير — كل تصميم لازم يكون تكويناً مختلفاً فعلياً على مستوى التخطيط حسب تعليمات المالك. ؛ إطلاق روتين السيلوليت بدون الصابونة أو بدون تحذير الحمل والرضاعة للريتينول — الروتين 3 قطع دايماً، والتحذير إلزامي في الـ Spec. ؛ اعتبار أي كرييتف فائزاً أو التصعيد قبل بيانات COD الفعلية — المكتبة صفر ولا أرقام أداء مسجلة، فكل شيء اختبار مقابل Target CPP 160.\nبيانات ناقصة بتضعف الخطة: رسوم Bosta الفعلية ونسب WhatsApp والتسليم الصافية مقابل افتراض 72%، وميزانية الاختبار الأسبوعية — بدونها أرقام المساهمة 381 للقطعة المُسلّمة تبقى تقديرية. ؛ COGS باقي المنتجات والمخزون وتوفر المنتج البطل في كل قناة قبل الإطلاق — خصوصاً لوشن اليوريا وزبدة الشيا والسكراب. ؛ أي أرقام أداء مسجلة للكرييتف أو الأورجانيك: CTR وCPP وROAS — المكتبة صفر فلا فائز ولا خاسر موثق. ؛ صوت العميل: مراجعات وأسئلة فعلية ومتاحية صانعات محتوى UGC — لا رؤى عملاء مسجلة. ؛ تكرار رصد لغة البحث وإعادة فحص Meta Ads Library قبل الإطلاق — إشارات البحث والمنافسين لقطة مسح واحد بتاريخ 2026-11-18/19 وليست اتجاهاً ثابتاً.','\n',char(10)),'الخطة اختبار شتاء مركّز على الهيرو المزدوج واليوريا، بلا وعود Scale وبلا فائز مزعوم: إذا ثبتت بيانات التسليم والتكلفة أن CPP تحت 160، نصعّد الفائز الحقيقي فقط؛ وإذا لم تثبت، نوقف ونعيد الزوايا من لغة البحث والمنافسين.','تنفيذ خطة الكرييتف «شتاء زيرا: الهيرو المزدوج أولاً»: 5 كرييتف مركّز بأولوياته وSpecs في طلبات التوليد (بانتظار اعتمادك) — راجِع الخطة واعتمدها أو عدّلها، والتنفيذ يبدأ بقرارك.',55,'مرفوض','أُغلقت بقرار المالك 2026-11-19 لصالح الدمج — ليست رفضاً للمحتوى: دُمجت مع خطة #17 في خطة موحدة واحدة سجلها المعتمد مدخل #17، وعنصراها الفريدان (UGC روتين السيلوليت في 3 خطوات + كاروسيل يوريا 25% لجلد الشتا الجاف) انتقلا للخطة الموحدة كطلبَي توليد 13 و12. باقي عناصرها كانت مكررة أو مندمجة في عناصر #17.',0,1795064669056);
INSERT INTO thinking_entries VALUES(17,'خطة الكرييتف للفترة الجاية — خطة كرييتف الشتا: اختبار الهيرو المزدوج أولاً — من مكتبة صفرية','اندمجت فيها: تعليمات مالك نشطة 2 · خطط مالك 0 · منتجات 23 · كرييتفز في المكتبة 0 (بتحليلاتها الأخيرة ودرجاتها البصرية) · تحليلات إعلانات منافسين 12 · رؤى عملاء 0 · ملاحظات تعلّم 0 · كلمات بحث 12 · طلبات توليد مفتوحة 0 · أورجانيك 15 — بتاريخ 2026-11-19 (يدوي — طلب المالك من «تحليل الكرييتف»).',replace('المكتبة المدفوعة فارغة تماماً (0 كرييتف) ولا توجد أرقام أداء أو صوت عميل مسجل، فلا يوجد فائز يُبنى عليه — كل المقترح اختبارات. أقوى إشارة مدمجة: موسم الشتا (نوفمبر–فبراير) في ذروة الجفاف، والهيرو المزدوج هو محور الريلونش: روتين جلد الوزة والفراولة وروتين السيلوليت بـ799 جنيه وCOGS مؤكد 350 لكل منهما وTarget CPP=160، بادعاءات معتمدة حذرة فقط (نعومة وترطيب من أول أسبوع، وتحسّن تدريجي في ملمس ومظهر السطح مع الانتظام 4–8 أسابيع). الاقتصاديات ما تزال EST: مساهمة 381/Break-even محسوبة بافتراضات افتراضية (تعبئة 20/شحن 70/مرتجع 50/COD 2% وتسليم صافٍ 72%) ورسوم Bosta الفعلية غير مؤكدة، فلا وعود ربح أو Scale. فجوات المنافسين المسجلة تدعم التخصص لا النسخ: Alejon يوريا 10% عامة بلا منتج مخصص لجلد الوزة وباقاته الـ14 نفدت، وNefertari وآخرون بصفر إعلانات ميتا نشطة في لقطة 2026-11-18، وسكرابا السيلوليت لدى Urban Ducks غائبان من تشكيلة Bloom الحالية. على TikTok توجد إشارة فيديو لجلد الوزة (الأعلى إعجاباً 12K بين أول 4 ووسم CTR أعلى) لكن اسم البراند غير مقروء وهوكه غير مسجل، وKolagra وحده في Top Ads بين 8 براندات بلا هوك أو عرض مسجل — الدرس: وضوح العبوة والاسم وتسجيل الهوك حرفياً. إشارات البحث (زبدة الشيا للبشرة، جلد الوزة والشعر تحت الجلد) رصد متقلب من مسح واحد، فتُختبر بحذر ولا تُعمّم. الأورجانيك عنده 15 بوست بأعمدة منتج وتعليمي ومشكلة وحل وثقة، لكن المدفوع ناقصه كل شيء: ستاتيك Clue للمشكلة، وفيديو UGC، وكاروسيل تعليمي، وتنويع Layout حقيقي يرضي Andromeda.\nترتيب التنفيذ: الخطوة 0 (قبل أي إنتاج): التأكد من توفر الروتينين في كل قناة معلنة + إعادة فحص Meta Ads Library + تجهيز تصوير عبوات رسمي واضح الاسم وتحذير الريتينول. الخطوة 1: إنتاج الستاتيكين الهيرو (1 و2) ببريفات للمصمم البشري بتكوينين مختلفين فعلياً وإطلاقهما كاختبار أول مقابل Target CPP=160. الخطوة 2 بالتوازي: تصوير فيديوهات (3 و4) دفعة واحدة مع تسجيل كل هوك حرفياً قبل التشغيل. الخطوة 3: الكاروسيل (5) ثم ستاتيك الشيا (6) كاختبارات موسمية/بحثية ثانوية. القياس والترقية فقط بعتبات Task D المعروفة وبعد ظهور CPP وتسليم فعليين — لا Scale ولا تعميم لأي زاوية قبل ذلك.\nنتجنب: أي ادعاء طبي أو علاجي أو نهائي أو مضمون، وأي وعد بتخسيس أو إزالة السيلوليت — الويبسايت نفسه ينفيها، وكلمة «علاج» لا تُنقل من لغة البحث إلى كوبي العميل. ؛ هوكات الإحراج، وكلمتا «سيستم» و«العناية الموضعية» في كوبي العميل — والبديل المعتمد هو «سكراب وكريم». ؛ أي كرييتف سيلوليت يُسقط الصابونة أو يُظهر أقل من 3 قطع كاملة: صابونة اللوف + السكراب + الكريم. ؛ نسخ المنافسين أو المقارنة باسم براند أو استعارة عروضهم مثل Buy 2 Get 2، أو نسبة هوك غير مسجل لـKolagra أو Alejon إلى زيرا. ؛ تكرار نفس التمبلت بتغيير الديكور، أو زحمة أسفل التصميم، أو تقديم رندر Muse كتصميم نهائي، أو وعود Scale قبل تحقق CPP والتسليم فعلياً — التصميم النهائي من بريف Muse عند مصمم بشري.\nبيانات ناقصة بتضعف الخطة: توفر روتينَي الهيرو فعلياً في كل قناة بيع معلنة قبل الإطلاق، ومكوّنات روتين جلد الوزة الرسمية كما ستظهر في التصوير (مكوّنات السيلوليت مؤكدة بقاعدة الـ3 قطع فقط). ؛ ميزانية الاختبار الأسبوعية، ونسب WhatsApp وDelivery الفعلية، ورسوم Bosta الفعلية — بدونها Break-even والمساهمة يفضلان EST بافتراضات افتراضية. ؛ COGS كل المنتجات غير الهيرو (منها روتين البشرة الجافة وزبدة الشيا) لتحديد أولوية اقتصادية كاملة. ؛ أي أرقام أداء سابقة أو صوت عميل أو اعتراضات شراء مسجلة — غيابها يجعل كل الهوكات فرضيات اختبار. ؛ إعادة رصد Meta Ads Library وTikTok قبل الإطلاق مباشرة وتكرار مسح لغة البحث — اللقطات الحالية يوم/مسح واحد ومتقلبة.','\n',char(10)),'الخطة إنتاج واختبار منضبط لا Scale: نبدأ بالهيرو المزدوج في الشتا بصور Clue وتكوينات مختلفة فعلياً، ونضيف فيديو يعالج فجوة الفورمات ووضوح العبوة، ثم نختبر الجفاف والشيا كفرص ثانوية. أي كرييتف هنا بلا أرقام أداء لزيرا، فهو فرصة اختبار تُقاس بـCPP المستهدف 160 وعتبات Task D المعروفة، ولا يُرقّى قبل بيانات تسليم وطلب فعلية.','تنفيذ خطة الكرييتف «خطة كرييتف الشتا: اختبار الهيرو المزدوج أولاً — من مكتبة صفرية»: 6 كرييتف مركّز بأولوياته وSpecs في طلبات التوليد (بانتظار اعتمادك) — راجِع الخطة واعتمدها أو عدّلها، والتنفيذ يبدأ بقرارك.',45,'معتمد','اعتمد المالك الخطة الموحدة (دمج #16+#17) بتاريخ 2026-11-19 وأمر ببدء تنفيذ الخطوة 0 فوراً: (أ) التحقق من توفر الروتينين الهيرو في كل قناة بيع معلنة، (ب) إعادة فحص Meta Ads Library، (ج) تجهيز تصوير عبوات رسمي واضح الاسم وتحذير الريتينول. الاعتماد يفتح طلبات التوليد السبعة (6، 7، 8، 9، 11، 12، 13) للإنتاج بالتسلسل المعتمد.',17,1795064753019);
INSERT INTO thinking_entries VALUES(18,'خطة الكرييتف للفترة الجاية — خطة كرييتف الشتا: الهيرو المزدوج أولاً — موجة تكميلية بلا تكرار','اندمجت فيها: تعليمات مالك نشطة 2 · خطط مالك 0 · منتجات 23 · كرييتفز في المكتبة 0 (بتحليلاتها الأخيرة ودرجاتها البصرية) · تحليلات إعلانات منافسين 12 · رؤى عملاء 0 · ملاحظات تعلّم 0 · كلمات بحث 12 · طلبات توليد مفتوحة 7 · أورجانيك 15 — بتاريخ 2026-11-19 (تلقائي — لوب التشغيل شغال ورا المالك).',replace('المكتبة صفر فلا فائز مسجلاً: كل شيء اختبار. أقوى إشارة هي لغة بحث Google Egypt فقط — جلد الوزة منطقة-منطقة، ويوريا للجسم بصيغ متعددة وurea باللاتينية، وزبدة الشيا للبشرة والأصلية، ونية سعرية، ونية منزلية، وفرق سيلوليت/ليبوديما — وليست أداء إعلانات، فلا أرقام CTR أو CPP فعلية. الشتا (نوفمبر–فبراير) ذروة الجفاف فيجعل اليوريا وجلد الوزة أولوية، والهيرو المزدوج (سيلوليت + جلد الوزة، 799 جنيه لكل روتين، COGS مؤكد 350) هو محور الريلونش، لكن اقتصادياته تقديرية: مساهمة 381 جنيه/مُسلَّم وBreak-even 275 مبنية على افتراضات (تعبئة 20، شحن 70، مرتجع 50، COD 2%، تسليم صافٍ 72%) ورسوم Bosta الفعلية غير مؤكدة وهدف CPP 160 بلا ميزانية اختبار مسجلة. الفجوة: لا صوت عميل ولا COGS لباقي المنتجات ولا نسب واتساب/تسليم فعلية. القائمة المفتوحة أصلاً تغطي هيرو الستاتيك والكاروسيل والـUGC والـFounder للسيلوليت وزبدة الشيا للبشرة، فالموجة الجديدة هنا تكمّلها فقط بزوايا وفورمات مختلفة: منطقة محددة، ولوشن يوريا مفرد بالفيديو، وكاروسيل تعليمي، وأصالة الشيا بالفيديو، وFounder منزلي — ودرس المنافسين الوحيد القابل للنسخ بحذر هو وضوح عرض القيمة، لكن بلا اختراع خصم غير مسجل لزيرا.\nترتيب التنفيذ: 1) ابدئي بالتوازي: ستاتيك جلد الوزة في الرجل + UGC لوشن يوريا 25% — أسرع اختبار شتوي للهيرو واليوريا. 2) كاروسيل سيلوليت ولا ليبوديما — اختبار تعليمي للهيرو الثاني. 3) UGC زبدة الشيا الأصلية. 4) Founder روتين جلد الوزة من البيت. قيّمي كل كرييتف كاختبار بعتبات Task D المعروفة قبل أي توسع، ولا Scale قبل بيانات.\nنتجنب: أي ادعاء طبي أو نتيجة نهائية أو ضمان 100% أو تخسيس أو إزالة السيلوليت — محظورة في الملف المعتمد، والويبسايت نفسه ينفي إزالة السيلوليت، والادعاءات المعتمدة فقط هي نعومة وترطيب من أول أسبوع وتحسّن تدريجي 4–8 أسابيع. ؛ هوكات الإحراج بأي صيغة — تخالف قواعد المالك وتضر بالثقة، والبديل هوك بصري Clue للمشكلة أو سؤال بحث حرفي محايد. ؛ تكرار طلبات التوليد المفتوحة أو نفس الزاوية/الهوك/الفورمات، وستاتيك بنفس اللياوت مع تغيير ديكور فقط — المالك يشترط لياوت مختلفاً فعلياً، والتشابه يضيع الاختبار. ؛ ذكر براند منافس أو اسم شخص في هوك/عنوان، ونسخ عرض Buy 1 Get 1 أو أي خصم غير مسجل لزيرا — عرض Melano مسجل عليه تناقض وعدم تحقق على صفحة المنتج، ولا عرض مسجل لزيرا. ؛ زحمة العناصر أسفل الستاتيك، والنص الطويل والحشو، وكلمة «سيستم» ومصطلح «العناية الموضعية» في كوبي العميل، وإسقاط الصابونة من روتين السيلوليت — الروتين 3 قطع دائماً (الصابونة + السكراب + الكريم)، واستخدمي «سكراب وكريم» في الكوبي.\nبيانات ناقصة بتضعف الخطة: رسوم Bosta الفعلية ونسب واتساب/التسليم الفعلية ونسبة التسليم الصافي — أرقام Break-even والمساهمة تقديرية بافتراضات السكربت. ؛ ميزانية الاختبار الأسبوعية وعدد الاختبارات المتاح — بدونها لا يمكن تحديد حجم الموجة أو سرعة الحكم. ؛ COGS باقي المنتجات (لوشن اليوريا وزبدة الشيا وغيرهما) — بدونها لا أولوية اقتصادية دقيقة خارج الهيروين. ؛ صوت عميل مسجل: اعتراضات ونتائج وتجارب فعلية — غيابه يجعل الهوكات مبنية على لغة بحث فقط. ؛ أي بيانات أداء لكرييتف سابق (المكتبة صفر) وحجم بحث فعلي لعبارات البحث — الاقتراحات لا تثبت حجم طلب أو نية شراء.','\n',char(10)),'الخطة موجة تكميلية اختبارية من مكتبة صفرية: ركّزي على الهيرو المزدوج في الشتا بزوايا بحث حرفية مختلفة وفورمات مختلفة، بلا تكرار للقائمة المفتوحة وبلا وعود طبية أو عروض مخترعة، واحكمي بالبيانات فقط — أي كرييتف بلا أرقام يبقى اختباراً، والتوسع بعد إثبات CPP مقابل هدف 160 والاقتصاديات الفعلية بعد تأكيد رسوم Bosta ونسب التسليم.','تنفيذ خطة الكرييتف «خطة كرييتف الشتا: الهيرو المزدوج أولاً — موجة تكميلية بلا تكرار»: 5 كرييتف مركّز بأولوياته وSpecs في طلبات التوليد (بانتظار اعتمادك) — راجِع الخطة واعتمدها أو عدّلها، والتنفيذ يبدأ بقرارك.',58,'بانتظار قرارك','',0,1795068316645);
INSERT INTO thinking_entries VALUES(19,'قبل أي صرف: اقتصاديات COD لسه تقديرية [EST] ومش قرار Scale/Kill','الملف الأساسي بتاريخ 2026-11-19 واللقطة المالية Dual Hero بتاريخ 2026-11-18: سعر الهيروين 799 وCOGS 350 مؤكد من المالك، لكن Break-even 275 والمساهمة 381/مُسلّم محسوبة بافتراضات افتراضية (تعبئة 20 / شحن 70 / مرتجع 50 / COD 2%) عند تسليم صافٍ 72% افتراضي، وWhatsApp%=0 وDelivery%=0، وموضوع 0 ومُسلّم 0 وRTO 0% وBreak-even ROAS 0، وحقول أساسية ممتلئة 3/7، وTarget CPP=160، وميزانية الاختبار الأسبوعية وCOGS باقي المنتجات لسه مش مدخلة.','لأن المُسلّم الفعلي 0 ونسب التسليم والواتساب الفعلية 0/غير مسجلة، إذن مفيش بيانات فعلية تثبت التسليم الصافي 72% ولا الـ381 ولا الـ275. ولأن رسوم Bosta الفعلية غير مؤكدة، إذن أي حساب Break-even مبني على 70 شحن و50 مرتجع ممكن يتغير كله. ولأن Target CPP=160 موجود بس من غير ميزانية اختبار أسبوعية مسجلة، إذن مش معروف أصلاً هنختبر بإيه. إذن القرار الصح دلوقتي مش Scale ولا Kill.','اقتصاديات الهيروين لسه [EST] ومش صالحة لقرار صرف، ولازم تتثبت بالأرقام الفعلية الأول.','قرار جمع بيانات واحد: اطلبي من المالك كتابةً رسوم Bosta الفعلية ونسب WhatsApp/Delivery الفعلية وميزانية الاختبار الأسبوعية، وسجليها في الملف وأعيدي حساب Break-even والمساهمة/مُسلّم، والقياس هو اكتمال الحقول دي وإعادة الحساب قبل أي قرار صرف — ومفيش Scale/Kill قبل Payday وبيانات فعلية.',30,'بانتظار قرارك','',0,1795110980538);
INSERT INTO thinking_entries VALUES(20,'بوابة AEO قبل أي كرييتف: موافقة المالك ومنع الادعاء الطبي أولاً','المعطيات بتاريخ 2026-11-19: تحليلات كرييتف أخيرة: لا تحليلات بعد، وتحليلات إعلانات منافسين مسجلة بصيغة مشروطة: اختبار محتوى استخدام زبدة الشيا للشفاه بعد موافقة المالك فقط، واختبار مقارنة سكراب الكافيين الجاهز مقابل المنزلي دون ادعاءات طبية، واختبار توضيح إن روتين KP الحالي يشمل منطقة البكيني دون ادعاء علاج طبي ودون منتج جديد، والأورجانيك 15 بوست مسجل و0 معتمد.','لأن مفيش تحليل كرييتف مسجل أصلاً، إذن مفيش دليل إن أي صياغة من دي اتجربت عند زيرا. ولأن الاختبارات المقترحة نفسها مشروطة بموافقة المالك وعدم الادعاء الطبي، إذن نشرها من غير البوابة دي يخالف الشرط المسجل نفسه. ولأن 0 بوست أورجانيك معتمد، إذن مفيش اعتماد مسجل يسمح بالنشر دلوقتي. إذن أي اختبار لازم يعدي من البوابة الأول.','مفيش كرييتف جاهز للنشر أو الاختبار لحد ما تتسجل الموافقة وقائمة الامتثال لكل قطعة.','قرار جمع بيانات/اعتماد واحد: جهزي قائمة تحقق AEO مكتوبة لكل قطعة مقترحة (موافقة المالك + لا ادعاء طبي + لا منتج جديد) واطلبي اعتمادها كتابةً قبل أي نشر، والقياس هو عدد القطع المجتازة للبوابة والمسجلة — ولو مفيش اعتماد، مفيش اختبار.',25,'بانتظار قرارك','',0,1795110980552);
INSERT INTO thinking_entries VALUES(21,'«مشكلتك ليها روتين» لوحدها مش تمييز قدام منافس بتركيز مطابق','الملف الأساسي بتاريخ 2026-11-19: عرض الهيرو «روتينات متكاملة لكل مشكلة بشرة/جسم — مشكلتك ليها روتين» وأكتر من 1000 عميلة طلبوا من زيرا كما هو معلن على الويبسايت، والمنتجات 23 والهيروين روتين السيلوليت وروتين جلد الوزة والفراولة بسعر 799، والمنافسون 33، وتنبيهات السوق: Meli-Godal منافس جديد بتركيز مطابق وU-Richi دخول منافس جديد، وتحليل مسجل لـ Clementine Organics: اختبري البيع حسب المشكلة مع تسمية المادة الفعالة بوضوح في العنوان والإعلان وقيسي أثره على التحويل مقارنة بالوصف العام، وتسجيل تبنّي لغة «الأصلية» و«الخام» لزبدة الشيا مع إثبات قابل للتحقق (المصدر/المواصفات).','لأن Meli-Godal مسجل بتركيز مطابق، إذن البيع حسب المشكلة لوحده مش فارق مسجل عن المنافس الجديد. ولأن التحليل المسجل بيقترح تسمية المادة الفعالة كاختبار قياس مش كحقيقة مثبتة، إذن مينفعش نعتبرها ميزة مؤكدة قبل ما تتقاس. ولأن لغة «الأصلية» و«الخام» مشروطة في التسجيل بإثبات قابل للتحقق (المصدر/المواصفات)، إذن استخدامها من غير الإثبات ده يبقى ادعاء مش هوية. إذن التمييز لازم يتبني على اختبار وإثبات، مش على شعار.','هوية «مشكلتك ليها روتين» محتاجة إثبات واختبار مسجل قبل ما تتقدم كميزة تنافسية، خصوصاً مع دخول منافس بتركيز مطابق.','قرار جمع بيانات واحد: اجمعي من المالك الإثبات القابل للتحقق لزبدة الشيا (المصدر/المواصفات) وحددي هيرو واحد بس — روتين السيلوليت — لاختبار عنوان يسمّي المادة الفعالة بوضوح مقابل الوصف العام، والقياس يتسجل بعد توفير ميزانية الاختبار ونسب التحويل الفعلية، ومفيش تعميم للغة «الأصلية/الخام» قبل تسجيل الإثبات.',30,'بانتظار قرارك','',0,1795110980564);
INSERT INTO thinking_entries VALUES(25,'تركيز التيست: 600 ج/يوم على جلد الوزة بس، والبيكسل يتأكد بشراء تجريبي قبل الأحد','قرار المالك بتاريخ 2026-11-19: ميزانية التيست 600 ج/يوم مركزة على روتين جلد الوزة فقط (السيلوليت مرحلة تانية). والبيكسل: المالك أكد 2026-11-19 إنه مربوط بأداة فيسبوك وشغال — التأكيد التجريبي باختبار شراء قبل إطلاق الأحد. وأهداف الريلونش المسجلة: هيرو السيلوليت مستهدف 0 ومحقق 0، وهيرو جلد الوزة مستهدف 0 ومحقق 0. والشغل: 45 عنصر (0 متأخر) · اعتمادات معلّقة: 1.','لأن الميزانية المسجلة مركزة على هيرو واحد والمستهدف والمحقق للهيروين 0 ← إذن تقسيم الـ600 ج على الهيروين هيشتّت التيست ويخلّي البيانات أضعف ← إذن لازم التيست يفضل مركز، ولأن تأكيد البيكسل من المالك لسه من غير تأكيد تجريبي ← إذن إطلاق الأحد من غير اختبار شراء هيخلي أي بيانات بعد كده مش موثوقة.','التيست الصح من المعطيات دي هو هيرو واحد بميزانية واحدة، بعد تأكيد تجريبي للبيكسل، مش إطلاق مزدوج من غير تحقق.','القرار المقترح: تنفيذ اختبار شراء واحد قبل إطلاق الأحد لتأكيد البيكسل عملياً، وتسجيل نتيجته (شغال/مش شغال) قبل ما يتصرف أي جنيه من الـ600 ج/يوم على جلد الوزة، والمالك هو اللي يقرر.',40,'معتمد','',51,1795119836347);
INSERT INTO thinking_entries VALUES(26,'اقتصاديات COD أولاً: تيست جلد الوزة 600 ج/يوم من غير Kill/Scale قبل Payday فعلي','الملف الأساسي 2026-11-19: قرار المالك ميزانية التيست 600 ج/يوم مركزة على روتين جلد الوزة فقط، والسيلوليت مرحلة تانية؛ سعر روتين جلد الوزة 799 وCOGS 350 مؤكد من المالك؛ Target CPP=160؛ Break-even (275) والمساهمة 381/مُسلّم محسوبة بافتراضات السكربت الافتراضية (تعبئة 20 / شحن 70 / مرتجع 50 / COD ‏2%) عند تسليم صافٍ 72% افتراضي، ورسوم Bosta الفعلية لسه غير مؤكدة؛ اللقطة المالية Dual Hero [EST] 2026-11-18: موضوع 0، مُسلّم 0، RTO 0%، Break-even ROAS 0؛ WhatsApp% وDelivery% مسجلة 0 ولسه الفعلية على المالك (API بوسطه)؛ البيكسل مؤكد من المالك 2026-11-19 إنه مربوط وشغال، والتأكيد التجريبي باختبار شراء قبل إطلاق الأحد.','لأن كل أرقام الربحية الحالية [EST] ومبنية على افتراضات مش على رسوم Bosta فعلية ولا نسب تسليم فعلية، ولأن موضوع ومُسلّم لسه 0 فمفيش CPP فعلي يتقارن بـ160 ولا بـ275، إذن أي حكم Kill/Scale دلوقتي هيبقى تخمين مش قرار؛ إذن الأولوية تجميع البيانات الفعلية وتثبيت التيست زي ما المالك قرر من غير تشتيت على السيلوليت.','التيست مينفعش يتقيم اقتصادياً لحد ما تتسجل رسوم Bosta الفعلية ونسب التسليم الفعلية وأول طلبات فعلية في Payday.','قبل إطلاق الأحد: اطلبي من المالك رسوم Bosta الفعلية ونسب WhatsApp/Delivery الفعلية مكتوبة، ونفّذي اختبار الشراء لتأكيد البيكسل وسجّلي نتيجته، وخلّي صرف الـ600 ج/يوم على جلد الوزة بس، وما يتاخدش قرار Kill/Scale إلا بعد تسجيل أول أرقام فعلية موضوع/مُسلّم في Payday.',30,'معتمد','',50,1795123415092);
INSERT INTO thinking_entries VALUES(27,'بوابة AEO: اختبار صياغة «عند النساء» في صفحة جلد الوزة بس من غير ادعاء طبي','المعطيات المسجلة: اختبر صياغة «عند النساء» في محتوى البحث والأسئلة الشائعة وعناوين صفحات زيرا ذات الصلة، دون ادعاء علاج طبي؛ والملف الأساسي 2026-11-19: هيرو التيست الحالي هو روتين جلد الوزة والفراولة (799 / COGS 350)، وحقول أساسية ممتلئة 4/7؛ ولا توجد تحليلات كرييتف مسجلة بعد، ولا أرقام بحث/زيارات فعلية مسجلة في المعطيات.','لأن الصياغة دي مقترحة للبحث والـFAQ بس مش مثبت تأثيرها عند زيرا، ولأن مفيش بيانات بحث فعلية ولا تحليلات كرييتف تقول إنها بتجيب نتيجة، إذن تعميمها على كل الصفحات هيبقى مخاطرة من غير قياس؛ إذن اختبارها محدود على هيرو التيست الحالي وبصياغة ملتزمة من غير ادعاء طبي هو الطريق الآمن.','صياغة «عند النساء» لسه فرضية اختبار مش قاعدة معممة، ولازم تتقاس على صفحة واحدة قبل أي تعميم.','عدّلي عنوان وFAQ صفحة روتين جلد الوزة بس بصياغة «عند النساء» من غير أي ادعاء علاج طبي، وسجّلي تاريخ التعديل وأي أسئلة/زيارات بتيجي بعدها لو اتوفرت من المالك، ولو مفيش بيانات قياس يبقى النتيجة جمع بيانات مش تعميم.',35,'مرفوض','',0,1795123415107);
INSERT INTO thinking_entries VALUES(28,'وضوح السعر النهائي: اعرضي روتين جلد الوزة 799 كسعر نهائي معلن بدل خصم عام','تحليل إعلانات منافسين مسجل: Joviality اختبر عرضاً موسمياً بعنوان خصم واضح وسقف محدد، مع باندلات بسعر نهائي معلن بدل خصم عام فقط؛ الملف الأساسي 2026-11-19: سعر روتين جلد الوزة 799 وCOGS 350 مؤكد، وTarget CPP=160، وميزانية التيست 600 ج/يوم على جلد الوزة فقط؛ تنبيهات سوق أخيرة مسجلة: Meli-Godal منافس جديد بتركيز مطابق وU-Richi دخول منافس جديد، والمنافسون المسجلون 33؛ ولا توجد تحليلات كرييتف لزيرا بعد.','لأن اللي اتسجل عن Joviality هو إن السعر النهائي المعلن كان بديل للخصم العام، ولأن سعر زيرا النهائي المسجل فعلاً هو 799 من غير نسبة خصم مسجلة، إذن اختراع خصم أو سقف مش مسجل هيبقى هلوسة؛ إذن الاختبار الصح هو وضوح الـ799 كسعر نهائي للروتين المتكامل في إعلان التيست وقياس CPP الفعلي ضده.','وضوح السعر النهائي 799 فرضية مستعارة من منافس مش نتيجة مثبتة عند زيرا، ولازم تتقاس بـCPP فعلي قبل أي Scale.','في إعلان تيست جلد الوزة بس، اكتبي الروتين بسعره النهائي المعلن 799 من غير خصم عام مخترع، وقيسي CPP الفعلي مقابل Target CPP 160 المسجل، ولو لسه مفيش CPP فعلي يبقى القرار جمع بيانات مش Scale.',40,'بانتظار قرارك','',0,1795123415119);
INSERT INTO thinking_entries VALUES(29,'هوية البراند: ركّزي «مشكلتك ليها روتين» على جلد الوزة لحد ما الأورجانيك يتحسم','الملف الأساسي 2026-11-19: عرض الهيرو «روتينات متكاملة لكل مشكلة بشرة/جسم — مشكلتك ليها روتين» وأكتر من 1000 عميلة طلبوا من زيرا (كما هو معلن على الويبسايت)؛ الأورجانيك: 15 بوست مسجل و0 معتمد؛ الشغل: 45 عنصر و0 متأخر واعتماد واحد معلّق؛ قرار المالك 2026-11-19: التيست المدفوع 600 ج/يوم على جلد الوزة فقط والسيلوليت مرحلة تانية.','لأن الأورجانيك المسجل 0 معتمد من 15، ولأن المدفوع مركز على جلد الوزة بس بقرار مالك، إذن تشتيت الأورجانيك بين الهيروين هيضعّف الرسالة وهيخلّي القياس مش واضح؛ إذن تركيز الهوية على هيرو التيست لحد حسم الاعتماد المعلق هو اللي يخلي البراند والمدفوع ماشيين في نفس الاتجاه.','هوية «مشكلتك ليها روتين» لسه محتاجة حسم اعتماد قبل التوسع، والتركيز على جلد الوزة هو اللي يطابق قرار التيست المدفوع.','اطلبي حسم الاعتماد الواحد المعلق، وقدّمي بوست واحد من الـ15 المسجلة عن روتين جلد الوزة بس بصيغة «مشكلتك ليها روتين» من غير ادعاء طبي، وسجّلي اتقبل ولا اترفض وسببه لو اتسجل، وما تعمّميش على السيلوليت لحد ما يخلص تيست جلد الوزة.',35,'معتمد','',48,1795123415131);
INSERT INTO thinking_entries VALUES(30,'اقتصاديات COD الأول: تيست جلد الوزة بـ600 ج/يوم من غير Kill/Scale قبل البيانات الفعلية','المصدر: الملف الأساسي بتاريخ 2026-11-19: Target CPP = 160، وميزانية التيست بقرار المالك 2026-11-19 هي 600 ج/يوم مركزة على روتين جلد الوزة فقط، والسيلوليت مرحلة تانية. المنتجات المسجلة: روتين جلد الوزة والفراولة سعره 799 وCOGS بتاعه 350 EGP مؤكد من المالك. آخر لقطة مالية Dual Hero — اقتصاديات وحدة محسوبة [EST] بتاريخ 2026-11-18: موضوع 0، مُسلّم 0، مساهمة/مُسلّم 381، Break-even ROAS 0، RTO 0%. رايات عدم يقين في نفس الملف: Break-even (275) والمساهمة (381/مُسلّم) محسوبة بافتراضات السكربت الافتراضية (تعبئة 20 / شحن 70 / مرتجع 50 / COD 2%) عند تسليم صافٍ 72% افتراضي، ورسوم Bosta الفعلية لسه غير مؤكدة، ونسب WhatsApp/Delivery الفعلية = 0 في التسجيل ولسه على المالك (API بوسطه). البيكسل: المالك أكد 2026-11-19 إنه مربوط بأداة فيسبوك وشغال، والتأكيد التجريبي باختبار شراء قبل إطلاق الأحد.','لأن كل أرقام الربحية لحد دلوقتي [EST] ومبنية على افتراضات مش على تسليم فعلي، ولأن موضوع 0 ومُسلّم 0 في لقطة 2026-11-18، ولأن WhatsApp%=0 وDelivery%=0 في التسجيل، إذن مفيش أساس فعلي نقارن بيه CPP الفعلي بـ Target CPP 160 ولا بـ Break-even 275 [EST]، وإذن أي قرار Kill/Scale دلوقتي هيكون تخمين مش قرار.','مفيش تقييم ولا توسع ولا إيقاف للتيست قبل ما تتجمع البيانات الفعلية: رسوم Bosta، ونسب WhatsApp/Delivery، وCPP والتسليم الفعلي بعد اختبار الشراء، وبعد Payday.','جمع بيانات بس قبل أي قرار تنفيذي: نفّذي اختبار شراء تجريبي قبل إطلاق الأحد لتأكيد البيكسل، واطلبي من المالك رسوم Bosta الفعلية ونسب WhatsApp/Delivery الفعلية، وشغّلي التيست 600 ج/يوم على روتين جلد الوزة فقط، وسجّلي CPP الفعلي ومعدل التسليم الفعلي لمقارنتهما بـ Target CPP 160 وBreak-even 275 [EST] بعد Payday والبيانات الفعلية.',30,'معتمد','',47,1795130898212);
INSERT INTO thinking_entries VALUES(31,'AEO يوريا: اختبري «كريم يوريا للجسم» 25% من غير ادعاء طبي ومن غير ذكر ماركات','المصدر: من التسجيل: اختبر محتوى AEO بعنوان/سؤال «كريم يوريا للجسم» يذكر يوريا 25% والاستخدام للجسم بوضوح، دون ادعاء طبي ودون ذكر أي ماركة — والتسجيل هنا مقطوع/غير مكتمل في آخر الجملة، فالقائمة الكاملة للماركات ناقصة. ومن نفس التسجيل: اختبر محتوى AEO يجيب عن أسئلة البحث المسجلة بلغة المستخدمين، دون ادعاءات طبية ودون تقديم زيرا كمنتج عشبي. أليجون منافس متتبَّع مذكور صراحة، وظهر أيضاً Mixa وEveline في اقتراحات البحث المسجلة. تحليلات كرييتف أخيرة: لا تحليلات بعد، والأورجانيك: 15 بوست مسجل (0 معتمد).','لأن السؤال المسجل محدد («كريم يوريا للجسم») والتركيز المطلوب يوريا 25% للجسم، ولأن بوابة الامتثال واضحة: من غير ادعاء طبي ومن غير تقديم زيرا كمنتج عشبي، ولأن التسجيل مقطوع في جزء «دون ذكر أي ماركة من...» إذن الأسلم من غير ما أخترع قائمة: ما نذكرش أي ماركة منافسة خالص في المحتوى ده لحد ما يتأكد الجزء الناقص، وإذن الاختبار لازم يكون محتوى واحد ملتزم بالبوابات دي وبس.','محتوى AEO واحد عن يوريا 25% للجسم بلغة المستخدمين يقدر يتختبر، لكن أداؤه لسه غير معروف لأن مفيش تحليلات كرييتف بعد و0 بوست معتمد من 15 بوست مسجل.','جهّزي واختبري بوست AEO واحد بس بعنوان/سؤال «كريم يوريا للجسم» يذكر يوريا 25% والاستخدام للجسم بوضوح، من غير ادعاء طبي ومن غير تقديم زيرا كمنتج عشبي ومن غير ذكر أي ماركة منافسة خالص، وسجّلي اعتماده أو عدم اعتماده ونتيجته المسجلة قبل أي تعميم.',35,'مرفوض','',0,1795130898225);
INSERT INTO thinking_entries VALUES(32,'بوابة امتثال: الليبوديما مش مسار منتج ولا لغة طبية في الكوبي','المصدر: من التسجيل: تجنب: لا تُحوَّل «سيلوليت و ليبوديما» إلى مسار منتج أو عرض، ولا تُستخدم لغة طبية/مرضية في الكوبي. وتجنب: لا يُدَّعى تشخيص؛ وتجنب تحويل الليبوديما إلى مسار منتج أو تموضع لزيرا، وتجنب اللغة الطبية/المرضية في الكوبي. وأي محتوى توعوي يفرّق بين السيل... — والتسجيل مقطوع هنا، فباقي الجملة ناقص. الهيروات المسجلة بس هما روتين السيلوليت وروتين جلد الوزة والفراولة.','لأن التحذير متكرر في التسجيل بصيغ مختلفة، ولأن الليبوديما مذكورة كموضوع تجنب مش كهيرو — والهيروات المسجلة بس هما روتين السيلوليت وروتين جلد الوزة والفراولة — إذن أي كوبي يربط الليبوديما بعرض أو بتشخيص هيخالف بوابة الامتثال، وإذن الفكرة دي لازم تفضل «ممنوع» مش «فرصة اختبار».','مفيش عرض ولا تموضع ولا محتوى يحوّل الليبوديما لمسار منتج لزيرا، وأي محتوى توعوي عن الفرق لازم يفضل واقف لحد ما يتأكد نص التسجيل المقطوع.','راجعي الكوبي الحالي والمقترح مرة واحدة على قاعدة واحدة قابلة للقياس: صفر جملة تربط الليبوديما بعرض أو منتج أو تشخيص، وصفر لغة طبية/مرضية، ولو لقيتي جملة مخالفة شيليها قبل الاعتماد، وسجّلي نتيجة المراجعة.',45,'مرفوض','',0,1795130898237);
INSERT INTO thinking_entries VALUES(33,'هوية التيست: هيرو واحد بس — جلد الوزة — والسيلوليت مرحلة تانية','المصدر: الملف الأساسي بتاريخ 2026-11-19: عرض الهيرو «روتينات متكاملة لكل مشكلة بشرة/جسم — «مشكلتك ليها روتين» · أكتر من 1000 عميلة طلبوا من زيرا (كما هو معلن على الويبسايت)». قرار المالك 2026-11-19: ميزانية التيست 600 ج/يوم مركزة على روتين جلد الوزة فقط، والسيلوليت مرحلة تانية. أهداف الريلونش: هيرو السيلوليت مستهدف 0 ومحقق 0، وهيرو جلد الوزة مستهدف 0 ومحقق 0. المنافسون المسجلون 33، وتنبيهات سوق أخيرة: Meli-Godal منافس جديد بتركيز مطابق، وU-Richi دخول منافس جديد، وAlejon منتج جديد، وMelano Pharma — Uremel عرض جديد. تابع أولاً من التسجيل: متابعة من هو ضياء العوضي وما المحتوى الذي يحرّك البحث قبل أي قرار، دون افتراض أنه منافس أو شريك.','لأن قرار المالك في 2026-11-19 حسم التركيز على هيرو واحد، ولأن أهداف الريلونش لسه 0 و0 للهيروين، ولأن فيه منافسين جدد بتركيز مطابق ودخول جديد مسجل، ولأن ضياء العوضي لسه غير معروف هو منافس ولا شريك حسب التسجيل، إذن تشتيت التيست على الهيروين أو ربط هوية زيرا باسم جديد قبل التتبع هيضيّع تركيز «مشكلتك ليها روتين» وهيخلي التقييم مش قابل للقياس، وإذن الثبات على هيرو واحد هو الصح دلوقتي.','هوية التيست تفضل: جلد الوزة والفراولة بس، والسيلوليت يستنى مرحلته التانية، ومن غير أي ربط بضياء العوضي ولا بأي منافس جديد قبل ما يتجمع عنه بيانات.','التزمي بتيست روتين جلد الوزة والفراولة فقط بميزانية 600 ج/يوم، وسجّلي في نفس ملف التيست إن السيلوليت مرحلة تانية وإن أي ربط بضياء العوضي مؤجل لحد ما تتجمع بيانات التتبع عنه: مين هو وإيه المحتوى اللي بيحرّك البحث، من غير افتراض إنه منافس أو شريك.',40,'معتمد','',46,1795130898258);
INSERT INTO thinking_entries VALUES(41,'هوك السيلوليت للنساء صراحةً يتختبر في مرحلته — من غير ادعاء طبي','من التسجيل (من غير تاريخ محدد في المعطيات): اختبري الهوك بصياغة البحث المسجلة حرفياً «علاج السيلوليت عند النساء» موجهاً للنساء صراحةً مقابل صياغة محايدة، دون ادعاءات؛ وتبنَّ مخاطبة النساء صراحة في هوك زيرا عند الحديث عن السيلوليت باستخدام لغة البحث المسجلة دون ادعاء طبي؛ وتحليلات كرييتف أخيرة: لا تحليلات بعد.','لأن الصياغة المسجلة حرفياً موجودة كفرضية اختبار مش كنتيجة، ولأن مفيش تحليلات كرييتف بعد تثبت إنها بتكسب ← إذن مينفعش نعمّمها كهوية ثابتة، ← إذن لازم تتختبر A/B في مرحلة السيلوليت التانية بس.','الهوك النسائي الصريح فرضية اختبار مؤجلة لمرحلة السيلوليت، مش قرار هوية نهائي.','جمع بيانات: لما توصل مرحلة السيلوليت التانية، اختبري هوك «علاج السيلوليت عند النساء» مقابل هوك محايد على نفس الروتين (799)، وقيسي الفرق في التحويل من غير أي ادعاء طبي، ومتعمّميش الصياغة قبل النتيجة.',35,'معتمد','',49,1795138016527);
INSERT INTO thinking_entries VALUES(46,'بوابة AEO: متنتجيش كرييتف Tetavara وزبدة الشيا قبل مسحين وموافقة المالك','تحليلات إعلانات منافسين أخيرة: غير محدد من التسجيل: تابعي ثبات «زبدة الشيا الاصلية» في المسحات التالية قبل أي استنتاج، وما تبنيش قرار محتوى أو منتج على مسح واحد (05:50 EET)؛ واقتراح Tetavara المسجل: اختبري إبراز قيمة روتين زيرا (يوريا 25% + سكراب + كريم) من غير ذكر منافس بالاسم ومن غير ادعاء طبي؛ وغير محدد من التسجيل: ما تتخذيش أي قرار محتوى/إنتاج قبل تأكيد ظهور الاقتراح في المسحين التاليين والحصول على موافقة المالك؛ وتحليلات كرييتف أخيرة: لا تحليلات بعد؛ والأورجانيك بتاريخ 2026-11-20: 15 بوست مسجل (0 معتمد).','لأن الاقتراح لسه مش مؤكد في المسحين التاليين وموافقة المالك لسه ناقصة، ولأن مفيش تحليلات كرييتف بعد و0 بوست معتمد من 15، إذن تنفيذ كرييتف دلوقتي هيكسر بوابة الامتثال AEO، ولأن المسح الواحد لوحده مش كفاية حسب التسجيل، إذن لازم التأكيد يتسجل الأول.','اقتراح Tetavara و«زبدة الشيا الأصلية» لسه اقتراحات تحت التأكيد، مش قرار محتوى جاهز للتنفيذ.','قرار تجميع بيانات واحد: استني المسحين الجايين وسجّلي هل ظهر الاقتراح و«زبدة الشيا الأصلية» بثبات ولا لأ، واطلبي موافقة المالك قبل أي إنتاج، وما تنفذيش الكرييتف قبل التأكيدين دول.',25,'بانتظار قرارك','',0,1795148589756);
INSERT INTO thinking_entries VALUES(51,'هوية «مشكلتك ليها روتين» — اختبار زاوية 3 قطع من غير ادعاء طبي','المصدر: تحليلات إعلانات منافسين أخيرة المسجلة في الملف بتاريخ 2026-11-20 (05:50 EET). المقترح المسجل: اختبار زاوية «روتين 3 قطع + يوريا/ريتينول» كبديل قابل للاختبار مقابل المنتج المفرد، من غير ادعاء نتيجة طبية أو زمنية محددة، واختبار لغة «الأصلية» والشفافية حول مصدر/جودة زبدة الشيا كمكوّن في روتين KP، من غير ادعاءات طبية. والملف بيحذر: تابعي ثبات «زبدة الشيا الاصلية» في المسحات التالية قبل أي استنتاج، ولا تبني قرار محتوى أو منتج على مسح واحد. Shaan: تتبع منتج اليوريا 30% الحي في الجولات القادمة من حيث السعر والحجم والتوافر، قبل أي قرار إنتاج أو محتوى، وبموافقة المالك. Zynah تحمل 4 منتجات سيلوليت مسجلة: Hathor Organics وMeraki وAreej وBel Clinic، والبروفايل المطابق المسجل هو Norshek (تشابه 46/100) وليس مسجلاً له منتج سيلوليت. تحليلات الكرييتف الأخيرة: لا تحليلات بعد.','لأن مفيش تحليلات كرييتف بعد، ولأن اقتراح زاوية الروتين 3 قطع وزبدة الشيا الأصلية مبني على مسح واحد بس والملف نفسه بيحذر من البناء على مسح واحد، ولأن منتج يوريا 30% عند Shaan لسه محتاج تتبع قبل أي قرار إنتاج أو محتوى وبموافقة المالك، إذن مفيش أساس نثبت بيه إن الزاوية دي هي هوية البراند أو إنها هتتفوق على المنتج المفرد، إذن الصح نختبرها كفرضية صغيرة قابلة للقياس من غير ادعاء طبي أو زمني.','زاوية الروتين 3 قطع وزبدة الشيا الأصلية فرضية اختبار مش هوية مثبتة، ولازم تتختبر بشفافية ومن غير ادعاء طبي أو زمني، ومفيش قرار محتوى أو منتج مبني عليها من مسح واحد.','اختبري في محتوى زيرا زاوية «روتين 3 قطع + يوريا/ريتينول» مقابل المنتج المفرد، ضمن تيست روتين جلد الوزة بس، بصياغة شفافة عن زبدة الشيا الأصلية من غير ادعاء طبي أو زمني محدد، وسجّلي النتيجة قبل أي قرار محتوى أو منتج، وبموافقة المالك.',30,'بانتظار قرارك','',0,1795152145161);
INSERT INTO thinking_entries VALUES(55,'منافسين: Meraki ويوريا 30% مراقبة وتتبع بس — مفيش رد سعري ولا محتوى دلوقتي','تنبيهات سوق أخيرة بتاريخ 2026-11-20: Zynah — قناة توزيع (Meraki Cellulite Buster Cream عبر القناة): منتج ظهر حديثاً (تاريخ الإدراج غير مؤكد)؛ Hepta Skin: عرض/سعر جديد؛ Centevia: تغير سعري/عرضي؛ Soralone: تغيّر سعري؛ U-Richi: قناة/توفر؛ Mazora: توفر؛ Estiara: توفر؛ Haven: متجر غير متاح. وتحليل Shaan المسجل: تتبع ظهور منتجات يوريا 30% في الجولات القادمة ومراجعة تموضع الـ25% أمام المالك قبل أي قرار، ولا قرار إنتاج/محتوى من غير موافقة المالك. والمنافسون المسجلون: 33.','لأن تنبيه Meraki بيقول «ظهر حديثاً» بس وتاريخ الإدراج غير مؤكد ومفيش سعر ولا حجم ولا توافر في المعطيات ← إذن مينفعش نستنتج تهديد سعري ولا نرد عليه. ولأن تعليم Shaan المسجل صريح: تتبع يوريا 30% ومراجعة تموضع الـ25% أمام المالك قبل أي قرار ← إذن أي قرار دلوقتي هيخالف التسجيل. فالخطوة المنطقية تتبع موثق وبعدين عرض على المالك.','مفيش رد فعل سعري ولا محتوى ولا إنتاجي دلوقتي على Meraki ولا يوريا 30%، لأن مفيش سعر ولا حجم ولا توافر مسجل ليهم — الخطوة مراقبة وتتبع بس.','جمع بيانات بس في الجولة الجاية: يتسجل كتابة سعر وحجم وتوافر Meraki Cellulite Buster Cream ومنتج يوريا 30% الحي (Shaan)، ويتعرض الجدول ده على المالك قبل أي قرار إنتاج أو محتوى أو سعر — القياس: اكتمال جدول التتبع بالتلات خانات لكل منتج.',20,'بانتظار قرارك','',0,1795155706276);
INSERT INTO thinking_entries VALUES(63,'هوية الشيا في روتين KP: «الأصلية» لازم تتقال بصياغة قابلة للتحقق ومن غير ادعاءات طبية','تسجيل أخير (التاريخ غير مسجل في المعطيات): اختبري لزيرا رسالة أصالة/جودة الشيا في روتين KP بصياغة قابلة للتحقق دون ادعاءات طبية، واختبري لغة «الأصلية» والشفافية حول مصدر/جودة زبدة الشيا 75 جم كمكوّن في روتين KP دون مقارنة، واختبري صياغة «للبشرة» في وصف زبدة الشيا 75 جم الحالية ضمن روتين KP دون تقديمها كمنتج جديد؛ الأورجانيك 2026-11-20: 15 بوست مسجل و0 معتمد؛ الشغل: 51 عنصر واعتمادات معلّقة 2.','لأن مفيش تحليلات كرييتف بعد، و0 بوست معتمد من 15، ولأن ادعاء الأصالة من غير إثبات قابل للتحقق يعرّض هوية البراند للخطر ← إذن ماينفعش نعمّم لغة «الأصلية» على كل المحتوى، وإذن الاختبار لازم يكون في قطعة واحدة موثقة ومقيدة بالوصف الحالي للمنتج الحالي.','هوية الشيا محتاجة اختبار صياغة واحد قابل للتحقق، مش تعميم على كل المحتوى ولا منتج جديد.','جهّزي قطعة محتوى واحدة لروتين KP بصياغة «الأصلية» القابلة للتحقق مع «للبشرة» في وصف زبدة الشيا 75 جم الحالية، واطلبي اعتمادها كقطعة واحدة وسجّلي نتيجة الاعتماد — وقياس النجاح هو اعتماد/رفض موثق لقطعة واحدة، مش نشر جماعي.',30,'بانتظار قرارك','',0,1795170092317);
INSERT INTO thinking_entries VALUES(65,'بوابة AEO: اختبري «يوريا 30% مقابل 25%» بوصف بس — من غير ادعاء طبي ولا مقارنة ببراند','تحليلات إعلانات منافسين أخيرة — المصدر غير محدد من التسجيل: اختبار محتوى AEO يجيب عن نية «يوريا 30% مقابل 25%» و«كريم يوريا ٣٠ للجسم» بلغة وصفية دون ادعاء طبي أو مقارنة باسم براند، وتقوية الفرصة #1 القائمة (يوريا 30%) واختبارها، لأن «يوريا 40» دليل مستمر على طلب تركيز أعلى من 25% — دون فتح فرصة مكررة. وفي نفس التسجيل بتاريخ 2026-11-20: لا تحليلات كرييتف بعد، والأورجانيك 15 بوست مسجل (0 معتمد).','لأن النية المسجلة موجودة («يوريا 30% مقابل 25%» و«كريم يوريا ٣٠ للجسم») ولأن «يوريا 40» متسجل كدليل مستمر على طلب تركيز أعلى من 25%، إذن فيه فرصة AEO قائمة #1 تستاهل الاختبار من غير ما نفتح فرصة مكررة، ولأن الشرط المسجل صريح — لغة وصفية من غير ادعاء طبي ولا مقارنة باسم براند — إذن المحتوى لازم يلتزم بالحد ده بالظبط، ولأن مفيش تحليلات كرييتف بعد و0 بوست معتمد من 15، إذن الاختبار لازم يبقى قطعة واحدة قابلة للقياس مش حملة.','نختبر فرصة يوريا 30% القائمة بقطعة AEO واحدة وصفية وملتزمة، من غير فرصة مكررة ومن غير ادعاء طبي أو مقارنة ببراند.','اعملي قطعة AEO واحدة تجاوب على «يوريا 30% مقابل 25%» و«كريم يوريا ٣٠ للجسم» بلغة وصفية بس، من غير ادعاء طبي ومن غير ذكر أي براند منافس بالاسم، وسجّلي ظهورها ونقرها، واعتبري النتيجة تجريبية لحد ما تتجمع بيانات فعلية.',35,'بانتظار قرارك','',0,1795173701743);
INSERT INTO thinking_entries VALUES(66,'هوية البراند: «زبدة الشيا الخام» تتختبر حرفياً — و«لمسة حرير» تفضل مراقبة بس','تحليلات إعلانات منافسين أخيرة — المصدر غير محدد من التسجيل: اختبر استخدام عبارة «زبدة الشيا الخام» حرفياً في عنوان صفحة زيرا ووصفها، وقارن النقر والظهور قبل التغيير وبعده؛ واعتمدوا اسم «زبدة الشيا الخام» حرفياً في عنوان ووصف منتج زيرا 250 ج كما يكتبه الباحثون، واختبروا ظهوره، دون ادعاء منتج ج؛ واختبر قبل التبني: راقب «لمسة حرير» في مسحات جوجل التالية للتثبت قبل أي خطوة منتج أو محتوى. والملف الأساسي بتاريخ 2026-11-20: عرض الهيرو «مشكلتك ليها روتين» وأكتر من 1000 عميلة طلبوا من زيرا (كما هو معلن على الويبسايت).','لأن الصياغة المسجلة للباحثين هي «زبدة الشيا الخام» حرفياً، إذن الاختبار لازم يستخدم نفس اللفظ بالظبط مش صياغة قريبة منه، ولأن الشرط المسجل هو «دون ادعاء منتج ج»، إذن مينفعش ندّعي صفة مش متسجلة، ولأن «لمسة حرير» متسجلة كـ«اختبر قبل التبني» و«راقب في مسحات جوجل التالية»، إذن هي لسه مرحلة مراقبة مش تبني، وإذن القرار لازم يبقى اختبار واحد محسوب لـ«زبدة الشيا الخام» ومراقبة بس لـ«لمسة حرير».','نختبر «زبدة الشيا الخام» حرفياً في العنوان والوصف ونقيس قبل/بعد، ونسيب «لمسة حرير» في المراقبة بس لحد ما مسحات جوجل التالية تثبتها.','غيّري عنوان ووصف منتج زيرا 250 ج لاستخدام «زبدة الشيا الخام» حرفياً كما يكتبه الباحثون، من غير ادعاء منتج ج، وسجّلي النقر والظهور قبل التغيير وبعده للمقارنة، ومتاخديش أي خطوة منتج أو محتوى بـ«لمسة حرير» قبل ما تظهر وتتثبت في مسحات جوجل التالية.',35,'بانتظار قرارك','',0,1795173701763);
INSERT INTO thinking_entries VALUES(70,'متجريش ورا «يوريا ٣٠٪» و«سيلوليت جورجينا»: مسح واحد مش دليل','تحليلات إعلانات منافسين أخيرة بتاريخ 2026-11-20: اختبر ثبوت «يوريا ٣٠٪» بصيغتي الأرقام العربية (٣٠٪) واللاتينية (30%) في المسحات الجاية قبل أي خطوة، ولا تبنِ قرار محتوى أو استهداف على مسح واحد؛ ولا تبنِ حملة زيرا على ترند «سيلوليت جورجينا» — اسم مشهور قصير العمر وموته بعد مسح واحد متوقَّع حسب ملاحظة #86 — وراقب «سيلوليت جورجينا» و«سيلوليت رول امازون» في المسحات القادمة قبل أي إنفاق.','لأن التعليمات المسجلة نفسها بتقول إن الثبوت لسه محتاج مسحات جاية، وإن ترند جورجينا قصير العمر ومتوقع موته بعد مسح واحد ← إذن استخدامه في كرييتف التيست دلوقتي هيبقى بناء على مسح واحد مش على اتجاه ثابت، وإذن أي ادعاء أو استهداف مبني عليه هيخاطر ببوابة الامتثال AEO وبهوية البراند.','مفيش مبرر مسجل لاستخدام «يوريا ٣٠٪» أو «سيلوليت جورجينا» في التيست الحالي؛ الاتنين لسه تحت المراقبة مش فرص مؤكدة.','استبعدي «يوريا ٣٠٪» و«سيلوليت جورجينا» و«سيلوليت رول امازون» من كرييتف واستهداف تيست جلد الوزة، وسجلي في المسحات الجاية بس «ظهر/مظهرش» لكل صيغة وترند قبل أي قرار استخدام، والقياس: عدد مرات الظهور في المسحات الجاية مش انطباع واحد.',30,'مرفوض','',0,1795184798005);
INSERT INTO thinking_entries VALUES(72,'اقتصاديات COD لروتين جلد الوزة لسه تقديرية — من غير بيانات فعلية مفيش حكم','الملف الأساسي بتاريخ 2026-11-20: Break-even (275) والمساهمة (381/مُسلّم) محسوبة بافتراضات السكربت الافتراضية (تعبئة 20 / شحن 70 / مرتجع 50 / COD 2%) عند تسليم صافٍ 72% افتراضي، ورسوم Bosta الفعلية لسه غير مؤكدة، وWhatsApp%=0 وDelivery%=0 والفعلية لسه على المالك (API بوسطه). COGS الهيروين = 350 EGP من المالك (مؤكد)، وسعر روتين جلد الوزة 799. قرار المالك 2026-11-19: ميزانية التيست 600 ج/يوم مركزة على روتين جلد الوزة فقط، وTarget CPP=160. آخر لقطة مالية (Shopify daily sync — trailing 7 days to 2026-11-20، 2026-11-20): موضوع 3 · مُسلّم 0 · مساهمة/مُسلّم 0 · Break-even ROAS 0 · RTO 0%.','لأن Break-even 275 والمساهمة 381/مُسلّم مبنيين على افتراضات افتراضية مش على رسوم Bosta الفعلية، ولأن التسليم الصافي 72% افتراضي وWhatsApp/Delivery الفعلية ناقصة، ولأن آخر 7 أيام في Shopify مسجلة موضوع 3 ومُسلّم 0 ومساهمة/مُسلّم 0، إذن مفيش تكلفة فعلية ولا مساهمة فعلية نقيس عليها Target CPP=160 ولا ميزانية 600 ج/يوم، إذن لازم نجمع البيانات الفعلية الأول قبل أي حكم اقتصادي.','مفيش اقتصاديات COD فعلية نقدر نحكم عليها دلوقتي؛ كل الأرقام اللي عندنا تقديرية [EST] أو صفرية في التسليم، وأي قرار Kill/Scale دلوقتي هيبقى تخمين.','جمع بيانات مش قرار تنفيذي: قبل إطلاق الأحد المالك يجيب رسوم Bosta الفعلية ونسب WhatsApp/Delivery الفعلية من الـAPI، ونعمل اختبار شراء للتأكيد التجريبي إن البيكسل مربوط بأداة فيسبوك وشغال زي ما أكد المالك 2026-11-19، ونعيد حساب Break-even والمساهمة بالأرقام الفعلية، ومن غير أي قرار Kill/Scale قبل Payday والبيانات الفعلية.',30,'معتمد','',60,1795199074875);
INSERT INTO thinking_entries VALUES(80,'بوابة الامتثال AEO: يوريا 30% فرضية طلب مش قرار منتج، وبلا أي ادعاء طبي','تحليلات إعلانات منافسين أخيرة — غير محدد من التسجيل: راقبي في المسحات التالية طلب «كريم يوريا 30 للجسم» (فرصة #1) مقابل تركيز زيرا الحالي 25% قبل أي قرار منتج، وبدون ادعاءات؛ واختبري كفرضية طلب مسجلة محتوى أو عرضًا حول يوريا 30% مقارنة بنسبة 25% الحالية لزيرا، دون أي ادعاء طبي أو فعالية علاجية. ونفس المصدر: اختبري صيغة urea اللاتينية بجانب يوريا العربية في عناوين ووصف زيرا، ولا تعتبريها ميتة إلا بعد مسح أو اثنين للتأكيد؛ واختبري الصيغة اللاتينية «كريم urea للجسم» في عناوين البحث ووصف المنتج، لكن لا تعتمديها نهائيًا قبل مسح أو اثنين للتأكيد. تحليلات كرييتف أخيرة: لا تحليلات بعد.','لأن الطلب على يوريا 30% مسجل كفرصة للمراقبة مش كنتيجة مؤكدة، إذن مينفعش يتحول لمنتج أو ادعاء فعالية. ولأن الصيغة اللاتينية لسه محتاجة مسح أو اثنين للتأكيد كما ورد، إذن اعتبارها ميتة أو اعتمادها نهائي دلوقتي هيبقى استنتاج من مسح ناقص. ولأن مفيش تحليلات كرييتف بعد، إذن الاختبار لازم يبقى محتوى ووصف بس وبصياغة ملتزمة بدون ادعاءات.','الخطوة الصح اختبار لغوي ومحتوى محدود على جلد الوزة، مش تغيير منتج ولا ادعاء طبي ولا اعتماد نهائي للصيغة اللاتينية.','قرار مقترح واحد: جمع بيانات باختبار واحد قابل للقياس — ضيفي صيغة urea اللاتينية بجانب يوريا العربية في عنوان ووصف روتين جلد الوزة بس، مع إشارة محايدة لفرضية يوريا 30% مقابل 25% الحالية بدون أي ادعاء طبي أو علاجي، وسجّلي الأداء في المسح أو المسحين الجايين قبل أي اعتماد نهائي.',35,'مرفوض','',0,1795213483033);
INSERT INTO thinking_entries VALUES(81,'المرساة السعرية: ثبّتي سعر قبل/بعد واحد وقيسي، بدل تغيير السعر المتكرر','تحليلات إعلانات منافسين أخيرة — Soralone: اختبري لزيرا تثبيت مرساة سعرية واضحة (سعر قبل/بعد) لفترة محددة وقياس أثرها على التحويل بدل تغيير السعر المتكرر. الملف الأساسي 2026-11-20: سعر روتين جلد الوزة 799 وCOGS 350 مؤكد من المالك، وTarget CPP 160. قرار المالك 2026-11-19: ميزانية التيست 600 ج/يوم مركزة على روتين جلد الوزة فقط. آخر لقطة مالية Shopify daily sync بتاريخ 2026-11-20: موضوع 3، مُسلَّم 0.','لأن التوصية المسجلة من Soralone هي التثبيت والقياس مش التغيير المتكرر، إذن أي تغيير سعري جديد قبل القياس هيبوّظ الاختبار. ولأن السعر 799 والـCOGS 350 هما الثابتين المؤكدين الوحيدين في الملف، إذن المرساة لازم تتبني عليهم وسعر قبلها يتوثق من المالك مش يتخمن. ولأن آخر لقطة Shopify بتاريخ 2026-11-20 فيها 3 موضوع و0 مُسلَّم، إذن مفيش خط أساس تحويل فعلي كافي للحكم دلوقتي.','المرساة اختبار قياس مش قرار تسعير نهائي، وسعر قبلها لسه ناقص ولازم يتوثق من المالك قبل التثبيت.','قرار مقترح واحد: جمع بيانات — ثبّتي مرساة سعرية واحدة واضحة على روتين جلد الوزة بس، بسعر قبل موثّق من المالك وسعر بعد 799 المسجل، طول فترة تيست الـ600 ج/يوم، وسجّلي التحويل والطلبات المُسلَّمة الفعلية بدون أي تغيير سعري تاني، وأجّلي الحكم لـPayday والبيانات الفعلية.',30,'معتمد','',59,1795213483052);
INSERT INTO thinking_entries VALUES(84,'بوابة الامتثال AEO: صياغة واحدة ضيقة غير طبية عن الملمس — وقيسي الفهم قبل التوسع','تحليلات إعلانات منافسين أخيرة بتاريخ اللقطة 2026-11-20: Vee Allure (Veexia) وVeexia — Vee Allure Urea Hydro Cream 10%: اختبري لزيرا تموضعاً ضيقاً واحداً للملمس الخشن المتكتل بدلاً من ادعاءات عامة، بصياغة تجميلية عن المظهر والترطيب والملمس، وصياغة وصفية غير طبية حول مشكلة ملمس محددة (جفاف/خشونة/تكتل)، وقيسي فهم الجمهور واستجابته قبل التوسع. تحليلات كرييتف أخيرة: لا تحليلات بعد. الأورجانيك بتاريخ 2026-11-20: 15 بوست مسجل و0 معتمد، والشغل: 57 عنصر واعتمادات معلّقة 2.','لأن مفيش تحليلات كرييتف بعد و0 بوست أورجانيك معتمد من 15، إذن مفيش دليل فعلي إن الجمهور فاهم رسالة زيرا الحالية. ولأن تحليل إعلانات المنافسين المسجل بيقترح تموضعاً ضيقاً واحداً للملمس بصياغة وصفية غير طبية وقياس الفهم قبل التوسع، إذن الاختبار الآمن هو صياغة واحدة ضيقة والتزام ببوابة الامتثال دي، مش التعميم.','بوابة الامتثال قبل التوسع هي صياغة واحدة ضيقة غير طبية عن الملمس، ولازم تتقاس فهم الجمهور ليها الأول، لأن مفيش لسه أي تحليل كرييتف أو بوست معتمد يثبت إن الصياغة العامة الحالية مفهومة.','قرار مقترح واحد: جمع بيانات — اختبري صياغة واحدة ضيقة غير طبية لروتين جلد الوزة عن الملمس الخشن المتكتل (المظهر والترطيب والملمس) بدل الادعاءات العامة، وسجّلي فهم الجمهور واستجابته ليها، وما توسّعيش الصياغة دي ولا تعمّميها قبل ما تسجّلي النتيجة.',30,'معتمد','',58,1795217053110);
INSERT INTO competitor_ad_analyses VALUES(1,1,'غير محدد من التسجيل','لا زاوية إعلان مسجلة. مستنتج من المسجل فقط: هيكل كتالوج من 23 منتجًا منظّم كروتينات حسب المشكلة (سيلوليت، جلد الوزة، بشرة دهنية/جافة/باهتة، كيت الساحل) + مفردات، بمكونات معلنة: ملح سيوة، يوريا 25%، كافيين، ريتينول، زبدة شيا.','غير مسجل — لا يوجد هوك أو نص أو محتوى إعلان موصوف في التسجيل.','غير مسجل كإعلان — المادة المسجلة قراءة ويبسايت zyra-care.com (الكتالوج والسياسات) بتاريخ رصد 2026-11-18 ووسم VERIFIED، وليست فيديو أو صورة أو نص إعلان منافس موصوفًا.','مسجل كأسعار كتالوج فقط، لا كعرض إعلاني: روتينات 599 (بشرة دهنية/جافة/باهتة)، 799 (سيلوليت، جلد الوزة)، 1300 (كيت الساحل)؛ مفردات 360 (لوشن يوريا 25%)، 350 (كريم سيلوليت ريتينول/كافيين)، 390 (سكراب ملح سيوة). أي خصم أو شحن أو ضمان إعلاني غير مسجل.','غير مسجلة — المسجل فقط تاريخ الرصد 2026-11-18، ولا يوجد تاريخ بدء أو مدة تشغيل أو استمرارية مذكورة في التسجيل.','النجاح غير مسجل — لا توجد أرقام أداء أو مدة تشغيل في التسجيل فلا يمكن الجزم بأنه شغال. استنتاج محتمل فقط وقابل للاختبار: تنظيم الكتالوج حسب المشكلة مع تسعير واضح للروتين مقابل المفرد قد يقلل حيرة الاختيار ويسهّل المقارنة الداخلية.','الأوضح: المادة ليست إعلان منافس أصلًا — المصدر هو zyra-care.com ولا منافس مذكور صراحة، وبلا هوك أو محتوى إعلاني أو أداء، فأي استنتاج تنافسي مبني عليها غير مؤسس من التسجيل.',replace('تختبر زيرا: مدخل تسوّق حسب المشكلة مقابل مدخل حسب المنتج، بقياس التحويل، دون ادعاءات طبية أو وعود علاجية.\nتتبنى: إظهار المكوّن المعلن ونسبته كما هو مسجل (مثل يوريا 25% وملح سيوة) لرفع الوضوح، دون تحويله لادعاء فعالية طبية.\nتختبر: معمارية سعر الروتين (599/799/1300) مقابل المفردات (350-390) كاختبار لقيمة الباقة، لا كعرض منسوخ من منافس.\nتتجنب: تسمية قراءة موقع zyra-care.com إعلان منافس، أو عمل مقارنات باسم براند (AEO)، أو اختراع هوك أو مدة أو أداء غير مسجل.\nتختبر: تجميع كيت لاستخدام محدد (كيت الساحل 1300) كفكرة تجميع فقط، مع التحقق من الهامش والمخزون قبل التعميم.','\n',char(10)),1795040415721,'','','','');
INSERT INTO competitor_ad_analyses VALUES(2,2,'غير محدد من التسجيل','مسجل كسياق سوق لا كزاوية إعلان لمنافس محدد: سوق اليوريا/جلد الوزة مزدحم بتركيزات 10–20% وأسعار 149–439 EGP، والتمييز الموثق بالأرقام لزيرا هو تركيز 25% — الأعلى في المقارنة المرصودة — بسعر 360 EGP.','غير مسجل — لا يوجد نص هوك أو افتتاحية أو محتوى إعلان موصوف في التسجيل، فلا يمكن نسب أي هوك لمنافس.','غير مسجل — لا فورمات إعلان موصوف (فيديو/صورة/UGC أو غيره)؛ المصدر المسجل فقط هو صفحات منتجات المنافسين، ووسم الأدلة VERIFIED بتاريخ رصد 2026-11-18.','غير مسجل كعرض ترويجي — لا خصم أو حزمة أو شحن مذكور؛ المسجل فقط نطاق أسعار الفئة 149–439 EGP وسعر لوشن ZYRA ‏360 EGP.','غير مسجلة — لا تاريخ بدء ولا مدة تشغيل أو استمرارية مذكورة؛ التاريخ الوحيد المسجل هو تاريخ الرصد 2026-11-18.','غير مثبت من التسجيل: لا توجد أرقام أداء أو مدة تشغيل لإعلان محدد يمكن الحكم بنجاحه منها. المستنتج فقط أن المقارنة الرقمية القابلة للتحقق (25% مقابل نطاق 10–20% المرصود) واضحة وسهلة الفهم، وقد تساعد على التمييز في فئة مزدحمة — وهذا استنتاج وليس نتيجة مسجلة.','لا نقطة ضعف مسجلة لإعلان محدد لعدم وجود إعلان محدد. الفجوة الأوضح مستنتجة من المسجل: التفوق الرقمي وحده لا يحسم المنافسة لأن المنافسة الأقوى مسجلة في توزيع الصيدليات لا في الإعلان فقط، وسعر 360 EGP ليس الأرخص ضمن 149–439 EGP دون مبرر قيمة إضافي مسجل.',replace('اختبر: إبراز الرقم الموثق 25% في عنوان الإعلان/صفحة المنتج مقابل وصف عام للفئة، دون ذكر أسماء براندات ودون ادعاء طبي، وقارن النقر والتحويل بين النسختين.\nتبنَّ: مقارنة فئوية مجهولة المصدر بالأرقام فقط (نطاق السوق المرصود 10–20%) بدل المقارنة باسم منافس، مع الاحتفاظ بمصدر وتاريخ الرصد.\nاختبر: عرض السعر 360 EGP بشفافية مع اختبار رسائل تبرير القيمة بالتركيز الأعلى، بدل الدخول في منافسة سعرية نحو حد 149 EGP الأدنى دون دليل.\nتبنَّ واختبر: أولوية توزيع/توفر في الصيدليات بالتوازي مع الإعلان، لأن المنافسة الأقوى مسجلة كقناة توزيع؛ قِس التوفر والطلب قبل زيادة الإنفاق الإعلاني.\nتجنب: نسخ زوايا الفئة المزدحمة أو ادعاءات علاجية/نتائج لجلد الوزة غير موثقة في التسجيل، وتجنب ادعاء نجاح أي زاوية قبل اختبارها ببيانات أداء فعلية.','\n',char(10)),1795040444453,'','','','');
INSERT INTO competitor_ad_analyses VALUES(3,3,'غير محدد من التسجيل','مستنتجة من لغة البحث المسجلة وليست زاوية إعلان منافس موصوفة: الثقة/الأصالة — التمييز بين «زبدة الشيا الاصلية» والمقلدة، كما ورد في تفاصيل الرصد أنها زاوية يمكن توظيفها في محتوى زبدة الشيا.','غير مسجل — لا يوجد هوك أو نص إعلان موصوف؛ العبارة الوحيدة المسجلة هي اقتراح البحث نفسه: «زبدة الشيا الاصلية».','غير مسجل كفورمات إعلان — المسجل فقط اقتراح بحث في Google Egypt Autocomplete (المصدر: suggestqueries.google.com، hl=ar، gl=eg) ضمن قائمة 10 اقتراحات للكلمة المتبعة «زبدة الشيا».','غير مسجل — لا سعر ولا خصم ولا منتج معروض ولا عرض ولا CTA مذكور في التسجيل.','غير مسجلة — لا تاريخ بدء إعلان ولا مدة تشغيل/استمرارية مذكورة؛ المسجل فقط أول ظهور للاقتراح في مسح 2026-11-18 23:10 EET.','غير مثبت كنجاح إعلاني من التسجيل — لا توجد أرقام أداء أو مبيعات مسجلة أصلاً لأنه ليس إعلاناً موصوفاً. المستنتج فقط: دخول الصياغة قائمة الاقتراحات العشرة وحلولها محل «زبدة الشيا للبشرة» في مسح 2026-11-18 يشير على الأرجح إلى نية بحث مرتبطة بالتحقق من الأصالة والثقة، وهي تصلح فرضية محتوى قابلة للاختبار لا دليل نجاح.','الأوضح: إشارة لقطة واحدة بلا حجم بحث ولا استمرارية ولا منافس ولا عرض ولا آلية إثبات أصالة مسجلة، فلا تكفي وحدها لبناء ادعاء أصالة أو قرار منتج/حملة؛ والتسجيل نفسه ينفي كونها منتجاً جديداً غائباً عن زيرا.',replace('اختبر ولا تتبنَّ نهائياً بعد: عنوان/قسم أسئلة بصياغة البحث المسجلة «زبدة الشيا الاصلية» مقابل عنوان عام عن زبدة الشيا، وقارن الظهور والنقرات من بحث Google قبل التعميم.\nتبنَّ: محتوى إثبات أصالة على شكل Checklist للتحقق قبل الشراء، يعتمد فقط على حقائق موثقة لدى زيرا (مثل قائمة المكونات وبيانات المصدر/الدفعة والتغليف إن كانت موثقة داخلياً) — دون اختراع مواصفات غير مسجلة.\nتجنب: الادعاءات الطبية/العلاجية، والمقارنات باسم أي براند، ووصف منتجات أخرى بأنها مقلدة دون دليل، وإنشاء فرصة منتج جديد؛ فالتسجيل يؤكد أن زبدة الشيا مكوّن موجود أصلاً لدى زيرا.\nاختبر الاستمرارية قبل التوسع: أعد رصد اقتراحات «زبدة الشيا» في مسوح لاحقة بنفس إعدادات مصر (hl=ar، gl=eg)، ولا توسّع المحتوى إلا إذا تكرر بقاء الاقتراح ضمن العشرة، لأن الرصد الحالي لقطة واحدة.\nاختبر رسالتين دون نسخ أعمى: نسخة تعليمية (كيف تتحققين من الأصالة) مقابل نسخة ثقة بالأدلة الموثقة لدى زيرا، وقارن التفاعل/التحويل المسجل فعلياً قبل اعتماد أيهما.','\n',char(10)),1795040473717,'','','','');
INSERT INTO competitor_ad_analyses VALUES(4,13,'غير محدد من التسجيل','غير مسجلة كزاوية إعلان — المسجل فقط إشارة لغة بحث: التمييز بين الأصلي والمقلّد لـ«زبدة الشيا»، وهي صفة أصالة على منتج/مكوّن موجود أصلاً (مكوّن في منتجات زيرا)، وليست منتجاً أو مشكلة جديدة.','غير مسجل — لا يوجد نص أو صورة أو هوك إعلاني موصوف في التسجيل؛ العبارة المسجلة الوحيدة هي اقتراح البحث نفسه «زبدة الشيا الاصلية».','غير مسجل كفورمات إعلان — المصدر اقتراح Google Egypt Autocomplete (suggestqueries.google.com, hl=ar, gl=eg، وسم SEARCH_LANGUAGE) ظهر تحت الكلمة المفتاحية «زبدة الشيا» في المركز 9 من 10.','غير مسجل — لا سعر أو خصم أو ضمان أو أي عرض مذكور في التسجيل.','غير مسجلة — لا مدة تشغيل إعلان مذكورة؛ المسجل فقط أول ظهور للاقتراح في 2026-11-19 00:29 EET، وعدم وجوده في لقطة 2026-11-18 22:10 UTC، ضمن مسح دوري كل 20 دقيقة وتاريخ رصد 2026-11-19.','نجاح إعلاني غير مسجل — لا أرقام أداء أو مبيعات أو محتوى إعلان في التسجيل. كإشارة طلب فقط، دخول صفة «الاصلية» إلى اقتراحات البحث يوحي على الأرجح باهتمام الباحثين بالتحقق من الأصالة قبل الشراء، لا بإثبات نجاح إعلان منافس.','أوضح ضعف/حدّ: إشارة وحيدة عند أول ظهور وفي مركز متأخر (9 من 10)، بلا منافس أو محتوى إعلان أو عرض مسجل، وباقي الكلمات الـ11 بلا اقتراحات جديدة تماماً — فلا تكفي لإثبات طلب واسع أو تفوق منافس.',replace('اختبر: قسم أسئلة شائعة/محتوى بعنوان يطابق لغة البحث «زبدة الشيا الاصلية» يشرح علامات تحقق قابلة للفحص لمنتج زيرا (قائمة المكونات والمصدر الموثقان)، وقِس الدخول والنقرات قبل التوسع.\nتبنّى: إبراز أدلة أصالة زيرا نفسها (مصدر المكوّن، بيانات التشغيلة، قنوات الشراء الرسمية) دون مقارنات باسم أي براند ودون ادعاءات طبية.\nتجنّب: اعتبار الإشارة فرصة منتج جديد أو إطلاق منتج منفصل — التسجيل ينص صراحة أنها صفة على مكوّن موجود أصلاً ولا تحمل فرصة منتج جديدة.\nاختبر بالمراقبة: إعادة فحص استمرار الاقتراح ومركزه في مسوح لاحقة قبل بناء حملة دائمة؛ أول ظهور واحد في المركز 9 لا يكفي وحده لقرار كبير.\nتجنّب: استخدام «الأصلية» كادعاء مطلق بلا إثبات موثق، أو وصف منتجات أخرى بأنها مقلّدة.','\n',char(10)),1795042089856,'','','','');
INSERT INTO competitor_ad_analyses VALUES(5,4,'Mazora — مصدر الرصد: Meta Ads Library، مصر، إعلانات نشطة، بتاريخ 2026-11-18 (VERIFIED). بروفايله المسجّل: براند مصري لكريمات شدّ الجسم والسيلوليت يبيع بعروض خصم موسمية قوية.','مسجّل: زاوية تخسيس عبر مكملات فقط (Fat Burner, Zero Belly, Slim) مقترنة بعروض كمية/خصم — وليست زاوية سيلوليت/شدّ على Meta، إذ إن Cell Firming Cream غير مُعلَن عنه حاليًا هناك رغم أنه منتج فئة الشدّ والسيلوليت في البروفايل المطابق. أي زاوية كريتيف تفصيلية أخرى غير مسجّلة.','غير مسجّل — التسجيل لا يصف نص هوك أو افتتاحية أو مشهدًا أو ادعاءً محددًا لأي إعلان؛ المسجّل فقط أسماء المنتجات والعروض، ولا يمكن اختراع هوك منها.','غير مسجّل — التسجيل لا يذكر نوع الفورمات (فيديو/صورة/كاروسيل/UGC) ولا بنية أو طول أي إعلان؛ المسجّل فقط وجود ~10 إعلانات نشطة على Meta.','مسجّل على إعلانات Meta النشطة لمكملات التخسيس: Buy 2 Get 1 / القطعة الثانية بخصم 50%. وبشكل منفصل في البروفايل المسجّل بتاريخ 2026-11-12: Cell Firming Cream بخصم Black Friday −50% بسعر 600 EGP — ولا يُنسب هذا كعرض إعلان Meta لأن الكريم مسجّل كغير مُعلَن عنه حاليًا هناك.','مسجّل: تاريخ الرصد 2026-11-18، وأقدم الإعلانات من 23 سبتمبر 2026 — أي 56 يومًا حتى تاريخ الرصد حسب التسجيل. لا يثبت ذلك أن كل إعلان من الـ~10 استمر 56 يومًا، ولا توجد مدة تشغيل فردية أخرى مسجّلة.','لا نجاح مؤكّد مسجّل: لا توجد أرقام أداء (مبيعات/CTR/ROAS) في التسجيل. المؤشر الوحيد للاستنتاج بحذر هو بقاء ~10 إعلانات نشطة ووجود أقدمها منذ 56 يومًا، مع عرض كمية واضح قد يفسّر الاستمرارية بتخفيض التكلفة الظاهرة للوحدة — لكن الاستمرارية ليست إثبات فعالية.','الفجوة الأوضح مسجّلة: انفصال بين تموضع الشدّ والسيلوليت ومنتج Cell Firming Cream وعرضه الموسمي −50% بتاريخ 2026-11-12، وبين غيابه تمامًا عن إعلانات Meta النشطة التي اقتصرت على مكملات التخسيس — فيترك فئة السيلوليت بلا تغطية إعلانية منه على Meta وقت الرصد.',replace('اختبار الفراغ: اختبر لزيرا حضورًا على Meta مخصصًا لزاوية الشدّ والعناية بمظهر السيلوليت التي تركها المنافس بلا إعلان وقت الرصد، دون ادعاءات طبية ودون ذكر المنافس أو المقارنة باسمه في الإعلان، وقِس النتائج قبل التوسّع.\nاختبار العرض لا نسخه: جرّب A/B مبدأ عرض الكمية (باقة متعددة مقابل خصم على القطعة الثانية) بما يناسب سعر وهامش زيرا فقط، ولا تنسخ Buy 2 Get 1 أو −50% نسخًا أعمى.\nاختبار التوقيت الموسمي: جرّب عرضًا واضحًا مرتبطًا بموسم محدد بسقف خصم مدروس وموعد انتهاء معلن، بدل تحويل الخصم الكبير إلى سعر دائم.\nتجنّب الاعتماد على الخصم وحده: ادعم العرض برسالة منتج وروتين عناية ومحتوى تعليمي غير طبي، لأن التسجيل المنافس يوثّق منتجات وعروضًا فقط ولا يوثّق زاوية محتوى مميزة يمكن البناء عليها.\nالتتبّع قبل الحكم: كرّر الرصد المؤرّخ لعدد الإعلانات واستمراريتها وتغيّر العروض، ولا تعتبر بقاء الإعلان نشطًا وحده دليل مبيعات أو نجاح.','\n',char(10)),1795045337618,'','','','');
INSERT INTO competitor_ad_analyses VALUES(6,5,'Alejon','مسجل: زاوية «الاستمرارية أولاً» للتعامل مع جلد الوزة وآثاره، عبر روتين ثنائي: غسول جسم + كريم يوريا، داخل إطار White Friday تحفيزي. مستنتج: الزاوية تبيع الالتزام بالروتين والباقة أكثر من منتج منفرد، مستندة إلى تموضع صيدلي عام مسجل للبراند: كريم يوريا 10% و20% للجلد الجاف الخشن وجلد الوزة.','«حل جلد الوزه واثار جلد الوزه قبل اي حاجه هو الاستمرار» — كما هو مسجل حرفياً؛ يضع الاستمرارية قبل أي حلّ أو منتج.','فيديو مباشر مسجل لجلد الوزة مدته 2:37 دقيقة، يذكر غسول جسم + كريم يوريا، وCTA: Get offer. غير مسجل: هوية/أسلوب المقدّم، النصوص على الشاشة، اللقطات، الشهادات، أو أي قبل/بعد؛ وباقي صيغ الـ~84 إعلاناً النشطة غير موصوفة في التسجيل.','نمط White Friday مسجل للبراند: Buy 2 Get 2 Free + هدية سرية Secret Gift (محتواها وقيمتها غير مسجلين) + شحن مجاني فوق 1,000 EGP. البروفايل المطابق: Urea Cream 10% — 200ml بسعر 380 EGP لدى AlFouad Pharmacies، وهو سعر بروفايل/صيدلية وليس سعراً مسجلاً لهذا الفيديو تحديداً. سعر باقة الغسول + الكريم في الفيديو وتركيز الكريم المستخدم فيه: غير مسجل.','الفيديو: بدء مسجل في 4 نوفمبر 2026 وكان ضمن النشط عند الرصد في 18 نوفمبر 2026؛ مدة تشغيل صريحة له غير مسجلة، و2:37 هي مدة الفيديو لا مدة التشغيل. تنبيه استمرارية: أقدم إعلانات البراند من 19 أغسطس 2026 (91 يوماً كما هو مسجل) تخص كريمات اليد والقدم والوجه، وليست دليلاً على عمر فيديو جلد الوزة. الـ~84 إعلاناً هي إجمالي نشاط البراند النشط عند الرصد، لا عدد إعلانات هذا المنتج.','استنتاج محتمل فقط — لا أرقام أداء مسجلة (لا CTR ولا مبيعات ولا ROAS): 1) الهوك يخاطب سبباً شائعاً لفشل الروتين وهو التوقف، فيبني توقعاً أكثر واقعية من وعد فوري، 2) pairing الغسول + الكريم يجعل الباقة منطقية ويرفع قيمة السلة، 3) حافز White Friday الكمي والشحن المجاني يخلق إلحاحاً موسمياً، 4) التموضع الصيدلي المسجل قد يدعم الثقة. بقاؤه نشطاً من 4 نوفمبر حتى الرصد مؤشر استمرار فقط، لا إثبات نجاح.','الأوضح من التسجيل: الرسالة عامة وقابلة للنسخ — «الاستمرار» دون تفاصيل مسجلة عن مدة الروتين أو خطواته أو ما يميز هذا الكريم، ودون توضيح مسجل إن كان كريم الفيديو 10% أم 20%. كذلك الهدية السرية غامضة القيمة، وعتبة الشحن المجاني 1,000 EGP (مستنتج حسابياً) بعيدة عن سعر العبوة المسجل 380 EGP، فالعرض يضغط نحو شراء كميات بدل تجربة أولى سهلة.',replace('اختبر/تبنَّ: زاوية الاستمرارية كروتين واضح الخطوات والتكرار لزيرا، لكن بصياغة استخدام واقعية وبلا وعد علاجي أو ضمان نتيجة؛ وقارنها بهوك فائدة يومية ملموسة.\nاختبر: نسخة فيديو تعليمية أطول مقابل نسخة مختصرة بنفس الروتين والـCTA، مع تثبيت العرض أثناء الاختبار حتى تُعرف نتيجة الصيغة لا العرض.\nتبنَّ بحذر: منطق الباقة الثنائية (تنظيف + كريم) كروتين واحد بدل منتج منفرد، مع إعلان السعر والحجم والتركيز بوضوح منذ البداية.\nتجنب النسخ الأعمى: لا تنسخ Buy 2 Get 2 Free + Secret Gift قبل حساب الهامش وسلة الشراء؛ اختبر هدية معلنة القيمة وعتبة شحن متناسبة مع سعر منتج زيرا بدل هدية غامضة.\nتجنب: أي مقارنة باسم Alejon وأي ادعاءات طبية أو علاجية لجلد الوزة؛ ميّز زيرا فقط بمواصفات موثقة خاصة بها (التركيز، الحجم، القوام، طريقة الاستخدام) دون ادعاء غير مسجل.','\n',char(10)),1795045379399,'','','','');
INSERT INTO competitor_ad_analyses VALUES(7,6,'Soralone','مسجل: منتجات يوريا لجلد الوزة بأسعار منخفضة — Urea 15% Cream Gel + Urea 5% Shower Gel. مستنتج: الزاوية سعرية-موسمية بالأساس: دفعة Black Friday + دفع العميل لباقة/روتين من منتجين وشراء 3 منتجات، وليست زاوية نتيجة أو ادعاء طبياً موصوفاً في التسجيل.','غير مسجل: لا يوجد نص هوك أو جملة افتتاحية أو سكريبت أو وصف للمشاهد الأولى في التسجيل، فلا يمكن اختراع هوك محدد أو نسبته لهذه الدفعة.','مسجل في البروفايل العام: اعتماد على ريلز صانعي المحتوى وقمع شراء عبر واتساب، ونشاط على Meta Ads Library مصر بنحو ~56 إعلاناً نشطاً. غير مسجل: فورمات كل إعلان بعينه، مدة الفيديو، النص الإعلاني، الـCTA، أو كيفية تقسيم الـ~56 إعلاناً.','مسجل: خصم 50% عند شراء 3 منتجات + شحن مجاني فوق 1,500 EGP. سعر مخفض مسجل لـUrea 15% Gel: ~125 EGP (مسح 2026-11-18). سعر Urea 5% Shower Gel والسعر قبل الخصم: غير مسجل.','مسجل: كل الإعلانات بدأت بين 3–18 نوفمبر 2026 ورُصدت نشطة بتاريخ 2026-11-18، ولا يوجد إعلان عمره 30+ يوماً في الصفحة الأولى — دفعة Black Friday جديدة بالكامل. استمرارية أو مدة تشغيل مثبتة بعد تاريخ الرصد: غير مسجلة، فلا يُستنتج وجود إعلان رابح طويل العمر.','أداء فعلي مثبت: غير مسجل — لا توجد أرقام CTR أو مبيعات أو ROAS. مستنتج كفرضية فقط: إطلاق ~56 إعلاناً دفعة واحدة في Black Friday قد يتيح اختبار نسخ كثيرة بسرعة، بينما وضوح حافز الباقة والسعر المنخفض وتكامل الكريم والشاور وريلز الصانعين وواتساب قد يقلل احتكاك الشراء. هذه أسباب محتملة للانتشار، لا دليل نجاح.','الأوضح مسجلاً: غياب أي إعلان بعمر 30+ يوماً في الصفحة الأولى، أي لا دليل على استمرارية أو Winner دائم خارج حداثة الدفعة. مستنتج: الجاذبية تبدو معتمدة على الخصم والسعر أكثر من تمايز موصوف، وشرط شراء 3 منتجات وعتبة 1,500 EGP للشحن المجاني قد يرفعان حاجز إكمال السلة مقارنة بسعر الوحدة المخفض المسجل ~125 EGP.',replace('تختبر زيرا: إطلاق دفعة متنوعة ومنظمة في موسم شرائي بريلز صانعي محتوى ومسار شراء واضح، مع تتبع أي نسخة تستمر 30+ يوماً — دون افتراض أن كثرة الإعلانات وحدها دليل نجاح.\nتختبر زيرا: عرض روتين/باقة من منتجين مكملين وخصماً عند تعدد الوحدات مقابل عرض المنتج الواحد، مع قياس حجم السلة والهامش — دون نسخ 50% أو عتبة 1,500 EGP بشكل أعمى.\nتتبنى زيرا: توضيح التركيزات والروتين والسعر كما هي موثقة على منتجاتها وصفحاتها، دون ادعاءات طبية أو وعود بالعلاج أو الاختفاء، ودون ذكر Soralone أو المقارنة باسمه في الإعلان.\nتتجنب زيرا: الاعتماد الكلي على خصم موسمي عميق وعتبة شحن مرتفعة؛ تُختبر عتبة متناسبة مع سلة زيرا الفعلية وتُعرض شروط العرض بشفافية من البداية.\nتختبر زيرا: إبقاء إعلان Evergreen ثابت خارج الموسم ومراقبة استمراريته، للتمييز بين طلب حقيقي مستدام واندفاع موسمي مؤقت.','\n',char(10)),1795048153463,'','','','');
INSERT INTO competitor_ad_analyses VALUES(8,7,'Centevia — براند مصري للعناية بالجسم بتركيز على الترطيب وباقات العرائس، منافس من جانب السيلوليت؛ وسم الأدلة: VERIFIED، والمصدر: Meta Ads Library — مصر.','المسجل: فيديو يتناول «جلد الوزة» ضمن فئة الترطيب والشدّ، ويرتبط بعرض Black Friday. المستنتج: زاوية مشكلة محددة مرتبطة بالترطيب ومظهر/ملمس الجلد، مع دافع شراء موسمي للتخزين — لا توجد في التسجيل صياغة حل أو ادعاء نتيجة محددة لهذا الإعلان.','غير مسجل نصياً أو بصرياً: التسجيل يذكر فقط أن الفيديو عن «جلد الوزة»، ولا يصف الجملة الافتتاحية أو المشهد الأول أو أول الثواني؛ لذلك لا يمكن الجزم بهوك محدد سوى أن موضوع المشكلة نفسه هو عنصر الجذب الموصوف.','المسجل: إعلان فيديو على Meta، ضمن نحو 7 إعلانات نشطة، وCTA: Send message. غير مسجل: مدة الفيديو بالثواني، أبعاده، نصه، وهل يظهر فيه صانع محتوى أو عرض بجهاز قياس الترطيب؛ فجهاز القياس ورد في تموضع البراند عامةً، لا في تفاصيل هذا الفيديو تحديداً.','المسجل في الإعلان: Black Friday — Buy 2 Get 2، دون ذكر منتج أو سعر محدد داخل تفاصيل الإعلان المسجلة. سياق منفصل من بروفايل المنافس بمسح 2026-11-18: Nourish-30 Lotion بسعر 400 EGP وباقة Bridal Bundle بسعر 888 EGP؛ لا يثبت التسجيل أن أيّاً منهما هو منتج هذا الفيديو أو أساس حساب عرضه.','المسجل: بدأ الإعلان في 15 أكتوبر 2026، ورُصد نشطاً في 18 نوفمبر 2026، والمدة المذكورة في التسجيل 34 يوماً حتى تاريخ الرصد. غير مسجل: أي استمرار أو توقف بعد 18 نوفمبر 2026.','استنتاج مرجّح لا نجاح مثبت: بقاؤه 34 يوماً حتى الرصد، ضمن نحو 7 إعلانات نشطة، مؤشر استمرارية فقط. يُرجّح أنه يعمل لثلاثة أسباب: مشكلة محددة وسهلة الفهم، عرض عددي بسيط في موسم Black Friday، وCTA محادثة منخفض الاحتكاك نسبياً للاستفسار والطلب. على مستوى البراند فقط سُجل توزيع قوي عبر صانعي المحتوى، لكن غير مسجل أن هذا الفيديو تحديداً من إنتاجهم. لا توجد أرقام CTR أو تكلفة أو مبيعات مسجلة، فلا يمكن تأكيد الأداء التجاري.','الأوضح من التسجيل: غموض قيمة العرض داخل تفاصيل الإعلان؛ فـBuy 2 Get 2 مذكور بلا منتج أو سعر أو إجمالي نهائي محدد، وبلا عنصر إثبات موصوف داخل هذا الفيديو تحديداً، بينما يضيف CTA المحادثة خطوة قبل الشراء ويتطلب العرض التزاماً بكمية أكبر قبل التجربة.',replace('اختبر ولا تنسخ: فيديو يفتتح بمشكلة بصرية واحدة محددة — مظهر الخشونة/جلد الوزة لغرض تجميلي — مقابل فيديو ترطيب عام، بنفس الجمهور والميزانية، وقارن بدء المحادثات المؤهلة ومعدل إتمام الطلب.\nتبنَّ الوضوح لا الصيغة حرفياً: اعرض ميكانيكية أي حزمة بصياغة وسعر خاصين بزيرا مع الإجمالي النهائي والشحن من أول رسالة، واختبر حزمة تجربة أصغر مقابل حزمة كمية أكبر لقياس حاجز الالتزام عند أول شراء.\nاختبر مسار الاستجابة: Send message مقابل مسار طلب مباشر لفترة محددة، واحكم بتكلفة المحادثة المؤهلة ونسبة تحويل المحادثة إلى طلب مؤكد، لا بعدد الرسائل فقط.\nأضف إثباتاً بصرياً خاصاً بزيرا بشروط تصوير وقياس موحدة لتوضيح الترطيب والملمس، دون ادعاء علاج أو نتيجة مضمونة؛ ولا تفترض أن هذا الإعلان المنافس استخدم إثباتاً بجهاز قياس، لأنه غير مسجل في تفاصيله.\nتجنب الاعتماد على خصم موسمي فقط: اختبر نسخة «عرض + قيمة/روتين استخدام» مقابل نسخة «عرض فقط»، وتابع الأداء الداخلي الفعلي بعد انتهاء الموسم قبل اعتبار أي صيغة رابحة.','\n',char(10)),1795048205535,'','','','');
INSERT INTO competitor_ad_analyses VALUES(9,8,'Nefertari — المنافس المطابق (عناية جسم طبيعية، تشابه 68/100)؛ الرصد نفسه شمل أيضًا Tetavara وEra Care وKolagra وكلهم بصفر إعلانات نشطة','غير مسجلة — لا توجد زاوية إعلانية: صفر إعلانات نشطة لـNefertari على ميتا في مصر بتاريخ الرصد 2026-11-18 (VERIFIED، Meta Ads Library، ضمن رصد شمل أيضًا Tetavara وEra Care وKolagra). ما هو مسجل من البروفايل فقط — لا من إعلان — هو تموضع عناية جسم طبيعية 100% مصنوعة يدويًا منذ 1998 وروتينات خطوتين (سكراب + كريم)، ولا يجوز نسبته لإعلان غير موجود.','غير مسجل — لا يوجد هوك إعلاني، لأنه لا يوجد إعلان نشط مسجل لـNefertari يمكن استخراج أول سطر أو مشهد أو رسالة جذب منه.','غير مسجل — لا يوجد فورمات إعلاني لفحصه (لا فيديو أو صورة أو كاروسيل أو نص إعلان موصوف في التسجيل) لعدم وجود أي إعلان نشط مسجل؛ مصدر الرصد فقط هو Meta Ads Library.','عرض إعلاني غير مسجل لعدم وجود إعلان. العرض المسجل من موقع Nefertari الرسمي وردود البراند فقط — وليس من إعلان ميتا — هو: The Secret Scrub وروتينات خطوتين (سكراب/كريم)، بأسعار سكراب 465-535 EGP، زبدة شيا 455 EGP، كريم/سكراب قدم 465-535 EGP. ملحوظة سياقية مسجلة منفصلة: Tetavara كان مظلمًا على ميتا رغم عرض Pink Friday على موقعه (كريم Buy 1 Get 1 بسعر 350 EGP)، وهذا عرض Tetavara لا Nefertari.','غير مسجلة — لا يوجد تاريخ بدء إعلان ولا مدة تشغيل ولا استمرارية مسجلة. التاريخ الوحيد المسجل هو تاريخ الرصد 2026-11-18 الذي أظهر صفر إعلانات نشطة، ولا يمكن استنتاج مدة الغياب أو سببه من رصد واحد.','لا يمكن القول إنه شغال أو ناجح: غير مسجل أي إعلان أصلًا وغير مسجلة أي أرقام أداء أو مبيعات أو تفاعل في التسجيل. المستنتج فقط — كفرضية غير مثبتة — أن صفر إعلانات للأربعة براندات في لقطة 2026-11-18 قد يترك مساحة ظهور أقل ازدحامًا على ميتا، وهذا يحتاج اختبارًا وقياسًا فعليًا من حملات زيرا ولا يُقدَّم كنتيجة مسجلة عن Nefertari.','الضعف الأوضح المسجل: غياب كامل عن إعلانات ميتا النشطة في مصر وقت الرصد، رغم أن Nefertari يبيع أونلاين وله فروع في مصر ومنتجات وروتينات قابلة للترويج المدفوع؛ أي لا توجد رسالة مدفوعة مسجلة لالتقاط الطلب على هذه القناة في ذلك التاريخ. سبب الغياب (إيقاف مقصود أو الاعتماد على قنوات أخرى) غير مسجل.',replace('اختبر: حضورًا مدفوعًا منتظمًا لزيرا على ميتا لاستغلال فراغ اللقطة المسجلة 2026-11-18، مع إعادة فحص Meta Ads Library قبل الإطلاق مباشرة لأن الرصد لقطة يوم واحد وليس دليل غياب دائم.\nاختبر: محتوى روتين خطوتين (سكراب ثم كريم) بصياغة ومنتجات زيرا الخاصة، دون نسخ اسم The Secret Scrub أو أي ادعاء خاص بالمنافس.\nتبنَّ فقط ما هو مثبت لزيرا: لا تستخدم طبيعي 100% أو مصنوع يدويًا أو منذ 1998 في رسائل زيرا إلا إذا كانت صحيحة وموثقة لزيرا نفسها.\nتجنب: الادعاءات الطبية أو العلاجية مثل مضاد للسيلوليت أو الشد أو العلاج؛ اكتفِ بوصف تجميلي غير علاجي ومتوافق مع مستندات المنتج.\nاختبر: وضوح السعر والباقة في الإعلان مستخدمًا نطاق المنافس المسجل 465-535 EGP كمرجع سوقي داخلي فقط، دون ذكر اسم أي براند منافس أو عمل مقارنة باسم براند في الإعلان.','\n',char(10)),1795061570566,'','','','');
INSERT INTO competitor_ad_analyses VALUES(10,9,'Alejon','زاوية مسجّلة موقعياً لا إعلانياً: يوريا 10% عامة للجلد الجاف الخشن مع تقشير لطيف يحسّن مظهر جلد الوزة/KP، داخل تموضع كوزميسيوتيكالز من تصميم صيدلانيات مصريات وتوزيع صيدلي. لا يوجد منتج مخصص لجلد الوزة؛ ذكرها المسجل في 4 صفحات فقط على الموقع كله. ملحوظة تناقض: بروفايل المنافس يذكر يوريا 10% و20%، لكن التصفح المسجل لم يُظهر للجسم إلا 10%، و30% لكريم القدم فقط.','غير مسجل: لا هوك إعلاني أو افتتاحية كرييتيف موصوفة. أقرب عنصر جذب مسجل على الموقع هو بانر White Friday: Buy 2 Get 2 + Secret Gift، ولا يجوز نسبته كهوك لحملة إعلانية غير موصوفة.','غير مسجل كفورمات إعلاني: لا نص أو فيديو أو صورة إعلان موصوفة في التسجيل. المسجل تصفح مباشر موثّق VERIFIED لموقع alejon.com بتاريخ 2026-11-18، يشمل كتالوجاً وصفحات منتجات وبانر White Friday.','مسجل موقعياً: Urea Cream 10% + Salicylic 2% + Shea بسعر 380 EGP/200ml و660 EGP/500ml (جديد)؛ Urea Body Wash 10% بسعر 390 EGP/500ml؛ Foot Cream 30% بسعر 295 EGP/75ml للقدم/الكالو فقط؛ Whitening Body Milk بسعر 360 EGP/200ml؛ Post-Laser Cream بسعر 240 EGP/75ml. العروض: Buy 2 Get 2 على أغلب الفردي، واشترِ 4 واحصل على الأرخصين مجاناً + هدية + شحن مجاني فوق 1,000 EGP. الباقة القريبة الوحيدة القابلة للشراء: Drink Your Water Box من 1,275 إلى 890 EGP؛ وكل الباقات الـ14 نفدت مخزوناً.','غير مسجلة: لا تاريخ بدء إعلان ولا مدة تشغيل ولا استمرارية مسجلة. المسجل فقط تاريخ رصد وتصفح واحد هو 2026-11-18، فلا يمكن استنتاج أن هذا إعلان مستمر أو طويل التشغيل.','لا نجاح أو أداء مثبت في التسجيل: لا مبيعات أو CTR أو تحويلات أو مدة تشغيل مسجلة. على الأرجح فقط، عوامل الجذب هي انخفاض السعر الفعلي عبر B2G2/شراء 4، وقيمة الحجم الأكبر (500ml بـ660 مقابل 200ml بـ380)، والثقة الصيدلية وادعاء التصميم بواسطة صيدلانيات مصريات، وتوفر منتجات فردية مكملة للغسول والترطيب؛ وهذا استنتاج من بنية العرض والتوزيع، لا نتيجة موثقة.','الأوضح: فجوة تخصص وتوفر وشفافية. لا منتج مخصص لجلد الوزة وتركيز الجسم المسجل 10% فقط، وكل الباقات الـ14 نفدت رغم قوة العروض، وقوائم INCI مقصوصة على الصفحات، وبعض المقاسات مستمدة من محتويات البوكسات لا صفحات المنتجات؛ فيتشتت مسار الشراء داخل كتالوج واسع بنحو 110 منتجات.',replace('تتبنّى/تختبر: منتج وصفحة واضحَين ومخصصَين لمشكلة واحدة بصياغة تحسين المظهر غير الطبية، وقياس أثر وضوح التخصص على التحويل مقابل تقديم منتج عام متعدد الاستخدامات.\nتختبر: سلّم أحجام بقيمة أوضح للملّيليتر وحجم أكبر أوفر، مع قياس متوسط قيمة الطلب وحجم السلة، دون نسخ أسعار المنافس أو عروضه حرفياً.\nتتجنّب: الترويج لباقات غير متوفرة؛ اختبر باقة واحدة ذات صلة ومتوفرة فعلياً، مع إظهار التوفر والشحن والعتبة بوضوح قبل أي حملة.\nتتبنّى: شفافية كاملة بنشر قوائم INCI غير مقصوصة، والتركيز ومنطقة الاستخدام لكل منتج للفصل بين استخدام الجسم والقدم، وقياس أثر ذلك على الأسئلة والمرتجعات.\nتختبر منفصلاً A/B: رسالة ثقة صيدلية/تركيبية، وهدية، وشحن مجاني فوق عتبة شراء، لمعرفة المحرك الحقيقي للشراء، دون ادعاءات علاج أو شفاء ودون مقارنات باسم أي براند في المحتوى العام.','\n',char(10)),1795061606215,'','','','');
INSERT INTO competitor_ad_analyses VALUES(11,9,'Alejon — خط اليوريا / جلد الوزة (بيانات موقع موثقة VERIFIED من alejon.com)','مسجل: تموضع صيدلي «كوزميسيوتيكالز من تصميم صيدلانيات مصريات» حول يوريا 10% للعناية بالجلد الجاف الخشن وتحسين مظهر جلد الوزة بتقشير لطيف — كريم 10% + ساليسيليك 2% + شيا — وليس منتجاً مخصصاً لجلد الوزة. مستنتج: الزاوية قائمة على اللطف والثقة الصيدلية ودفع الشراء بالعروض، أكثر من التخصص في مشكلة واحدة.','الهوك الإعلاني (نص أو مشهد إعلان) غير مسجل — لا محتوى إعلان موصوفاً في التسجيل. أقرب عناصر جذب مسجلة على الموقع فقط: بانر White Friday ‏(Buy 2 Get 2 + Secret Gift)، وادعاء كريم اليوريا 10% المسجل: تقشير لطيف يحسّن مظهر جلد الوزة.','الفورمات الإعلاني غير مسجل. المسجل فقط: تصفح مباشر لموقع alejon.com في 2026-11-18 — صفحات منتجات فردية وكتالوج (~110 منتجات: 85 فردياً + 14 باقة + 11 بوكس) وبانرات عروض موقع، دون أي فيديو أو نص إعلان أو منصة إعلانية موصوفة في التسجيل.','مسجل: Urea Cream 10% ‏200ml بـ380 EGP و500ml بـ660 EGP (جديد)؛ Urea Body Wash 10% ‏500ml بـ390 EGP؛ Foot Cream 30% ‏75ml بـ295 EGP (قدم/كالو فقط)؛ Whitening Body Milk ‏200ml بـ360 EGP؛ Post-Laser Cream ‏75ml بـ240 EGP. عروض الموقع: Buy 2 Get 2 على أغلب الفردي + اشترِ 4 وخد الأرخصين مجاناً + هدية + شحن مجاني فوق 1,000 EGP. كل الـ14 باقة نفدت؛ أقرب باقة قابلة للشراء لجلد الوزة: Drink Your Water Box من 1,275 إلى 890 EGP.','غير مسجلة: لا تاريخ بدء ولا مدة تشغيل ولا استمرارية ولا أرقام أداء في التسجيل. المسجل فقط تاريخ رصد وتصفح واحد: 2026-11-18، مصدره alejon.com عبر جهاز المالك — ولا يجوز الاستنتاج منه مدة عرض أو نجاح.','الأداء/النجاح غير مسجل — لا أرقام أداء في التسجيل، والتالي مستنتج لا مسجل: على الأرجح الجاذبية من (1) ثقة التموضع الصيدلي وادعاء تصميم صيدلانيات مصريات والتوزيع الصيدلي الوارد في البروفايل المطابق، (2) عرض قيمة قوي: Buy 2 Get 2 وهدية وشحن مجاني فوق 1,000 EGP يخفض سعر الوحدة الفعلي، (3) مرساة حجم كبير 500ml بـ660 EGP مقابل 200ml بـ380 EGP، (4) تركيبة مفهومة للمستهلك: يوريا 10% + ساليسيليك 2% + شيا. يقابل ذلك تشتت كتالوج واسع ~110 منتجات.','أوضح نقطة ضعف مسجلة: غياب التخصص وانكسار مسار الشراء معاً — لا منتج مخصص لجلد الوزة وذكرها في 4 صفحات فقط على الموقع كله، وتركيز الجسم المسجل 10% فقط (30% للقدم/الكالو فقط)، وفي الوقت نفسه كل الـ14 باقة نفدت رغم دفع عروض وهدايا، مع قوائم INCI مقصوصة تضعف الشفافية. تنبيه تسجيلي: البروفايل المطابق يذكر يوريا 20% أيضاً، لكن التصفح الموثق لم يرصد للجسم إلا 10%.',replace('تتبنّى/تختبر: منتج وصفحة روتين مخصصين بوضوح لمشكلة واحدة بدل خط عام — اختبار A/B لصفحة متخصصة مقابل صفحة منتج عام بقياس التحويل وإتمام الشراء، دون أي ادعاء طبي.\nتختبر: مرساة حجم/قيمة واضحة (حجم أكبر بسعر أوضح لكل مل) وعتبة شحن مجاني محددة — بقياس متوسط قيمة السلة، دون نسخ الأسعار أو عرض Buy 2 Get 2 حرفياً.\nتتجنّب: تكديس عروض متداخلة والترويج لباقات غير متوفرة — اختبار عرض واحد واضح وباقة واحدة متوفرة فعلياً مقابل تعدد العروض، بقياس التخلي عن السلة.\nتتبنّى: شفافية كاملة — نشر قوائم INCI كاملة والمقاسات من صفحات المنتجات نفسها لا من محتويات البوكسات، واختبار أثر ذلك على أسئلة العملاء والتحويل.\nتختبر: محتوى ثقة قائم على خبرة فريق التطوير وروتين استعمال واضح (كيف ومتى ولأي منطقة) بصياغة تجميلية فقط، دون ادعاءات علاجية ودون مقارنات باسم أي براند.','\n',char(10)),1795061639748,'','','','');
INSERT INTO competitor_ad_analyses VALUES(12,10,'غير محدد من التسجيل','مسجل: إعلان فيديو للعناية بالجسم ظهر ضمن بحث «جلد الوزة» (آخر 180 يومًا)، وظهرت نفس العبوة البيضاء بمضخة ضمن بحث «كريم يوريا». مستنتج بحذر فقط: الزاوية مرتبطة باهتمام جلد الوزة والعناية بالجسم؛ لا نص إعلاني أو وعد أو ادعاء مسجل في التسجيل.','غير مسجل: لا وصف في التسجيل للثواني الأولى أو لأي نص أو حوار أو عبارة افتتاحية لهذا الإعلان؛ المسجل فقط الصورة المصغرة لعبوة بيضاء بمضخة واسم غير مقروء.','مسجل: إعلان فيديو على TikTok Top Ads (مصر)، بصورة مصغرة تُظهر عبوة بيضاء بمضخة. غير مسجل: مدة الفيديو وأسلوب التصوير لهذا الإعلان؛ أسلوب صانع المحتوى مسجل لفيديو آخر بأنبوب أخضر مزرق ولا يُنسب لهذا الإعلان.','غير مسجل: لا سعر أو خصم أو حزمة أو ضمان مذكور في التسجيل؛ المسجل فقط هدف الحملة Traffic وميزانية عالية.','غير مسجلة: لا تاريخ بدء ولا مدة تشغيل للإعلان نفسه مسجلة؛ المسجل فقط تاريخ الرصد 2026-11-18 ونوافذ البحث — غائب في آخر 30 يومًا وظاهر في آخر 180 يومًا — وهذه النوافذ لا تثبت مدة تشغيل.','مسجل: ضمن أول 4 نتائج معروضة مجانًا لـ«جلد الوزة» كان الأعلى إعجابًا (12K)، مع وسم CTR أعلى 25% وميزانية عالية وهدف Traffic، وظهرت نفس العبوة في بحث «كريم يوريا» (9K إعجاب، CTR أعلى 22%)، وTop Ads عرض منتقى للأعلى أداءً. مستنتج: نجاحه الأرجح داخل هذا العرض هو جذب النقر والإعجاب عبر كلمتين مرتبطتين؛ لا مبيعات أو تحويلات مسجلة لإثبات أثر تجاري.','الأوضح مسجلًا: اسم البراند غير مقروء في الصورة المصغرة رغم الميزانية العالية وعدد الإعجاب الأعلى بين المعروض — جذب وإنفاق دون هوية واضحة قابلة للتمييز أو التذكر من التسجيل.',replace('اختبر: موضوع «جلد الوزة» على TikTok مصر بميزانية اختبار محدودة — المسجل صفر نتائج في آخر 30 يومًا و4 فقط في آخر 180 يومًا في العرض المجاني — وقِس CTR والإعجاب، دون اعتبار الغياب دليلًا على غياب كل المنافسة.\nتبنَّ: وضوح هوية زيرا واسمها مقروءًا في الصورة المصغرة وإطار الفيديو الأول، وتجنَّب هوية غير مقروءة كما في ضعف الإعلان المسجل؛ اختبر نسختين وقارن النقر والتذكر.\nتجنَّب: النسخ الأعمى للعبوة البيضاء بمضخة أو افتراض هوك أو أسلوب غير مسجل؛ اختبر فورمات فيديو عناية بالجسم خاصًا بزيرا بعرض عبوة واضح وسياق استخدام دون أي ادعاء طبي.\nاختبر: هدف Traffic بميزانية محدودة مقابل هدف حملة أعمق، وقارن جودة الزيارة والإجراء اللاحق لا الإعجاب وحده — فالمسجل للمنافس هو Traffic وميزانية عالية دون بيانات مبيعات.\nتجنَّب: بناء قرار إنفاق كبير على Top Ads وحده؛ وسّع الرصد قبل التوسع لأن العرض المجاني يُظهر أول 4 نتائج فقط وهو عرض منتقى للأعلى أداءً وليس مكتبة كاملة.','\n',char(10)),1795061696366,'','','','');
INSERT INTO competitor_ad_analyses VALUES(13,25,'غير محدد من التسجيل','مستنتجة من العبارة المسجلة فقط: تخصيص نية «علاج جلد الوزة» بمنطقة محددة هي الوجه — صياغة [حل/علاج + المشكلة + الموضع]. ليست زاوية إعلان منافس موصوفة في التسجيل.','غير مسجل — لا يوجد هوك أو نص إعلاني موصوف؛ المسجل فقط عبارة الاقتراح نفسها: «علاج جلد الوزة في الوجه».','غير مسجل كفورمات إعلان — المصدر المسجل فقط هو اقتراح Google Egypt autocomplete بوسم SEARCH-LANGUAGE، ولا يوجد وصف لإعلان نصي أو بصري أو فيديو.','غير مسجل — لا يوجد منتج أو سعر أو خصم أو ضمان أو دعوة لاتخاذ إجراء في التسجيل.','غير مسجلة — لا يوجد تاريخ بدء تشغيل إعلان أو مدته؛ المسجل فقط تاريخ الرصد 2026-11-19 وأول ظهور الاقتراح في مسح 03:11 EET مقارنة بمسح 02:49 EET، وهذا لا يثبت استمرارية.','غير مسجل أي نجاح أو أرقام أداء. المستنتج على الأرجح فقط: ظهور الصياغة الجديدة كإشارة لغة بحث قد يدل على اهتمام بصياغة تجمع نية الحل مع تحديد الوجه، ما قد يرفع صلة المحتوى المطابق لعبارة المستخدم — دون إثبات نقرات أو تحويلات أو نجاح إعلان.','الأوضح: هشاشة الإشارة وتقلبها — اقتراح واحد ظهر واقتراح «علاج جلد الوزة في منطقة البكيني» اختفى بين مسحين متقاربين وباقي الكلمات الـ11 ثابتة، بلا منافس أو عرض أو أداء مسجل، فلا يمكن الجزم باتجاه حقيقي مقابل تذبذب عابر في autocomplete.',replace('اختبر: استخدام عبارة البحث المسجلة كسؤال/عنوان محتوى خاص بالوجه مقابل المحتوى العام عن جلد الوزة، مع قياس الظهور والنقر — دون وعد علاجي أو نتيجة مضمونة.\nتبنَّ: تقسيم الرسائل والمحتوى حسب منطقة الجسم ونية البحث بدل صياغة عامة واحدة، بشرط تأكد الإشارة بتكرار الرصد.\nاختبر بالمراقبة: إعادة مسح autocomplete في مواعيد وأيام متعددة قبل أي قرار؛ لا تُبنى استراتيجية على ظهور واحد في مسح 03:11 EET.\nتجنب: حذف أو إيقاف محتوى منطقة البكيني بناءً على اختفائه في مسح واحد فقط، وتجنب النسخ الأعمى لتقلب الاقتراحات.\nتجنب: أي ادعاءات طبية قاطعة خاصة بالوجه أو مقارنات باسم براند؛ استخدم لغة معلوماتية حذرة وأحِل الحالات الحساسة لمختص.','\n',char(10)),1795062502332,'','','','');
INSERT INTO competitor_ad_analyses VALUES(14,24,'غير محدد من التسجيل','زاوية مسجلة كاقتراح بحث/محتوى محتمل، لا كزاوية إعلان موصوفة: ربط علاج جلد الوزة (KP) بالشعر تحت الجلد، مع شرح العلاقة بين التقشير/اليوريا والشعر تحت الجلد ضمن روتين KP.','غير مسجل كخطاف إعلاني؛ العبارة المسجلة الوحيدة هي اقتراح الإكمال التلقائي «علاج جلد الوزة والشعر تحت الجلد».','غير مسجل كفورمات إعلان؛ نوع الدليل المسجل هو SEARCH من Google Egypt autocomplete (suggestqueries.google.com، hl=ar، gl=eg) لكلمة «علاج جلد الوزة»، بتاريخ رصد 2026-11-19.','غير مسجل — لا يوجد عرض أو سعر أو خصم أو منتج أو دعوة لاتخاذ إجراء مذكورة في التسجيل.','غير مسجلة — لا توجد مدة تشغيل أو استمرارية مسجلة؛ المسجل فقط أول ظهور في مسح 2026-11-19 الساعة 02:30 EET، وحلوله محل «علاج جلد الوزة في المنزل» الذي خرج من القائمة.','لا يوجد نجاح إعلاني أو أرقام أداء مسجلة؛ المستنتج فقط أن الإشارة قد تكون قيّمة كدليل اهتمام بحثي، لأن الباحثين جمعوا مشكلتي جلد الوزة والشعر تحت الجلد في استعلام واحد وفق التسجيل، ما قد يطابق نية بحث مركّبة — وهذا استنتاج لا إثبات فعالية.','أوضح نقطة ضعف: الدليل نقطة رصد واحدة لاقتراح إكمال تلقائي متقلب، بلا منافس أو محتوى إعلان أو عرض أو أداء مسجل، فلا يثبت وحده حجم الطلب أو استمراريته أو نية الشراء.',replace('اختبر: محتوى تعليمي لزيرا يجيب عن الاستعلام المركّب ويشرح صلة التقشير/اليوريا بالشعر تحت الجلد بلغة عناية وصفية غير علاجية، وقارن تفاعله بمحتوى KP العام.\nتبنّى: إعادة مسح اقتراحات Google Egypt لنفس الكلمة في مسوح لاحقة للتحقق من بقاء الاقتراح قبل اعتباره اتجاهاً ثابتاً.\nاختبر: قسم أسئلة/إجابة مباشرة يطابق صياغة «علاج جلد الوزة والشعر تحت الجلد»، دون ادعاءات طبية أو مقارنات باسم براند.\nتجنّب: تحويل رصد واحد إلى ادعاء بحجم بحث أو نجاح منافس أو أساس لحملة واسعة؛ لا منافس ولا أداء مسجل هنا.\nتجنّب: النسخ الأعمى للزاوية كوعد بالعلاج أو الشفاء، وأخضع أي صياغة مختبرة لمراجعة الادعاءات أولاً.','\n',char(10)),1795062513427,'','','','');
INSERT INTO competitor_ad_analyses VALUES(15,25,'غير محدد من التسجيل','مسجل: زاوية لغة بحث علاجية محددة بالموضع — «علاج جلد الوزة في الوجه» ضمن مجموعة «علاج جلد الوزة». مستنتج فقط: وجود اهتمام بصياغة مخصصة للوجه بدل الصياغة العامة. لا توجد زاوية إعلان لمنافس مسجلة.','غير مسجل — لا يوجد هوك إعلان في التسجيل. العبارة الظاهرة «علاج جلد الوزة في الوجه» هي اقتراح بحث فقط، ولا يمكن اعتبارها هوكاً إعلانياً لمنافس.','غير مسجل كفورمات إعلان — المصدر المسجل هو Google Egypt autocomplete (suggestqueries.google.com, hl=ar, gl=eg) بوسم الأدلة SEARCH-LANGUAGE. لا يوجد وصف لنص أو صورة أو فيديو أو قالب إعلان.','غير مسجل — لا يوجد منتج أو سعر أو خصم أو ضمان أو باقة أو دعوة لاتخاذ إجراء مذكورة في التسجيل.','غير مسجلة — لا توجد مدة تشغيل أو استمرارية لإعلان. المسجل فقط: تاريخ الرصد 2026-11-19، وظهور الاقتراح لأول مرة في مسح 03:11 EET مقابل مسح سابق في 02:49 EET من اليوم نفسه؛ هذا توقيت رصد لاقتراح بحث، وليس تاريخ بدء إعلان أو مدته.','لا يوجد دليل مسجل على أن إعلاناً ناجح أو على أي أرقام أداء. المستنتج المحتمل كإشارة طلب فقط: التحديد بالموضع في «في الوجه» قد يعكس نية بحث أدق من البحث العام عن علاج جلد الوزة، لكن ظهوره في مسح واحد لا يثبت حجم الطلب أو استمراره أو ارتباطه بأي منافس.','أوضح ضعف: الإشارة غير منسوبة وربما عابرة؛ ظهر اقتراح واحد في مسح واحد بينما اختفى «علاج جلد الوزة في منطقة البكيني» وبقيت الكلمات الـ11 الأخرى دون تغيير، ولا يوجد منافس أو محتوى أو عرض أو أداء يمكن تقييمه، لذا لا تصلح وحدها أساساً لاستنتاج تنافسي.',replace('اختبر: محتوى تعليمياً بصيغة سؤال وجواب موجز يطابق لغة البحث «جلد الوزة في الوجه»، مع توضيح الفرق بين احتياجات الوجه والجسم ودون وعد بالعلاج أو الشفاء.\nتبنَّ: الرصد المتكرر لاقتراحات البحث عبر مسوح متعددة قبل اتخاذ قرار؛ لا تبنِ حملة على ظهور واحد في مسح 03:11 EET.\nاختبر: صفحة أو قسم أسئلة شائعة بالعربية المصرية يستخدم عبارة البحث نفسها في العنوان والسؤال، ثم قِس الطلب الفعلي من الاستفسارات وبيانات البحث قبل توسيع المحتوى.\nتجنب: استخدام كلمة «علاج» كادعاء طبي لمنتج زيرا، وتجنب أي مقارنات باسم براند منافس؛ استخدم لغة تعليمية حذرة ومراجعة مختص عند الحاجة.\nاختبر: ما إذا كان التخصيص بالموضع (الوجه) يحقق تفاعلاً أعلى من المحتوى العام عن جلد الوزة، مع مقارنة النتائج داخلياً فقط ودون ادعاء تفوق غير موثق.','\n',char(10)),1795062519766,'','','','');
INSERT INTO competitor_ad_analyses VALUES(16,11,'Kolagra','غير مسجّلة صراحةً: المسجّل فقط إعلانات فيديو للعناية بالبشرة بصور منتجات يظهر عليها اسم البراند، وأبرزها أنبوب «KOLAGRA 50+» وأنبوب أخضر. أي زاوية مشكلة/حل أو فائدة أو ادعاء غير مسجّل، ولا تُنسب إليها فئة اليوريا/جلد الوزة الخاصة ببروفايل Alejon.','غير مسجّل: لا يوجد في التسجيل نص هوك أو جملة افتتاحية أو وصف للمشاهد أو الثواني الأولى أو الصوت أو CTA، فلا يمكن تحديده أو نسخه.','مسجّل: 4 إعلانات فيديو على TikTok Creative Center — Top Ads (مصر)، واسم البراند ظاهر على صور المنتجات. مدة الفيديو ونوع التنفيذ (UGC/استوديو/متحدث) والصوت وCTA غير مسجّلة.','غير مسجّل لـKolagra: لا سعر ولا خصم ولا حجم عبوة ولا ضمان ولا CTA موصوف في التسجيل. عرض Urea Cream 10% — 200ml بسعر 380 EGP يخص بروفايل Alejon المطابق، وليس عرض Kolagra.','مدة التشغيل/تاريخ البدء: غير مسجّلة. المسجّل فقط: رصد بتاريخ 2026-11-18؛ في نافذة بحث آخر 180 يومًا ظهرت 4 إعلانات، وفي نافذة آخر 30 يومًا لم تظهر أي نتائج لـKolagra — وهذا لا يثبت وحده مدة تشغيل فعلية أو تاريخ إيقاف لكل إعلان.','استنتاج محتمل من مؤشرات مسجّلة فقط: Kolagra هو الوحيد بين 8 براندات بُحثت الذي ظهر في Top Ads — وهو عرض منتقى لأفضل الإعلانات أداءً — وأقوى إعلاناته 2K إعجاب وCTR ضمن أعلى 28% وبميزانية عالية، والثاني 1K إعجاب وCTR ضمن أعلى 49% وبميزانية عالية؛ يُرجّح أن وضوح المنتج/البراند بصريًا وملاءمة نسختين لجمهور TikTok ساعدا على النقر والتفاعل. لا يوجد دليل مسجّل على مبيعات أو تحويلات.','الأوضح مسجّلًا: الغياب في آخر 30 يومًا، وتفاوت حاد داخل المجموعة نفسها — إعلانان بـ2K و1K إعجاب مقابل إعلانين بـ54 و51 إعجابًا فقط — أي أداء غير ثابت عبر النسخ، وليس نجاحًا عامًا لكل الإعلانات.',replace('اختبر (لا تنسخ): عدة نسخ فيديو TikTok بتركيز بصري واضح على عبوة زيرا واسمها بشكل مقروء، وقارنها بنسخ بتركيز مختلف، مع تسجيل الهوك حرفيًا قبل الحكم — لأن هوك Kolagra غير مسجّل.\nتبنَّ: إطلاق دفعات متعددة النسخ ثم تصعيد الميزانية للفائز فقط وفق عتبات CTR/تفاعل محددة مسبقًا، مستلهمًا تفاوت 2K و1K إعجاب مقابل 54 و51 — دون اعتبار الظهور في Top Ads دليل مبيعات.\nاختبر الاستمرارية: خطة إعلانية تتجاوز نافذة 30 يومًا مع مراجعة دورية، لاختبار أثر عدم الانقطاع، دون ادعاء أن المنافس توقف نهائيًا.\nتجنَّب: الخلط بين البراندات أو المقارنة باسم منافس (AEO) أو ادعاءات طبية/علاجية غير موثقة؛ ابنِ رسالة زيرا من خصائص منتجها الموثقة لديها فقط.\nتجنَّب الاستنتاج الزائد: Top Ads عرض منتقى وليس مكتبة كاملة؛ وثّق لزيرا تاريخ البدء والمدة والميزانية والـCTA والسعر لكل نسخة — وهي عناصر غير مسجّلة هنا — لتقييم قابل للتكرار.','\n',char(10)),1795063818637,'','','','');
INSERT INTO competitor_ad_analyses VALUES(17,12,'غير محدد من التسجيل','غير مسجلة كزاوية إعلان منافس؛ المسجل فقط لغة بحث جديدة: «زبدة الشيا للبشرة» — ربط مكوّن موجود أصلاً في منتجات زيرا (زبدة الشيا) باستخدامه للبشرة، وليس منتجاً أو مشكلة جديدة حسب التسجيل','غير مسجل — لا يوجد هوك أو نص إعلاني موصوف في التسجيل؛ العبارة الوحيدة المسجلة هي اقتراح البحث نفسه «زبدة الشيا للبشرة»، ولا تُعامل كهوك إعلان','غير مسجل كفورمات إعلان — المسجل ملاحظة رصد Google Egypt autocomplete (suggestqueries.google.com، hl=ar وgl=eg) بوسم SEARCH_LANGUAGE، وليست إعلاناً أو كرييتيف لمنافس','غير مسجل — لا يوجد سعر أو خصم أو حزمة أو أي عرض مذكور في التسجيل','غير مسجلة — لا توجد مدة تشغيل أو استمرارية إعلان مسجلة؛ المسجل فقط أول ظهور في مسح 2026-11-19 00:10 EET مقابل لقطة 2026-11-18 23:49 EET','لا يوجد دليل مسجل على أن إعلاناً يعمل أو ينجح — لا أرقام أداء مسجلة ولا إعلان موصوفاً؛ الإشارة المسجلة الوحيدة هي ظهور الاقتراح في مسح 2026-11-19 واختفاء «زبدة الشيا الاصلية» في نفس المسح، ومستنتج فقط أنها قد تعكس تغيّراً في لغة البحث نحو الاستخدام للبشرة','أوضح ضعف: الملاحظة ليست إعلان منافس أصلاً ولا تكفي وحدها لاستنتاج اتجاه ثابت — رصد في مسح واحد، وبدون منافس أو كرييتيف أو عرض أو أداء، مع قابلية اقتراحات الإكمال التلقائي للتغيّر بين اللقطات',replace('اختبر: استخدام عبارة «زبدة الشيا للبشرة» كعنوان سؤال/قسم محتوى لمنتجات زيرا الحالية المحتوية على زبدة الشيا، بصياغة تجميلية غير طبية وبدون ادعاءات علاجية، وقياس الظهور والنقر قبل التعميم\nتبنّ: متابعة الرصد المتكرر للاقتراح عبر مسوح لاحقة للتحقق من استمراره، قبل تغيير رسائل أو ميزانية بناءً على مسح واحد\nتجنّب: فتح فرصة منتج جديد بناءً على هذه الملاحظة — فالتسجيل نفسه يوضح أن المكوّن موجود أصلاً في منتجات زيرا وأنه ليس منتجاً أو مشكلة جديدة\nتجنّب: اعتبار ظهور الاقتراح دليل نجاح إعلان منافس أو سبباً للنسخ الأعمى؛ لا منافس ولا عرض ولا أداء مسجلاً في التسجيل\nاختبر: محتوى يركّز على الاستخدام للبشرة مقابل محتوى يركّز على الأصالة، ولا تحذف محتوى «الاصلية» لمجرد اختفاء اقتراح «زبدة الشيا الاصلية» في مسح واحد فقط','\n',char(10)),1795063843651,'','','','');
INSERT INTO competitor_ad_analyses VALUES(18,14,'غير محدد من التسجيل','مسجلة كلغة بحث لا كإعلان منافس: اهتمام بجلد الوزة في منطقة البكيني تحديداً، وهي ضمن نطاق روتين KP الحالي لزيرا للجسم وليست منتجاً جديداً، وتُوصف في التسجيل كزاوية محتوى/إعلان حساسة تُدار بحذر.','غير مسجل: لا يوجد هوك أو نص إعلان موصوف في التسجيل. العبارة المسجلة وحدها هي اقتراح البحث نفسه: «علاج جلد الوزة في منطقة البكيني».','غير مسجل كفورمات إعلان: لا يوجد فيديو أو صورة أو نص إعلاني موصوف. المسجل فقط اقتراح من Google Egypt autocomplete (suggestqueries.google.com، hl=ar، gl=eg) بوسم SEARCH_LANGUAGE عن الكلمة المتتبعة «علاج جلد الوزة».','غير مسجل: لا يوجد عرض أو سعر أو خصم أو منتج محدد مذكور. المسجل فقط أن الموضوع ضمن روتين KP الحالي للجسم وليس منتجاً جديداً.','غير مسجلة: لا يوجد تاريخ بدء إعلان أو مدة تشغيل مسجلة. المسجل فقط تاريخ الرصد 2026-11-19 ومسح 2026-11-19 01:29 EET، وأن الاقتراح لم يظهر في اللقطة السابقة 2026-11-18 23:11 UTC وحل محل «علاج جلد الوزة في الوجه».','غير مثبت بالأداء: لا توجد أرقام أداء أو نجاح مسجلة. كاستنتاج فقط، قوة الإشارة المحتملة تأتي من تحديدها منطقة جسم بعينها بدل بحث عام عن جلد الوزة، ما يعكس نية بحث أكثر تخصصاً وخصوصية وملاءمة مباشرة لروتين KP للجسم الحالي.','أوضح ضعف: لا توجد مادة إعلانية قابلة للتحليل أصلاً — لا منافس ولا كرييتيف ولا عرض ولا دليل أداء — والظهور جديد في لقطة واحدة وحل محل اقتراح آخر، ما يجعل إشارة autocomplete عرضة للتقلب، إضافة إلى حساسية المنطقة وارتفاع مخاطر الادعاء الطبي وقيود المنصات.',replace('اختبر: محتوى تعليمياً آمناً يجيب عن نية البحث حسب منطقة الجسم ضمن روتين KP الحالي، بلغة عناية وروتين دون وعد بالعلاج أو نتيجة طبية، وقِس تفاعله مقابل محتوى KP العام للجسم.\nتبنّ: تتبّع لغة البحث حسب المنطقة كمدخل لتقسيم الزوايا، بدل افتراض زاوية واحدة لكل الجسم.\nتجنّب: نسخ عبارة البحث كادعاء إعلاني حرفي، وأي صور أو لغة محرجة أو وعود خاصة بمنطقة حساسة، وراجع ملاءمتها لسياسات المنصات قبل أي إعلان.\nاختبر بحذر: صياغتين محترمتين وخصوصيتين للمحتوى/الإعلان حول المنطقة الحساسة مقابل صياغة جسم عامة، دون مقارنات باسم براند ودون ادعاءات طبية.\nراقب قبل التوسع: أعد مسح autocomplete في لقطات لاحقة للتحقق من استمرار الاقتراح، ولا تبنِ حملة كاملة على ظهور واحد متقلب.','\n',char(10)),1795063868735,'','','','');
INSERT INTO competitor_ad_analyses VALUES(19,15,'غير محدد من التسجيل','زبدة الشيا للبشرة تحديداً — زاوية فائدة/استخدام المكوّن للبشرة، بدلاً من زاوية الأصالة؛ فالاقتراح الجديد حلّ محل «زبدة الشيا الاصلية» في نتائج الإكمال التلقائي.','غير مسجل كهوك إعلاني؛ العبارة الوحيدة المسجلة هي اقتراح البحث «زبدة الشيا للبشرة»، ولا يوجد نص إعلان أو افتتاحية مسجلة.','غير مسجل كفورمات إعلان؛ المسجل فقط اقتراح إكمال تلقائي من Google Egypt (suggestqueries.google.com، hl=ar، gl=eg) للكلمة المتتبعة «زبدة الشيا».','غير مسجل؛ لا يوجد عرض أو سعر أو دعوة لاتخاذ إجراء في التسجيل.','مدة التشغيل غير مسجلة؛ المسجل فقط تاريخا رصد: لقطة سابقة في 2026-11-18 23:11 UTC لم يظهر فيها الاقتراح، ومسح في 2026-11-19 01:29 EET ظهر فيه، وتاريخ الرصد 2026-11-19.','مستنتج وليس أداءً مسجلاً: يرجّح أن يعمل لأنه يعكس طلب بحث محدداً على استخدام زبدة الشيا للبشرة، لا بحثاً عاماً عن المكوّن أو أصالته، فيطابق نية أوضح لدى الباحث؛ ولا توجد أرقام أداء مسجلة تؤكد نجاحه.','الأوضح أنه لا يوجد إعلان مسجل أصلاً — مجرد إشارة لغة بحث عامة عن مكوّن شائع بلا عرض أو دليل أو تمييز لعلامة، ولا يحدد مشكلة بشرة محددة، فيسهل تقليده من أي منافس.',replace('اختبر محتوى يطابق عبارة البحث المسجلة حرفياً «زبدة الشيا للبشرة» كسؤال/عنوان، واربطه بمنتجات زيرا الحالية التي تحتوي زبدة الشيا، دون ادعاء طبي.\nحدّد سياق استخدام واحداً قابلاً للاختبار في كل قطعة محتوى بدل وعود عامة عن البشرة، مثل طريقة الاستخدام ضمن روتين العناية.\nاختبر زاوية الفائدة للبشرة مقابل زاوية الأصالة، وقس الفرق من خلال الاستفسارات والبحث الداخلي لا بمقارنة براند منافس.\nتجنّب النسخ الأعمى للاقتراح كشعار؛ أضف ما ينقصه: المكوّنات وطريقة الاستخدام وما يمكن توقعه بشكل واقعي.\nلا تعتبر ظهور الاقتراح مرة واحدة اتجاهاً ثابتاً؛ تتبّع استمراره في لقطات لاحقة قبل توسيع الاستثمار في هذه الزاوية.','\n',char(10)),1795064453695,'','','','');
INSERT INTO competitor_ad_analyses VALUES(20,16,'Urban Ducks','المسجل تاريخياً: تموضع حول سكراب القهوة/البرتقال بخطاب السيلوليت، مؤكد من مقال Source Beauty بتاريخ 14 نوفمبر 2023. أما في تشكيلة Bloom الحالية المسجلة بتاريخ 2026-11-18 فهذه الزاوية غائبة عملياً لأن سكرابي القهوة/البرتقال غير موجودين، والظاهر فقط هو ترطيب الجسم عبر المرطب واللوشن وزبدة الجسم دون خطاب سيلوليت موثق في القائمة الحالية.','غير مسجل — لا يوجد عنوان أو نص هوك موثق في التسجيل؛ المصدر المسجل هو قائمة منتجات متجر وليس إبداعاً إعلانياً.','غير مسجل كإعلان فيديو أو صورة أو نص إعلاني؛ المسجل فقط هو صفحة تشكيلة على موقع Bloom Pharmacy (Collection) بزحف 2026-11-18 23:46 UTC، وليس فورمات إعلان موثق.','المسجل على Bloom: مرطب Liquid Silk Body Moisturizer 250 مل بـ 255 EGP بدل 300 EGP (خصم 15%)؛ لوشن Chocolate Cookies 120 مل بـ 180 EGP بعد أن كان 170 EGP في لقطة 2026-11-18 (زيادة 10 EGP)؛ زبدة جسم Strawberry Vanilla Shake 120 مل بـ 210 EGP بدون تغيير؛ ولا منتج جديد ولا عرض موسمي جديد مسجل، وسكرابا القهوة/البرتقال وزيت الجسم غائبان من تشكيلة Bloom الحالية.','غير مسجلة — لا يوجد تاريخ بدء أو مدة تشغيل مذكورة؛ التواريخ المسجلة فقط هي زحف Bloom في 2026-11-18 23:46 UTC وتاريخ الرصد 2026-11-19 ومقال Source Beauty في 14 نوفمبر 2023، وهي ليست مدة تشغيل إعلان.','لا توجد أرقام أداء مسجلة تثبت النجاح، فهذا استنتاج وليس نتيجة موثقة: العنصر الأوضح احتمالاً للعمل هو خصم المرطب بسعر مرجعي واضح (300 إلى 255 EGP) وثبات سعر زبدة الجسم عند 210 EGP، لكن غياب منتج البطل المرتبط بالزاوية الأصلية يضعف على الأرجح استمرارية الرسالة.','نقطة الضعف الأوضح: غياب سكرابي القهوة/البرتقال بخطاب السيلوليت وزيت الجسم تماماً من تشكيلة Bloom الحالية رغم أنهما أساس التموضع المسجل، مع زيادة سعر اللوشن 10 EGP في نفس وقت خصم 15% على المرطب، ما يشتت رسالة القيمة؛ والغياب موثق على Bloom فقط ولم يُتأكد كسحب منتج لأن Zynah لم تُفحص صفحةً صفحةً.',replace('تتبنى لزيرا: التحقق من توفر المنتج البطل في كل قناة بيع معلنة قبل إطلاق أي زاوية، واختبار الحملة فقط عندما يكون المنتج متاحاً فعلاً.\nتتجنب لزيرا: رفع سعر منتج في نفس فترة تقديم خصم على منتج آخر، لأن ذلك يشتت رسالة القيمة ويصعب فهم العرض.\nتختبر لزيرا: خصماً واحداً واضحاً بسعر مرجعي معلن (سعر قبل/بعد) على منتج ترطيب واحد، وقياس أثره على التحويل بدل توزيع الخصومات على عدة منتجات.\nتتبنى لزيرا: تثبيت سعر منتج مرجعي معروف خلال فترة الاختبار ليكون مرجعاً سعرياً واضحاً للعميل.\nتتجنب لزيرا: بناء الرسالة على أي ادعاء طبي أو نتيجة علاجية؛ واختبار بدلاً من ذلك زوايا قابلة للإثبات مثل الترطيب والملمس والرائحة وتجربة الاستخدام.','\n',char(10)),1795064515584,'','','','');
INSERT INTO competitor_ad_analyses VALUES(21,17,'غير محدد من التسجيل','مسجَّل كإشارة زاوية تعليمية فقط، وليس كإعلان مؤكد: الفرق بين السيلوليت والليبوديما، ومتابعة مَن هو ضياء العوضي وماذا يقول عن علاج السيلوليت.','غير مسجل كهوك إعلاني؛ العبارتان المسجلتان فقط هما «سيلوليت و ليبوديما» و«علاج السيلوليت ضياء العوضي»، ولا يوجد نص هوك موصوف في التسجيل.','غير مسجل كفورمات إعلاني؛ المصدر المسجل فقط هو لغة بحث: Google Egypt autocomplete (suggestqueries.google.com, hl=ar, gl=eg) لكلمتي «سيلوليت» و«علاج السيلوليت».','غير مسجل — لا يوجد عرض أو سعر أو دعوة لاتخاذ إجراء موصوف في التسجيل.','غير مسجلة — تاريخ الرصد المسجل فقط هو 2026-11-19 في مسح 01:51 EET، ولا يوجد تاريخ بدء إعلان أو مدة تشغيل مسجلة.','لا توجد أرقام أداء مسجلة تثبت النجاح؛ المستنتج فقط: ظهور «سيلوليت و ليبوديما» في اقتراحات البحث يدل على نية بحث تعليمية قائمة — جمهور يريد التمييز قبل العلاج — فالزاوية التعليمية تلتقط طلباً موجوداً بدل خلقه، وارتباط اسم صانع محتوى بالبحث يشير إلى تفضيل شرح بشري مبسط.','الأوضح: الملاحظة ليست إعلاناً ولا تحتوي محتوى أو عرضاً أو دليل أداء مسجلاً؛ والاعتماد على اسم شخص آخر وعلى تمييز طبي دقيق دون محتوى موثق يعرّض زيرا لخطر نسخ اسم الغير وادعاءات طبية غير مثبتة.',replace('اختبري لزيرا محتوى تعليمياً يشرح الفرق العام بين السيلوليت والليبوديما بلغة مبسطة دون تشخيص أو وعد علاجي، وقيسي الحفظ/التفاعل مقابل محتوى علاجي مباشر.\nلا تنسخي اسم «ضياء العوضي» في هوك أو عنوان؛ استخدميه فقط كمؤشر لغة بحث مسجل، وابني سلطة زيرا الخاصة بمحتوى موثق.\nاستخدمي عبارات البحث المسجلة حرفياً كأسئلة AEO في صفحة أسئلة شائعة: «سيلوليت وليبوديما» و«علاج السيلوليت»، دون ادعاء نتيجة.\nتجنبي أي ادعاء طبي أو مقارنة باسم براند؛ والتزمي بوصف عام وتوجيه لاستشارة مختص عند الشك في الليبوديما.\nكرري مسح autocomplete بنفس الكلمات والمصدر قبل الاستثمار في سلسلة كاملة، لأن الرصد الحالي لحظة واحدة فقط في 19 نوفمبر 01:51 EET.','\n',char(10)),1795065023658,'','','','');
INSERT INTO competitor_ad_analyses VALUES(22,18,'غير محدد من التسجيل','مسجل: نية شرائية سعرية مباشرة — «سعر كريم جلد الوزة» و«زبدة الشيا بكام» — مع نية علاجية قوية — «علاج جلد الوزة نهائيا» و«علاج جلد الوزة والشعر تحت الجلد».','غير مسجل: لا يوجد نص إعلان أو هوك موصوف في التسجيل؛ أقرب صيغة مسجلة هي سؤال السعر نفسه («سعر كريم جلد الوزة» / «زبدة الشيا بكام»)، وليست هوك إعلاني مثبت.','غير مسجل كفورمات إعلان (لا فيديو ولا صورة ولا كاروسيل موصوفة)؛ المسجل فقط اقتراحات إكمال تلقائي من Google Egypt (suggestqueries.google.com، hl=ar، gl=eg) لكلمات: كريم جلد الوزة، زبدة الشيا، علاج جلد الوزة.','غير مسجل: لا سعر ولا خصم ولا باقة ولا عرض موصوف في التسجيل؛ المسجل فقط استفسار الباحثين عن السعر قبل الشراء.','تاريخ الرصد المسجل: 2026-11-19 الساعة 01:51 EET؛ تاريخ بدء أو مدة تشغيل غير مسجلة.','لم يُسجل أي رقم أداء يثبت نجاح إعلان؛ مستنتج: قوة الإشارة المسجلة تأتي من نية شرائية صريحة — السؤال عن السعر يأتي قبل الشراء — ومن تطابق زاوية «جلد الوزة + الشعر تحت الجلد» مع ما يذكره التسجيل عن سكراب زيرا، ما يجعل الطلب جاهزاً للتحويل إذا وجد إجابة سعر واضحة.','الأوضح: الاستفسارات المسجلة عامة بلا براند ولا عرض ولا تمييز، فالمنافسة فيها سعرية بحتة وقابلة للسرقة من أي منافس؛ كما أن صيغة «علاج نهائيا» ترفع توقعاً لا يمكن ضمانه وتقترب من ادعاء طبي، فهي نقطة ضعف إذا استُخدمت كوعد إعلاني.',replace('اختبر صفحة منتج/أسئلة شائعة AEO تجيب مباشرة عن «سعر كريم جلد الوزة» و«زبدة الشيا بكام» بالسعر الحالي وما يشمله الروتين، وقِس ظهورها ونقراتها بدلاً من افتراض النجاح.\nاختبر زاوية محتوى مسجلة: «جلد الوزة + الشعر تحت الجلد» مع السكراب، بصيغة روتين وتجربة استخدام، لا بصيغة علاج.\nتجنّب نسخ وعد «علاج نهائيا» وأي ادعاء طبي؛ استخدم لغة قابلة للاختبار عن المظهر والملمس والاستمرارية في الروتين.\nتجنّب المنافسة على السعر وحده؛ اختبر توضيح القيمة (الحجم، المكونات، طريقة الاستخدام) بجانب السعر في نفس الصفحة.\nتجنّب أي مقارنة باسم براند منافس؛ اختبر إجابات بحثية محايدة تعتمد على السؤال نفسه والمنتج دون ذكر منافسين.','\n',char(10)),1795065065662,'','','','');
INSERT INTO competitor_ad_analyses VALUES(23,19,'Alejon — المنافس المطابق للبروفايل؛ وظهرت أيضاً Mixa وEveline وNovera في نفس اقتراحات البحث المسجلة','يوريا 10% و20% للجلد الجاف الخشن وجلد الوزة — تموضع صيدلي','عبارة البحث المسجلة حرفياً: «كريم اليجون يوريا للجسم» — وليست نص إعلان إبداعي مسجلاً','اقتراحات بحث Google Egypt autocomplete (suggestqueries.google.com، hl=ar، gl=eg) لكلمتي «يوريا» و«كريم يوريا للجسم»؛ لا يوجد فورمات إعلان فيديو أو صورة موصوف في التسجيل','Urea Cream 10% — 200ml بسعر 380 EGP لدى صيدليات الفؤاد؛ تركيز 20% مذكور في التموضع دون سعر أو حجم مسجل له','غير مسجلة — لا يوجد تاريخ بدء أو مدة تشغيل مذكورة؛ المسجل فقط تاريخا الرصد: لقطة 18 نوفمبر 23:32 UTC ومسح 19 نوفمبر 01:51 EET','مستنتج وليس مسجلاً، ولا توجد أرقام أداء مسجلة: عبارة البحث تجمع اسم البراند مع «يوريا» و«للجسم»، ما يشير إلى نية بحث محددة، ووضوح التركيز والاستخدام (جلد جاف خشن وجلد الوزة) والتوفر الصيدلي يجعل العرض سهل الفهم والقرار.','الأوضح من التسجيل نفسه: نفس اقتراحات اليوريا تُظهر Mixa وEveline وNovera بنفس الصيغة، فالظهور بالاسم ليس حصرياً، ولا يوجد في التسجيل ميزة موصوفة تميّز عرض 10% / 200ml عنهم سوى التركيز والحجم والسعر.',replace('اختبر استهداف نية البحث العامة «كريم يوريا للجسم» بمحتوى يوضح التركيز والاستخدام دون ادعاء طبي ودون ذكر براند منافس.\nاختبر محتوى AEO يجيب عن أسئلة اليوريا للجسم والجلد الجاف الخشن وجلد الوزة بصيغة واضحة عن التركيز والحجم والاستخدام العام دون وعود علاجية.\nتبنَّ وضوح العرض: التركيز + الحجم + السعر + مكان التوفر، واختبر أي ترتيب لها يزيد وضوح القرار.\nتجنب نسخ صيغة «براند + يوريا» أو المزايدة على أسماء منافسين؛ ركّز على الكلمات العامة ونية الاستخدام.\nاختبر رصداً دورياً بنفس كلمات اليوريا والتواريخ لقياس ظهور زيرا، دون افتراض أداء من ظهور مرة واحدة.','\n',char(10)),1795065639563,'','','','');
INSERT INTO competitor_ad_analyses VALUES(24,20,'غير محدد من التسجيل','علاج جلد الوزة في المنزل — حل منزلي بدلاً من العيادة/الليزر، حسب لغة البحث المسجلة','«علاج جلد الوزة في المنزل» — هوك مباشر بلغة الباحث نفسه كما ظهر في اقتراح البحث','غير مسجل كفورمات إعلان؛ المسجل فقط أنه اقتراح بحث في Google Egypt autocomplete ‏(suggestqueries.google.com، hl=ar، gl=eg)‏، وليس فيديو أو صورة أو نص إعلان موصوف','غير مسجل؛ لا يوجد عرض منافس مذكور في التسجيل. المذكور فقط تموضع زيرا: روتين KP منزلي متكامل بسعر 799 ج، وهو ليس عرضاً في إعلان مسجل','غير مسجلة كمدة تشغيل أو تاريخ بدء إعلان؛ المسجل فقط تاريخ الرصد 2026-11-19، وظهور الاقتراح لأول مرة في مسح 02:12 EET ولم يكن في لقطة 01:51 EET في اليوم نفسه','لا توجد أرقام أداء مسجلة، فلا يمكن تأكيد النجاح. المرجح — كاستنتاج وليس كحقيقة مسجلة — أنه قوي لغوياً لأنه يطابق نية بحث صريحة عن حل منزلي، ويستبعد ضمنياً خيار العيادة/الليزر، ويتطابق مع روتين منزلي جاهز لدى زيرا','ليس إعلاناً مثبتاً ولا دليل أداء؛ مجرد اقتراح بحث جديد ظهر في مسح واحد، وصيغته عامة وسهلة النسخ من أي منافس، ولا تحمل تمييزاً أو إثباتاً أو عرضاً مسجلاً، كما أنه لا يخلق فرصة منتج جديدة لزيرا حسب التسجيل',replace('اختبر الهوك حرفياً «علاج جلد الوزة في المنزل» في عنوان أو أول سطر لمحتوى/إعلان روتين KP الحالي (799 ج)، وقِس مقابل صياغة زيرا الحالية قبل التعميم.\nاعتمد زاوية «في المنزل مقابل العيادة/الليزر» في التموضع والرسالة، دون ادعاءات طبية بأن الروتين يعالج أو يشفي.\nلا تطلق منتجاً جديداً لهذا الاقتراح؛ التسجيل يقول إنه ليس مشكلة/منتجاً جديداً لا تحمله زيرا، فالاستثمار يكون في الرسالة لا في منتج جديد.\nتابع الاقتراح في مسوح لاحقة للتحقق من استمراره قبل زيادة الإنفاق، لأنه ظهر لأول مرة في مسح 02:12 EET ولم يكن في 01:51 EET ولا توجد مدة تشغيل مسجلة.\nتجنب النسخ الأعمى والمقارنات باسم أي براند والادعاءات الطبية؛ استخدم لغة البحث كإلهام للصياغة فقط (AEO).','\n',char(10)),1795065675659,'','','','');
INSERT INTO competitor_ad_analyses VALUES(25,21,'غير محدد من التسجيل','غير مسجلة كزاوية إعلان؛ المسجل رصد بحث فقط: نية البحث عن «كريم يوريا للجسم»، والجديد الحقيقي المسجل هو كتابة urea بالحروف اللاتينية لأول مرة.','غير مسجل؛ لا يوجد هوك إعلاني موصوف في التسجيل، والمسجل فقط عبارة البحث «كريم urea للجسم» كصيغة بحث لا كهوك.','غير مسجل كفورمات إعلان؛ المسجل فقط مصدر الرصد: اقتراحات Google Egypt autocomplete (suggestqueries.google.com, hl=ar, gl=eg) للكلمة المتتبعة «كريم يوريا للجسم».','غير مسجل؛ لا يوجد عرض سعر/خصم/حزمة موصوف في التسجيل، والمسجل فقط أن الصيغ ضمن منتج موجود عند زيرا (لوشن يوريا 25%) دون عرض مسجل.','مدة تشغيل الإعلان غير مسجلة؛ المسجل فقط تاريخ الرصد 2026-11-19، ومسح 02:12 EET مقابل لقطة 01:51 EET في اليوم نفسه، وهذا فارق بين لقطتي رصد وليس مدة تشغيل إعلان.','غير مثبت من التسجيل — لا توجد أرقام أداء تثبت نجاح إعلان؛ المستنتج بحذر فقط هو أن نية «كريم يوريا للجسم» متكررة بصيغ متعددة (أرقام 10/20 و«أفضل/أحسن»)، وظهور «urea» باللاتينية لأول مرة يوسّع الوصول لشريحة تكتب المصطلح بالإنجليزية، وهذا اتساع لغوي في البحث وليس دليل أداء إعلاني.','الأوضح: لا يوجد إعلان أو منافس محدد مسجل أصلاً، والاعتماد على autocomplete فقط لا يثبت حجم طلب أو نية شراء؛ كما أن 3 من 4 صيغ ليست طلباً جديداً بل متغيرات صياغة لنفس النية، فتفسيرها كفرصة جديدة يضخّم الفرصة، والصيغة اللاتينية وحدها جديدة ولم تُثبت استمراريتها من لقطتين في يوم واحد.',replace('اختبر إضافة «urea» باللاتينية بجانب «يوريا» في عنوان/وصف محتوى زيرا عن لوشن يوريا 25% (AEO/بحث)، دون ادعاء طبي ودون مقارنة ببراند.\nوحّد صيغ «١٠/10» و«٢٠/20» و«احسن/افضل» تحت نية واحدة موجودة أصلاً ولا تبنِ عليها منتجاً أو حملة منفصلة؛ المسجل يقول إنها متغيرات صياغة لا طلب جديد.\nتجنب نسخ الصيغ حرفياً كادعاء أن لوشن زيرا بتركيز 10 أو 20؛ المسجل أن منتج زيرا هو لوشن يوريا 25%، فوضّح التركيز الفعلي فقط.\nاختبر قبل التوسع: راقب استمرار ظهور «كريم urea للجسم» في مسوح لاحقة، لأن المسجل لقطتان في 2026-11-19 بفارق 21 دقيقة فقط ولا يثبت استمرارية.\nلا تبنِ فرصة منتج جديدة من هذه الملاحظة؛ المسجل صراحة أن كل الصيغ ضمن منتج موجود عند زيرا، فركّز على تغطية لغوية/بحثية للمنتج الحالي.','\n',char(10)),1795066277735,'','','','');
INSERT INTO competitor_ad_analyses VALUES(26,22,'Melano Pharma','مسجّل: زاوية عرض موسمي للقيمة في White Friday / 11/11 — Buy 1 Get 1 يخفض السعر الفعّال للوحدة؛ مستنتج: ليست زاوية منتج جديد أو روتين متكامل، فلا منتج جديد لجلد الوزة/سيلوليت ولا روتين متكامل مسجّل.','مسجّل: بانر «البيضاء الجمعة عروض SALE 11/11 — لفترة محدودة فقط» مع شارة Buy 1 Get 1 على Uremel 20% في شبكة العرض؛ أي نص هوك آخر غير مسجّل.','مسجّل: بانر صفحة رئيسية على المتجر + بطاقة منتج في شبكة عرض بشارة Buy 1 Get 1 وسعر 350 EGP؛ صيغة الإعلان (فيديو/صورة ثابتة/UGC) ومنصة الإعلان غير مسجّلة.','مسجّل: Buy 1 Get 1 على Uremel 20% بسعر 350 EGP (سعر فعّال 175 EGP للوحدة)، وUremel 10% ظاهر بـ 220 EGP مع شارة Buy 1 Get 1؛ ملاحظة عدم يقين مسجّلة: صفحة المنتج نفسها لا تذكر B1G1 والتطبيق الفعلي للعرض على Uremel يحتاج تحققًا. السعر الأساسي ثابت 350 EGP والتركيبة نفسها (يوريا 20% + ساليسيليك 2%).','مدة التشغيل غير مسجّلة — لا تاريخ بدء أو مدة أو تاريخ انتهاء مذكور؛ المسجّل فقط: لم يُرصد عرض أو خصم في لقطة 2026-11-18 21:32 UTC، ورُصد العرض في زحف 2026-11-19 00:30 UTC / 02:30 EET، والبانر يقول «لفترة محدودة فقط» دون مدة محددة مسجّلة.','مستنتج، ولا أرقام أداء مسجّلة: العرض واضح وقابل للحساب فورًا (350 EGP لوحدتين، أي 175 EGP للوحدة)، والسعر الأساسي ثابت فيُفهم التوفير دون خصم سعري مباشر، ويرتبط بمناسبة تسوّق موسمية مع إلحاح عام؛ التقييم المسجّل 4.9/5 (8 مراجعات) قد يدعم الثقة لكنه عينة صغيرة.','مسجّل وواضح: صفحة المنتج نفسها لا تذكر B1G1، والتطبيق الفعلي للعرض على Uremel يحتاج تحققًا — مستنتج: هذا التناقض بين شبكة العرض وصفحة المنتج قد يسبب ارتباكًا أو شكًا عند الشراء ويضعف تحويل العرض رغم وضوح الشارة.',replace('تبنَّ واختبر عرض قيمة واحدًا واضحًا وقابلًا للحساب (مثل Buy 1 Get 1 مع السعر الفعّال للوحدة مكتوبًا صراحة)، ولا تكتفِ بشارة دون سعر فعّال.\nتجنّب التناقض المسجّل هنا: وحّد صياغة العرض وشروطه في البانر وشبكة العرض وصفحة المنتج وصفحة الدفع قبل الإطلاق، واختبرها بنفسك.\nاختبر إلحاحًا محددًا بتاريخ/مدة انتهاء معلنة بدل «لفترة محدودة فقط» وحدها، حتى يمكن قياس أثر الإلحاح.\nلا تعتمد على عينة تقييمات صغيرة كدليل وحيد؛ اختبر عرض مراجعات أكثر تنوعًا دون ادعاءات طبية.\nاختبر مقابل خصم الوحدة الواحدة: عرض قيمة لمنتج قائم مقابل روتين متكامل، دون نسخ العرض أعمى ودون مقارنة باسم براند منافس.','\n',char(10)),1795066314139,'','','','');
INSERT INTO competitor_ad_analyses VALUES(27,23,'Mixa وEveline','ربط اسم البراند مباشرة بمكوّن اليوريا واستخدام الجسم في لغة البحث: «كريم [براند] للجسم يوريا» بدلاً من المنافسة على «يوريا» كمصطلح عام فقط — مسجّل كاقتراحات بحث، وليس كرسالة إعلانية موصوفة.','صيغ الاقتراحات المسجلة نفسها: «كريم mixa للجسم يوريا» و«كريم ايفلين للجسم يوريا»، إلى جانب صيغ عامة جديدة مثل «كريم ترطيب للجسم يوريا» و«كريم في يوريا للجسم» — لا يوجد هوك إعلاني مصوّر أو نصي مسجّل غير ذلك.','SEARCH — اقتراحات إكمال تلقائي من Google Egypt (suggestqueries.google.com، hl=ar، gl=eg) لكلمة «كريم يوريا للجسم»؛ ليس إعلان فيديو أو صورة مسجّلاً، ولا يوجد وصف لمحتوى إعلاني.','غير مسجل — لا يوجد عرض أو سعر أو خصم أو دعوة لاتخاذ إجراء مذكورة في التسجيل.','غير مسجلة كمدة تشغيل أو تاريخ بدء؛ المسجّل فقط تاريخ رصد واحد: 19 نوفمبر 2026 الساعة 02:30 EET، وذُكر أن الاقتراحين ظهرا لأول مرة في ذلك المسح.','لا توجد أرقام أداء مسجلة، فلا يمكن تأكيد النجاح؛ التفسير المستنتج فقط: ظهور اسمَي براند في اقتراحات مصطلح عام يشير إلى أن باحثين يربطون اليوريا للجسم بهذين الاسمين ويبحثون بهما، وأن الإكمال التلقائي قد يعزّز هذا الربط ويوجّه بحثاً إضافياً نحوهما، مع استمرار وجود «كريم يوريا ٣٠ للجسم» بما يدل على استمرار الاهتمام باليوريا في البحث.','الضعف الأوضح من التسجيل: المنافسة تتم على مصطلح مكوّن عام («يوريا للجسم») بلا تميّز أو عرض مسجّل، والاقتراح لا يثبت تفضيلاً أو شراءً؛ كما يعتمد على اقتراح بحث غير مملوك وقابل للتغيّر، واستمرار «كريم يوريا ٣٠ للجسم» في القائمة يعني أن جزءاً من الطلب ما زال مرتبطاً بالتركيز لا بالبراند.',replace('اختبار الظهور في لغة بحث اليوريا بصيغ وصفية عامة دون ادعاء طبي ودون ذكر براند منافس: محتوى وصفحات AEO حول «كريم يوريا للجسم» و«كريم ترطيب للجسم يوريا» و«كريم يوريا ٣٠ للجسم»، مع قياس الظهور في الاقتراحات قبل الاختبار وبعده.\nتجنّب نسخ صيغة «براند + يوريا» كادعاء تفوق أو مقارنة باسم براند؛ وبناء ربط زيرا باليوريا عبر محتوى متسق ووصف منتج واضح فقط.\nاختبار أسئلة AEO شائعة حول اليوريا والترطيب وطريقة الاستخدام بصياغة وصفية حذرة دون ادعاءات علاجية.\nمراقبة اقتراحات Google Egypt دورياً بنفس الكلمة وتسجيل التاريخ والوقت وأول ظهور وتغيّر القائمة، بدلاً من الاستنتاج من رصد واحد.\nتجنّب اعتبار اقتراح بحث واحد مؤشر نجاح؛ وربط أي اختبار بمقاييس مسجلة مثل الظهور والنقرات والبحث باسم زيرا قبل التوسع.','\n',char(10)),1795066824129,'','','','');
INSERT INTO competitor_ad_analyses VALUES(28,26,'غير محدد من التسجيل','الاستهداف حسب الاستخدام المحدد: زبدة الشيا للبشرة تحديداً، بدلاً من التركيز العام أو على الأصالة (عبارة «زبدة الشيا الاصلية» خرجت من القائمة حسب التسجيل).','«زبدة الشيا للبشرة» — العبارة نفسها كما ظهرت في اقتراحات الإكمال التلقائي لـ«زبدة الشيا».','اقتراح إكمال تلقائي في بحث جوجل مصر (hl=ar, gl=eg) ضمن مسح لغة بحث؛ لا يوجد فورمات إعلان مسجل (فيديو/صورة/نص إعلاني).','غير مسجل — لا يوجد عرض أو سعر أو خصم أو دعوة لاتخاذ إجراء في الملاحظة؛ هي إشارة بحث فقط.','غير مسجلة — رصد واحد فقط بتاريخ 2026-11-19 الساعة 03:49 EET، ولا يوجد تاريخ بدء أو مدة تشغيل/استمرارية مسجلة.','[مستنتج، وليس أداءً مسجلاً] يرجح أن العبارة تعمل كإشارة نية أوضح لأنها تحدد الاستخدام (للبشرة) بدل البحث العام، فالمحتوى المطابق لها حرفياً قد يكون أسهل اكتشافاً في البحث؛ ولا توجد أرقام أداء مسجلة تثبت نجاحاً إعلانياً.','الأوضح: أنها ملاحظة لحظية واحدة من مسح واحد، لا تثبت استمرارية الاتجاه أو نية شراء أو أداء إعلاني، والعبارة والمكوّن عامان وغير حصريين، فلا تميّز برانداً بذاتها.',replace('اختبر محتوى أورجانيك (AEO/أسئلة شائعة) بعبارة «زبدة الشيا للبشرة» حرفياً، مع توضيح استخدامها للبشرة مقابل الجسم والشعر، دون ادعاءات طبية.\nلا تبنِ منتجاً جديداً على هذه الإشارة وحدها؛ التسجيل يقول إن المكوّن موجود عند زيرا أصلاً، فالفرصة في صياغة المحتوى لا في منتج ناقص.\nتابع ظهور العبارة في مسوح لاحقة قبل اعتبارها اتجاهاً ثابتاً، وقارنها بعبارة «زبدة الشيا الاصلية» الخارجة من القائمة.\nتجنب نسخ العبارة كادعاء تميّز أو أصالة، وتجنب أي مقارنة باسم براند؛ استخدمها كإجابة على سؤال استخدام محدد.\nاختبر صفحات/عناوين منفصلة لكل استخدام (للبشرة/للجسم/للشعر) لقياس أيها يجذب بحثاً عضوياً أكثر، دون افتراض نتيجة مسبقة.','\n',char(10)),1795066867308,'','','','');
INSERT INTO competitor_ad_analyses VALUES(29,27,'غير محدد من التسجيل','المسجل: زاوية الأصالة والتمييز بين الأصلي والمغشوش؛ الإشارة المسجلة أن الباحثين يميزون بين زبدة شيا أصلية ومغشوشة، وأن قلق الأصالة واضح في لغة البحث.','المسجل: عبارة البحث نفسها «زبدة الشيا الاصلية» — ظهرت كاقتراح جديد في Google Egypt autocomplete لكلمة «زبدة الشيا».','المسجل: SEARCH — اقتراح إكمال تلقائي من Google Egypt (suggestqueries.google.com، hl=ar، gl=eg)، وليس إعلان فيديو أو صورة مسجلاً؛ لا يوجد محتوى إعلان موصوف في التسجيل.','غير مسجل — لا يوجد سعر أو خصم أو هدية أو عرض مذكور في التسجيل.','غير مسجلة — تاريخ الرصد المسجل فقط هو 2026-11-19، مسح 04:50 EET، وظهر الاقتراح لأول مرة في ذلك المسح بديلاً عن «زبدة الشيا للبشرة»؛ لا يوجد تاريخ بدء أو مدة تشغيل مسجلة.','لا توجد أرقام أداء مسجلة، فلا يمكن تأكيد نجاح إعلان؛ المستنتج فقط: الإشارة قوية على الأرجح لأنها تطابق قلق أصالة واضحاً لدى الباحثين، وتحول نية البحث المسجل من الاستخدام العام «للبشرة» إلى التحقق من الأصالة قبل الشراء.','الأوضح: الاقتراح عام بلا براند أو منتج أو دليل أصالة أو عرض مسجل مرتبط به، فكلمة «أصلية» وحدها لا تثبت جودة ولا تميز بائعاً عن آخر، ويمكن لأي منافس استهدافها، ولا يوجد محتوى إعلان مسجل لقياس فعاليته.',replace('اختبر لزيرا محتوى AEO يجيب عن «كيف أميز زبدة الشيا الأصلية؟» بمعايير تحقق عملية وشفافة، دون ادعاءات طبية.\nتبنَّ لغة الأصالة في عنوان ووصف المنتج: المصدر وطريقة الاستخلاص وما يمكن للمشتري التحقق منه، بدل الاكتفاء بكلمة «أصلية».\nتجنب ادعاء الأصالة بلا دليل قابل للتحقق، وتجنب أي مقارنة باسم براند منافس.\nاختبر استهداف نية «الأصلية» مقابل «للبشرة» في العناوين والوصف، وقس أيهما يجلب بحثاً ونقراً وتحويلاً لزيرا.\nاختبر إثباتات شفافية غير طبية مثل توضيح المصدر والتغليف وسياسة الإرجاع، بدل نسخ عبارة البحث أعمى.','\n',char(10)),1795067424849,'','','','');
INSERT INTO competitor_ad_analyses VALUES(30,29,'Kyra Naturals','غير مسجلة كزاوية إعلان؛ المسجل فقط تموضع عام: عناية طبيعية مصرية صغيرة (تركيبات معتمدة من UK حسب ادعاء البراند) تُباع عبر Source Beauty، بلوشنات جوز هند وبارادايز بزبدة الشيا وزيت اللوز وشاور جل وباث فيز.','غير مسجل؛ لا يوجد هوك أو نص إعلان موصوف في التسجيل، والمسجل فقط «For orders DM» على إنستجرام.','غير مسجل كفورمات إعلان (فيديو/صورة/كاروسيل)؛ المسجل هو رصد حي لصفحة مجموعة Source Beauty وإنستجرام في 2026-11-19.','حسب لقطة 2026-11-18 (غير قابلة للتأكيد اليوم): Coconut Body Lotion 130ml بـ110 EGP، لوشنات 110، شاور جل 85، باث فيز 100؛ وحالياً 0 منتج مدرج على Source Beauty، فلا عرض نشط مسجل.','غير مسجلة؛ لا تاريخ بدء ولا مدة تشغيل مذكورة في التسجيل. المسجل فقط: فحص حي 2026-11-19 06:30–06:34 EET، وتاريخ رصد 2026-11-19، ولقطة أسعار سابقة بتاريخ 2026-11-18.','لا يوجد دليل مسجل على نجاح إعلان. المستنتج فقط — وليس مسجلاً — أن السعر المنخفض نسبياً (85–110 EGP في اللقطة القديمة) والبيع عبر منصة تجميع قد يسهّلان التجربة الأولى، لكن الاختفاء الكامل الحالي (0 منتج و404) يمنع اعتبار ذلك نجاحاً مستمراً.','الأوضح والمسجل: اختفاء كامل من Source Beauty — 0 منتج بعد وصف قديم بـ39+ منتجاً، ورابط منتج قديم أصبح 404، وبحث «Kyra» يعيد 0 منتج؛ وإنستجرام ما زال موجوداً (11.1K متابع) بلا رابط متجر ويعتمد على «For orders DM» فقط، وسبب الإزالة غير معروف، ولا منتج جديد ولا عرض موسمي مسجل.',replace('تجنّب الاعتماد على قناة بيع واحدة: اختبر لزيرا توفراً احتياطياً ورابط متجر مباشراً واضحاً حتى لا يتحول أي انقطاع إلى اختفاء كامل.\nتبنَّ مراقبة دورية للتوفر والروابط: اختبر تنبيهاً داخلياً لصفحات فارغة أو 404 قبل أن يراها العميل، مع رسالة بديلة واضحة عند نفاد المنتج.\nاختبر نقطة سعر دخول واضحة ومحددة لمنتج واحد بسعر معلن، دون ادعاءات طبية، وقِس أثرها على التجربة الأولى فقط.\nتجنّب التموضع العام «طبيعي» وحده: اختبر لزيرا رسالة تميّز محددة قابلة للقياس في الاستخدام والتجربة، لا وعوداً علاجية.\nتبنَّ استمرارية التواصل عند أي تغيير في التوفر: اختبر تحديثاً يوضح البديل وطريقة الطلب بدل ترك العملاء أمام صفحة فارغة وDM فقط.','\n',char(10)),1795067477053,'','','','');
INSERT INTO competitor_ad_analyses VALUES(31,30,'غير محدد من التسجيل','زبدة الشيا للبشرة تحديداً — تموضع استخدام للبشرة وليس للشعر، وفق عبارة البحث المسجلة «زبدة الشيا للبشرة».','لا يوجد هوك إعلاني إبداعي مسجل؛ العبارة الوحيدة المسجلة هي اقتراح البحث «زبدة الشيا للبشرة».','SEARCH — اقتراح إكمال تلقائي في Google Egypt (suggestqueries.google.com، hl=ar، gl=eg) لكلمة «زبدة الشيا»، وليس إعلان فيديو أو صورة مسجلاً.','غير مسجل — لا يوجد عرض أو سعر أو منتج محدد مذكور في التسجيل.','غير مسجلة كمدة تشغيل إعلان؛ المسجل فقط أول ظهور في مسح 2026-11-19 الساعة 06:49 EET، ولا يثبت تاريخ بدء إعلان أو مدة استمراريته.','المسجل لا يثبت أداءً أو نجاحاً؛ الاستنتاج فقط: العبارة أكثر تحديداً للنية (للبشرة) من عبارة عامة، وحلّت محل «زبدة الشيا الاصلية» في القائمة، ما يشير — استنتاجاً لا قياساً — إلى أن لغة الباحثين تتجه لتحديد الاستخدام، وهو ما يطابق منتجات زيرا الحالية للعناية بالجسم التي تحمل زبدة الشيا كمكوّن.','لا يوجد إعلان أو منافس أو عرض أو دليل تمييز مسجل؛ العبارة عامة وغير مملوكة لأي براند، ولا تثبت نية شراء أو تفضيل منتج، والاعتماد عليها وحدها لا يميز زيرا عن أي منافس يستخدم نفس المكوّن.',replace('اختبر استخدام العبارة الحرفية «زبدة الشيا للبشرة» في عنوان/محتوى صفحة منتجات العناية بالجسم التي تحتوي زبدة الشيا، مع توضيح أنها للبشرة وليست للشعر، وقس الاستجابة بدلاً من افتراضها.\nاختبر محتوى AEO/أسئلة وأجوبة بالعربية المصرية حول استخدام زبدة الشيا للبشرة ضمن منتجات زيرا الحالية، دون ادعاءات طبية.\nتجنب بناء منتج جديد على هذه الملاحظة؛ المسجل يقول صراحة إنها اتجاه لغة بحث وليست فرصة منتج جديدة، وزيرا تحمل المكوّن أصلاً.\nتجنب الاعتماد على عبارة «زبدة الشيا الاصلية» في التموضع؛ المسجل أنها اختفت من اقتراحات 19 نوفمبر، فاختبر البديل المحدد بالاستخدام بدلاً منها.\nلا تنسخ الاقتراح كادعاء إعلاني ولا تقارن ببراند باسم؛ استخدمه كلغة بحث فقط، وميّز زيرا بمنتج/تجربة استخدام محددة قابلة للاختبار.','\n',char(10)),1795068018275,'','','','');
INSERT INTO competitor_ad_analyses VALUES(32,31,'غير محدد من التسجيل','علاج جلد الوزة منطقة-منطقة، حسب التسجيل: «جلد الوزة في الرقبة» و«جلد الوزة في الاندر ارم»، و«علاج جلد الوزة بين الفخذين» و«علاج جلد الوزة في الرجل» و«علاج جلد الوزة في الذراعين»، مع نية كريم للإخفاء/الترطيب/الإزالة.','غير مسجل كهوك إعلاني؛ أقرب صيغ مسجلة قابلة للاختبار فقط هي عبارات البحث نفسها: «جلد الوزة في الرقبة»، «جلد الوزة في الاندر ارم»، «علاج جلد الوزة بين الفخذين»، «علاج جلد الوزة في الرجل»، «علاج جلد الوزة في الذراعين»، و«كريم لاخفاء جلد الوزة» و«كريم ترطيب جلد الوزة» و«كريم يضيع جلد الوزة».','غير مسجل كفورمات إعلان؛ المصدر المسجل فقط هو مسح لغة بحث Google Egypt autocomplete (suggestqueries.google.com، hl=ar، gl=eg)، وليس فيديو أو صورة أو نص إعلان موصوفاً.','غير مسجل؛ لا سعر ولا خصم ولا باقة ولا عرض مذكور في التسجيل، والمسجل فقط نية كريم للإخفاء/الترطيب/الإزالة تحت «كريم جلد الوزة».','غير مسجلة؛ المسجل فقط تاريخ الرصد 2026-11-19 ومسح 07:49 EET مقابل لقطة 07:31 EET، ولا يوجد تاريخ بدء إعلان أو مدة تشغيل مسجلة.','مستنتج وليس أداءً مسجلاً: يطابق نية بحث محددة منطقة-منطقة بدل وعد عام، ويطابق نية كريم واضحة (إخفاء/ترطيب/إزالة)، ما يجعل الرسالة أقرب لما تبحث عنه الباحثات فعلاً حسب عبارات 19 نوفمبر المسجلة.','الأوضح من التسجيل: الرسالة عامة وقابلة للنسخ، فكل المناطق والعبارات ضمن روتين KP الحالي ولا فرصة منتج جديدة مسجلة، وصيغة «يضيع» توحي بوعد إزالة يصعب إثباته بدون ادعاء طبي، ولا يوجد تمييز أو أداء مسجل.',replace('اختبر زوايا محتوى/إعلان منفصلة لكل منطقة مسجلة (الرقبة، الأندر آرم، بين الفخذين، الرجل، الذراعين) بدل رسالة عامة واحدة عن جلد الوزة.\nاستخدم لغة البحث المسجلة حرفياً في العناوين القابلة للاختبار، خصوصاً «كريم ترطيب جلد الوزة» و«كريم لاخفاء جلد الوزة».\nتجنب وعد «يضيع/يزيل» كادعاء طبي أو نهائي؛ صِغ الرسالة حول الترطيب وتحسين المظهر بدون ادعاءات طبية وبدون مقارنة باسم براند.\nلا تبنِ منتجاً جديداً على هذه الملاحظة؛ التسجيل يقول إنها ضمن نطاق روتين KP الحالي للجسم، فاربط المناطق الجديدة بالروتين الحالي.\nاختبر الترطيب مقابل الإخفاء كزاويتين مختلفتين، ولا تنسخ الصيغ أعمى؛ فهي لغة بحث عامة غير مسجلة كأداء إعلان.','\n',char(10)),1795068070465,'','','','');
INSERT INTO competitor_ad_analyses VALUES(33,32,'غير محدد من التسجيل','زاوية تعليمية معرفية مسجلة: «استخدامات ملح سيوة» عموماً وللبشرة/الجسم، وليست زاوية شراء مباشرة — نية معرفية جديدة ظهرت لأول مرة في مسح 19 نوفمبر 07:49 EET.','غير مسجل — لا يوجد هوك إعلان موصوف في التسجيل؛ العبارة المسجلة الوحيدة هي استعلام البحث «استخدامات ملح سيوة».','غير مسجل — المصدر المسجل هو مسح Google Egypt autocomplete (suggestqueries.google.com، hl=ar، gl=eg) وليس فورمات إعلان؛ لا يوجد فورمات إعلان موصوف في التسجيل.','غير مسجل كعرض إعلان — المنتج الوحيد المذكور في الملاحظة هو سكراب ملح سيوة 390 ج عند زيرا كمكوّن بطل، وليس عرض منافس مسجلاً.','غير مسجلة — التاريخ الوحيد المسجل هو تاريخ الرصد 2026-11-19 في مسح 07:49 EET وظهور العبارة لأول مرة فيه؛ لا تاريخ بدء إعلان ولا مدة تشغيل مسجلة.','مستنتج، وليس أداءً مسجلاً: يعمل على الأرجح لأنه يطابق لغة بحث فعلية ظهرت لأول مرة في المسح («استخدامات ملح سيوة») ونية معرفية واسعة، فيجيب سؤالاً عاماً قبل الشراء ويربطه بمكوّن بطل عند زيرا، بدل الدفع المباشر للشراء.','الأوضح: النية معرفية لا شرائية — الباحثون يسألون عن الاستخدامات عموماً، فالتعليم وحده قد يجذب قرّاءً بلا نية شراء، كما أن باقي الصيغ الجديدة في نفس الكلمة سياحية أو صياغة، ولا فرصة منتج جديدة مسجلة، ولا يوجد دليل أداء أو منافس مسجل للتحقق.',replace('تبنَّ: أنشئ محتوى AEO يجيب مباشرة عن «استخدامات ملح سيوة» للبشرة/الجسم بنفس صياغة البحث، مع ربط واضح بسكراب ملح سيوة 390 ج دون ادعاءات طبية.\nاختبر: قارن محتوى تعليمياً يجيب عن الاستخدامات ثم يقترح السكراب، مقابل صفحة منتج مباشرة، لقياس أيهما يحوّل نية معرفية إلى شراء.\nتجنّب: لا تعامل «ملح صخرى سيوة» و«ملح واحة سيوة» و«بحيرة/كهف ملح سيوة» كنية شراء؛ المسجل أنها متغيرات صياغة أو سياحة، وليست لغة شراء.\nتجنّب النسخ الأعمى: لا يوجد منافس أو إعلان مسجل هنا، فلا تنسخ هوكاً أو فورماتاً غير موصوف؛ ابنِ على لغة البحث المسجلة فقط.\nاختبر: أضف سؤالاً شائعاً واحداً بصيغة «ما استخدامات ملح سيوة؟» وإجابة موجزة غير طبية، ثم دعوة تجريبية للسكراب، وراقب ظهوره في مسوح بحث لاحقة قبل التوسع.','\n',char(10)),1795068631349,'','','','');
INSERT INTO competitor_ad_analyses VALUES(34,33,'غير محدد من التسجيل','الزاوية المسجلة: طلب تجربة شخصية حقيقية قبل الشراء — «تجربتي» لزبدة الشيا للوجه والشعر، بدلاً من وصف المنتج.','لا يوجد نص هوك إعلاني مسجل؛ أقرب صيغ مسجلة يمكن أن تعمل كهوك هي عبارات البحث نفسها: «زبدة الشيا للوجة تجربتي» و«زبدة الشيا للشعر تجربتي».','غير مسجل — التسجيل مصدره Google Egypt autocomplete (اقتراحات بحث) فقط، ولا يصف فورمات إعلان (فيديو/صورة/نص).','غير مسجل — لا يوجد عرض إعلاني (سعر/خصم/حزمة) في التسجيل؛ «زبدة الشيا بكام» وردت كسؤال بحث فقط، وليست عرضاً.','غير مسجلة — لا يوجد تاريخ بدء أو مدة تشغيل في التسجيل؛ تاريخ الرصد الوحيد هو 2026-11-19 في مسح 07:49 EET، وظهور «تجربتي» فيه لأول مرة حسب التسجيل، وهذا رصد بحث وليس مدة تشغيل إعلان.','استنتاج من الإشارة المسجلة فقط، وليس رقم أداء مسجل: يطابق نية بحث ما قبل الشراء — الباحثات يطلبن تجربة شخص قبل الشراء، والتسجيل يشير إلى أن تجارب/ريفيوهات حقيقية لزبدة الشيا أقوى من وصف المنتج، لأنها تخفف التردد قبل الشراء.','الأوضح: الإشارة بحثية فقط ولا يوجد إعلان أو محتوى تجربة مسجل يثبت نجاحها؛ و«تجربتي» عامة وتتفرع بين الوجه والشعر والشعر الجاف، فتجربة واحدة عامة قد لا تطابق نية كل باحثة، وأي محتوى بلا تفاصيل استخدام حقيقية سيبدو ادعاءً.',replace('اختبار محتوى تجربة استخدام حقيقية وموثقة لزبدة الشيا الحالية عند زيرا للوجه وللشعر الجاف، باستخدام صيغ البحث المسجلة حرفياً في العناوين/الأسئلة، دون ادعاءات طبية.\nتجنب نسخ «تجربتي» كعنوان فارغ: أي محتوى تجربة يجب أن يذكر سياق الاستخدام المسجل فقط (للوجه/للشعر/للشعر الجاف) وطريقة الاستخدام، وإلا يفقد الثقة التي يبحث عنها المستخدم.\nاختبار قسم أسئلة يجيب عن «الأصلية» و«بكام» و«الأفريقية» بشكل منفصل، لأنها ظهرت في نفس المسح، دون مقارنات باسم براند.\nتبنّي زاوية «قبل الشراء اسأل عن التجربة» في المحتوى التعليمي لا في وصف المنتج فقط، وقياس الاستجابة بسؤال بحث/تفاعل وليس بادعاء أداء.\nلا تطلق منتجاً جديداً من زبدة الشيا بناءً على هذه الإشارة وحدها — التسجيل ينص أن المكوّن موجود عند زيرا، فالفرصة في إعادة تقديم المنتج الحالي بمحتوى تجربة.','\n',char(10)),1795068689377,'','','','');
INSERT INTO competitor_ad_analyses VALUES(35,34,'غير محدد من التسجيل','زاوية مسجلة من لغة البحث: استهداف السيلوليت في منطقتين جديدتين مسجلتين لأول مرة — الأرداف والبطن — مع اتجاه لعلاج طبيعي «بالأعشاب» وربط فضولي باسم مشهورة «سيلوليت جورجينا»؛ وهي إشارة لغة بحث وليست نص إعلان مسجل.','لا يوجد هوك إعلاني مسجل؛ الصيغ المسجلة حرفياً في مسح 07:49 EET هي: «سيلوليت الارداف» و«علاج السيلوليت في البطن» و«علاج السيلوليت بالاعشاب» و«سيلوليت جورجينا».','غير مسجل كإعلان بصيغة محددة؛ المصدر المسجل هو مسح لغة بحث عبر Google Egypt autocomplete (suggestqueries.google.com، hl=ar، gl=eg) لكلمتي «سيلوليت» و«علاج السيلوليت».','غير مسجل — لا يوجد عرض أو سعر أو منتج محدد مذكور في التسجيل.','غير مسجلة — المسجل فقط تاريخ الرصد 2026-11-19 ومسح الساعة 07:49 EET وظهور الصيغ لأول مرة في ذلك المسح؛ لا يوجد تاريخ بدء أو مدة تشغيل مسجلة.','استنتاج من الإشارات المسجلة فقط، وليس أداءً مسجلاً: ظهور منطقتين جديدتين يوسّع صلة روتين السيلوليت الحالي باحتياجات بحث أوسع، و«بالأعشاب» يعكس طلباً مسجلاً على بديل طبيعي، و«سيلوليت جورجينا» يضيف عنصر فضول مرتبط باسم مشهورة؛ ولا توجد أرقام أداء مسجلة تثبت نجاحاً فعلياً.','الأوضح أن «بالأعشاب» اتجاه علاجي عام وليس منتجاً محدداً تحمله زيرا، وأن الربط باسم مشهورة يرجّح الفضول أكثر من نية شراء مؤكدة، كما لا يوجد في التسجيل إعلان أو عرض أو أداء يثبت تحويل هذا الاهتمام إلى شراء.',replace('اختبر زاوية محتوى للسيلوليت في الأرداف والبطن ضمن روتين السيلوليت الحالي، باستخدام الصيغ المسجلة كعناوين بحث/AEO، دون ادعاءات طبية.\nاختبر محتوى يشرح «ليه سكراب وكريم مش أعشاب» لمعالجة نية البحث عن بديل طبيعي، دون ادعاء فعالية الأعشاب أو تقديمها كمنتج.\nتجنّب بناء عرض أو منتج حول الأعشاب أو اسم المشهورة؛ عاملهما كإشارة لغة بحث وزاوية محتوى فقط، لا كفرصة منتج.\nتجنّب المقارنات باسم براند والادعاءات الطبية؛ اجعل المقارنة بين طريقة الاستخدام والروتين فقط.\nاختبر الصيغ الجديدة كأسئلة شائعة أو صفحات منفصلة للأرداف والبطن والأعشاب، وقارن الاهتمام بها قبل التوسع، دون تقديم الصيغ كوعد علاجي.','\n',char(10)),1795069230407,'','','','');
INSERT INTO competitor_ad_analyses VALUES(36,35,'Alejon — يوريا / جلد الوزة (صيدلي)','المسجل في بروفايل Alejon: يوريا 10% و20% للجلد الجاف الخشن وجلد الوزة بتموضع صيدلي. أما ملاحظة لغة البحث فلا تسجل زاوية إعلانية نصية؛ البراندات الجديدة تظهر فقط ضمن فئات: كريم سيلوليت، ويوريا، وسكراب جسم.','غير مسجل — لا يوجد نص هوك أو عنوان إعلان في التسجيل؛ المسجل فقط عبارات بحث في اقتراحات جوجل مثل «كريم قود باي سيلوليت» و«يوريا كريم ليلاك» و«سكراب جسم ايفا».','غير مسجل كفورمات إعلان (فيديو/صورة/إعلان نصي)؛ المصدر المسجل هو Google Egypt autocomplete (suggestqueries.google.com, hl=ar, gl=eg) — مسح لغة بحث، وسم الأدلة SEARCH_LANGUAGE.','المسجل لبروفايل Alejon: Urea Cream 10% — 200ml بسعر 380 EGP لدى AlFouad Pharmacies. ولا يوجد عرض أو خصم أو باقة مسجلة في ملاحظة لغة البحث للبراندات الجديدة.','غير مسجلة — المسجل فقط تاريخ الرصد 2026-11-19 ووقت المسح 07:49 EET؛ لا يوجد تاريخ بدء أو مدة تشغيل مذكورة.','استنتاج من المسجل فقط، وليس رقم أداء مسجلاً: المستخدمون يبحثون بصيغة اسم/منتج + فئة/مشكلة (كريم سيلوليت، يوريا، سكراب جسم)، وظهور أسماء جديدة لأول مرة في اقتراحات جوجل مصر واستمرار نمط سابق مسجل في ملاحظة 19 يشير إلى أن لغة البحث نفسها أصبحت تحمل أسماء محددة، ما قد يسهّل اكتشاف تلك المنتجات عند البحث عن الفئة — دون أن يثبت ذلك مبيعات أو فعالية إعلان.','الأوضح من المسجل: لا يوجد إعلان أو محتوى أو عرض موصوف لتقييمه، والإشارة كلها اقتراحات بحث؛ الظهور في الاقتراحات لا يثبت نية شراء أو استمرارية أو تمييزاً للمنتج، والبراندات الجديدة غير مميزة في التسجيل سوى بالفئة (سيلوليت/يوريا/سكراب جسم).',replace('اختبر لزيرا صيغ بحث/محتوى بصيغة الفئة + المشكلة المسجلة (كريم سيلوليت، يوريا، سكراب جسم) وقِس الظهور في اقتراحات البحث، دون نسخ أسماء أو صياغات منافسة.\nتابع مسح لغة البحث دورياً بنفس الكلمات والمصدر المسجلين (Google Egypt autocomplete) ووثّق أول ظهور لأي صيغة جديدة، دون اعتبار الظهور وحده مؤشر نجاح تجاري.\nاختبر تموضعاً واضحاً لزيرا بالفئة والاستخدام والحجم/التركيز عند توفرهما ومسجلين، دون مقارنة باسم أي براند ودون ادعاءات طبية عن علاج جلد الوزة أو السيلوليت.\nتجنّب نسخ أسماء منتجات منافسة أو صياغاتها في عناوين زيرا؛ اختبر وصفاً خاصاً بزيرا يرتبط بالفئة والمشكلة فقط.\nاختبر محتوى توضيحياً عن الاستخدام والروتين للفئات المسجلة، وقيّم البحث والتفاعل، مع الالتزام بعدم تقديم وعود علاجية أو نتائج غير مسجلة.','\n',char(10)),1795069304798,'','','','');
INSERT INTO competitor_ad_analyses VALUES(37,36,'Altin Beauty','تخسيس عبر منتج مفرد — كريم Glofirm — يظهر ضمن نتائج بحث «سيلوليت»، وليس روتين سيلوليت منزلياً متكاملاً','غير مسجل — التسجيل لم يصف نص الهوك أو محتوى/مشاهد الفيديو','فيديو (Meta Ads Library، مصر، بحث «سيلوليت») — لا تفاصيل أخرى عن الفيديو مسجلة','كريم Glofirm للتخسيس بسعر 600 ج؛ لا خصم أو باقة أو شحن أو تفاصيل عرض أخرى مسجلة','نشط منذ 30 سبتمبر 2026، وكان موجوداً وقت خط الأساس 2026-11-18، وظهر مجدداً في فحص 2026-11-19؛ مدة التشغيل الكلية وأرقام الأداء غير مسجلة','لا توجد أرقام أداء مسجلة، فلا يمكن تأكيد النجاح؛ المرجح كاستنتاج فقط: استمرار ظهوره منذ 30 سبتمبر حتى 19 نوفمبر في نتائج «سيلوليت» مع عرض بسيط مفهوم (منتج واحد وسعر واضح 600 ج) يسهل الفهم والقرار، دون أن يعني ذلك تفوقاً في الأداء.','منتج مفرد بخطاب تخسيس فقط، ولا يقدم روتين سيلوليت منزلياً متكاملاً (3 قطع)؛ وهذه الفجوة المسجلة هي ما يترك الممر مفتوحاً لزيرا.',replace('اختبر تموضع زيرا كروتين منزلي متكامل من 3 قطع للسيلوليت، مقابل عرض منتج مفرد، وقِس وضوح الفكرة والنية الشرائية.\nتجنب نسخ خطاب التخسيس المفرد؛ اختبر رسالة تركز على الروتين والاستخدام المنزلي والاستمرارية دون ادعاءات طبية.\nاختبر وضوح عرض وسعر باقة الروتين كاملة، مع اختبار صيغ عرض مختلفة دون افتراض خصم أو ميزة غير مختبرة.\nاختبر هوك فيديو يشرح الروتين في خطوات خلال الثواني الأولى، لأن محتوى الفيديو في التسجيل غير موصوف ولا يمكن نسخه.\nتابع مكتبة ميتا لبحث «سيلوليت» في مصر دورياً لرصد أي دخول DTC جديد لروتين متكامل، قبل افتراض بقاء الممر مفتوحاً.','\n',char(10)),1795069819325,'','','','');
INSERT INTO competitor_ad_analyses VALUES(38,37,'غير محدد من التسجيل','غير مسجلة كزاوية إعلان؛ المسجل فقط نية بحث عن «كريم يوريا للجسم» بصيغة «كريم urea للجسم» — أي مطابقة لغة الباحث (لاتيني مع عربي) والتركيز على منتج يوريا للجسم، دون نص إعلاني مسجل يحدد زاوية.','غير مسجل؛ لا يوجد نص إعلان أو هوك مسجل في الملاحظة، والمسجل فقط عبارة البحث/الاقتراح «كريم urea للجسم».','SEARCH — اقتراح إكمال تلقائي من Google Egypt (suggestqueries.google.com، hl=ar، gl=eg) في مسح 19 نوفمبر 08:49 EET؛ ليس إعلان فيديو أو صورة مسجلاً.','غير مسجل؛ لا يوجد عرض سعر أو خصم أو عرض منتج مسجل في الملاحظة، والمنتج المذكور هو لوشن يوريا 25% الموجود لدى زيرا دون عرض مرتبط به.','تاريخ الرصد المسجل: 2026-11-19، ومسح 19 نوفمبر 08:49 EET؛ تاريخ بدء أو مدة تشغيل غير مسجلة، وهي لقطة مسح واحدة وليست استمرارية مثبتة.','لا يوجد رقم أداء مسجل يثبت نجاح إعلان؛ المستنتج من المسجل فقط أن الصيغة ظهرت جديدة كلياً ضمن العشرة الأوائل، ما يشير إلى استخدام فعلي من باحثين لكتابة urea باللاتيني مع عربي، وتطابقها المباشر مع نية محددة (كريم يوريا للجسم) وصيغ تركيز ظهرت معها (10 و20) — وهذا يجعلها إشارة لغة بحث قابلة للاختبار، لا دليل أداء.','الأوضح: لا يوجد إعلان مسجل أصلاً لتقييم قوته أو ضعفه، والإشارة لقطة واحدة قابلة للتدوير؛ ففي المسح نفسه خرجت 3 اقتراحات من العشرة الأوائل وبقيت 11 كلمة بلا جديد، والملاحظة نفسها تنبه أن الخروج تدوير اقتراحات وليس اختفاء طلب بالضرورة، فلا يمكن البناء على اقتراح واحد كطلب مستقر.',replace('اختبار إضافة urea جنب يوريا في عنوان ووصف وSEO لوشن يوريا 25% الحالي لدى زيرا، دون تقديمه كمنتج جديد.\nاختبار صيغ التركيز والأرقام (10 و20 و25، بأرقام عربية وإنجليزية) في الكوبي/SEO لأن المسح سجلها بدائل لنفس النية.\nتجنب تفسير خروج اقتراحات من العشرة الأوائل كاختفاء طلب؛ اعتباره تدوير اقتراحات ومتابعة مسوح لاحقة قبل تغيير الكوبي أو المخزون.\nتجنب نسخ عبارة البحث حرفياً كادعاء، وتجنب أي ادعاء طبي أو مقارنة باسم براند؛ الاكتفاء بلغة البحث ووصف المنتج المسجل.\nاختبار صغير أولاً وقياس ظهور/نقر لصيغة urea قبل تعميمها على كل الكوبي، لأن الدليل المسجل لقطة واحدة في 19 نوفمبر 08:49 EET فقط.','\n',char(10)),1795071681621,'','','','');
INSERT INTO competitor_ad_analyses VALUES(39,38,'غير محدد من التسجيل','المسجل: تمييز تعليمي بين السيلوليت والليبوديما — «سيلوليت ولا ليبوديما»؛ مصدره اقتراح بحث مسجل «سيلوليت و ليبوديما» ضمن اقتراحات «سيلوليت» في مسح Google Egypt، وزاوية كاروسيل تعليمي مخططة أصلاً في خطة الكرييتف التكميلية.','غير مسجل كهوك إعلاني لمنافس؛ المستنتج فقط من لغة البحث المسجلة هو سؤال التمييز نفسه: «سيلوليت ولا ليبوديما؟» — وليس نص إعلان موثق.','كاروسيل تعليمي مخطط — وليس فورمات إعلان منافس مسجل — كما ورد في التسجيل عن الزاوية المخططة أصلاً.','غير مسجل؛ التسجيل ينص صراحة: لا فرصة منتج جديدة — زاوية محتوى/توعية وليست عرض منتج.','غير مسجلة؛ المسجل فقط هو تاريخ/وقت الرصد: 19 نوفمبر 2026، 10:10 EET — ولا يوجد تاريخ بدء إعلان أو مدة تشغيل مسجلة.','مستنتج وليس أداءً مسجلاً: يعمل على الأرجح لأنه يطابق سؤالاً حقيقياً في لغة البحث — باحثون يميّزون بين الحالتين ويطلبون التوضيح — فالمحتوى التعليمي يجيب على نية بحث قائمة بدل خلقها؛ ولا توجد أرقام أداء مسجلة تثبت نجاحه.','الأوضح: لا يوجد إعلان منافس موثق أصلاً لتقييمه، والاستنتاج مبني على اقتراح بحث واحد؛ وتحذير منهجي مسجل: «مسجَّل لأول مرة» لا يعني «جديد كلياً» لأن المسوحات السابقة سجّلت أول 10 اقتراحات فقط مقابل حتى 15 في هذا المسح، وقد يكون الاقتراح موجوداً سابقاً دون تسجيل؛ كما أن الزاوية توعوية بلا عرض منتج.',replace('تبنَّ: نفّذ الكاروسيل التعليمي «سيلوليت ولا ليبوديما» بلغة البحث المسجلة نفسها كعنوان/سؤال، واختبره كمحتوى توعية.\nاختبر: قارن نسخة تبدأ بسؤال التمييز مقابل نسخة تعريفية عامة، وقِس التفاعل/الحفظ دون ادعاء نتيجة طبية.\nتجنّب: لا تدّعِ تشخيصاً أو علاجاً أو فرقاً طبياً حاسماً، ولا تقدّم الزاوية كحل منتج — التزم بالتوعية العامة وحدود AEO.\nتجنّب: لا تسوّق الاقتراح كـ«جديد كلياً» أو كاتجاه مثبت؛ اذكر أنه أول تسجيل في هذا المسح فقط بسبب تغيّر حد التسجيل من 10 إلى 15.\nاختبر: وسّع المسح لاقتراحات «ليبوديما» نفسها قبل التوسع في السلسلة، لتأكيد أن الطلب على التمييز متكرر وليس اقتراحاً منفرداً.','\n',char(10)),1795076433971,'','','','');
INSERT INTO competitor_ad_analyses VALUES(40,39,'Alejon','مسجّل: يوريا للجسم للجلد الجاف الخشن وجلد الوزة، بتركيز 10% و20% حسب البروفايل؛ والقراءة المسجلة أن البحث عن اليوريا أصبح مرتبطاً بأسماء علامات محددة وليس بالتركيز فقط.','غير مسجّل كخطاف إعلاني؛ لا توجد صياغة إعلان مسجلة. أقرب ما هو مسجّل هو عبارة البحث نفسها في اقتراحات الإكمال التلقائي: «كريم اليجون يوريا للجسم».','مسجّل: إشارة بحث SEARCH وليس إعلاناً مصوّراً مسجّلاً — مسح لغة بحث في Google Egypt autocomplete بتاريخ 19 نوفمبر 10:10 EET (hl=ar, gl=eg) لكلمات «يوريا» و«كريم يوريا للجسم» و«كريم سيلوليت». لا يوجد فورمات إعلان (فيديو/صورة/نص إعلاني) مسجّل.','مسجّل: Urea Cream 10% — 200ml بسعر 380 EGP لدى AlFouad Pharmacies، ضمن تموضع يشمل أيضاً 20% حسب البروفايل، دون سعر أو حجم مسجّلين للـ20% في التسجيل.','غير مسجّلة: لا تاريخ بدء ولا مدة تشغيل مذكورة. المسجّل فقط هو تاريخ الرصد 2026-11-19 الساعة 10:10 EET وأنه أول ظهور مسجّل لهذه الأسماء في هذا المسح، مع تنبيه منهجي مسجّل أن المسوحات السابقة سجّلت أول 10 اقتراحات فقط وهذا المسح يرجع حتى 15، فهي «مسجّلة لأول مرة» وليست «مثبتاً أنها جديدة كلياً».','لا يوجد رقم أداء مسجّل يثبت النجاح؛ هذا استنتاج من القراءة المسجلة فقط: على الأرجح يعمل لأن الطلب أصبح يُبحث باسم العلامة + اليوريا + الجسم، أي أن المستخدم يصل وهو يعرف ما يبحث عنه بدل التثقيف عن المكوّن وحده، مع توافر صيدلي مسجّل في البروفايل.','مستنتج من الازدحام المسجّل: عبارة «علامة + يوريا للجسم» لم تعد مميّزة، إذ ظهرت في المسح نفسه أسماء Novera وLilac وMixa وEveline إلى جانب Alejon في لغة بحث اليوريا، فالمنافسة تتكثف على الكلمة نفسها دون تمييز إبداعي أو عرض مسجّل يفرّقها.',replace('اختبر لزيرا لغة بحث تربط الاستخدام والروتين اليومي للجسم بدل الاعتماد على نسبة اليوريا وحدها، وقِس ظهورها في الاقتراحات دون ادعاء علاجي.\nثبّت منهجية رصد الاقتراحات (نفس عدد الاقتراحات والتوقيت والتوثيق) قبل استنتاج صعود أو هبوط أي منافس، لتجنّب خطأ تغيير العينة من 10 إلى 15.\nتجنّب نسخ صيغة «علامة + يوريا للجسم» حرفياً؛ اختبر تمييزاً قابلاً للملاحظة مثل القوام أو طريقة الاستخدام أو الحجم بدل التنافس على الكلمة نفسها.\nلا تستخدم في نسخ زيرا ادعاءات طبية أو مقارنات بأسماء علامات؛ التزم بوصف الترطيب والاستخدام واختبر فقط ادعاءات آمنة قابلة للإثبات.\nتابع اقتراحات السيلوليت كإشارة تنافسية منفصلة للمتابعة فقط، ولا تبنِ عليها منتجاً أو ادعاءً جديداً من اقتراح بحث وحده، فالمسجّل يقول إنه لا فرصة منتج جديدة من هذه الاقتراحات.','\n',char(10)),1795076520208,'','','','');
INSERT INTO competitor_ad_analyses VALUES(41,40,'Naturelle','المسجل فقط هو التموضع العام: براند مصري يدوي للعناية الطبيعية — سكرابات جسم/قدم/يد ولوشن بارز «magic treatment» ولوشنات يد؛ لا توجد زاوية إعلانية محددة مسجلة في التسجيل.','غير مسجل — لا يوجد نص هوك أو محتوى إعلان موصوف في التسجيل.','غير مسجل كفورمات إعلان؛ المسجل فقط وجود حساب إنستجرام business وحساب فيسبوك professional، ومقال Cairo360 يسرد التشكيلة نفسها.','لا يوجد عرض مسجل؛ التشكيلة المسجلة هي سكرابات جسم/قدم/يد + لوشن بارز + لوشنات يد، بلا قائمة أسعار عامة وبلا عروض مقروءة، والبيع بالرسائل فقط، ولا يوجد سعر EGP موثّق في مسح 2026-11-18.','غير مسجلة — لا تاريخ بدء ولا مدة تشغيل مذكورة؛ المسجل فقط تاريخ الرصد 2026-11-19 والفحص الحي 10:30–10:40 EET وزحف Cairo360 الساعة 08:29 UTC في اليوم نفسه.','لا توجد أرقام أداء مسجلة تثبت أنه شغال/ناجح؛ المستنتج بحذر فقط هو أن الحسابين ما زالا عامين في الفحص الحي بتاريخ 2026-11-19 (4,200 متابع على إنستجرام و5,489 على فيسبوك) وأن التشكيلة نفسها مذكورة في Cairo360، ما يشير إلى استمرارية حضور فقط وليس إلى أداء إعلاني.','الأوضح: لا متجر عام ولا قائمة أسعار ولا عروض مقروءة والبيع بالرسائل فقط، ما يرفع احتكاك الشراء؛ ويضاف إليه تصادم الاسم مع براندين أجنبيين مختلفين يظهران في بحث الويب، ما يعرّض البراند المصري لالتباس ونسبة أسعار/منتجات أجنبية له خطأً، مع عدم تسجيل منتج جديد أو عرض أو تموضع جديد في جولة السوق رقم 30.',replace('اختبر نشر قائمة أسعار وكتالوج عام مقابل البيع بالرسائل فقط، وقِس أثره على الاستفسارات المكتملة والطلبات بدل الافتراض.\nتجنب الاعتماد على الرسائل وحدها؛ اختبر رابط متجر/طلب واضح في البايو بدل ربط إنستجرام بصفحة فيسبوك فقط.\nتتبنى تمييزاً واضحاً في الاسم والوصف في البحث والقنوات لتجنب الالتباس مع نتائج بحث أجنبية مشابهة، ولا تنسب أسعاراً أجنبية لمنتجات محلية.\nاختبر تموضعاً محدداً باستخدام واحد قابل للقياس بدل سرد تشكيلة عامة بلا عرض، من دون ادعاءات طبية.\nوحّد أسماء المنتجات ووصفها عبر الحسابات الرسمية والقوائم الخارجية حتى تتطابق التشكيلة المعروضة مع ما يجده العميل عند البحث.','\n',char(10)),1795077646419,'','','','');
INSERT INTO competitor_ad_analyses VALUES(42,41,'غير محدد من التسجيل','زاوية استخدام مسجلة: «زبدة الشيا للبشرة» — تموضع زبدة الشيا الموجودة أصلاً لدى زيرا (مكوّن في روتين KP) للاستخدام على البشرة، وليست منتجاً جديداً وفق التسجيل.','غير مسجل — التسجيل لا يصف هوك إعلان؛ العبارة المسجلة الوحيدة هي اقتراح البحث «زبدة الشيا للبشرة».','مسجل كدليل SEARCH فقط: اقتراح بحث في مسح Google Egypt autocomplete (hl=ar, gl=eg)؛ فورمات إعلان (فيديو/صورة/نص إعلاني) غير مسجل.','غير مسجل — لا يوجد عرض أو سعر أو خصم أو حزمة مذكورة في التسجيل.','غير مسجلة — تاريخ الرصد الوحيد المسجل هو 2026-11-19 الساعة 11:29 EET؛ لا يوجد تاريخ بدء أو مدة تشغيل مذكورة.','مستنتج، وليس أداءً مسجلاً: الاقتراح ظهر وحلّ محل «زبدة الشيا الاصلية» في قائمة اقتراحات «زبدة الشيا»، ما يشير إلى أن نية البحث تتجه من سؤال الأصالة إلى سؤال الاستخدام للبشرة؛ زاوية مطابقة لنية بحث مسجلة وتستفيد من منتج/مكوّن موجود، فلا تحتاج إطلاقاً جديداً. لا توجد أرقام أداء مسجلة لتأكيد النجاح.','الأوضح: إشارة بحث عامة غير مملوكة ولا تميّز برانداً، بلا إبداع أو عرض أو دليل تحويل مسجل؛ والرصد لقطة واحدة فقط، وباقي الـ11 كلمة مفتاحية بلا اقتراح جديد، فلا يمكن الاستنتاج بأنها طلب مستدام أو أنها ستتحول لمبيعات.',replace('اختبر زاوية محتوى «الشيا للبشرة» على زبدة الشيا الحالية في روتين KP — محتوى استخدام للبشرة بصياغة غير طبية، قبل أي استثمار في منتج جديد.\nاستهدف العبارة المسجلة حرفياً «زبدة الشيا للبشرة» في عنوان/سؤال AEO ومحتوى يجيب عن الاستخدام، دون مقارنة باسم براند.\nلا تبنِ إطلاق منتج جديد على هذه الملاحظة وحدها؛ التسجيل يصنفها زاوية تموضع/محتوى لا فرصة منتج.\nاختبر التخلي التدريجي عن التركيز على «الأصلية» وحدها بعد خروجها من اقتراحات «زبدة الشيا»، وقارن أداء زاوية الاستخدام مقابلها.\nتحقق من الاستمرارية في مسوح لاحقة قبل التوسع؛ الرصد الحالي لقطة واحدة بتاريخ 2026-11-19 11:29 EET وبلا بيانات أداء مسجلة.','\n',char(10)),1795081256287,'','','','');
INSERT INTO competitor_ad_analyses VALUES(43,42,'غير محدد من التسجيل','المسجل: ظهور «زبدة الشيا الاصلية» كاقتراح بحث. المستنتج: زاوية الأصالة والثقة — الباحث يريد التأكد من أن زبدة الشيا أصلية قبل الشراء أو الاستخدام.','المسجل حرفياً: «زبدة الشيا الاصلية» — وهو نص اقتراح البحث نفسه، وليس هوك إعلان مسجل.','غير مسجل كفورمات إعلان؛ المسجل فقط: اقتراح إكمال تلقائي في Google Egypt (hl=ar, gl=eg) لكلمة «زبدة الشيا»، وسم الأدلة SEARCH.','غير مسجل — لا يوجد عرض أو سعر أو خصم أو منتج محدد في التسجيل؛ المسجل أن زيرا تحمل زبدة شيا أصلية ضمن روتين KP، وأن الاقتراح فرصة محتوى/ثقة وليس منتجاً جديداً.','غير مسجلة كمدة تشغيل إعلان؛ المسجل فقط: رصد بتاريخ 2026-11-19، وظهور الاقتراح في لقطة 12:30 EET بعد اختفاء «زبدة الشيا للبشرة» من لقطة 12:20 EET. لا يوجد تاريخ بدء أو مدة تشغيل.','لا توجد أرقام أداء مسجلة؛ المستنتج: يعمل على الأرجح لأنه يطابق لغة بحث فعلية وقلقاً قائماً حول الأصالة، فيقلل الشك قبل القرار، ويجعل الثقة نفسها هي الرسالة بدلاً من وعد منتج جديد.','الأوضح: الاقتراح وحده لا يثبت نية شراء ولا يقدم دليل أصالة قابلاً للتحقق، وأي طرف يستطيع استخدام كلمة «الأصلية» دون إثبات؛ كما أن اختفاء «للبشرة» قد يكون تغيراً مؤقتاً في الاقتراحات وليس تحولاً مثبتاً في الطلب.',replace('تبنَّ: اختبر محتوى ثقة/AEO بعنوان «زبدة الشيا الأصلية» يوضح معايير الأصالة لدى زيرا وكيفية التحقق منها، دون ادعاءات طبية.\nاختبر: إجابة قصيرة بصيغة سؤال وجواب للبحث حول الأصالة، وقِس ظهورها ونقراتها بدلاً من افتراض النجاح.\nتجنب: استخدام «الأصلية» كشعار عام بلا دليل محدد قابل للتحقق، لأنها كلمة سهلة التقليد وتفقد قيمتها.\nتبنَّ: اربط الاقتراح بصفحة روتين KP الحالية بدلاً من إنشاء منتج جديد، لأن التسجيل يصفه كفرصة محتوى/ثقة.\nاختبر: رصد الاقتراحات في لقطات لاحقة قبل الاستثمار الكبير، لأن التغير المسجل كان خلال 10 دقائق فقط ولا يثبت استمرارية.','\n',char(10)),1795084800720,'','','','');
INSERT INTO competitor_ad_analyses VALUES(44,43,'غير محدد من التسجيل','نية بحث عن علاج جلد الوزة عبر قناة الصيدلية — تموضع قناة/سهولة وصول، وليس منتجاً جديداً مسجلاً','«علاج جلد الوزة من الصيدلية» — صيغة الاقتراح المسجلة نفسها في بحث جوجل مصر','اقتراح إكمال تلقائي في بحث جوجل مصر (Google Egypt autocomplete، hl=ar، gl=eg) — وسم الأدلة: SEARCH؛ لا يوجد فورمات إعلان فيديو/صورة مسجل','غير مسجل — لا يوجد عرض أو سعر أو خصم مذكور في الملاحظة؛ المسجل فقط أن روتين KP من زيرا يُباع أونلاين حالياً','غير مسجلة كمدة تشغيل إعلان؛ المسجل فقط تاريخ الرصد 2026-11-19 وظهور الاقتراح في لقطة 12:30 EET بعد غيابه في لقطة 12:20 EET، وهذا لا يثبت مدة أو استمرارية','لا توجد أرقام أداء مسجلة؛ المستنتج فقط — وليس مسجلاً — أن صيغة «من الصيدلية» قد تجذب لأنها تخاطب توقع التوفر والثقة في قناة مألوفة، بينما زيرا أونلاين فقط حسب التسجيل','إشارة قناة فقط وليست منتجاً أو عرضاً محدداً، وظهورها في لقطة واحدة لا يثبت طلباً مستداماً أو منافساً بعينه، كما تكشف فجوة قناة محتملة لزيرا الأونلاين مقابل توقع الصيدلية',replace('اختبر صفحة/محتوى AEO يجيب بوضوح عن سؤال «من الصيدلية» مع توضيح قناة بيع زيرا الحالية أونلاين دون ادعاء توفر صيدلي غير مسجل.\nلا تطلق منتجاً جديداً بناءً على هذا الاقتراح وحده؛ المسجل أنه إشارة قناة/تموضع وليست فرصة منتج جديدة.\nاختبر زاوية سهولة الوصول والروتين اليومي لـ KP مقابل توقع الصيدلية، بقياس البحث والنقر قبل أي تغيير في القناة.\nتجنب ادعاء «علاج» طبي ومقارنات باسم براند؛ استخدم لغة عناية/روتين قابلة للاختبار ومتسقة مع التسجيل.\nتابع الاقتراح في لقطات لاحقة قبل الاستثمار؛ ظهور واحد بفارق 10 دقائق (12:20 إلى 12:30 EET) لا يثبت استمرارية.','\n',char(10)),1795084825640,'','','','');
INSERT INTO competitor_ad_analyses VALUES(45,44,'Urepar','[مسجل] استهداف جلد الوزة (chicken skin) بكريم يوريا 10%، 200 مل، مع ميزة سعر قناة. [استنتاج] زاوية قيمة عملية: مشكلة محددة وواضحة + سعر ميسور، وليس زاوية روتين متكامل.','غير مسجل نص هوك إعلاني حرفي؛ [مسجل فقط] استهداف «جلد الوزة / chicken skin» وسعر 357 EGP مقابل 439 EGP. [استنتاج] الهوك المحتمل هو الجمع بين المشكلة والسعر الأرخص، لكنه غير موثق كنص إعلان.','غير مسجل فورمات إعلاني؛ [مسجل فقط] صفحة منتج على Cairo Drop ودليل منتجات على Beseha، دون وصف لفيديو أو صورة أو نص إعلاني.','[مسجل] لا تخفيض رسمي معلن من البراند؛ السعر المسجل هو 357 EGP على Beseha مقابل 439 EGP على Cairo Drop لعبوة 200 مل، بفرق قناة 82 EGP (−19%)، وليس عرضاً رسمياً.','غير مسجلة؛ لا تاريخ بدء ولا مدة تشغيل مذكورة. [مسجل فقط] تحديث دليل Beseha في 6 نوفمبر 2026، وفحص Cairo Drop الحي وتاريخ الرصد في 19 نوفمبر 2026.','[مسجل] صفحة Cairo Drop تسجل 8 مبيعات في آخر 18 ساعة وتستهدف جلد الوزة صراحة، وسعر Beseha (357 EGP) يقارب سعر لوشن زيرا المنفرد (360 EGP). [استنتاج] هذا المزيج — طلب حي موثق على الصفحة + مشكلة محددة + سعر عند مستوى لوشن منفرد — يفسر على الأرجح الجذب، دون أرقام أداء إعلانية أخرى مسجلة.','[مسجل] تركيز 10% مقابل 25% لزيرا، ومنتج مفرد لا روتين، وميزة السعر فرق قناة غير رسمي (357 مقابل 439 EGP) قد لا تستمر أو تتوفر في كل القنوات؛ القيمة أضيق والتمييز السعري هش.',replace('تبنَّ: اختبار رسالة «روتين متكامل + يوريا 25%» مقابل «منتج مفرد» وقياس الإضافة إلى السلة وإتمام الشراء، مع وضوح ما يشمله الروتين وقيمته.\nاختبار: لغة وصفية غير طبية حول مظهر الجلد وملمسه تستجيب لاهتمام شائع بجلد الوزة، وقياس النقر والإضافة للسلة دون أي وعد بنتيجة علاجية.\nتجنب: بناء عرض دائم على فرق سعر قناة غير رسمي؛ اختبر بدلاً من ذلك قيمة ثابتة وشفافة (باقة/حجم/قيمة مضافة) يمكن تكرارها.\nاختبار: تثبيت سعر مرجعي واضح في صفحة المنتج يشرح القيمة مقابل السعر (التركيز + عدد خطوات الروتين) بدلاً من منافسة أدنى سعر قناة.\nتبنَّ: مراقبة أسعار القنوات والطلب على الفئة أسبوعياً، وتحديد عتبة مسبقة للرد بعرض قيمة بدلاً من رد فعل سعري يومي.','\n',char(10)),1795086603519,'','','','');
INSERT INTO competitor_ad_analyses VALUES(46,45,'غير محدد من التسجيل','زاوية ثقة/أصالة: البحث عن «زبدة الشيا الاصلية» بدلاً من «زبدة الشيا الخام»، بما يعكس قلقاً مسجلاً من التقليد/الغش واهتماماً بالأصالة والمصدر، حسب التفاصيل المسجلة.','الهوك المسجل حرفياً هو عبارة البحث نفسها: «زبدة الشيا الاصلية»؛ لا يوجد هوك إعلاني أو نص كرييتف آخر مسجل.','غير مسجل كإعلان؛ المصدر المسجل هو اقتراح إكمال تلقائي من Google Egypt (suggestqueries.google.com، hl=ar، gl=eg) ضمن مسح لغة بحث، ووسم الأدلة SEARCH، وليس فورمات إعلان موصوفاً.','غير مسجل؛ لا يوجد عرض سعر أو خصم أو حزمة مذكورة في التسجيل.','غير مسجلة؛ لا يوجد تاريخ بدء إعلان أو مدة تشغيل مذكورة. المسجل فقط تاريخ الرصد 2026-11-19 ومسحان في اليوم نفسه 12:51 و13:09 EET، ظهر فيهما التغيير.','استنتاج وليس أداءً مسجلاً: الإشارة على الأرجح قوية لأنها تطابق طلب بحث قائماً وقلقاً مسجلاً حول الأصالة، وزيرا تحمل أصلاً زبدة شيا أصلية ضمن روتين KP، فالزاوية لا تحتاج منتجاً جديداً بل إثبات ثقة؛ لا توجد أرقام أداء مسجلة تدعم نجاحاً فعلياً.','الأوضح: كلمة «أصلية» وحدها ادعاء عام سهل التكرار، ولا يوجد في التسجيل أي إثبات مسجل للمصدر أو طريقة تحقق؛ كما أن الإشارة تغيير في اقتراح واحد دون حجم بحث أو أداء مسجل، فلا يمكن تعميمها كدليل نجاح إعلان.',replace('تبنّي زاوية الأصالة/الثقة في محتوى روتين KP الحالي: إظهار المصدر وطريقة التأكد من الأصالة بشكل ملموس بدلاً من الاكتفاء بكلمة «أصلية».\nاختبار صياغة «الأصلية» مقابل «الخام» في العناوين والمحتوى لمعرفة أي لفظة يفهمها جمهور زيرا أكثر، دون ادعاءات طبية.\nتجنب نسخ الاقتراح كادعاء منافس أو المقارنة باسم براند؛ بناء الثقة بأدلة زيرا الخاصة فقط.\nتجنب إطلاق منتج جديد بناءً على هذه الإشارة وحدها — التسجيل نفسه يقول إنها ليست فرصة منتج جديد.\nمراقبة استمرار الاقتراح في مسوح لاحقة قبل الاستثمار الكبير فيه، لأن التغيير مسجل في مسح واحد فقط بين 12:51 و13:09 EET.','\n',char(10)),1795087184079,'','','','');
INSERT INTO competitor_ad_analyses VALUES(47,46,'Era Care — مصدر الفحص eracare-eg.com؛ وبروفايل Black Lotus مرفق في التسجيل كمنافس مطابق لكن لا يوجد له إعلان أو جولة مسجلة اليوم','غير مسجلة — التسجيل لا يصف زاوية إعلانية أو رسالة إبداعية؛ المسجل فقط ثبات أسعار اليوريا مقابل خط الأساس 2026-11-18، وليس إعلاناً موصوفاً.','غير مسجل — لا يوجد هوك موصوف في التسجيل؛ ولا يجوز اختراع نص هوك من الأسعار المسجلة.','غير مسجل — لا يوجد فورمات إعلاني موصوف (لا فيديو ولا صورة ولا نص إعلاني)؛ المسجل فحص حي لموقع eracare-eg.com في 2026-11-19 ~13:20 EET.','لا عرض مسجل — صراحة: لا تغيير ولا عرض موسمي ولا منتج جديد؛ الأسعار المسجلة الثابتة: لوشن يوريا 25% بـ 56–110 EGP، سكراب يوريا 25% بـ 130 EGP، كريم قدم 68 EGP، كريم يد 20% بـ 56 EGP.','غير مسجلة — لا تاريخ بدء ولا مدة تشغيل مذكورة؛ المسجل فقط تاريخا رصد: خط أساس 2026-11-18 وفحص حي 2026-11-19 ~13:20 EET، أي ثبات سعر ليوم واحد مسجل فقط، وليست مدة إعلان.','لا يوجد دليل مسجل على أنه شغال أو ناجح — لا أرقام أداء في التسجيل؛ المستنتج بحذر فقط هو أن ثبات السعر ووضوح النسبة والسعر قد يقللان احتكاك الشراء، لكن هذا استنتاج وليس دليلاً مسجلاً على نجاح.','الأوضح من التسجيل: غياب أي جديد — لا عرض ولا منتج جديد ولا هوك أو فورمات موصوف، فالملاحظة كلها ثبات أسعار، ولا يوجد في التسجيل ما يفسّر لماذا يُختار هذا المنتج تحديداً.',replace('اختبر في زيرا وضوح نسبة المكوّن والسعر معاً في صفحة المنتج مقابل إخفائهما، وقس معدل التحويل — دون أي ادعاء طبي.\nلا تعتبر ثبات السعر دليل نجاح: اختبر عرضاً محدوداً بزمن واضح مقابل سعر ثابت، وقس أثره على التحويل، لأن التسجيل لا يثبت نجاح الثبات وحده.\nاختبر بيع روتين جاهز كحزمة بسعر حزمة واضح مقابل بيع القطع منفردة، وقس متوسط قيمة الطلب — دون نسخ أسماء أو أسعار منافس بعينه.\nاعتمد قائمة تحقق للتغطية قبل اعتماد أي ملخص: تأكد من وجود جولة فعلية لكل منافس، فالتسجيل أظهر أن ادعاء «كل المنافسين لهم جولة اليوم» كان غير دقيق.\nوثّق خط الأساس وتاريخ الفحص وساعته لكل رصد سعري (كما في 2026-11-18 مقابل 2026-11-19 ~13:20 EET) حتى تكون المقارنة قابلة للتحقق.','\n',char(10)),1795087800616,'','','','');
INSERT INTO competitor_ad_analyses VALUES(48,47,'غير محدد من التسجيل','الأصالة والجودة: التفرقة بين زبدة الشيا الأصلية والمغشوشة، وليست منتجاً جديداً','«زبدة الشيا الاصلية» — عبارة البحث/الاقتراح المسجلة نفسها','غير مسجل كفورمات إعلان؛ المسجل فقط اقتراح إكمال تلقائي في مسح Google Egypt autocomplete (hl=ar, gl=eg) لكلمة «زبدة الشيا»','غير مسجل؛ لا يوجد عرض مسجل في الملاحظة، والمسجل صراحة أنها ليست فرصة منتج','غير مسجلة؛ المسجل فقط تاريخ الرصد 2026-11-19 في مسح 14:10 EET، وأن اللقطة السابقة كانت 9 اقتراحات والجديدة 10 — لا تاريخ بدء ولا مدة تشغيل مذكوران','لا يوجد إعلان مسجل ليُحكم على نجاحه من أداء؛ المسجل فقط ظهور اقتراح جديد تماماً عن الأصالة، والاستنتاج — وليس المسجل — أن الباحثين يهتمون بالتمييز بين الأصلي والمغشوش، ما يجعل زاوية الثقة والأصالة ذات صلة بزيرا التي تحمل زبدة شيا أصلية ضمن روتين KP','لا يوجد إعلان أو إبداع أو عرض أو دليل مسجل؛ الاقتراح عام وغير مرتبط ببراند، فكلمة «الأصلية» وحدها لا تميّز زيرا ولا تثبت الجودة دون دليل قابل للتحقق',replace('اختبر كوبي ومحتوى يشرح عملياً كيف يفرّق الباحث بين زبدة الشيا الأصلية والمغشوشة، واربطه بروتين KP عند زيرا دون ادعاءات طبية.\nاستخدم عبارة البحث المسجلة «زبدة الشيا الاصلية» حرفياً في عناوين وأسئلة المحتوى لالتقاط نية البحث عن الأصالة (AEO).\nتجنب نسخ الاقتراح كادعاء عام؛ قدّم دليل أصالة محدداً وقابلاً للتحقق مثل المصدر والمكونات وطريقة الاستخدام.\nتجنب المقارنات باسم براند والادعاءات الطبية؛ ركّز على الجودة والشفافية وتجربة الاستخدام.\nاختبر زاوية الأصالة مقابل زاوية أخرى مسجلة لزيرا وقارن الاستجابة، بدلاً من افتراض أن ظهور الاقتراح يعني نجاح إعلان.','\n',char(10)),1795090809741,'','','','');
INSERT INTO competitor_ad_analyses VALUES(49,48,'غير محدد من التسجيل','مستنتج من مصطلح البحث المسجل فقط، وليس زاوية إعلان موصوفة: الطلب على تركيز أعلى من اليوريا — «يوريا ٣٠٪» مقابل 25% المذكورة كمرجع في الملاحظة.','غير مسجل في التسجيل — لا يوجد نص هوك لإعلان موصوف؛ المصطلح المسجل فقط هو «يوريا ٣٠٪» ضمن اقتراحات البحث.','غير مسجل — المصدر المسجل هو مسح Google Egypt autocomplete (hl=ar, gl=eg) لكلمة «يوريا»، وليس فورمات إعلان موصوف.','غير مسجل في التسجيل — لا يوجد عرض سعر أو منتج أو حزمة موصوفة؛ المسجل فقط أن «يوريا ٣٠٪» فرصة منتج رقم 1 قيد الدراسة.','غير مسجلة كمدة تشغيل إعلان — لا يوجد تاريخ بدء إعلان أو مدة؛ المسجل فقط تواريخ رصد الاقتراحات في 2026-11-19: ظهور 01:51 EET، واختفاء من لقطة 13:51 EET، وعودة في 14:10 EET.','لا توجد أرقام أداء مسجلة؛ المستنتج فقط من التسجيل أن عودة «يوريا ٣٠٪» بعد اختفاء مؤقت، وحلولها محل «يوريا الدم» التي خرجت، تشير إلى استمرار بحث المستخدمين عن تركيز أعلى من 25% في ذلك اليوم.','التذبذب وعدم الثبات: المصطلح اختفى من لقطة 13:51 EET ثم عاد 14:10 EET، والتذبذب مسجل كطبيعي في الاقتراحات؛ فلا يثبت حجم طلب أو نية شراء، ولا يوجد إعلان أو منتج موصوف لتقييم ضعفه الإبداعي.',replace('اختبر فرصة المنتج رقم 1 القائمة وقيد الدراسة (يوريا ٣٠٪) قبل أي قرار جديد، ولا تسجلها كفرصة مكررة.\nاستخدم لغة البحث المسجلة حرفياً «يوريا ٣٠٪» في أسئلة AEO/FAQ لزيرا، دون ادعاء طبي بأن التركيز الأعلى أفضل أو أنسب.\nلا تبنِ زاوية إعلان على تذبذب الاقتراحات وحده؛ راقب لقطات متعددة في أوقات مختلفة قبل الاستنتاج.\nتجنب المقارنة باسم براند أو بالتركيز 25% كادعاء تفوق؛ اقتصر على وصف التركيز والاستخدام العام دون وعود علاجية.\nاختبر اهتمام المستخدمين بصفحة/سؤال توضيحي عن تركيز 30% مقابل 25% لقياس نية البحث، دون افتراض حجم طلب أو مبيعات من الاقتراحات.','\n',char(10)),1795090832231,'','','','');
INSERT INTO competitor_ad_analyses VALUES(50,49,'Norshek (عبر Zynah)','لا توجد زاوية يوريا/سيلوليت أو جلد وزة مسجلة؛ الظاهر فقط زاوية موسمية عامة (Black Friday) وتموضع عام للبراند: طبيعي/صديق للبيئة، لوشن غير دهني بزبدة الشيا وحليب جوز الهند، دون ربط مسجل بمشكلة محددة.','غير مسجل كنص هوك لإعلان منافس؛ المسجل فقط بانر Black Friday عام على الماركت بليس كله (حتى 60% + B1G1) دون هوك خاص بالمنتج.','بانر عام على الماركت بليس / صفحة Shop by Concern (483 منتجاً)؛ تفاصيل الوسائط ونص الإعلان الكامل غير مسجلة، ولا يوجد إعلان هيرو خاص بالمنافس مسجل.','لا يوجد عرض منافس خاص مسجل في مساحة الهيرو؛ السعر المفحوص ثابت: Skin Kin Body Lotion 395 EGP (500مل 475 EGP حسب البروفايل) مقابل خط أساس 2026-11-18، والعرض المسجل الوحيد عرض موسمي عام للماركت بليس حتى 60% + B1G1، مع خصم ~20% مسجل على أقنعة وجه Trace فقط.','غير مسجلة — لا تاريخ بدء ولا مدة تشغيل مذكورة؛ المسجل فقط تاريخ الرصد 2026-11-19 ~14:30 EET ومقارنة سعرية بخط أساس 2026-11-18، دون مدة استمرارية للإعلان أو البانر.','لا يوجد رقم أداء مسجل يثبت نجاحه؛ التفسير المحتمل فقط [مستنتج]: البانر الموسمي العام قد يستفيد من طلب Black Friday والخصم الواسع حتى 60% + B1G1 وحركة الماركت بليس، مع سعر ثابت واضح 395 EGP وتموضع طبيعي بسيط — وهذا استنتاج وليس دليل أداء مسجل.','الأوضح: غياب كامل للتموضع في مساحة زيرا (لا منتج يوريا ولا رسالة جلد وزة/سيلوليت)، وعرض عام غير مخصص لا يميز المنتج في الهيرو، وسعر بلا حافز خاص مسجل — فالظهور يعتمد على الماركت بليس والموسم لا على حل مشكلة محددة.',replace('اختبر لزيرا تموضعاً بمشكلة محددة وواضحة في الهيرو مقابل خصم موسمي عام، وقس النقر والتحويل — دون نسخ البانر العام.\nاختبر هوكاً يصف التجربة الحسية للاستخدام بصياغة غير طبية، مثل الإحساس غير الدهني، مقابل هوك سعري فقط.\nتجنب جعل خصم عام حتى 60% + B1G1 الرسالة الرئيسية؛ اختبر عرضاً محدداً بقيمة واضحة وسعر معلن.\nاختبر الظهور في صفحات التصفح حسب المشكلة بعنوان مشكلة صريح، بدل الظهور ضمن قائمة براندات عامة.\nثبت سعراً مرجعياً وراقبه يومياً قبل الموسم وأثناءه لقياس أثر الخصم فعلياً، ولا تستنتج نجاحاً من وجود بانر فقط.','\n',char(10)),1795092019980,'','','','');
INSERT INTO competitor_ad_analyses VALUES(51,50,'غير محدد من التسجيل','زاوية علاجية بصياغة بحث فعلية: «كريم علاج جلد الوزة» — بديل مسجل لـ«كريم ضد جلد الوزة»، وقريبة من «كريم لعلاج جلد الوزة» و«كريم لازالة جلد الوزة».','الهوك المسجل هو الاقتراح نفسه: «كريم علاج جلد الوزة» كصياغة بحث مباشرة عن علاج، دون نص إعلاني إضافي مسجل.','SEARCH — اقتراح إكمال تلقائي من Google Egypt (hl=ar, gl=eg)؛ ليس إعلان فيديو أو صورة أو نص إعلاني كامل مسجل.','غير مسجل — لا يوجد عرض أو سعر أو منتج محدد مذكور في الملاحظة، والملاحظة تنص على أنه لا فرصة منتج جديدة.','غير مسجلة — تاريخ الرصد فقط هو 2026-11-19 الساعة 14:50 EET، ولا يوجد تاريخ بدء أو مدة تشغيل مسجلة.','مستنتج وليس أداءً مسجلاً: على الأرجح يعمل كصياغة كوبي/SEO لأنه تأكيد إضافي مسجل على أن الصياغة مستخدمة فعلاً في لغة البحث المصرية، وقريبة من صيغتين موجودتين أصلاً، فتطابق نية البحث بدل اختراع صياغة جديدة.','ضعفه الأوضح: صياغة عامة غير مميزة ولا تثبت منتجاً أو عرضاً أو أداءً؛ ظهورها كاقتراح بحث فقط لا يعني حجم طلب أو تحويل، والملاحظة نفسها تنفي وجود فرصة منتج جديدة.',replace('تبنَّ الصياغة حرفياً في اختبار SEO/كوبي لزيرا: «كريم علاج جلد الوزة» مقابل «كريم لعلاج جلد الوزة» و«كريم لازالة جلد الوزة»، وقِس النقرات/الظهور دون ادعاء نتيجة علاجية.\nاختبرها كسؤال/إجابة AEO بصياغة البحث نفسها، مع وصف محايد للمنتج واستخداماته دون ادعاءات طبية.\nتجنب نسخ الاقتراح كوعد علاجي أو كتمييز للمنتج؛ الصياغة عامة وموجودة بصيغ قريبة أصلاً.\nتجنب اعتبار ظهور الإكمال التلقائي دليل أداء أو طلب؛ لا توجد أرقام مسجلة، فعامِله كإشارة لغة فقط تستحق الاختبار.\nاختبر الصياغة في عنوان/وصف صفحة واحدة فقط أولاً، ثم قارن قبل تعميمها على باقي كوبي زيرا.','\n',char(10)),1795093232001,'','','','');
INSERT INTO competitor_ad_analyses VALUES(52,51,'غير محدد من التسجيل','طلب تركيز يوريا 30% — أعلى من بطل زيرا 25% حسب التسجيل — كمحور طلب بحث متكرر، وليس كادعاء إعلاني مسجل','غير مسجل — لا يوجد نص هوك لإعلان في التسجيل؛ المسجل فقط اقتراح بحث «يوريا ٣٠٪»','SEARCH — اقتراح إكمال تلقائي في Google Egypt (hl=ar, gl=eg)، وليس فورمات إعلان مسجل','غير مسجل — لا يوجد عرض مذكور في التسجيل','غير مسجلة — لا تاريخ بدء إعلان ولا مدة تشغيل مذكورة؛ المسجل فقط تاريخ الرصد 2026-11-19 ومسحا 14:31 EET (غياب الاقتراح) و14:50 EET (عودته)','لا يوجد إعلان مسجل ولا أرقام أداء، فلا يمكن تأكيد نجاح إعلان؛ المستنتج فقط أن تكرار ظهور «يوريا ٣٠٪» في اقتراحات «يوريا» يشير إلى طلب بحث متكرر على تركيز 30%، وليس إلى أداء إعلان','الإشارة متذبذبة وغير ثابتة — ظهر الاقتراح في 14:50 EET بعد غيابه في 14:31 EET في اليوم نفسه — ولا يوجد منافس أو محتوى إعلان أو عرض أو أداء مسجل لتقييمه',replace('اختبار محتوى AEO يستهدف سؤال البحث «يوريا 30%» صراحة دون ادعاء طبي ودون مقارنة باسم براند، وقياس الطلب الفعلي بدل الاعتماد على الاقتراح المتذبذب\nعدم تسجيل فرصة مكررة: الفرصة مسجلة أصلاً (id 1) — التركيز على اختبار تنفيذها كمنتج أو صفحة بدل إعادة توثيقها\nتجنب نسخ اقتراح بحث كأنه إعلان ناجح؛ لا توجد أرقام أداء أو هوك أو عرض مسجلة يمكن تقليدها\nتكرار الرصد في أوقات ومسحات مختلفة قبل أي قرار، لأن الظهور المتذبذب بين 14:31 و14:50 EET لا يثبت طلباً ثابتاً\nاختبار رسالة تعليمية محايدة حول كيفية اختيار تركيز اليوريا حسب الاستخدام، دون وعود علاجية ودون الإشارة لمنافس','\n',char(10)),1795093268192,'','','','');
INSERT INTO competitor_ad_analyses VALUES(53,52,'غير محدد من التسجيل','زاوية محتوى/استهداف مسجلة: «علاج جلد الوزة في منطقة البكيني» تحديداً، باستخدام روتين KP الحالي الذي يغطي هذه المنطقة — وليست منتجاً جديداً حسب التسجيل.','الهوك المسجل الوحيد هو عبارة البحث نفسها: «علاج جلد الوزة في منطقة البكيني» — لا نص إعلاني آخر مسجل.','اقتراح إكمال تلقائي في Google Egypt (hl=ar, gl=eg)، وسم الأدلة: SEARCH — لا صيغة إعلان فيديو أو صورة مسجلة.','غير مسجل — لا عرض أو سعر أو منتج جديد مذكور في التسجيل؛ الملاحظة تصف زاوية محتوى/استهداف فقط.','تاريخ الرصد المسجل فقط: 2026-11-19، مسح 14:50 EET؛ تاريخ بدء أو مدة تشغيل/استمرارية غير مسجلة.','المسجل: اقتراح جديد ظهر في مسح 19 نوفمبر ضمن اقتراحات «علاج جلد الوزة»، بدل «علاج جلد الوزة في الوجه» الذي اختفى من المسح نفسه. المستنتج: يرجح أن الزاوية تعمل لأنها تطابق نية بحث محددة بمنطقة جسم معينة بدل سؤال عام، دون الحاجة لمنتج جديد.','أوضح ضعف: لا يوجد إعلان أو دليل أداء مسجل أصلاً — مجرد اقتراح بحث ظهر في مسح لحظي واحد، دون حجم بحث أو استمرارية أو عرض، فلا يثبت نجاحاً أو طلباً مستداماً.',replace('اختبر محتوى بحث/AEO بعنوان وسؤال مطابقين للعبارة المسجلة، يشرح أن روتين KP الحالي يغطي منطقة البكيني، دون ادعاء علاج أو شفاء طبي.\nاختبر زاوية البكيني مقابل زاوية الوجه في المحتوى والاستهداف، لأن التسجيل يوثق ظهور الأولى واختفاء الثانية في المسح نفسه.\nتجنب إطلاق منتج جديد بناءً على اقتراح بحث واحد؛ التسجيل ينص صراحة: لا فرصة منتج جديدة.\nتجنب الادعاءات الطبية والمقارنات باسم براند، والتزم بلغة وصفية عن الروتين والعناية دون وعود علاجية.\nراقب استمرارية الاقتراح في مسوح لاحقة قبل التوسع فيه، لأن الرصد الحالي لحظي ولا يثبت طلباً مستداماً.','\n',char(10)),1795093802764,'','','','');
INSERT INTO competitor_ad_analyses VALUES(54,53,'غير محدد من التسجيل','المسجَّل: زاوية بحث عامة حول «علاج السيلوليت» دون تحديد «عند النساء»، بعد اختفاء الصيغة الأخيرة من اقتراحات كلمة «علاج السيلوليت». المستنتَج فقط: صياغة عامة غير مخصصة لجنس محدد؛ لا زاوية إبداعية لمنتج أو مشكلة جديدة مسجلة.','المسجَّل: المصطلح نفسه «علاج السيلوليت» كاقتراح إكمال تلقائي في بحث جوجل مصر. لا نص هوك إعلاني آخر مسجل.','SEARCH — اقتراحات Google Egypt autocomplete (hl=ar, gl=eg) لكلمة «علاج السيلوليت»؛ ليس فورمات إعلان فيديو أو صورة مسجلاً.','غير مسجل — لا منتج أو عرض أو سعر أو دعوة لاتخاذ إجراء مذكورة في الملاحظة.','تاريخ الرصد المسجل: 2026-11-19 فقط؛ تاريخ بدء أو مدة تشغيل غير مسجلة.','لا يوجد دليل أداء مسجل يثبت أن إعلاناً يعمل. المستنتَج فقط: المصطلح العام «علاج السيلوليت» قد يعبّر عن نية بحث أوسع من الصيغة المحددة «عند النساء»، لكن ظهوره كاقتراح إكمال تلقائي وحده ليس دليل نجاح إعلاني أو أداء.','أوضح ضعف: تغيير طفيف في تكوين الاقتراحات فقط؛ لا منتج أو مشكلة جديدة ولا فرصة منتج مسجلة، والمصطلح عام وغير مميّز ولا يحمل عرضاً أو تمييزاً أو دليلاً قابلاً للاختبار كإعلان.',replace('اختبر لزيرا في محتوى البحث/AEO الصياغة العامة «علاج السيلوليت» مقابل صياغات محددة، دون ادعاءات طبية، وقِس الظهور والنقر فقط.\nتجنّب نسخ مصطلح عام كزاوية إعلانية؛ لا تمييز فيه ولا عرض، واستخدمه كإشارة نية بحث فقط.\nلا تبنِ منتجاً أو حملة على هذا التغيير؛ الملاحظة المسجلة تنص صراحة على أنه لا فرصة منتج جديدة.\nالتزم بلغة غير طبية ودون مقارنة بأي براند، وركّز على الأسئلة الشائعة والمعلومات العامة والعناية، واختبر صياغات بديلة آمنة.','\n',char(10)),1795096890264,'','','','');
INSERT INTO competitor_ad_analyses VALUES(55,54,'غير محدد من التسجيل','المسجل: لا توجد زاوية إبداعية لإعلان موصوفة في التسجيل؛ الإشارة الوحيدة هي طلب بحث «يوريا ٣٠٪» مقابل بطل زيرا 25% ضمن فرصة منتج موجودة (id 1). المستنتج فقط: زاوية محتملة قابلة للاختبار هي التركيز الأعلى 30%، وليست زاوية إعلان مؤكدة.','غير مسجل — لا يوجد نص هوك لإعلان في التسجيل؛ العبارة الوحيدة المسجلة هي اقتراح البحث «يوريا ٣٠٪».','SEARCH — مسح Google Egypt autocomplete (hl=ar, gl=eg) لكلمة «يوريا» بتاريخ 2026-11-19؛ وليس فورمات إعلان فيديو أو صورة مسجلاً.','غير مسجل — لا يوجد عرض سعر أو خصم أو حزمة مذكور في التسجيل.','مدة تشغيل الإعلان غير مسجلة؛ المسجل فقط هو الرصد في 2026-11-19: ظهور «يوريا ٣٠٪» في 01:51 EET، ثم اختفاؤه في مسح 15:32 EET وحلول «يوريا الدم» مكانه، ثم عودته في 15:49 EET بدل «يوريا الدم» — أي إشارة متقطعة خلال اليوم نفسه وليست مدة تشغيل.','لا يوجد دليل أداء مسجل لإعلان، فلا يمكن تأكيد نجاح إعلان. المستنتج فقط: ظهور «يوريا ٣٠٪» مرتين مسجلتين في اليوم نفسه (01:51 و15:49 EET) يشير إلى طلب بحث متكرر على تركيز 30% أعلى من 25%، وهذا يدعم فرصة المنتج الموجودة (id 1) ولا يستدعي فرصة جديدة — وهو استنتاج من تكرار الظهور وليس رقم أداء.','الأوضح: الإشارة غير مستقرة — اختفت في مسح 15:32 EET وحلّ محلها «يوريا الدم» — كما أن اقتراح بحث وحده لا يثبت نية شراء أو أفضلية لتركيز 30%، ولا يرتبط بمنافس أو إعلان أو عرض محدد مسجل.',replace('اختبر لزيرا محتوى AEO يجيب مباشرة عن سؤال البحث «يوريا ٣٠٪» والفرق المعلن على الملصق عن 25%، دون ادعاء طبي ودون مقارنة باسم براند.\nتبنَّ الرصد لا القرار النهائي: واصل تتبع autocomplete مصر لنفس الكلمة في أيام لاحقة قبل أي قرار منتج، لأن الإشارة اختفت في 15:32 EET ثم عادت في 15:49 EET.\nتجنب إطلاق ادعاء بأن 30% أفضل أو أقوى من 25% اعتماداً على اقتراح بحث فقط؛ الاقتراح يثبت طلب بحث لا فعالية ولا نية شراء.\nاختبر زاوية التركيز الأعلى كفرضية ضمن فرصة المنتج الموجودة (id 1)، ولا تفتح فرصة جديدة بناء على هذه الملاحظة وحدها كما هو مسجل.\nتجنب النسخ الأعمى: لا يوجد إعلان أو هوك أو عرض منافس مسجل هنا يمكن نسخه، فركّز اختبار زيرا على صياغة إجابة البحث نفسها.','\n',char(10)),1795096984319,'','','','');
INSERT INTO competitor_ad_analyses VALUES(56,55,'غير محدد من التسجيل','المسجل: اقتراح «علاج جلد الوزة في منطقة البكيني» — نفس مشكلة جلد الوزة مع تحديد منطقة جسم حساسة (البكيني) بدلاً من الوجه/الجسم العام. المستنتج: زاوية تحديد منطقة الجسم في العلاج.','المسجل حرفياً: «علاج جلد الوزة في منطقة البكيني» — وهو اقتراح بحث، وليس نص هوك إعلاني مسجل.','SEARCH — اقتراحات بحث جوجل مصر (hl=ar, gl=eg) لكلمة «علاج جلد الوزة»؛ ليس فيديو ولا إعلاناً إبداعياً مسجلاً.','غير مسجل في التسجيل — لا يوجد عرض مذكور.','غير مسجلة؛ تاريخ الرصد الوحيد المسجل هو 2026-11-19 16:30 EET، ولا يوجد تاريخ بدء أو مدة تشغيل مذكورة.','المسجل: ظهر الاقتراح الجديد وحلّ محل «علاج جلد الوزة في الوجه»، و«جلد الوزة في البكيني» موجود أصلاً ضمن اقتراحات «جلد الوزة». المستنتج: التحديد بالمنطقة يطابق على الأرجح نية بحث محددة لدى الباحثات، لا أنه إعلان ناجح مثبت — لا توجد أرقام أداء مسجلة.','الأوضح من التسجيل: ليست فرصة منتج جديدة؛ روتين KP الحالي للجسم يغطيها ضمناً، والاقتراح لغة بحث فقط ولا يثبت نية شراء أو أداء إعلان.',replace('اختبار: إضافة توضيح صريح بأن روتين KP الحالي للجسم يشمل منطقة البكيني، دون ادعاء علاج طبي ودون منتج جديد.\nتبنّي لغة البحث المسجلة حرفياً «جلد الوزة في البكيني» و«علاج جلد الوزة في منطقة البكيني» في عناوين وأسئلة المحتوى لاختبار مطابقتها لنية البحث.\nتجنب: إطلاق منتج جديد أو ادعاء مخصص للبكيني بناءً على اقتراح بحث فقط، لأن التسجيل ينفي أنها فرصة منتج جديدة.\nاختبار: محتوى يوضح تحديد المنطقة (بكيني/وجه/جسم) ضمن روتين واحد، دون مقارنات بأسماء براندات، لمعرفة أي صياغة تجذب البحث.\nاختبار مراقبة: متابعة ما إذا استمر الاقتراح في قائمة جوجل مصر بعد 2026-11-19 قبل الاستثمار فيه، لأن الظهور المسجل لحظة رصد واحدة فقط.','\n',char(10)),1795099248634,'','','','');
INSERT INTO competitor_ad_analyses VALUES(57,56,'غير محدد من التسجيل','الأصالة والثقة: استهداف الباحثات عن زبدة شيا أصلية وليست مقلدة، باستخدام لغة البحث نفسها','«زبدة الشيا الاصلية» — اقتراح بحث ظهر في قائمة اقتراحات «زبدة الشيا»','اقتراح بحث جوجل مصر (SEARCH) — ليس إعلان فيديو أو صورة مسجلاً','غير مسجل في التسجيل — لا يوجد عرض أو سعر أو خصم مذكور','مدة التشغيل/الاستمرارية غير مسجلة؛ تاريخ الرصد الوحيد المسجل هو 2026-11-19 16:30 EET، ولا يوجد تاريخ بدء أو مدة مذكورة','على الأرجح لأنه يطابق لغة بحث فعلية مسجلة: ظهر الاقتراح الجديد وحلّ محل «زبدة الشيا للبشرة» في القائمة نفسها، ووجود «الخام» أصلاً في الاقتراحات يشير — كما ورد في التسجيل — إلى اهتمام الباحثات بأصالة المنتج وتقليل الشك قبل الشراء. هذا استنتاج من التسجيل وليس رقم أداء مسجلاً.','نقطة الضعف الأوضح: «الأصلية» ادعاء بلا إثبات مسجل في التسجيل — لا مصدر ولا مواصفة ولا محتوى إعلاني أو عرض يثبتها؛ كما أن زيرا تحمل زبدة الشيا أصلاً، فاستخدام الكلمة وحدها لا يخلق تميّزاً.',replace('تبنّي لغة «الأصلية» و«الخام» في كوبي الثقة لمنتج زبدة الشيا الحالي لدى زيرا، مع إثبات قابل للتحقق (المصدر/المواصفات) بدل الاكتفاء بالكلمة.\nاختبار صيغة «زبدة الشيا الأصلية» في عنوان المنتج/الوصف مقابل الصيغة الحالية، وقياس النقر/التحويل قبل تعميمها.\nتجنّب الادعاء المطلق بالأصالة أو أي ادعاء طبي/علاجي للبشرة، وتجنّب أي مقارنة باسم براند منافس.\nاختبار محتوى إجابة (AEO/أسئلة شائعة) عن: كيف أتأكد أن زبدة الشيا أصلية/خام؟ باستخدام لغة البحث المسجلة نفسها.\nإعادة رصد اقتراحات «زبدة الشيا» في مسح لاحق قبل توسيع الاستثمار؛ الرصد الحالي لمرة واحدة في 2026-11-19 ولا يثبت استمرارية.','\n',char(10)),1795099309209,'','','','');
INSERT INTO competitor_ad_analyses VALUES(58,57,'Clementine Organics','غير مسجلة كزاوية إعلان؛ المسجل فقط هو تموضع البراند: البيع حسب المشكلة بمكونات فعالة مسماة (نياسيناميد، كافيين، ريتينول، هيالورونيك) للوجه فقط.','غير مسجل؛ لا يوجد نص هوك أو منطوق إعلان مذكور في التسجيل.','غير مسجل كفورمات إعلان؛ التسجيل هو فحص حي لموقع وكتالوج (clementineorganics.com/collections/all) وليس وصفاً لإعلان أو فيديو.','لا يوجد عرض مسجل؛ لم يظهر عرض موسمي أو خصم على الرئيسية أو صفحة المنتجات في فحص 2026-11-19، والمنتج المذكور في البروفايل هو Holiday Skin Niacinamide Serum بسعر 560 EGP دون خصم مذكور.','غير مسجلة؛ لا تاريخ بدء إعلان ولا مدة تشغيل مذكورة. المسجل فقط هو تاريخا الرصد: خط الأساس 2026-11-18 وإعادة الفحص 2026-11-19 ~18:30 EET، مع ثبات الأسعار والتوفر بينهما.','لا يوجد دليل أداء مسجل يثبت أن إعلاناً ما شغال؛ المستنتج بحذر فقط هو أن نفاد جميع المنتجات الستة مع ثبات الأسعار قد يعكس طلباً أو إحساساً بالندرة، لكنه قد يكون أيضاً نقص مخزون، ولا توجد أرقام أداء مسجلة للتأكيد.','الأوضح والمسجل: الكتالوج كامل (6 منتجات) Sold out في 2026-11-19، فلا يمكن الشراء؛ إضافة إلى الاقتصار على الوجه فقط وغياب منتج جديد أو منتج جسم/جلد وزة/سيلوليت أو روتين أو عرض موسمي في الفحص.',replace('اختبر البيع حسب المشكلة مع تسمية المادة الفعالة بوضوح في عنوان المنتج والإعلان، وقِس أثره على التحويل مقارنة بالوصف العام دون نسخ الصياغة.\nتجنّب إطلاق حملة والكتالوج كله غير متاح؛ اختبر زر «أعلمني عند التوفر» وإعلان إعادة التوفر فقط عند وجود مخزون فعلي.\nاختبر خطاً أو روتيناً للجسم يستهدف مشكلة جلد الوزة، وهي فجوة مسجلة لدى منافس الوجه فقط، دون ادعاءات طبية أو وعود علاجية.\nاختبر حزمة روتين أو عرضاً موسمياً محدوداً بزمن بدل بيع منتج مفرد بسعر ثابت، وقارن متوسط قيمة الطلب ومعدل التحويل.\nحافظ على ثبات الأسعار وشفافية التوفر؛ اختبر عرض تاريخ إعادة التوريد المتوقع بدل ترك المنتج Sold out دون بديل أو خيار انتظار.','\n',char(10)),1795106458239,'','','','');
INSERT INTO competitor_ad_analyses VALUES(59,58,'غير محدد من التسجيل','زاوية محتوى مسجلة: «سكراب جسم بالبيت» (DIY منزلي) مقابل السكراب الجاهز بتركيبة ثابتة، لسكراب الكافيين القائم ضمن روتين السيلوليت في زيرا — وليست فرصة منتج جديد حسب التسجيل','«سكراب جسم بالبيت» — عبارة البحث/الاقتراح المسجلة، وليس نص هوك إعلاني مسجلاً','اقتراح إكمال تلقائي في Google Egypt (suggestqueries.google.com، hl=ar، gl=eg) ضمن قائمة Chrome الـ15 لكلمة «سكراب جسم» — ليس إعلان فيديو مسجلاً','غير مسجل','تاريخ الرصد: 2026-11-19؛ ظهر الاقتراح لأول مرة في مسح 19 نوفمبر 18:49 EET — مدة التشغيل/الاستمرارية غير مسجلة','المسجل: ظهور الاقتراح لأول مرة ضمن قائمة الـ15 في مسح 19 نوفمبر 18:49 EET. المستنتج: ينجح على الأرجح لأنه يطابق نية بحث قائمة عن حل يُعمل بالبيت بدل خلق طلب جديد؛ لا توجد أرقام أداء مسجلة تثبت نجاح إعلان.','لا يوجد إعلان أو محتوى أو عرض أو أداء مسجل لتقييمه — مجرد اقتراح بحث قابل للتدوير والخروج من القائمة؛ والزاوية نفسها ضعيفة من جهة الوصفات المنزلية لأنها بلا تركيبة ثابتة مسجلة',replace('اختبر محتوى مقارنة (جاهز مقابل منزلي) يوضح ثبات تركيبة سكراب الكافيين الجاهز ضمن روتين السيلوليت، دون ادعاءات طبية ودون ذكر أي براند منافس، وبعد موافقة المالك فقط.\nاستخدم عبارة البحث المسجلة «سكراب جسم بالبيت» كسؤال/عنوان للمحتوى لالتقاط نية البحث المسجلة، دون نسخ أعمى لوصفات منزلية.\nتجنب تقديم الوصفات المنزلية كبديل متكافئ أو ادعاء نتائج لها؛ ركّز فقط على ما هو مسجل عن منتج زيرا القائم.\nراقب استمرار الاقتراح في مسوح لاحقة قبل أي استثمار في الإنتاج، لأن الاقتراحات قابلة للتدوير والخروج من القائمة كما خرج «سكراب جسم ازرق» في نفس المسح.\nلا تعتبره فرصة منتج جديد؛ اختبره كزاوية محتوى لمنتج قائم فقط، وقس تفاعل المحتوى التجريبي قبل التوسع.','\n',char(10)),1795107657750,'','','','');
INSERT INTO competitor_ad_analyses VALUES(60,59,'غير محدد من التسجيل','زاوية استخدام مستنتجة من عبارة البحث المسجلة: توجيه زبدة الشيا الحالية للشفايف («زبدة الشيا للشفايف»)، وليست فرصة منتج شفاه جديد حسب التسجيل ما لم يقرر المالك ذلك.','غير مسجل كهوك إعلاني؛ العبارة المسجلة الوحيدة هي اقتراح البحث «زبدة الشيا للشفايف» في موضع 15 من قائمة Chrome الموسعة.','غير مسجل كإعلان؛ المصدر المسجل هو اقتراح إكمال تلقائي Google Egypt autocomplete لكلمة «زبدة الشيا» (وسم SEARCH_LANGUAGE)، وليس فيديو أو صورة إعلانية.','غير مسجل؛ لا يوجد عرض أو سعر أو خصم مذكور في الملاحظة.','غير مسجلة كمدة تشغيل إعلان؛ المسجل فقط تاريخ الرصد 2026-11-19 ومسح 19:31 EET وظهور الاقتراح لأول مرة اليوم في ذلك المسح.','لم يُسجل أداء إعلان؛ المستنتج فقط أن الاقتراح يعكس بحثاً فعلياً من باحثين عن زبدة الشيا للشفايف، ما يجعل زاوية الاستخدام قابلة للاختبار كمحتوى لمنتج الشيا الحالي لدى زيرا.','إشارة ضعيفة ومتقلبة: موضع 15 الأخير في قائمة Chrome، ولم يتغير شيء في قائمة Firefox عن مسح 19:09، و«زبدة الشيا للبشرة» ظهرت 19:29 واختفت 19:31؛ كما أن زيرا لا تحمل منتج شفاه مخصصاً، ولا يوجد إعلان أو أداء مسجل للقياس عليه.',replace('اختبار محتوى استخدام فقط — بعد موافقة المالك — يشرح استخدام زبدة الشيا الحالية للشفاه بصياغة البحث المسجلة «زبدة الشيا للشفايف»، دون ادعاءات طبية ودون إطلاق منتج جديد.\nتجنب اعتبار الظهور في موضع 15 اتجاهاً مؤكداً؛ إعادة فحص الاقتراح في مسوح لاحقة قبل أي استثمار في المحتوى.\nاستخدام سؤال/عنوان بصيغة البحث نفسها في محتوى AEO قابل للاختبار، وقياس الظهور/النقر فقط من بيانات لاحقة مسجلة.\nتجنب نسخ أي إعلان أو ادعاء منافس؛ لا يوجد منافس أو إعلان مسجل هنا، فالإشارة مصدرها لغة بحث فقط.\nعدم اتخاذ قرار إنتاج منتج شفاه بناءً على هذه الملاحظة وحدها؛ القرار للمالك بعد إثبات استمرارية الطلب.','\n',char(10)),1795110049594,'','','','');
INSERT INTO competitor_ad_analyses VALUES(61,60,'غير محدد من التسجيل','خرافة مقابل حقيقة (Myth vs Fact) — تصحيح مفهوم شائع في البيوتي بصيغة تعليمية','التناقض بين خرافة شائعة وحقيقة مصححة (Myth vs Fact)؛ لا يوجد نص هوك حرفي مسجل في التسجيل','كاروسيل Myth vs Fact + سينماجراف (motion statics / الصورة الحيّة)','غير مسجل في التسجيل — لا يوجد عرض أو خصم مذكور','لا يوجد تاريخ بدء محدد مسجل؛ المسجل فقط أن الصيغتين من الأكثر ظهوراً في إعلانات بيوتي طويلة العمر (30+ يوم) في Q1 2026، وتاريخ الرصد 2026-11-19','الاستمرارية المسجلة (30+ يوم) والظهور المتكرر في Q1 2026 تشيران إلى صيغة قابلة للاستمرار؛ Myth vs Fact يثير الفضول ويقدم قيمة تعليمية سريعة، والسينماجراف يضيف حركة تلفت الانتباه دون الحاجة لفيديو كامل — هذا تفسير للصيغة وطول عمرها المسجل، وليس رقم أداء مسجلاً خاصاً بها','لا يوجد في التسجيل رقم تحويل أو CTR خاص بصيغتي Myth vs Fact والسينماجراف أنفسهما — الدليل المسجل هو طول العمر والظهور فقط — بينما قبل/بعد الكلاسيكي ما زال الأعلى تحويلاً حسب التسجيل، ففعالية التحويل المباشر لهذه الصيغة غير مثبتة بالأرقام في التسجيل',replace('اختبر لزيرا كاروسيل D7 خرافة×حقيقة تعليمياً بدون ادعاءات طبية وبدون مقارنة باسم براند\nاختبر D8 الصورة الحيّة (سينماجراف) بحركة خفيفة على المنتج/الملمس بدل الستاتيك منتج-فقط\nاعتمد UGC منظّم demo-first أولاً، فهو المتفوق المسجل 2.4× على متوسط الفئة (500 إعلان)\nتجنّب قبل/بعد الكلاسيكي لمخاطره القانونية المسجلة (FDA يناير 2026 وسياسات Meta)، واستبدله برحلة جلد مؤرخة + ماكرو ملمس\nتجنّب الستاتيك منتج-فقط والخصم-أولاً، فهما بيخفتان حسب التسجيل (0.7–0.88× CTR)','\n',char(10)),1795111274828,'','','','');
INSERT INTO competitor_ad_analyses VALUES(62,61,'غير محدد من التسجيل','مسجل: اقتراح بحث «علاج السيلوليت عند النساء» بصياغة موجّهة لجمهور نسائي. مستنتج: زاوية لغة بحث/محتوى، وليست فرصة منتج جديد — حسب الملاحظة المسجلة، روتين السيلوليت الحالي من زيرا يخاطب هذا الجمهور أصلاً.','مسجل: عبارة الاقتراح نفسها «علاج السيلوليت عند النساء»؛ لا يوجد نص هوك إعلاني آخر مذكور في التسجيل.','SEARCH — اقتراح إكمال تلقائي من Google Egypt (suggestqueries.google.com، hl=ar، gl=eg)؛ ليس فيديو ولا إعلاناً مصوّراً مسجلاً.','غير مسجل — لا يوجد عرض أو سعر أو منتج أو دعوة لاتخاذ إجراء مذكورة في التسجيل.','مدة التشغيل غير مسجلة؛ المسجل فقط: ظهر لأول مرة في مسح 19 نوفمبر 2026 الساعة 20:50 EET، وحلّ محل الاقتراح العام «علاج السيلوليت» في قائمة العشرة الأوائل، وباقي الكلمات الـ11 بلا تغيير عن مسح 20:31 EET في اليوم نفسه.','مستنتج بحذر فقط: الصياغة المحددة «عند النساء» تطابق لغة بحث الجمهور المستهدف، ودخولها قائمة العشرة الأوائل بدل الاقتراح العام المسجل قد يعكس بحثاً أكثر تحديداً؛ لا توجد أرقام أداء أو نتائج إعلان مسجلة لتأكيد أنه «شغال».','لا يوجد إعلان مسجل للتحليل — لا نص إعلاني ولا عرض ولا إثبات ولا منتج محدد؛ اقتراح بحث وحده لا يثبت فعالية إعلان، ولا يمنح تميّزاً، خاصة أن زيرا تخاطب هذا الجمهور أصلاً وفق الملاحظة المسجلة.',replace('اختبر صياغة «عند النساء» في محتوى البحث والأسئلة الشائعة وعناوين صفحات زيرا ذات الصلة، دون ادعاء علاج طبي.\nلا تبنِ منتجاً جديداً على هذا الاقتراح وحده؛ عامله كزاوية لغة بحث/محتوى لروتين السيلوليت الحالي فقط، كما ورد في التسجيل.\nتجنب نسخ الاقتراح كادعاء طبي أو مقارنة باسم براند؛ استخدم لغة وصفية محايدة عن الروتين والاستخدام.\nراقب في مسوح لاحقة ما إذا استمر الاقتراح في العشرة الأوائل أم اختفى، قبل توسيع الاستثمار في هذه الصياغة.\nاختبر نسختين من المحتوى: صياغة عامة مقابل صياغة «عند النساء»، وقارن إشارات البحث/الظهور المسجلة فقط دون افتراض أداء.','\n',char(10)),1795114856619,'','','','');
INSERT INTO competitor_ad_analyses VALUES(63,62,'Joviality','عرض موسمي سعري (Green Friday) على عناية جسم طبيعية بروائح وبوكسات/سيتس، بدون منتج جديد وبدون تموضع يوريا/جلد وزة/سيلوليت — حسب التسجيل.','«Up to 40% OFF!» — Green Friday، مع خصومات باندلات مسجلة من -12% إلى -41%.','فحص حي لمتجر إلكتروني (الرئيسية + Best Sellers) — صيغة الإعلان الإبداعي (فيديو/صورة) غير مسجلة في التسجيل، ولا يوجد وصف فيديو.','Green Friday «Up to 40% OFF!» مستمر؛ باندلات -12% إلى -41%؛ لوشن الجسم 340→289 EGP (-15%)، Foot Balm 360→306، Anti-Chafe Balm 320→272، زبدة الجسم 550 بلا خصم، زيت الجسم الجاف 470، الزيت اللامع 470، Skin Rescue Body Balm 360.','مدة التشغيل/تاريخ البدء غير مسجلة؛ المسجل فقط أن العرض نفسه كان قائماً في الجولة 11 واستمر دون تغيير حتى الفحص الحي 2026-11-19 ~22:30 EET، مقابل خط أساس 2026-11-18.','على الأرجح يعمل بسبب وضوح العرض الموسمي وثباته واستمراريته، وتنوع الباندلات/السيتس حتى 1,230 EGP، وتموضع براند طبيعي قائم منذ 2016 مع خطوط بروائح معروفة — لكن التسجيل لا يتضمن أي أرقام أداء، فهذا استنتاج وليس نتيجة مسجلة.','الأوضح: تكرار نفس العرض منذ الجولة 11 بلا منتج جديد ولا عرض جديد ولا حركة سعر، والمنتج الرئيسي (زبدة الجسم 550 EGP) بلا خصم رغم عنوان «حتى 40%»، ولا تموضع جديد يميّز العرض عن الخصم الموسمي العام.',replace('اختبر عرضاً موسمياً بعنوان خصم واضح وسقف محدد، مع باندلات بسعر نهائي معلن بدل خصم عام فقط.\nتجنب ترك المنتج الرئيسي بلا خصم بينما العنوان يعد بخصم كبير؛ اجعل الخصم يشمل المنتج الأبرز أو وضّح استثناءه.\nلا تنسخ الخصم الموسمي أعمى؛ اختبر زاوية تموضع مختلفة عن السعر/الرائحة لتفادي المنافسة على الخصم وحده.\nحافظ على ثبات الأسعار المعلنة أثناء الحملة حتى لا يفقد العرض مصداقيته عند المقارنة بين الفحوصات.\nاختبر تجديد العرض أو إضافة عنصر جديد قبل تكرار نفس العرض لفترات طويلة، حتى لا يفقد الإلحاح.','\n',char(10)),1795120857499,'','','','');
INSERT INTO competitor_ad_analyses VALUES(64,63,'غير محدد من التسجيل','مسجَّل: نية سعر صريحة في لغة البحث. مستنتَج: زاوية مقارنة سعر وشفافية سعر الروتين، وليست زاوية منتج/فعالية مسجَّلة.','مسجَّل: «سعر كريم جلد الوزة» ضمن اقتراحات «كريم جلد الوزة»، و«زبدة الشيا بكام» ضمن اقتراحات «زبدة الشيا».','مسجَّل: لغة بحث — Google Egypt autocomplete. لا يوجد فورمات إعلان فيديو أو صورة مسجَّل.','مسجَّل في الملاحظة كدعم للكوبي، وليس كعرض منافس موثَّق: سعر الروتين 799 ج، والشحن المجاني من تاني أوردر.','غير مسجلة؛ المسجَّل فقط تاريخ الرصد 2026-11-20 الساعة 00:50 EET، ولا يوجد تاريخ بدء إعلان أو مدة تشغيل مسجَّلة.','لا يوجد رقم أداء مسجَّل. مستنتَج: ظهور استعلامات سعر صريحة في اقتراحات Google Egypt يشير إلى شريحة في مرحلة مقارنة سعر، لذلك إبراز السعر والشحن المجاني قد يقلّل احتكاك القرار ويجذب باحثات جاهزات للمقارنة.','الأوضح: لا يوجد إعلان منافس مسجَّل أصلاً لتحليله — فقط لغة بحث؛ والتركيز على السعر وحده لا يميّز منتجاً ولا يقدّم دليل قيمة، وقد يجذب مقارنة سعرية بحتة.',replace('اختبار إبراز سعر الروتين 799 ج بوضوح في الكوبي مقابل نسخة بلا سعر، وقياس أثره على الاستفسار/التحويل.\nاختبار إبراز الشحن المجاني من تاني أوردر كحافز للاستمرارية، بصياغة واضحة عن الشرط دون مبالغة.\nتغطية استعلامَي «سعر كريم جلد الوزة» و«زبدة الشيا بكام» في محتوى وإعلانات بحث، دون ادعاءات طبية أو وعود علاجية.\nتجنّب بناء الكوبي على السعر وحده؛ اختبار نسخة تجمع السعر مع قيمة الروتين/طريقة الاستخدام لتفادي المنافسة السعرية البحتة.\nإعادة رصد اقتراحات Google Egypt قبل إطلاق الأحد وبعده لمقارنة استمرار نية السعر، وعدم تعميم نتيجة مسح واحد.','\n',char(10)),1795129274465,'','','','');
INSERT INTO competitor_ad_analyses VALUES(65,64,'أليجون — منافس متتبَّع مذكور صراحة؛ وظهر أيضاً Mixa وEveline في اقتراحات البحث المسجلة','زاوية مسجلة من لغة البحث وليست من إعلان إبداعي: الباحثات يبحثن عن كريم يوريا للجسم باسم ماركة محددة (أليجون / Mixa / Eveline)، أي أن فئة اليوريا مسعّرة بالماركة في لغة البحث نفسها، وبطل زيرا (يوريا 25%) ينافس ضمن هذه الفئة.','غير مسجل — لا يوجد هوك إعلاني أو نص منطوق في الملاحظة؛ المسجل فقط اقتراحات بحث مثل «كريم اليجون يوريا للجسم» و«كريم mixa للجسم يوريا» و«كريم ايفلين للجسم يوريا»','لغة بحث — اقتراحات Google Egypt autocomplete؛ ليس إعلان فيديو أو صورة مسجلاً','غير مسجل — لا يوجد عرض أو سعر أو خصم أو حزمة مذكورة في الملاحظة','غير مسجلة — المسجل فقط لقطة رصد واحدة بتاريخ 20 نوفمبر 2026 الساعة 00:50 EET، دون تاريخ بدء أو مدة تشغيل أو استمرارية','لا توجد أرقام أداء مسجلة تثبت نجاح إعلان؛ المستنتج فقط (وليس مسجلاً) أن ظهور أسماء ماركات محددة ضمن اقتراحات «كريم يوريا للجسم» يشير إلى طلب بحث يربط اليوريا بماركة معينة، وهو ما يجعل حضور الماركة في البحث نفسه ميزة ظهور.','الأوضح من التسجيل: لا يوجد تمييز أو عرض أو دليل مسجل يبرر اختيار ماركة على أخرى — المنافسة ظاهرة كاسم فقط في اقتراحات البحث، والملاحظة لقطة واحدة دون حجم بحث أو أداء، فلا يمكن الحكم على قوة إعلان أو منتج منها.',replace('اختبر محتوى AEO بعنوان/سؤال «كريم يوريا للجسم» يذكر يوريا 25% والاستخدام للجسم بوضوح، دون ادعاء طبي ودون ذكر أي ماركة منافسة.\nثبّت ارتباط «زيرا + يوريا 25% + للجسم» في العناوين والأوصاف والأسئلة الشائعة، واختبر أي صيغة تظهر أكثر في البحث.\nتجنب نسخ صيغ اقتراحات البحث حرفياً كادعاء تفوق؛ استخدمها فقط كإشارة لنية البحث واختبر رسائل تمييز خاصة بزيرا.\nاختبر صفحة/إجابة لسؤال «كيف أختار كريم يوريا للجسم؟» تعتمد التركيز والاستخدام والروتين، دون مقارنة بماركة ودون وعود علاجية.\nأعد رصد اقتراحات البحث في تواريخ وأوقات مختلفة قبل تعميم النتيجة، لأن المسجل لقطة واحدة في 20 نوفمبر 2026 00:50 EET.','\n',char(10)),1795129365599,'','','','');
INSERT INTO competitor_ad_analyses VALUES(66,65,'غير محدد من التسجيل','غير مسجلة كزاوية إعلان؛ المسجل فقط ربط بحثي في اقتراحات «سيلوليت»: «سيلوليت و ليبوديما»','غير مسجل؛ لا يوجد نص هوك مسجل، والمسجل فقط عبارة الاقتراح «سيلوليت و ليبوديما»','لغة بحث — اقتراح إكمال تلقائي في Google Egypt؛ ليس إعلان فيديو ولا إعلاناً مسجلاً','غير مسجل؛ لا يوجد عرض مسجل في الملاحظة','غير مسجلة؛ تاريخ الرصد المسجل هو 2026-11-20 الساعة 00:50 EET فقط، ولا يوجد تاريخ بدء أو مدة تشغيل مسجلة','غير مسجل؛ لا يوجد إعلان أو أرقام أداء مسجلة لتقييم نجاحه، والمسجل فقط أن باحثين يربطون بين السيلوليت والليبوديما في الاستعلام','لا يوجد إعلان أو منافس أو عرض مسجل لتقييمه، والربط البحثي بين حالتين متميزتين يخاطر بالخلط، وزيرا لا تحمل تموضعاً/منتجاً لليبوديما ولا يُحوَّل لمسار منتج',replace('تجنب تحويل الليبوديما إلى مسار منتج أو تموضع لزيرا، وتجنب اللغة الطبية/المرضية في الكوبي.\nأي محتوى توعوي يفرّق بين السيلوليت والليبوديما يحتاج موافقة المالك أولاً.\nلا تعتبر الاقتراح بحثاً طارئاً؛ المسح الحالي رجّع 13–15 اقتراحاً مقابل 10 في اللقطة السابقة، فهو جديد على السجل فقط.\nاختبر لغة بحث السيلوليت العامة دون ادعاءات طبية أو تشخيص أو مقارنات باسم براند.\nاستخدم اقتراحات بحث Google Egypt كمؤشر لغة فقط، دون نسخ أعمى أو استنتاج أداء إعلان.','\n',char(10)),1795130414013,'','','','');
INSERT INTO competitor_ad_analyses VALUES(67,65,'غير محدد من التسجيل','لا توجد زاوية إعلان مسجلة؛ الزاوية الوحيدة المستخلصة من التسجيل هي ربط الباحثين في الاستعلام بين السيلوليت والليبوديما كحالتين متميزتين، أي بحث عن العلاقة/التمييز بينهما، وليست زاوية منتج.','غير مسجل كهوك إعلان؛ النص المسجل الوحيد هو اقتراح البحث: «سيلوليت و ليبوديما».','ليست إعلاناً مسجلاً؛ المصدر المسجل هو لغة بحث — اقتراح Google Egypt autocomplete ضمن اقتراحات «سيلوليت» بتاريخ 2026-11-20 00:50 EET.','غير مسجل؛ لا يوجد عرض مسجل، والملاحظة تنص صراحة أن الليبوديما حالة طبية وليست مسار منتج، وأن زيرا لا تحمل تموضع/منتجاً لليبوديما.','غير مسجلة كمدة تشغيل إعلان؛ التاريخ المسجل الوحيد هو تاريخ الرصد 2026-11-20 00:50 EET، ولا يوجد تاريخ بدء أو مدة مذكورة. ملاحظة منهجية مسجلة: المسح الحالي أعاد 13–15 اقتراحاً مقابل 10 في اللقطة السابقة، فالاقتراح «جديد على السجل» وليس بالضرورة بحثاً طارئاً.','لا يوجد دليل أداء مسجل، فلا يمكن القول إنه إعلان ناجح. ما يفسر ظهور الاقتراح — كاستنتاج من لغة البحث فقط — هو أن باحثين يربطون بين السيلوليت والليبوديما في استعلام واحد، أي وجود حاجة للتمييز/الفهم قبل أي قرار، وليست نية شراء منتج مسجلة.','الأوضح: خلط محتمل بين حالتين متميزتين في استعلام واحد، مع خطر تحويل استعلام طبي/توعوي إلى مسار منتج؛ كما أن الظهور قد يكون أثراً منهجياً لاتساع عدد الاقتراحات (13–15 مقابل 10) وليس طلباً طارئاً، ولا يوجد تموضع/منتج لزيرا لليبوديما واللغة الطبية محظورة في الكوبي.',replace('تجنب: لا تُحوَّل «سيلوليت و ليبوديما» إلى مسار منتج أو عرض، ولا تُستخدم لغة طبية/مرضية في الكوبي.\nتجنب: لا يُدَّعى تشخيص أو علاج أو فرق طبي، ولا تُجرى مقارنات باسم براند؛ أي محتوى يفرّق بين السيلوليت والليبوديما للتوعية فقط وبعد موافقة المالك أولاً.\nاختبر بعد الموافقة: محتوى توعوي AEO يجيب عن سؤال الفرق بين الحالتين دون ربطه بمنتج لليبوديما ودون ادعاءات طبية.\nتبنَّ: مراقبة لغة البحث كمؤشر خلط/نية توعوية فقط، ولا يُعتبر «جديد على السجل» دليل طلب طارئ دون مقارنة منهجية بنفس عدد الاقتراحات.\nاختبر: فصل نية البحث التوعوية عن نية الشراء في صفحات السيلوليت، حتى لا تُعامل زيارات طبية بنية غير تجارية كأنها طلب على منتج.','\n',char(10)),1795130482809,'','','','');
INSERT INTO competitor_ad_analyses VALUES(68,66,'غير محدد من التسجيل','لغة بحث حول علاج السيلوليت تقودها طريقة عشبية تدخل الاقتراحات لأول مرة في السجل، وبحث باسم شخص «ضياء العوضي»، وبحث مرتبط بمشهورة «سيلوليت جورجينا» — أي زاوية طلب معلومات ومحتوى وأشخاص، وليست زاوية منتج مسجلة.','الاقتراحات المسجلة نفسها: «علاج السيلوليت بالاعشاب» و«علاج السيلوليت ضياء العوضي» و«سيلوليت جورجينا» ضمن اقتراحات «سيلوليت».','لغة البحث (Google Egypt autocomplete) — مسح اقتراحات بحث بتاريخ 2026-11-20، وليس إعلان فيديو أو إعلان منتج مسجلاً.','غير مسجل — لا يوجد عرض منتج في الملاحظة؛ والمسجل صراحة أنه لا فرصة منتج لأن زيرا ليست عشبية.','غير مسجلة — المسجل فقط تاريخ الرصد 2026-11-20 ووقت المسح 00:50 EET، وأن الطريقة العشبية تدخل الاقتراحات لأول مرة في السجل؛ لا تاريخ بدء إعلان ولا مدة تشغيل مذكورة.','لا توجد أرقام أداء مسجلة؛ والمرجح من التسجيل فقط أن البحث يعمل كإشارة طلب لأن محتوى وأشخاصاً يقودونه: فضول حول حل عشبي، واسم شخص يُبحث عنه مع العلاج، وارتباط بمشهورة يرفع قابلية البحث عن «سيلوليت» — دون ادعاء فعالية أو تحويل.','الأوضح: لا دليل منتج أو إعلان قابل للنسخ في التسجيل، وزيرا ليست عشبية فتقليد الزاوية العشبية سيكون غير مطابق؛ كما أن هوية ضياء العوضي والمحتوى المحرّك للبحث غير مسجلة، والارتباط بالمشهورة بحثي فقط دون محتوى أو عرض موصوف.',replace('تتبع/اختبار: متابعة من هو ضياء العوضي وما المحتوى الذي يحرّك البحث قبل أي قرار، دون افتراض أنه منافس أو شريك.\nتجنب: عدم نسخ زاوية «بالأعشاب» لأن زيرا ليست عشبية، وعدم تقديم ادعاءات طبية عن علاج السيلوليت.\nاختبار AEO: إنشاء محتوى إجابة واضح حول السيلوليت يجيب عن أسئلة البحث المسجلة بصيغة معلوماتية محايدة دون مقارنة باسم براند.\nاختبار: صياغة محتوى يفصل بين الطرق الشائعة في البحث وما تقدمه زيرا فعلياً، دون ربطها بالمشهورة أو بالشخص المذكور.\nتتبع: إعادة رصد اقتراحات «سيلوليت» لمعرفة هل تستمر الطريقة العشبية والاسم والمشهورة أم أنها إشارة لحظية بتاريخ 2026-11-20 فقط.','\n',char(10)),1795130489313,'','','','');
INSERT INTO competitor_ad_analyses VALUES(69,66,'غير محدد من التسجيل','زاوية بحث يقودها المحتوى والأشخاص والطريقة، لا منتج محدد: «علاج السيلوليت بالاعشاب» وبحث باسم ضياء العوضي وبحث مرتبط بجورجينا ضمن اقتراحات «سيلوليت».','صيغ البحث المسجلة نفسها: «علاج السيلوليت بالاعشاب» (أول ظهور لها في السجل)، و«علاج السيلوليت ضياء العوضي»، و«سيلوليت جورجينا» ضمن اقتراحات «سيلوليت».','لغة بحث — اقتراحات إكمال تلقائي في Google Egypt، وليس إعلان فيديو أو إعلان منتج مسجلاً','لا يوجد عرض مسجل؛ التسجيل يصرّح: لا فرصة منتج — زيرا ليست عشبية.','غير مسجلة؛ الرصد الوحيد المسجل هو مسح 20 نوفمبر 2026 الساعة 00:50 EET، ولا يوجد تاريخ بدء أو مدة تشغيل مذكورة.','المسجل: ثلاث صيغ بحث دخلت اقتراحات Google Egypt. المستنتج: يعمل هذا النوع من البحث على الأرجح لأنه يقوده أشخاص ومحتوى يبحث عنهم الناس بالاسم، وطريقة يبحث عنها الناس كحل، لا اسم منتج.','الأوضح: لا يوجد منتج أو عرض أو دليل أداء مسجل مرتبط بهذه الصيغ، والطلب مرتبط باسم شخص/مشهورة وطريقة عشبية، فلا يمكن نقله مباشرة إلى زيرا، وزيرا ليست عشبية.',replace('اختبر محتوى AEO يجيب عن أسئلة البحث المسجلة بلغة المستخدمين، دون ادعاءات طبية ودون تقديم زيرا كمنتج عشبي.\nتابع أولاً من هو ضياء العوضي وما المحتوى الذي يحرّك البحث عنه قبل بناء أي محتوى رد أو مقارنة.\nتجنّب نسخ زاوية الأعشاب أو استخدام اسمي ضياء العوضي وجورجينا في ادعاءات أو مقارنات باسم براند.\nاختبر محتوى يستهدف نية البحث عن طريقة وشخص/مصدر موثوق، وقِس ظهور زيرا في إجابات البحث بدلاً من افتراض تحويل مباشر.\nراقب اقتراحات «سيلوليت» في مسح لاحق لمعرفة هل تستمر صيغ الأعشاب والأسماء أم تختفي، قبل الاستثمار فيها.','\n',char(10)),1795130560055,'','','','');
INSERT INTO competitor_ad_analyses VALUES(70,67,'يوسيرين (Eucerin) — مذكورة صراحة في التسجيل فقط كاقتراح بحث مختفٍ «كريم يوسيرين يوريا للجسم»، وليس كمعلِن مؤكد؛ ولا يوجد بروفايل منافس مطابق مسجل.','زاوية لغة البحث المسجلة فقط: كريم يوريا للجسم حسب التركيز، والتركيزان 10% و20% هما محور البحث المستمر، مع ظهور صيغ تهجئة/أرقام بديلة دون ربط بماركة مسماة في الاقتراحات الجديدة.','غير مسجل — لا يوجد هوك إعلاني أو نص إعلان في التسجيل؛ المسجل فقط 3 اقتراحات بحث جديدة: «كريم urea للجسم» و«كريم يوريا ١٠ للجسم» و«كريم يوريا 20 للجسم».','ليس إعلاناً مسجلاً ولا فيديو — مسح لغة بحث: Google Egypt autocomplete لكلمة «كريم يوريا للجسم» (hl=ar, gl=eg).','غير مسجل — لا يوجد عرض سعر أو خصم أو حزمة في التسجيل.','غير مسجلة — تاريخ الرصد المسجل فقط هو 2026-11-20 02:09 EET؛ لا يوجد تاريخ بدء إعلان أو مدة تشغيل/استمرارية مسجلة.','لا يمكن إثبات نجاح إعلان من التسجيل — لا توجد أرقام أداء ولا إعلان مسجل؛ المسجل فقط استمرار 10% و20% كمحور بحث وظهور صيغ بديلة، وهو إشارة حذرية فقط إلى أن البحث في هذا المسح يتمحور حول التركيز والصيغة لا الماركة المسماة، وليس دليل نجاح.','أوضح نقطة ضعف في الاستنتاج نفسه: مسح واحد فقط، واقتراحات جوجل تدوّر كما هو مسجل صراحة، فاختفاء يوسيرين و«كريم يوريا مرطب للجسم» و«كريم يوريا ٤٠ للجسم» في هذا المسح ليس دليلاً قاطعاً ويحتاج تأكيداً في المسح التالي.',replace('تبنَّ/اختبر: غطِّ صيغ البحث المسجلة الجديدة في محتوى زيرا — «urea» بالإنجليزية و«يوريا ١٠» و«يوريا 20» — كصيغ لغوية بديلة لنفس الاستعلام، دون ادعاء طبي.\nتبنَّ: اجعل التركيزين المسجلين 10% و20% محور لغة المحتوى والأسئلة الشائعة، لأنهما محور البحث المستمر في المسح.\nتجنب: لا تبنِ قراراً على اختفاء ماركة مسماة من مسح واحد، ولا تقارن باسم براند؛ انتظر المسح التالي للتأكيد قبل أي استنتاج.\nاختبر: راقب في المسح التالي عودة أو استمرار اختفاء «مرطب» و«٤٠» وظهور صيغ جديدة، وحدّث قائمة صيغ البحث لزيرا بناءً على ما يُسجَّل فقط.\nتجنب نسخ اقتراحات البحث كادعاءات عن المنتج؛ استخدمها فقط كلغة استعلام يبحث بها المستخدمون.','\n',char(10)),1795134075394,'','','','');
INSERT INTO competitor_ad_analyses VALUES(71,68,'غير محدد من التسجيل','أصالة/ثقة — «زبدة الشيا الاصلية»: الباحثات يبحثن عن الأصلية قبل الشراء، حسب التسجيل؛ وليست فرصة منتج جديد لأن زيرا تحمل زبدة شيا أصلاً.','غير مسجل كهوك إعلان؛ العبارة المسجلة الوحيدة هي اقتراح البحث «زبدة الشيا الاصلية»','غير مسجل كفورمات إعلان؛ المصدر المسجل هو لغة بحث (Google Egypt autocomplete) وليس إعلاناً موصوفاً','غير مسجل — لا يوجد عرض مذكور في التسجيل','غير مسجلة — تاريخ الرصد الوحيد المسجل هو 2026-11-20 الساعة 02:09 EET، ولا يوجد تاريخ بدء أو مدة تشغيل مذكورة','استنتاج من التسجيل فقط وليس أداءً مسجلاً: يرجح أن الزاوية تعمل لأنها تطابق سلوك بحث مسجلاً — ظهور «زبدة الشيا الاصلية» لأول مرة واختفاء «زبدة الشيا للبشرة» — أي أن قرار الشراء مرتبط بالتحقق من الأصالة قبل الشراء، لا بذكر المنتج فقط.','لا يوجد إثبات مسجل للأصالة في التسجيل؛ الاكتفاء بكلمة «الأصلية» دون إثبات المصدر والخام وغياب الإضافات يترك فجوة ثقة، كما أن التسجيل لا يصف إعلاناً فعلياً أو أداءً يمكن الحكم عليه.',replace('اختبري كوبي/صفحة منتج تثبت الأصالة بالنقاط المسجلة: المصدر، الخام، بلا إضافات، بدل الاكتفاء بذكر «زبدة شيا».\nاختبري استخدام عبارة البحث المسجلة «زبدة الشيا الاصلية» في العنوان مقابل النسخة الحالية.\nتجنبي الاكتفاء بكلمة «أصلية» دون دليل قابل للتحقق، وتجنبي أي ادعاء طبي أو مقارنة باسم براند.\nاختبري محتوى يجيب عن سؤال الأصالة قبل الشراء بدل محتوى يذكر المنتج فقط.\nتتبعي ظهور/اختفاء اقتراحات «زبدة الشيا» في رصد لاحق قبل توسيع الزاوية.','\n',char(10)),1795134140490,'','','','');
INSERT INTO competitor_ad_analyses VALUES(72,69,'غير محدد من التسجيل','تفضيل رائحة داخل منتج مخمرية موجود: مخمرية برائحة «خمرة» — مسجل أن «خمرة» على الأرجح نكهة/عطر معروف، وأن زيرا تحمل مخمرية أصلاً، فهي ليست فرصة منتج جديد حسب التسجيل.','اقتراح البحث المسجل حرفياً: «مخمرية خمرة» ضمن اقتراحات «مخمرية» في Google Egypt autocomplete على Chrome.','لغة بحث — اقتراح إكمال تلقائي من Google Egypt (hl=ar, gl=eg) على عميل Chrome فقط؛ ليس إعلان فيديو مسجلاً.','غير مسجل — لا يوجد عرض أو سعر أو خصم مذكور في الملاحظة.','غير مسجلة — تاريخ الرصد المسجل فقط هو 2026-11-20 الساعة 02:09 EET، وذُكر أن الاقتراح ظهر لأول مرة؛ لا يوجد تاريخ بدء أو مدة تشغيل مسجلة، والتسجيل نفسه يطلب المتابعة في المسوحات التالية قبل أي استنتاج.','مستنتج بحذر، وليس أداءً مسجلاً: الإشارة — إن تكررت — تعكس طلب بحث مباشراً على رائحة محددة داخل منتج قائم لدى زيرا، ما يجعل مطابقة الوصف للرائحة أسهل من إطلاق منتج جديد؛ ولا توجد أرقام أداء مسجلة تثبت نجاحاً.','ضعف الدليل نفسه: ظهور لمرة واحدة فقط في Chrome، وقوائم Chrome أطول (15 اقتراحاً) وتدور أكثر من Firefox حسب التسجيل، واختفى في نفس المسح «مخمرية فيونكة»؛ فلا يمكن الاستنتاج منه وحده عن استمرارية أو حجم الطلب.',replace('تتبّع: تأكيد تكرار «مخمرية خمرة» في المسوحات التالية (Chrome وFirefox) قبل أي قرار؛ الظهور مرة واحدة غير كافٍ حسب التسجيل.\nاختبار: تجربة وصف مخمرية زيرا الحالية بما يوضح رائحة «خمرة» في عناوين/وصف البحث وAEO، دون ادعاء منتج جديد أو ادعاءات طبية.\nتجنّب: عدم إطلاق منتج جديد أو تغيير مخزون بناءً على اقتراح واحد، وعدم نسخ صياغة منافس أو المقارنة باسم براند.\nاختبار: مقارنة اهتمام هذه الرائحة مع اقتراحات أخرى مسجلة قبل ترتيب أولويات الروائح في المحتوى.\nتوثيق: تسجيل اختفاء «مخمرية فيونكة» مع ظهور «خمرة» لمتابعة تبدّل تفضيلات الروائح بدلاً من افتراض ثباتها.','\n',char(10)),1795134210019,'','','','');
INSERT INTO competitor_ad_analyses VALUES(73,69,'غير محدد من التسجيل','تفضيل رائحة داخل منتج المخمرية الحالي: باحثات يبحثن عن «مخمرية خمرة» — أي مخمرية برائحة الخمرة، وليس منتجاً جديداً','غير مسجل — الملاحظة اقتراح بحث وليست إعلاناً به هوك مسجل','لغة بحث — اقتراح إكمال تلقائي في Google Egypt (hl=ar, gl=eg) على Chrome، وليس إعلان فيديو','غير مسجل — لا يوجد عرض مسجل في الملاحظة','غير مسجلة — تاريخ الرصد فقط 2026-11-20 02:09 EET؛ ظهور لمرة واحدة لأول مرة، ويحتاج متابعة في المسوحات التالية قبل أي استنتاج','لا يوجد إعلان أو رقم أداء مسجل يثبت نجاحاً؛ الإشارة المسجلة الوحيدة هي ظهور اقتراح البحث لأول مرة، ما يوحي باهتمام بحثي برائحة محددة داخل منتج موجود تحمله زيرا أصلاً، فيفسر جاذبيته المحتملة كتفضيل رائحة لا كطلب منتج جديد.','ضعف الإشارة نفسها: ظهور لمرة واحدة فقط على Chrome، وقوائم Chrome أطول (15 اقتراحاً) وتدور أكثر من Firefox، مع اختفاء «مخمرية فيونكة» في المسح نفسه، وتفسير «خمرة» كرائحة هو «على الأرجح» وليس مؤكداً — فلا يمكن الاستنتاج منه وحده.',replace('تابع اقتراح «مخمرية خمرة» في المسوحات التالية على Chrome وFirefox قبل أي قرار؛ لا تبنِ إطلاقاً على ظهور لمرة واحدة.\nاختبر وصف الرائحة «مخمرية برائحة خمرة» في صفحة المخمرية الحالية ومحتوى الأسئلة الشائعة/AEO كتفضيل رائحة داخل منتج موجود، دون ادعاءات طبية.\nاستخدم لغة الباحثات حرفياً في التسمية والوسوم والبحث الداخلي لالتقاط هذا الطلب، دون نسخ أعمى ودون مقارنة باسم براند.\nتجنب الاستثمار في منتج أو مخزون جديد بناءً على هذه الإشارة وحدها؛ اعتبرها اختبار طلب رائحة داخل المخمرية التي تحملها زيرا أصلاً.\nراقب استمرار «مخمرية خمرة» مقابل عودة «مخمرية فيونكة» لتحديد أي رائحة تستحق الأولوية في الاختبار التالي.','\n',char(10)),1795134233822,'','','','');
INSERT INTO competitor_ad_analyses VALUES(74,70,'Norshek','عناية طبيعية صديقة للبيئة: لوشن للجسم بزبدة الشيا وحليب جوز الهند، غير دهني — حسب التموضع المسجل في بروفايل المنافس','غير مسجل — لا يوجد نص هوك أو محتوى إعلان موصوف في التسجيل','غير مسجل — التسجيل فحص حي لموقع norshek.com وصفحة منتج على Zynah، وليس وصفاً لصيغة إعلان','Skin Kin Body Lotion: 272 EGP للـ250مل على الموقع الرسمي و395 EGP للـ500مل على Zynah، وكلاهما نافد؛ لا عرض Black Friday/White Friday على الموقع الرسمي، ولافتة Black Friday على Zynah عامة للموقع كله','غير مسجلة — لا يوجد تاريخ بدء إعلان أو مدة تشغيل مسجلة؛ المسجل فقط فحصان حيان في 2026-11-20 (02:22–02:29 و02:31–02:37 EET)','لا يوجد رقم أداء مسجل؛ المستنتج فقط من التموضع المسجل هو أن التركيبة الطبيعية غير الدهنية بزبدة الشيا وحليب جوز الهند قد تجذب الباحثين عن عناية طبيعية خفيفة، لكن لا يمكن تأكيد نجاح الإعلان من التسجيل','الأوضح والمسجل: نفاد المخزون — Skin Kin نافد بالمقاسين (250مل و500مل)، وباقة Ultimate Hair Styling Bundle نافدة (610←518 EGP)، وHairapy Leave-In جديد ونافد بلا سعر؛ إضافة إلى غياب عرض Black Friday على الموقع الرسمي والتباس سعري سابق بين 272 و395 قبل توضيح فرق المقاس',replace('اختبر وضوح السعر حسب المقاس على صفحة المنتج نفسها (250مل مقابل 500مل) قبل أي حملة، لتجنب التباس سعري مثل المسجل.\nلا تروّج لمنتج نافد؛ تأكد من توفر المخزون أولاً، أو أوقف الترويج مؤقتاً حتى عودته.\nتبنَّ وضوح التركيبة والملمس في الوصف (طبيعي، غير دهني) دون ادعاءات طبية، واختبر أي صياغة يفهمها العميل أسرع.\nتجنب الاعتماد على لافتة خصم عامة للموقع كله إذا لم يكن للمنتج نفسه عرض واضح؛ اجعل العرض خاصاً بالمنتج وسعره النهائي ظاهراً.\nوحّد السعر حسب المقاس عبر قنوات البيع قبل الترويج، واختبر عرض الحزمة فقط وهي متوفرة وبسعرها بعد الخصم واضحاً.','\n',char(10)),1795135354101,'','','','');
INSERT INTO competitor_ad_analyses VALUES(75,71,'غير محدد من التسجيل','البحث عن علاج بديل طبيعي/منزلي للسيلوليت بالأعشاب بدل الروتين المكوّناتي أو المنتجات','«علاج السيلوليت بالاعشاب»','اقتراح بحث ضمن اقتراحات جوجل مصر لـ«علاج السيلوليت» — لغة بحث، وليس إعلان فيديو أو منتج مسجل','غير مسجل — لا يوجد منتج محدد ولا عرض أو سعر في التسجيل','رُصد لأول مرة في مسح 2026-11-20 الساعة 02:49 EET ولم يكن موجوداً في المسح السابق 02:35 EET في اليوم نفسه؛ مدة التشغيل/الاستمرارية غير مسجلة','مستنتج وليس مسجلاً كأداء: ظهور الاقتراح الجديد يشير إلى طلب بحث عن بديل طبيعي/منزلي يُنظر إليه كخيار أسهل أو أقل تكلفة؛ لا توجد أرقام أداء أو نجاح مسجلة في التسجيل.','الأوضح: إشارة عامة لطريقة بديلة بلا منتج محدد ولا عرض ولا دليل مسجل، والوصفات العشبية غير محددة في التسجيل؛ كما أن زيرا لا تحمل علاجاً عشبياً ولا تنويهاً، فلا يمكن تحويل الطلب مباشرة إلى منتج.',replace('اختبار محتوى صادق بعد موافقة المالك يجيب عن «ليه الروتين المكوّناتي بدل الوصفات العشبية» دون ادعاء علاج أو نتائج طبية.\nاستخدام صياغة البحث نفسها «علاج السيلوليت بالاعشاب» كسؤال يُجاب عنه في المحتوى، لا كوعد بمنتج عشبي.\nتجنب إطلاق منتج عشبي أو نسخ الوصفات البديلة؛ التسجيل ينص صراحة أنها ليست فرصة منتج جديد.\nمراقبة بقاء الاقتراح في مسوح جوجل اللاحقة قبل توسيع المحتوى، لأن الظهور مسجل مرة واحدة فقط بين 02:35 و02:49 EET في 2026-11-20.','\n',char(10)),1795136102247,'','','','');
INSERT INTO competitor_ad_analyses VALUES(76,72,'غير محدد من التسجيل','سؤال علاجي صريح ومحدد: علاج جلد الوزة في منطقة البكيني كمنطقة حساسة، وليس جلد الوزة بشكل عام','«علاج جلد الوزة في منطقة البكيني»','غير مسجل كفورمات إعلان — المصدر المسجل هو اقتراح بحث في مسح جوجل مصر، وليس إعلاناً موصوفاً','غير مسجل — لا عرض أو سعر أو منتج منفصل مسجل؛ التسجيل يوضح أنه ليس فرصة منتج جديد، بل روتين KP للجسم وسؤال تموضع/أمان يُعرض على المالك','غير مسجلة كمدة تشغيل إعلان؛ المسجل فقط أول ظهور في مسح 2026-11-20 02:49 EET بعد غيابه في مسح 02:35 EET في نفس اليوم','لا يوجد أداء إعلان مسجل يثبت نجاحه؛ المستنتج من التسجيل فقط أن إشارة الطلب قوية لأن السؤال علاجي صريح ومحدد بمنطقة واحدة، ما يقلل الغموض مقارنة بجلد الوزة العام ويتداخل مع موضوع المناطق الحساسة الموجود أصلاً','الأوضح: لا يوجد إعلان أو عرض أو دليل ملاءمة مسجل للمنطقة الحساسة، والسؤال علاجي لمنطقة حساسة يرفع مخاطر الادعاء الطبي والسلامة، وملاءمة الروتين لم تُحسم بعد وتحتاج قرار المالك',replace('اختبر محتوى AEO يجيب عن سؤال ملاءمة وأمان روتين KP للجسم في منطقة البكيني/المناطق الحساسة فقط بعد تأكيد المالك، دون ادعاء علاج.\nتجنب تقديمه كمنتج منفصل أو كعلاج طبي لمنطقة حساسة؛ التزم بلغة روتين/عناية وتعليمية.\nتبنَّ صياغة السؤال حرفياً «علاج جلد الوزة في منطقة البكيني» كنية بحث في المحتوى التعليمي، مع ربطها بموضوع المناطق الحساسة الموجود أصلاً.\nاختبر صيغة «علاج جلد الوزة في الوجه» الظاهرة في نفس المسح كسؤال تموضع منفصل، دون خلط المنطقتين في رسالة واحدة.\nتابع مسح جوجل مصر للتحقق من استمرار الاقتراح قبل الاستثمار فيه؛ ظهور واحد في 02:49 EET لا يثبت استمرارية.','\n',char(10)),1795136170617,'','','','');
INSERT INTO competitor_ad_analyses VALUES(77,73,'غير محدد من التسجيل','استهداف نسائي صريح لعلاج السيلوليت — تأكيد أن جمهور البحث نسائي بالأساس','علاج السيلوليت عند النساء','اقتراح بحث نصي في جوجل مصر — ليس فيديو مسجلاً','لا يوجد عرض مسجل — صياغة عامة بلا منتج أو طريقة جديدة، وليست فرصة منتج حسب التسجيل','مدة التشغيل/الاستمرارية غير مسجلة؛ المسجل فقط أول ظهور للاقتراح في مسح 2026-11-20 الساعة 02:49 EET وغيابه في مسح 02:35 EET، ولا يمثل ذلك مدة إعلان','لا يوجد إعلان مسجل يمكن الحكم على نجاحه أو أدائه؛ القوة المحتملة المستنتجة من التسجيل فقط هي مطابقة الصياغة للغة بحث نسائية فعلية، ما يجعل الهوك الموجه للنساء صراحةً أوضح وأقرب للجمهور','صياغة عامة جداً بلا منتج أو طريقة أو تمييز أو عرض؛ لا تقدم سبباً للاختيار ولا دليلاً، ولا يمكن نسخها كإعلان',replace('اختبري الهوك بصياغة البحث المسجلة حرفياً «علاج السيلوليت عند النساء» موجهاً للنساء صراحةً مقابل صياغة محايدة، دون ادعاءات طبية.\nلا تبني منتجاً أو ادعاء علاج على الاقتراح وحده؛ التسجيل يصفه بأنه إشارة تأكيد جمهور وليس فرصة منتج.\nتجنبي نسخ الصياغة العامة كما هي؛ أضيفي تمييزاً وعرضاً ودليلاً مسجلاً لزيرا قبل استخدامها كإعلان.\nراقبي استمرار الاقتراح في مسوح لاحقة قبل اعتباره اتجاهاً ثابتاً؛ ظهوره مرة واحدة لا يكفي.\nاستخدمي لغة البحث الفعلية في عناوين الصفحات والإعلانات الموجهة للنساء، واختبريها كزاوية استهداف لا كوعد علاجي.','\n',char(10)),1795137554207,'','','','');
INSERT INTO competitor_ad_analyses VALUES(78,73,'غير محدد من التسجيل','استهداف نسائي صريح مبني على لغة البحث: «علاج السيلوليت عند النساء» — تأكيد أن جمهور البحث نسائي بالأساس','«علاج السيلوليت عند النساء» — مخاطبة النساء صراحة في صياغة البحث نفسها','ملاحظة لغة بحث / اقتراح بحث في مسح جوجل مصر — ليست إعلاناً مسجلاً بصيغة فيديو أو نص إعلاني','غير مسجل — لا يوجد منتج أو طريقة أو عرض مذكور في التسجيل؛ صياغة عامة وليست فرصة منتج','غير مسجلة كمدة تشغيل إعلان؛ تاريخ الرصد فقط 2026-11-20، ظهر الاقتراح في مسح 02:49 EET ولم يكن موجوداً في المسح السابق 02:35 EET في اليوم نفسه','لا يوجد دليل أداء مسجل في التسجيل؛ المرجح (استنتاج وليس مسجلاً) أن الصياغة تطابق لغة البحث الحرفية وتخاطب الجمهور الأساسي مباشرة دون غموض، لذلك تدعم هوكاً نسائياً صريحاً — وليس دليلاً على نجاح إعلان','صياغة عامة بلا تمييز: لا منتج ولا طريقة ولا عرض ولا ادعاء قابل للاختبار، فلا يمكن تحويلها وحدها إلى إعلان أو فرصة منتج لزيرا',replace('تبنَّ مخاطبة النساء صراحة في هوك زيرا عند الحديث عن السيلوليت، باستخدام لغة البحث المسجلة دون ادعاء طبي.\nاختبر صيغة «عند النساء» مقابل صيغة محايدة لقياس وضوح الجمهور، دون افتراض تفوقها قبل الاختبار.\nتجنّب تحويل إشارة جمهور عامة إلى وعد علاجي أو فرصة منتج؛ التسجيل يصرّح بأنها ليست فرصة منتج.\nاستخدم إشارة لغة البحث لتأكيد الاستهداف فقط، وابنِ التميز على منتج أو طريقة أو عرض خاص بزيرا لا على الصياغة العامة.\nلا تنسخ الصياغة حرفياً كإعلان، ولا تقارن باسم براند، وصغها في سياق زيرا الخاص.','\n',char(10)),1795137612255,'','','','');
INSERT INTO competitor_ad_analyses VALUES(79,74,'Raw African','غير موصوف كزاوية إعلانية في التسجيل؛ الملاحظة المسجلة زيادة سعرية، والتموضع المسجل: عناية طبيعية مصرية قائمة على زبدة الشيا، شعر أولاً (شامبو وماسكات وليف-إن) ومنتجات جسم ثانوية','غير مسجل — لا يوجد نص هوك أو محتوى إعلاني موصوف في التسجيل','غير مسجل كفورمات إعلان؛ المصدر المسجل فحص حي لمتجر rawafrican.net وصيدليات الفؤاد في جولة سوق 68، وليس وصف فيديو أو صورة إعلان','المسجل: Shea Butter Hair Mask 250gm بسعر 299 EGP، وعروض B1G1 قوية على المتجر حسب البروفايل؛ وShea Leave In & Curl Enhancer 250جم بسعر 320 EGP بعد الزيادة من 240 EGP','غير مسجلة كمدة تشغيل إعلان؛ المسجل فقط تاريخا رصد: 2026-11-18 بسعر 240 EGP، و2026-11-20 ~02:51–02:52 EET بسعر 320 EGP، ولا يوجد تاريخ بدء أو مدة تشغيل مذكورة','لا يوجد رقم أداء مسجل في التسجيل؛ استنتاجاً فقط: الزيادة المؤكدة على قناتين مع توفر المنتج (In Stock) وعروض B1G1 المسجلة قد تدعم قبول سعر أعلى لمنتج شيا للشعر، وترفع سقف أسعار الشيا/الترطيب المجاور كما هو مسجل — وهذا تفسير محتمل وليس نتيجة أداء موثقة','الأوضح المسجل: زيادة +80 EGP (+33%) خلال يومين (من 240 في 2026-11-18 إلى 320 في 2026-11-20) قد تُضعف حساسية السعر وتفتح فرصة لبديل أرخص، والمنافس شعر أولاً وتشابه 43/100 فقط فلا ضغط مباشر مسجل على روتين الهيرو؛ كما أن Urea Heel Cream بلا سعر منفرد موثّق في التسجيل',replace('اختبري سقف سعر منتجات الشيا/الترطيب المجاورة تدريجياً بدل زيادة مفاجئة بنسبة كبيرة، وقيسي أثرها على التحويل قبل تعميمها.\nتبنّي: وضوح السعر والتوفر على قناتين (متجر وصيدلية) عند أي تغيير سعري، مع توثيق التاريخ والسعر السابق للمتابعة.\nتجنّبي نسخ عروض B1G1 أعمى؛ اختبريها كعرض محدود مقابل خصم مباشر وقارني هامش الربح والتحويل.\nاختبري رسالة ترطيب/شيا موجهة للشعر أولاً مقابل الجسم، لأن التموضع المسجل يفصل بينهما ولا يثبت أن نفس الرسالة تنجح للجسم.\nلا تستخدمي ادعاءات طبية ولا مقارنات بأسماء منافسين؛ ركّزي اختبار زيرا على الفائدة الحسية والتجربة والسعر مقابل القيمة.','\n',char(10)),1795137652288,'','','','');
INSERT INTO competitor_ad_analyses VALUES(81,75,'Soralone','خصم White Friday بنحو 50% على جل يوريا 15% لجلد الوزة، بتموضع ثابت لمناطق محددة: المرفقين والركب والكعبين واليدين','145 بدل 295 جنيه (−51%) لجل يوريا 15% 100 مل — خصم نحو 50% في White Friday','غير مسجل — المصدر المسجل صفحتا بيع (Nefro Glow وe-majestic) فقط، ولا يصف التسجيل فورمات فيديو أو صورة','جل يوريا 15% 100 مل بـ145 بدل 295 (−51%) على Nefro Glow، مع خصم نحو 50% على 7 منتجات في White Friday؛ تحقق متقاطع من e-majestic يطابق الأسعار المخفّضة (±3 EGP)','غير مسجلة — لا يوجد تاريخ بدء أو مدة تشغيل في التسجيل؛ تاريخ الرصد المسجل فقط هو 2026-11-20 (فحص حي ~04:19 EET)، ومسح سابق بتاريخ 2026-11-18','مرجّح (مستنتج، وليس رقم أداء مسجلاً): وضوح العرض — سعر مرساة 295 مقابل 145 ونسبة −51% — مع تركيز محدد (15%) ومناطق استخدام محددة، وتوافق الأسعار المخفّضة بين مصدرين، وتوقيت White Friday؛ عناصر تقلل التردد في قرار الشراء دون الحاجة لادعاءات إضافية','الأوضح المسجل: ظهور «Out of stock» على صفحة Nefro Glow رغم أن التسجيل يوضح أنها حالة عرض على مستوى الصفحة وليست نفاداً فعلياً، ما قد يوقف نية الشراء أو يربك المشتري؛ ويضاف إليه اختلاف سعر التخفيض المسجل سابقاً (~125 EGP في مسح 2026-11-18) عن 145 EGP في الرصد الحالي، ما قد يضعف وضوح السعر',replace('اختبر لزيرا عرض سعر مرساة واضحاً (قبل/بعد + نسبة الخصم) على منتج واحد محدد التركيز والاستخدام، مع توحيد السعر عبر كل القنوات قبل الإطلاق.\nتجنّب إطلاق حملة خصم بينما تظهر حالة «Out of stock» على مستوى الصفحة رغم توفر المنتج؛ راجع حالة التوفر والعرض قبل النشر.\nاعتمد تموضعاً محدداً بمناطق الاستخدام والتركيز في الرسالة الإعلانية، دون ادعاءات طبية أو وعود علاجية.\nاختبر خصم خط كامل لفترة موسمية محددة (مثل White Friday) مقابل خصم منتج واحد، وقِس أثره على متوسط سلة الشراء دون نسخ العرض حرفياً.\nتحقق متقاطعاً من الأسعار المخفّضة على كل نقاط البيع قبل الإطلاق لتجنب اختلاف السعر بين القنوات.','\n',char(10)),1795141382929,'','','','');
INSERT INTO competitor_ad_analyses VALUES(82,76,'غير محدد من التسجيل','الأصالة والتمييز قبل الشراء: الباحثة تبحث عن «الأصلية» وليس أي زبدة شيا، في سياق قلق مسجل من الأصالة/الغش في سوق الشيا','«زبدة الشيا الاصلية»','اقتراح بحث في مسح Google Egypt (hl=ar, gl=eg) ضمن اقتراحات «زبدة الشيا» — ليس إعلان فيديو أو صورة مسجلاً في التسجيل','غير مسجل — لا يوجد عرض مذكور في التسجيل','مدة تشغيل/استمرارية غير مسجلة؛ الظهور الأول المسجل فقط كان في مسح 2026-11-20 04:29 EET، وهي إشارة مسح واحد فقط تحتاج تأكيداً في المسحين التاليين','لا توجد أرقام أداء مسجلة في التسجيل؛ المستنتج من الملاحظة المسجلة فقط هو أن صيغة «الأصلية» تخاطب قلقاً مسجلاً من الأصالة/الغش قبل الشراء، فهي تعكس نية شرائية مصفّاة وليست بحثاً عاماً عن الشيا.','أوضح ضعف: إشارة مسح واحد فقط غير مؤكدة وقد تنعكس حسب ملاحظة التدوير المسجلة، ولا يوجد محتوى إعلان أو أرقام أداء مسجلة تثبت نجاحها، كما أنها ليست منتجاً جديداً.',replace('لا تتخذ أي قرار محتوى/إنتاج قبل تأكيد ظهور الاقتراح في المسحين التاليين والحصول على موافقة المالك.\nعند التأكيد، اختبر رسالة أصالة لزبدة شيا زيرا تعتمد على معلومات قابلة للتحقق فقط، دون ادعاءات طبية أو مقارنة باسم براند.\nاختبر محتوى تعليمياً يجيب عن سؤال «كيف أعرف الأصلية؟» بصيغة عامة قابلة للاختبار، بدلاً من نسخ صيغة الاقتراح كادعاء.\nتجنب تقديم «الأصلية» كوعد مطلق أو ادعاء جودة/فعالية غير موثق في التسجيل.\nراقب ما إذا كان الاقتراح يحل محل «زبدة الشيا للبشرة» بشكل مستمر أم أنه تدوير مؤقت، قبل تغيير أولويات المحتوى.','\n',char(10)),1795142405438,'','','','');
INSERT INTO competitor_ad_analyses VALUES(83,77,'Tetavara','مستنتج من التسجيل: تموضع سعري مباشر لجلد الوزة — مجموعة كاملة بـ500 EGP بمكونات طبيعية معلنة وبلا يوريا، مقابل روتين زيرا المسجل بـ799 EGP (يوريا 25% + سكراب + كريم)؛ منافسة على سعر الدخول الأقل بتركيبة أضعف حسب التسجيل.','غير مسجل — لا يوجد نص هوك إعلاني مسجل؛ المسجل فقط اسم المجموعة «ديزني لعلاج جلد الوزة» وسعر 500 EGP على صفحة المتجر.','صفحة منتج على tetavara.com.eg — فحص حي بالمتصفح (جولة سوق 78)؛ ليست فيديو مسجلاً ولا إعلان فيديو موصوفاً في التسجيل.','مجموعة «ديزني لعلاج جلد الوزة» بـ500 EGP ومتوفرة: صابونة 140 جم + سكراب 200 جم + زبدة 100 جم؛ ولا يوجد خصم أو عرض B1G1 مسجل لهذه المجموعة تحديداً في التسجيل.','غير مسجلة — لا تاريخ بدء ولا مدة تشغيل مذكورة؛ أول رصد مسجل 2026-11-20 ~04:31 EET، ولم تكن المجموعة في خط الأساس المسجل 2026-11-18، لكن المتجر لا يتيح تواريخ إطلاق فلا يمكن الجزم بأنها جديدة أو تحديد استمراريتها.','لا توجد أرقام أداء مسجلة؛ التفسير المرجح (مستنتج وليس مسجلاً): سعر دخول أقل (500 مقابل 799 EGP) يخفض حاجز الشراء، ومجموعة من 3 خطوات جاهزة، وقائمة مكونات طبيعية معلنة طويلة، واسم «ديزني» جذاب، وتوفر المنتج على متجر متخصص في الشد والسيلوليت.','أوضح ضعف مسجل: المجموعة بلا يوريا وبلا ريتينول، بينما روتين زيرا المسجل يحتوي يوريا 25% — أي تموضع أرخص لكن بتركيبة أضعف حسب المكونات المعلنة، ما يترك لزيرا مساحة تمييز واضحة بالتركيبة مقابل السعر.',replace('اختبر إبراز قيمة روتين زيرا مقابل السعر (يوريا 25% + سكراب + كريم) دون ذكر منافس بالاسم ودون ادعاء طبي — بالاعتماد على المكونات والخطوات المعلنة فقط.\nاختبر خيار دخول يخفض حاجز الـ799 EGP، مثل باقة أصغر أو تقسيط، دون خفض دائم للسعر الأساسي.\nتجنب نسخ طابع «ديزني» أو قائمة مكونات طويلة بلا تمييز؛ واعتمد على وضوح المكون المميز المعلن والخطوات الثلاث.\nتبنَّ مراقبة دورية لصفحات مجموعات جلد الوزة الأرخص وتسجيل السعر والتوفر والمكونات، لأن غياب المجموعة من خط الأساس 2026-11-18 وظهورها 2026-11-20 يوضح سرعة تغير العرض.\nاختبر محتوى مقارنة قيمة محايداً (السعر مقابل المكونات المعلنة وعدد الخطوات) يساعد العميل على فهم فرق السعر دون ادعاءات علاجية.','\n',char(10)),1795142458042,'','','','');
INSERT INTO competitor_ad_analyses VALUES(84,78,'Centevia — Nourish-30 Body Lotion','زاوية ادعاء محدد بالأرقام حول مظهر السيلوليت: تقليل مظهر السيلوليت خلال 48 ساعة ومضاعفة إنتاج الكولاجين الطبيعي، مدعومة بأرقام ترطيب +55.5% وتحسين نعومة +9.0% وTEWL −48% خلال 24 ساعة وتسريع التعافي +59%، بحسب نص صفحة المنتج المسجل.','«Assists in minimizing the appearance of cellulite» و«reduce the appearance of cellulite within 48 hours» — تسمية السيلوليت صراحةً مع وعد زمني 48 ساعة.','صفحة منتج مكتوبة على جوميا مصر (قائمة تجارة إلكترونية / نسخة منتج) — ليست فيديو مسجلاً، ولا يوجد وصف فيديو في التسجيل.','لوشن Nourish-30 بسعر 400 EGP (مسح 2026-11-18)، مع خصم Black Friday −25% على الخط كاملاً على جوميا في نفس الأسبوع؛ وباقة العروسة 888 EGP مذكورة في ملف المنافس.','غير مسجلة — تاريخ الرصد 2026-11-20 (فحص حي ~04:50 EET) ومسح الأسعار 2026-11-18 فقط؛ لا يوجد تاريخ بدء أو مدة تشغيل مذكورة في التسجيل.','على الأرجح يعمل لأنه يسمّي مشكلة السيلوليت صراحةً ويقدّم وعداً زمنياً محدداً (48 ساعة) وأرقاماً متعددة مكدّسة (ترطيب ونعومة وحاجز بشرة وتعافٍ)، ما يرفع الإحساس بالتحديد والمصداقية، مع خصم Black Friday −25% الذي يخفف حاجز السعر، وتوزيع قوي لصنّاع المحتوى وعروض إثبات بجهاز قياس الترطيب بحسب ملف المنافس — وهذا استنتاج من العناصر المسجلة وليس رقم أداء مسجلاً.','أوضح نقطة ضعف: ادعاءات قوية وسريعة (48 ساعة ومضاعفة الكولاجين) بلا إثبات موثق مذكور في هذا التسجيل سوى نص الصفحة، والصياغة مقيدة بـ«مظهر» السيلوليت و«Assists»، كما أن العرض منتج مفرد (لوشن) وليس روتيناً متكاملاً.',replace('اختبري زاوية «روتين متكامل من 3 قطع بسعر 799» مقابل منتج مفرد، مع التركيز على اكتمال الروتين والقيمة لا على وعد علاجي.\nتبنّي التحديد بالأرقام فقط لما يمكن إثباته لدينا (مثل الترطيب) واختبار صياغة رقمية محددة بدل الوعود العامة، دون نسخ وعود 48 ساعة أو مضاعفة الكولاجين.\nتجنّبي أي ادعاء طبي/علاجي للسيلوليت أو وعد زمني سريع غير موثق؛ الالتزام بصياغة المظهر والعناية فقط.\nاختبري فورمات إثبات قابل للقياس (مثل عرض قياس الترطيب) لروتيننا، بدل الاعتماد على نص الصفحة فقط.\nاختبري عرض قيمة واضح في أسبوع الخصومات (سعر الروتين الإجمالي 799) بدل خصم نسبة عامة على منتج مفرد، دون مقارنة باسم أي براند.','\n',char(10)),1795143651487,'','','','');
INSERT INTO competitor_ad_analyses VALUES(85,79,'غير محدد من التسجيل','الأصالة والتمييز بين زبدة الشيا الأصلية والمغشوشة — كإشارة بحث مسجلة في اقتراح «زبدة الشيا الاصلية»، وليست زاوية إعلان موثقة في التسجيل','غير مسجل كهوك إعلاني؛ العبارة المسجلة الوحيدة هي اقتراح البحث «زبدة الشيا الاصلية»','مسح اقتراحات بحث جوجل مصر (SEARCH) — لا توجد صيغة إعلان مسجلة، وليس فيديو','غير مسجل — لا يوجد عرض مسجل في الملاحظة','غير مسجلة؛ التواريخ المسجلة فقط هي 2026-11-20 ومسحا 05:31 و05:50 EET، ولا يوجد تاريخ بدء إعلان أو مدة تشغيل مذكورة','غير مسجل في التسجيل دليل على أن إعلاناً يعمل أو أرقام أداء؛ المستنتج بحذر فقط هو أن ظهور «الاصلية» قد يعكس اهتماماً بحثياً بالتمييز بين الأصلي والمغشوش، لكن إشارة مسح واحد لا تكفي والتدوير معروف، فلا يمكن تأكيد نجاح','الأوضح: إشارة مسح واحد فقط غير مستقرة مع تدوير معروف للاقتراحات، وغياب منافس وإعلان وعرض وأرقام أداء مسجلة؛ وخروج «زبدة الشيا للبشرة» في نفس المسح يمنع قراءة اتجاه من مسح واحد',replace('تابع ثبات «زبدة الشيا الاصلية» في المسحات التالية قبل أي استنتاج؛ لا تبنِ قرار محتوى أو منتج على مسح واحد (05:50 EET).\nاختبر محتوى AEO تعليمياً حول التمييز بين الأصلي والمغشوش وعلامات الجودة القابلة للتحقق، دون ادعاءات طبية ودون مقارنة باسم براند.\nلا تعتبر الاقتراح فرصة منتج جديدة؛ التسجيل ينص صراحة أنه ليس منتجاً جديداً لا تحمله زيرا.\nتحقق من عودة «زبدة الشيا للبشرة» في المسحات التالية قبل افتراض تراجع الاهتمام بها، لأن تدوير الاقتراحات بين المسحات معروف.\nتجنب نسخ ادعاء «الأصلية» كشعار إعلاني دون دليل مسجل؛ اختبر صياغات وصفية قابلة للتحقق بدلاً من ذلك.','\n',char(10)),1795147227509,'','','','');
INSERT INTO competitor_ad_analyses VALUES(86,80,'Zynah (قناة توزيع) تحمل 4 منتجات سيلوليت مسجلة: Hathor Organics وMeraki وAreej وBel Clinic؛ والبروفايل المطابق المسجل هو Norshek (عناية طبيعية/إيكو، مجاور، تشابه 46/100) — وليس مسجلاً له منتج سيلوليت في التسجيل','المسجل: منتجات سيلوليت مفردة (كريم/زيت/لوشن) بأسعار 230–590 ج.م، مع وصف Meraki المسجل «top-seller» وادعاء «تحسّن ملحوظ من اليوم الثالث». المستنتج فقط: زاوية منتج مفرد بتحسّن سريع مزعوم، مقابل زاوية زيرا المضادة المسجلة: «روتين 3 قطع + يوريا/ريتينول».','غير مسجل — لا يوجد نص هوك أو منطوق إعلاني في التسجيل؛ المسجل فقط وسم «new» على كريم Meraki في نتائج البحث ووصف «top-seller» على صفحته.','غير مسجل كإعلان — التسجيل فحص حي لموقع zynah.me (بحث «cellulite» وصفحات منتجات ومجموعة)، وليس وصفاً لإعلان فيديو أو صورة أو نص إعلاني.','المسجل: 4 منتجات سيلوليت مفردة على Zynah: Areej بـ230 ج.م، وHathor بـ360 ج.م، وBel Clinic بـ550 ج.م، وMeraki بـ590 ج.م (150مل، OutOfStock) — كلها تحت 799 ج.م؛ وعرض البروفايل المطابق المسجل: Norshek Skin Kin Body Lotion بـ395 ج.م.','غير مسجلة — لا تاريخ بدء إعلان/إدراج ولا مدة تشغيل مذكورة؛ المسجل فقط: فحص حي 2026-11-20 ~06:30 EET (جولة سوق 86) وتصحيح جولة 46 بتاريخ 2026-11-19، والموقع لا يعرض تاريخ إدراج لأي منتج فلا يمكن الجزم بأن أي منتج إطلاق جديد.','لا توجد أرقام أداء مسجلة، فلا يمكن تأكيد النجاح. المستنتج فقط كاحتمال: توفّر بدائل مفردة منخفضة الحاجز السعري (230–590 ج.م) على قناة مصرية معروفة، مع وسم «new» ونفاد مخزون Meraki — وهي إشارة طلب محتملة غير مؤكدة — وادعاء تحسّن سريع قد يجذب الانتباه، لكنه غير مثبت في التسجيل.','الأوضح المسجل: كريم Meraki (590 ج.م، الأعلى سعراً بين الأربعة) OutOfStock وموسوم «new» لكنه غير موجود في صفحة مجموعة Meraki نفسها (6 منتجات فقط) وبلا تاريخ إدراج مؤكد؛ إضافة إلى أن العرض كله منتجات مفردة متنافسة سعرياً وليس روتيناً متكاملاً، ولا يوجد منتج يوريا مسمّى أو منتج جلد وزة مسجل على القناة.',replace('اختبر زاوية «روتين 3 قطع + يوريا/ريتينول» كبديل قابل للاختبار مقابل المنتج المفرد، دون ادعاء نتيجة طبية أو زمنية محددة.\nتجنّب ادعاءات سرعة النتيجة مثل «من اليوم الثالث» ما لم تكن موثقة؛ واستخدم لغة وصفية قابلة للتحقق بدل وعود زمنية.\nتبنَّ التحقق من بحث الموقع نفسه قبل الاعتماد على بحث جوجل العام عند رصد المنافسين، لأن الاعتماد على الأخير أدى لخطأ في جولة 46.\nاختبر حزمة قيمة بسعر إجمالي واضح تحت سقف 799 ج.م مع توضيح دور كل قطعة في الروتين، بدل منافسة سعرية على منتج مفرد.\nتأكد قبل أي إطلاق/إعلان من توفّر المخزون واكتمال صفحة المجموعة وظهور المنتج فيها، وتجنّب وسم «جديد» بلا تاريخ إدراج قابل للتحقق.','\n',char(10)),1795149637801,'','','','');
INSERT INTO competitor_ad_analyses VALUES(87,81,'Shaan','غير مسجلة كزاوية إعلان؛ المسجل فقط وجود منتج حي بتركيز يوريا 30% يطابق إشارة بحث مسجلة، دون وصف لزاوية أو رسالة إعلانية.','غير مسجل؛ لا يوجد نص هوك أو منطوق أو محتوى إعلاني موصوف في التسجيل.','غير مسجل؛ التسجيل رصد منتج حي على قناة توزيع مصرية (Nefro Glow — جولة سوق 87)، وليس وصف إعلان أو فورمات.','Shaan يوريا 30% كريم 100جم بـ270 بدل 320، وShaan يوريا 10% كريم 200جم بـ239 بدل 280 — منتجان حيّان على قناة توزيع مصرية بتاريخ الرصد.','غير مسجلة؛ لا تاريخ بدء ولا مدة تشغيل مذكورة، والمسجل فقط تاريخ رصد حي 2026-11-20 ~07:10 EET (جولة سوق 87).','لا يوجد دليل مسجل على نجاح أو أداء أو مبيعات، ولا ادعاء فعالية؛ المستنتج فقط أن المنتج يطابق إشارة بحث مسجلة («يوريا 30»، «كريم يوريا ٣٠ للجسم») وفرصة «طلب بحث على يوريا 30%»، فوجود منتج 30% فعلي في السوق قد يجذب هذا البحث — وهذا توافق محتمل مع الطلب، وليس نتيجة أداء مثبتة.','الأوضح: لا يوجد أي محتوى إعلاني أو دليل أداء موصوف في التسجيل لتقييمه، والمنتج 30% مسجل بحجم 100جم فقط مقابل منتج 10% بحجم 200جم، فلا يمكن من التسجيل معرفة ميزة القيمة؛ والتسجيل نفسه ينص على عدم وجود ادعاء فعالية أو مبيعات.',replace('تتبع منتج اليوريا 30% الحي في الجولات القادمة من حيث السعر والحجم والتوافر، قبل أي قرار إنتاج أو محتوى، وبموافقة المالك.\nاختبر تموضع تركيز 25% الخاص بزيرا أمام وجود تركيز 30% في السوق، بصياغة تمايز واضحة وقابلة للقياس دون ادعاء طبي ودون مقارنة باسم براند.\nاختبر استخدام لغة البحث المسجلة نفسها («يوريا 30»، «كريم يوريا ٣٠ للجسم») كفرضية صياغة، لا كادعاء فعالية.\nتجنب نسخ العرض السعري المسجل أعمى؛ واختبر عرضاً خاصاً بزيرا بسعر وحجم معلنين بوضوح.\nلا تعتبر الرصد الحي الواحد استمرارية؛ اطلب رصداً متكرراً في الجولات التالية للتأكد من ثبات التوافر والسعر قبل أي استنتاج عن المنافسة.','\n',char(10)),1795151996811,'','','','');
INSERT INTO competitor_ad_analyses VALUES(88,81,'Shaan','مستنتج من المسجل: التموضع حول تركيز يوريا 30% كريم للجسم كمنتج فعلي يطابق إشارة بحث مسجلة («يوريا 30»، «كريم يوريا ٣٠ للجسم»)، مع خصم سعري.','غير مسجل — لا يوجد نص هوك أو منطوق إعلاني موصوف في التسجيل؛ المسجل فقط السعر المخفض (270 بدل 320) وليس هوكاً موصوفاً.','غير مسجل كإعلان فيديو أو صورة — التسجيل ملاحظة رصد سوق / قائمة منتج حي على قناة توزيع مصرية (Nefro Glow) في جولة سوق 87.','Shaan يوريا 30% كريم 100جم بـ270 بدل 320؛ والمسجل أيضاً Shaan يوريا 10% كريم 200جم بـ239 بدل 280.','غير مسجلة — لا تاريخ بدء ولا مدة تشغيل مذكورة؛ المسجل فقط أن المنتج حي في فحص 2026-11-20 ~07:10 EET (جولة سوق 87، زحف طازج <دقيقة).','لا توجد أرقام أداء مسجلة؛ المستنتج فقط أنه على الأرجح يلفت الانتباه لأنه منتج 30% فعلي يطابق طلب بحث مسجلاً (لم يعد مجرد بحث) مع خصم سعري واضح 270 بدل 320، لكن نجاحه الفعلي غير مسجل.','الأوضح من التسجيل: لا يوجد محتوى إعلاني موصوف (لا هوك ولا فيديو ولا رسالة مميزة) ولا أي ادعاء أو دليل مسجل عن فعالية أو مبيعات؛ الظهور المسجل قائمة سعر وتركيز فقط، وعبوة الـ30% المسجلة 100جم أصغر من عبوة الـ10% المسجلة 200جم.',replace('تتبع ظهور منتجات يوريا 30% في الجولات القادمة ومراجعة تموضع الـ25% أمام المالك قبل أي قرار، ولا قرار إنتاج/محتوى من غير موافقة المالك.\nاختبار صياغة تستخدم لغة البحث المسجلة («يوريا 30»، «كريم يوريا ٣٠ للجسم») دون أي ادعاء طبي أو ادعاء فعالية.\nاختبار وضوح العرض السعري والحجم معاً (سعر قبل/بعد وحجم العبوة) لأن المسجل يبرز السعر والحجم، دون نسخ السعر أو التركيز أعمى.\nتجنب المقارنة باسم براند والادعاءات الطبية في محتوى زيرا، والاكتفاء بوصف المنتج والاستخدام المسجل دون تعميمات فعالية.','\n',char(10)),1795152021373,'','','','');
INSERT INTO competitor_ad_analyses VALUES(89,82,'غير محدد من التسجيل','قلق الأصالة/الجودة عند باحثي زبدة الشيا — البحث عن «الأصلية» وتمييزها عن أي شيا، وليس منتجاً أو مشكلة جديدة مسجلة','«زبدة الشيا الاصلية»','اقتراح إكمال تلقائي في Google Egypt (hl=ar, gl=eg) — لغة بحث، وليس إعلان فيديو أو صورة مسجلاً','غير مسجل في الملاحظة — لا يوجد عرض مذكور','غير مسجلة كمدة تشغيل/استمرارية؛ المسجل فقط هو أول ظهور في مسح 07:10 EET بتاريخ 2026-11-20، ولا يوجد تاريخ بدء إعلان أو مدة مسجلة','المسجل: ظهر الاقتراح لأول مرة وحلّ محل «زبدة الشيا للبشرة» بينما بقيت الكلمات الـ11 الأخرى بلا تغيير عن مسح 06:51 EET. المستنتج: يرجّح أن الرسالة تلقى صدى لأنها تخاطب قلق الأصالة/الجودة لدى الباحثين (البحث عن «الأصلية» لا أي شيا)، وزيرا تحمل الشيا أصلاً كمكوّن في روتين KP، فالاهتمام موجود أصلاً ولا يحتاج خلق منتج أو مشكلة جديدة.','إشارة مسح واحد فقط لا تكفي؛ المسجل في الملاحظة رقم 21 أن الاقتراحات تدوّر وتنعكس بين المسحات، فلا يوجد دليل مسجل على ثبات الاقتراح أو على أداء/نجاح إعلان، وقد يختفي في المسح التالي.',replace('اختبر في محتوى زيرا لغة «الأصلية» والشفافية حول مصدر/جودة زبدة الشيا كمكوّن في روتين KP، دون ادعاءات طبية ودون مقارنة باسم براند.\nلا تبنِ حملة أو تغييراً دائماً على مسح واحد؛ تابع المسحات القادمة لتأكيد ثبات «زبدة الشيا الاصلية» قبل توسيع الاستثمار.\nأجب عن أسئلة AEO بصيغة توضيحية عن المقصود بالأصلية وكيفية تقييم الجودة عموماً، دون وعود علاجية.\nتجنب نسخ الاقتراح حرفياً كادعاء منتج؛ استخدمه كإشارة بحث فقط حتى يثبت في مسحات لاحقة.\nاختبر رسالة الأصالة مقابل رسالة الاستخدام للبشرة التي خرجت من القائمة في هذا المسح، دون استنتاج أداء من مسح واحد.','\n',char(10)),1795152040003,'','','','');
INSERT INTO competitor_ad_analyses VALUES(90,82,'غير محدد من التسجيل','قلق الأصالة/الجودة عند باحثي زبدة الشيا — البحث عن «الأصلية» وليس أي زبدة شيا','«زبدة الشيا الاصلية» — كلمة «الأصلية» كمحدد للبحث يميز المنتج الأصلي عن غيره','لغة بحث — اقتراح إكمال تلقائي Google Egypt (hl=ar, gl=eg)، وليس إعلان فيديو مسجلاً','غير مسجل — لا يوجد عرض مسجل في الملاحظة','مدة التشغيل غير مسجلة؛ أول ظهور مسجل في مسح 07:10 EET بتاريخ 2026-11-20، ولم تكن موجودة في مسح 06:51 EET في نفس اليوم','لا توجد أرقام أداء مسجلة؛ القوة المسجلة هي أن الاقتراح حلّ محل «زبدة الشيا للبشرة» في نفس المسح بينما بقيت الكلمات الـ11 الأخرى بلا تغيير، ما يشير — وفق التفسير المسجل — إلى أن الباحثين يميزون الأصلية ويبحثون عنها تحديداً، وهو قلق يتقاطع مع وجود الشيا أصلاً كمكوّن في روتين KP لدى زيرا.','إشارة مسح واحد فقط لا تكفي؛ الملاحظة نفسها تنبه (ملاحظة #21) إلى أن الاقتراحات تدوّر وتنعكس بين المسحات، فقد تختفي في المسح التالي، كما أنها ليست منتجاً/مشكلة جديدة — فزيرا تحمل الشيا أصلاً — فلا يمكن اعتبارها دليل نجاح إعلان أو طلب جديد.',replace('اختبر لزيرا رسالة أصالة/جودة الشيا في روتين KP (ما الذي يجعلها أصلية/موثوقة) بصياغة قابلة للتحقق، دون ادعاءات طبية أو مقارنة باسم براند.\nتابع اقتراح «زبدة الشيا الاصلية» في المسحات التالية قبل تثبيته كزاوية؛ لا تبنِ حملة على إشارة مسح واحد قابلة للانعكاس.\nاختبر محتوى AEO/بحث يجيب عن سؤال الأصالة: كيف يميز الباحث الشيا الأصلية، باستخدام لغة البحث المسجلة نفسها.\nتجنب نسخ الاقتراح حرفياً كادعاء، وتجنب تحويله إلى وعد علاجي أو تفوق على منافس محدد غير مسجل.\nاختبر بدائل صياغة حول الجودة/الأصالة مقابل صياغة الاستخدام («للبشرة») التي خرجت من القائمة في هذا المسح، لمعرفة أيهما يثبت في المسحات التالية.','\n',char(10)),1795152072018,'','','','');
INSERT INTO competitor_ad_analyses VALUES(91,83,'غير محدد من التسجيل','المسجل: صياغة استخدام عام «زبدة الشيا للبشرة»؛ المستنتج: زاوية استخدام على البشرة بدل زاوية الأصالة «زبدة الشيا الاصلية».','المسجل: عبارة الاقتراح نفسها «زبدة الشيا للبشرة» ضمن أعلى 10 اقتراحات لكلمة «زبدة الشيا»؛ لا يوجد نص هوك إعلاني آخر مسجل.','لغة بحث — Google Egypt autocomplete (hl=ar, gl=eg)، اقتراح بحث ضمن أعلى 10 اقتراحات؛ ليس فيديو ولا إعلان مدفوع مسجلاً في الملاحظة.','غير مسجل — لا يوجد عرض أو سعر أو خصم أو باقة مذكورة في الملاحظة.','مدة التشغيل/الاستمرارية غير مسجلة؛ المسجل فقط: تاريخ الرصد 2026-11-20، ظهور العبارة في مسح 07:49 EET بعد غيابها في مسح 07:31 EET، وخروج «زبدة الشيا الاصلية» بعد 5 مسحات متتالية.','لا توجد أرقام أداء مسجلة فلا يمكن تأكيد نجاح إعلاني؛ المسجل فقط عودتها لأعلى 10 اقتراحات. المستنتج: صياغة «للبشرة» على الأرجح تتوافق مع لغة بحث عامة وواضحة عن الاستخدام، أبسط وأوسع من صياغة الأصالة.','صياغة عامة غير مميزة بلا براند أو عرض أو تمييز، ومتقلبة — ظهرت بعد غياب في المسح السابق — ولا تفتح فرصة منتج جديدة لزيرا لأنها تحمل زبدة شيا (75 جم) ضمن روتين KP.',replace('تبنَّ/اختبر صياغة «للبشرة» في وصف زبدة الشيا 75 جم الحالية ضمن روتين KP، دون تقديمها كمنتج جديد.\nاختبر صياغة الاستخدام على البشرة مقابل صياغة الأصالة في عناوين AEO، بصياغة عامة دون ادعاءات طبية ودون مقارنة باسم براند.\nتجنب الاعتماد على اقتراح واحد متقلب: أعد المسح في الأيام التالية للتأكد من الثبات قبل توسيع المحتوى.\nلا تلغِ شرط بوابة AEO في ملاحظة #25 بسبب خروج «الاصلية»؛ الخروج يوقف سلسلة الثبات فقط وباقي موافقة المالك.\nتجنب نسخ صياغة الأصالة كزاوية وحيدة؛ باقي الكلمات الـ11 بلا تغيير، فلا تعميم من مسح واحد.','\n',char(10)),1795154422003,'','','','');
INSERT INTO competitor_ad_analyses VALUES(92,84,'غير محدد من التسجيل','زاوية لغة البحث بالمكوّن: استخدام الصيغة اللاتينية «urea» داخل استعلام عربي عن كريم يوريا للجسم، بدلاً من الاقتصار على «يوريا» بالعربية','«كريم urea للجسم» — أول ظهور مسجل للصيغة اللاتينية «urea» في اقتراحات جوجل مصر','اقتراح بحث في جوجل مصر (وسم الأدلة: SEARCH) — وليس إعلان فيديو أو صورة مسجلاً','غير مسجل — لا يوجد عرض مذكور في التسجيل','تاريخ الرصد المسجل: 2026-11-20، ومسح لغة بحث جوجل مصر 2026-11-20 11:30 EET؛ وهو أول ظهور في سلسلة المسحات. مدة تشغيل/استمرارية غير مسجلة.','لم تسجل أرقام أداء؛ والمسجل هو أول ظهور للصيغة اللاتينية في المسح، ما يشير — كاستنتاج لا كرقم مسجل — إلى دخول «urea» لغة البحث المصرية عن كريم اليوريا، أي بحث قائم على المكوّن وليس على اسم منتج محدد.','أضعف نقطة: ظهور واحد فقط في مسح واحد بتاريخ 2026-11-20 دون تكرار مثبت في مسحات لاحقة، ودون محتوى إعلان أو عرض أو أرقام أداء مسجلة؛ فلا يمكن اعتباره اتجاهاً ثابتاً بعد، والصيغة اللاتينية وحدها قد لا تكون مفهومة لكل الباحثين بالعربية.',replace('اختبر إدراج «urea» بجانب «يوريا» في عناوين ووصف منتج زيرا الحالي (لوشن KP يوريا 25%) وفي SEO، ولا تعتمدها أساساً قبل ثبوتها في المسحات القادمة.\nلا تطلق منتجاً جديداً بناءً على هذا الاقتراح؛ التسجيل نفسه يوضح أن زيرا تحمل كريم يوريا للجسم أصلاً.\nتابع في المسحات القادمة هل تتكرر «urea» وتستمر أم كانت ظهوراً عابراً، قبل أي تغيير دائم في الكوبي.\nلا تعتبر «كريم يوريا ١٠ للجسم» و«كريم يوريا 20 للجسم» طلباً جديداً؛ المسجل أنهما تبديل شكل أرقام لاستعلامي 10 و20 الموجودين أصلاً.\nتجنب الادعاءات الطبية أو المقارنة باسم براند في أي كوبي مستوحى من هذا الاقتراح، والتزم بما هو مسجل عن المنتج فقط.','\n',char(10)),1795167650625,'','','','');
INSERT INTO competitor_ad_analyses VALUES(93,85,'يوسيرين','غير مسجلة كزاوية إعلان؛ المسجل فقط اتجاه بحث في اقتراحات «كريم يوريا للجسم»: الترطيب وطلب تركيز يوريا أعلى من 25%، كما في استعلام «كريم يوريا 40 للجسم» — وهذا استنتاج من نصوص البحث وليس زاوية إعلان موصوفة.','غير مسجل — لا يوجد هوك إعلاني أو نص إعلان في التسجيل؛ المسجل فقط نصوص اقتراحات البحث الثلاثة','مسح لغة بحث جوجل مصر (SEARCH_LANGUAGE) — اقتراحات بحث، وليس إعلان فيديو أو صورة مسجلاً','غير مسجل — لا يوجد عرض سعر أو خصم أو حزمة في التسجيل','غير مسجلة — لا تاريخ بدء إعلان ولا مدة تشغيل مسجلة؛ المسجل فقط أوقات المسح في 2026-11-20: 11:10 و11:30 و11:49 EET، وتذبذب خلال نحو 40 دقيقة','لا يوجد دليل أداء إعلاني مسجل يثبت نجاحاً؛ ما يمكن قوله من التسجيل فقط هو أن عودة الاقتراحات الثلاثة إلى أعلى 10 في 11:49 بعد خروجها في 11:30 تشير إلى طلب بحث متكرر ومستمر حول كريم يوريا للجسم وليس ظهوراً لمرة واحدة، مع بقاء باقي الكلمات الـ11 بلا تغيير — وهذا استنتاج من التذبذب وليس مقياس أداء.','التذبذب وعدم الثبات: الاقتراحات الثلاثة خرجت من أعلى 10 في مسح 11:30 قبل أن تعود في 11:49، و«كريم urea للجسم» ظهر ثم خرج في الفترة نفسها؛ فلا يمكن الاعتماد على لحظة مسح واحدة، كما أن أحد الاقتراحات الثلاثة استعلام عن علامة منافسة وليس طلب منتج عام، والمسح نفسه ينص على أنه لا فرصة منتج جديدة فيه.',replace('تقوية الفرصة #1 القائمة (يوريا 30%) واختبارها، لأن «يوريا 40» دليل مستمر على طلب تركيز أعلى من 25% — دون فتح فرصة مكررة.\nتبنّي لغة البحث المسجلة «كريم يوريا مرطب للجسم» و«كريم يوريا 40 للجسم» في عناوين ووصف زيرا، دون ادعاءات طبية.\nتجنّب اعتبار تذبذب نحو 40 دقيقة اتجاهاً جديداً؛ انتظار ثبات الاقتراحات عبر مسوحات لاحقة قبل أي تغيير في المنتج أو المحتوى.\nتجنّب بناء محتوى أو منتج على استعلام العلامة المنافسة؛ المسجل أنه استعلام علامة وليس فجوة منتج عند زيرا.\nاختبار صياغتي «يوريا» العربية و«urea» الإنجليزية في البحث والمحتوى، لأن «كريم urea للجسم» ظهر أول مرة في 11:30 ثم خرج في 11:49 — مراقبة فقط دون قرار فوري.','\n',char(10)),1795168864506,'','','','');
INSERT INTO competitor_ad_analyses VALUES(94,86,'غير محدد من التسجيل','الزاوية المستخلصة من عبارات البحث المسجلة فقط: تحديد التركيز والمشكلة والمنطقة — «كريم يوريا ٣٠ للجسم» وجلد الوزة والسيلوليت، مع تحديد منطقة مثل البكيني — بدل كلمة عامة عن الترطيب.','هوك إعلاني غير مسجل؛ المسجل فقط عبارات بحث، أبرزها «كريم يوريا ٣٠ للجسم» و«علاج جلد الوزة في منطقة البكيني» و«كريم ازالة سيلوليت».','لغة بحث: Google Egypt autocomplete — مسح 12:29 EET مقابل مسح 12:10 EET في 2026-11-20؛ لا يوجد إعلان فيديو أو صورة مسجل.','غير مسجل — لا يوجد عرض أو سعر أو خصم مذكور في الملاحظة.','غير مسجلة كمدة تشغيل إعلان؛ المسجل فقط تاريخ الرصد 2026-11-20 ووقتا المسح 12:10 و12:29 EET، ولا تاريخ بدء إعلان مسجل.','لا يوجد رقم أداء إعلان مسجل؛ قوة الإشارة المسجلة وحدها هي عودة «كريم يوريا ٣٠ للجسم» إلى أعلى 10 مع وجود «يوريا 30»/«يوريا ٣٠٪» في المراتب 11–12، ما يشير — حسب الملاحظة — إلى طلب ثابت على تركيز أعلى من 25% وليس ومضة، إضافة إلى تحديد الباحثات للمنطقة والمشكلة.','الأوضح: إشارة مسح واحد لا تكفي؛ الكلمة العارية خرجت من أعلى 10 في 11 من 12 كلمة، فهو تدوير قائمة لا موجة طلب (ملاحظة #21)، و«سيلوليت جورجينا» ترند باسم مشهورة يُتوقع موته بعد مسح واحد كما حدث مع «كريم urea للجسم» الغائب حتى الآن.',replace('اختبار محتوى AEO يجيب عن نية «يوريا 30% مقابل 25%» و«كريم يوريا ٣٠ للجسم» بلغة وصفية دون ادعاء طبي أو مقارنة باسم براند.\nاختبار محتوى يحدد المنطقة والمشكلة كما في «علاج جلد الوزة في منطقة البكيني» و«علاج جلد الوزة والشعر تحت الجلد»، بدل استهداف كلمة عامة فقط.\nتجنب الاستثمار في ترند المشاهير «سيلوليت جورجينا» قبل تأكيد استمراره في أكثر من مسح.\nتجنب استهداف «سيلوليت و ليبوديما»؛ التسجيل يذكر أن زيرا لا تعالج ليبوديما.\nعدم اتخاذ قرار من مسح واحد: تأكيد أي كلمة في مسحين متتاليين على الأقل قبل إنتاج محتوى أو إعلان حولها، بسبب تدوير القائمة المسجل.','\n',char(10)),1795171224116,'','','','');
INSERT INTO competitor_ad_analyses VALUES(95,87,'غير محدد من التسجيل','من الاسم المسجل فقط: زاوية اسم محدد بوعد حسي بالملمس — «لمسة حرير» — بدل «مخمرية» العامة؛ ولا يوجد وصف إبداعي أو زاوية إعلان مسجلة غير ذلك.','الهوك الظاهر في التسجيل فقط هو الاسم نفسه في اقتراحات البحث: «مخمرية لمسة حرير»؛ ولا يوجد نص هوك أو منطوق إعلان مسجل.','ليس إعلان فيديو مسجلاً؛ المصدر المسجل هو مسح اقتراحات بحث جوجل مصر (لغة بحث) — فورمات الإعلان نفسه غير مسجل.','غير مسجل — لا سعر ولا عرض ولا باقة مذكورة لـ«لمسة حرير» في التسجيل؛ السعر المسجل 199 ج يخص مخمرية زيرا الكريمي (8 روايح) فقط.','غير مسجلة — لا تاريخ بدء ولا مدة تشغيل مذكورة؛ تاريخ الرصد الوحيد المسجل هو 2026-11-20 الساعة 13:09 EET، وهي إشارة مسح واحد فقط.','على الأرجح: اسم محدد دخل أعلى 10 اقتراحات «مخمرية» وحلّ محل «مخمرية فيونكة» التي خرجت، ما يشير — كاستنتاج من إشارة واحدة فقط — إلى طلب بحث متصاعد على اسم/رائحة بعينها لا على فئة عامة؛ لم يثبت استمراره بعد.','ضعف الإثبات: إشارة مسح واحد فقط (وسم الأدلة UNKNOWN) بلا محتوى إعلان أو سعر أو عرض مسجل، و«لمسة حرير» غير معروف إن كانت منتج منافس أو مجرد اسم رائحة مطلوبة، وقد تختفي في المسحات القادمة كما اختفت «مخمرية فيونكة».',replace('اختبر قبل التبني: راقب «لمسة حرير» في مسحات جوجل التالية للتثبت قبل أي خطوة منتج أو محتوى.\nاختبر وصفاً حسياً للملمس الناعم لمخمرية زيرا الكريمي الحالية (8 روايح، 199 ج) دون نسخ الاسم «لمسة حرير» أو الادعاء أنه منتج زيرا.\nاختبر محتوى يستهدف أسماء روائح محددة مطلوبة بدل «مخمرية» العامة فقط، وقس ظهورها في الاقتراحات.\nتجنّب نسخ الاسم أعمى أو إطلاق منتج بنفس الاسم قبل التأكد من مصدره وطلب حقيقي مستمر.\nتتبّع دورة دخول وخروج أسماء المخمرية في أعلى 10 كمؤشر طلب، ولا تبنِ قراراً على مسح واحد.','\n',char(10)),1795173560575,'','','','');
INSERT INTO competitor_ad_analyses VALUES(96,88,'غير محدد من التسجيل','غير مسجلة كزاوية إعلان — المسجل فقط إشارة بحث: الباحثون يكتبون «زبدة الشيا الخام» بالاسم، ودخلت أعلى 10 اقتراحات «زبدة الشيا» مكان «زبدة الشيا للبشرة».','غير مسجل — لا يوجد نص هوك أو محتوى إعلان مذكور في التسجيل.','غير مسجل كفورمات إعلان — المسجل مسح اقتراحات بحث جوجل مصر بتاريخ 2026-11-20 13:09 EET، وليس إعلاناً موصوفاً.','غير مسجل — لا يوجد عرض مذكور؛ المسجل فقط أن زيرا تحمل المنتج نفسه (زبدة الشيا الخام، 250 ج).','غير مسجلة — لا يوجد تاريخ بدء أو مدة تشغيل؛ تاريخ الرصد الوحيد المسجل 2026-11-20 13:09 EET، وهي إشارة مسح واحد.','لا يوجد أداء إعلان مسجل؛ ما يمكن استنتاجه بحذر من الإشارة وحدها هو أن مطابقة الاسم كما يكتبه الباحثون («الخام») قد تسهل الظهور في الاقتراحات، بدليل دخولها أعلى 10 مكان «زبدة الشيا للبشرة» — لكن وسم الأدلة UNKNOWN وإشارة واحدة، فلا يمكن تأكيد نجاح.','الأوضح: إشارة مسح واحد فقط بوسم أدلة UNKNOWN، لم تثبت في مسحات لاحقة، ولا يوجد محتوى إعلان أو أداء مسجل — فالاعتماد عليها وحدها للتوسع مخاطرة؛ كما أن «الخام» وحدها لا تميز المنتج لأن زيرا تحمل المنتج نفسه.',replace('اعتمدوا اسم «زبدة الشيا الخام» حرفياً في عنوان ووصف منتج زيرا 250 ج كما يكتبه الباحثون، واختبروا ظهوره، دون ادعاء منتج جديد.\nحافظوا على «زبدة الشيا الاصلية» الثابتة (ملاحظة #34) ولا تستبدلوها بـ«الخام»؛ اختبروا الصياغتين معاً.\nلا توسعوا بناءً على مسح واحد — راقبوا المسحات القادمة لتثبيت دخول «الخام» أعلى 10 أو خروجها قبل أي استثمار.\nتجنبوا أي ادعاءات طبية أو مقارنات باسم براند عند استخدام «الخام» أو «الاصلية»؛ ركزوا على وصف المنتج فقط.','\n',char(10)),1795173582297,'','','','');
INSERT INTO competitor_ad_analyses VALUES(97,88,'غير محدد من التسجيل','غير مسجلة كزاوية إعلانية؛ الإشارة المسجلة فقط هي بحث باسم «زبدة الشيا الخام» بدل «زبدة الشيا للبشرة»','غير مسجل؛ لا يوجد نص هوك أو منطوق في التسجيل','غير مسجل كفورمات إعلان؛ المصدر المسجل هو اقتراحات بحث جوجل مصر، وليس فيديو أو إعلاناً موصوفاً','غير مسجل؛ لا سعر ولا خصم مذكور، والتسجيل يذكر فقط أن زيرا تحمل زبدة الشيا الخام 250 ج','غير مسجلة؛ تاريخ الرصد المسجل الوحيد هو 2026-11-20 والمسح 20 نوفمبر 13:09 EET، ولا تاريخ بدء ولا مدة مذكورة، وهي إشارة مسح واحد','لا يوجد دليل أداء مسجل؛ الاستنتاج الوحيد المسموح به أن دخول «الخام» مكان «للبشرة» في أعلى 10 يشير إلى أن الباحثين يكتبون اسم المنتج كما هو ويركزون على صفة الخام، مع ثبات «الأصلية» (ملاحظة #34)','إشارة مسح واحد بوسم UNKNOWN؛ قد تختفي في المسح التالي، ولا تثبت نية شراء أو تفوق منتج، ولا يوجد منافس أو إعلان محدد يمكن تحليل ضعفه الإبداعي',replace('اختبر استخدام عبارة «زبدة الشيا الخام» حرفياً في عنوان صفحة زيرا ووصفها، وقارن النقر والظهور قبل التغيير وبعده.\nاحتفظ بصيغة «زبدة الشيا الاصلية» الثابتة (ملاحظة #34) ولا تستبدلها بـ«الخام» بالكامل؛ اختبرهما كصيغتين منفصلتين.\nلا تبنِ ميزانية أو حملة على إشارة مسح واحد؛ انتظر تثبيتها في مسحين قادمين على الأقل قبل التوسع.\nتجنب الادعاءات الطبية وربط «الخام» بفوائد للبشرة، والتزم بوصف المنتج كما هو: زبدة الشيا الخام 250 ج.\nاختبر أسئلة AEO بصيغة الباحثين أنفسهم مثل «ما زبدة الشيا الخام؟» بإجابة قصيرة تعتمد الاسم المسجل دون مقارنة بأي براند.','\n',char(10)),1795173582552,'','','','');
INSERT INTO competitor_ad_analyses VALUES(98,89,'غير محدد من التسجيل','غير مسجلة — التسجيل لا يصف زاوية إعلانية؛ المسجل فقط تقلّب اقتراحي بحث «مخمرية فيونكة» و«مخمرية لمسة حرير» حول حد أعلى 10 اقتراحات «مخمرية».','غير مسجل — لا يوجد نص هوك أو منطوق في التسجيل؛ المسجل فقط دخول «مخمرية فيونكة» مركز 5 في مسح 13:30 وخروج «مخمرية لمسة حرير».','غير مسجل كفورمات إعلان؛ المصدر المسجل هو مسح لغة بحث جوجل مصر، وليس وصف فيديو أو صورة إعلان.','غير مسجل — لا يوجد عرض أو سعر أو خصم مذكور في التسجيل.','مدة تشغيل الإعلان غير مسجلة. المسجل زمنياً فقط: «لمسة حرير» موجودة من 19 نوفمبر 02:49 في 37 مسحاً، و«فيونكة» من 19 نوفمبر 16:09 في 53 مسحاً، وآخر مسح مسجل 20 نوفمبر 13:30 EET؛ وهذا يخص استمرارية الظهور في اقتراحات البحث وليس مدة إعلان.','لا يوجد دليل أداء أو نجاح مسجل، فلا يمكن تأكيد أن إعلاناً يعمل. المسجل فقط أن اسم مخمرية محدد يستمر في الظهور ضمن أعلى 10 اقتراحات «مخمرية» ويتبادل الخانة العاشرة، وأن «زبدة الشيا الاصلية» ما زالت موجودة في مسح 13:30 — أي اهتمام بحثي متكرر بالاسم المحدد، وليس دليل نجاح إعلان.','التقلب وعدم الثبات عند حد أعلى 10 هو الأوضح: «لمسة حرير» خرجت في 12:49 ورجعت 13:09 ثم خرجت مجدداً 13:30 بعد مسح واحد، و«فيونكة» تتبادل معها الخانة العاشرة؛ كما أن وصفها بأنها «جديدة» كان غير صحيح وصححه التسجيل، فأي استنتاج مبني على مسح واحد هش.',replace('اختبر قبل التبني: لا تعتبر ظهور اسم في مسح واحد فرصة جديدة؛ اشترط تكرار الظهور في مسحات متتالية قبل أي محتوى لزيرا.\nتجنب ادعاء «جديد» أو أي ادعاء أداء أو طبي: تحقق تاريخياً قبل صياغة أي عنوان، كما صحح التسجيل وصف «لمسة حرير» بأنها جديدة.\nاختبر محتوى AEO يجيب عن البحث باسم مخمرية محدد دون ذكر براند منافس أو مقارنة باسمه، وبمعلومات مسجلة فقط عن الاستخدام والاختيار.\nراقب الاستمرارية لا اللحظة: تتبع الاسمين و«زبدة الشيا الاصلية» عبر مسحات لاحقة، واعتبر الثبات في أعلى 10 إشارة أقوى من الدخول مرة واحدة.\nلا تنسخ أعمى: التسجيل لا يصف إعلاناً أو عرضاً أو هوكاً، فلا يوجد نموذج إعلاني قابل للنسخ؛ ابنِ اختبار زيرا على نية البحث المسجلة فقط.','\n',char(10)),1795174780715,'','','','');
INSERT INTO competitor_ad_analyses VALUES(99,89,'غير محدد من التسجيل','غير مسجلة كزاوية إعلان؛ المسجل فقط تقلّب اقتراحات بحث «مخمرية» حول اسمين محددين («فيونكة» و«لمسة حرير») حول حد أعلى 10.','غير مسجل؛ لا يوجد نص إعلان أو هوك مسجل، والمسجل فقط دخول «مخمرية فيونكة» إلى أعلى 10 اقتراحات «مخمرية» في المركز 5 في مسح 13:30.','غير مسجل كفورمات إعلان؛ المصدر المسجل هو مسح لغة بحث جوجل مصر، وليس وصف إعلان أو فيديو.','غير مسجل؛ لا يوجد عرض مذكور في التسجيل.','مدة تشغيل إعلان غير مسجلة؛ المسجل فقط تواريخ الرصد: «لمسة حرير» موجودة من 19 نوفمبر 02:49، و«فيونكة» من 19 نوفمبر 16:09، حتى مسح 20 نوفمبر 13:30، مع تقلّب مستمر حول الخانة العاشرة.','لا يوجد دليل أداء مسجل يثبت أن إعلاناً يعمل؛ المستنتج فقط من التسجيل أن بقاء اسم مخمرية محدد ضمن أعلى 10 اقتراحات «مخمرية» عبر 53 مسحاً لـ«فيونكة» و37 مسحاً لـ«لمسة حرير» قد يعكس بحثاً متكرراً باسم محدد، وليس نجاح إعلان مثبتاً.','التذبذب وعدم الثبات: الاسمان يتبادلان الخانة العاشرة، و«لمسة حرير» خرجت في 12:49 ورجعت 13:09 ثم خرجت مجدداً في 13:30 بعد مسح واحد؛ كما أن وصفها بأنها «جديدة» تم تصحيحه في التسجيل، فالإشارة لا تثبت طلباً مستقراً أو نجاحاً.',replace('اختبر محتوى أو استهدافاً حول اسم مخمرية محدد يبحث عنه المستخدمون، وقِس ثباته عبر مسحات متعددة قبل التوسع، ولا تعتمد على مسح واحد.\nتجنّب وصف أي اتجاه بأنه «جديد» دون فحص تاريخي؛ وتحقق من مسحات 19 نوفمبر قبل إطلاق أي ادعاء زمني.\nاعتبر التذبذب حول الخانة العاشرة إشارة ضعيفة، واختبر أولاً بصيغ صغيرة بدل بناء حملة كاملة عليها.\nاختبر صياغة AEO عامة حول «مخمرية» دون ادعاءات طبية ودون مقارنة باسم أي براند.\nتابع استمرارية «زبدة الشيا الاصلية» المسجلة في مسح 13:30 كمؤشر منفصل، واختبر محتوى حولها مستقلاً عن تقلّب اسمي المخمرية.','\n',char(10)),1795174790149,'','','','');
INSERT INTO competitor_ad_analyses VALUES(100,90,'هيبتا','غير مسجلة في التسجيل — الملاحظة المسجلة عن تعارض التوفر على الموقع الرسمي وقوائم صيدليات طرف ثالث، وليست وصفاً لزاوية إعلان','غير مسجل — لا يوجد نص هوك أو محتوى إعلاني موصوف في التسجيل','غير مسجل كفورمات إعلان — التسجيل يصف صفحة منتج على ehepta.com وقوائم صيدليات طرف ثالث فقط','Carbamide Twenty 50GM بـ140 EGP؛ السعر نفسه مسجل على الموقع الرسمي وعند صيدلية د. أحمد العزبي (متوفر لديها)، ولا يوجد خصم أو عرض إضافي مسجل. وسُجل أيضاً لوشن Panthenol Plus Carbamide لدى Beseha بـ160–264 EGP.','غير مسجلة — لا تاريخ بدء إعلان أو مدة تشغيل مذكورة؛ تاريخ الرصد فقط 2026-11-20 ~14:30 EET (جولة سوق 90)، والتعارض نفسه سبق تسجيله في الجولة 84 بلا حسم','لا يمكن الاستنتاج بأن الإعلان يعمل أو ناجح من التسجيل — لا توجد أرقام أداء أو مبيعات مسجلة؛ المسجل فقط أن المنتج متوفر عند طرف ثالث بنفس سعر الموقع الرسمي، ما قد يُبقي خيار الشراء متاحاً رغم وسم «Sold out» — وهذا استنتاج وليس دليل أداء مسجلاً.','الأوضح المسجل: تعارض التوفر على الموقع الرسمي — وسم «Sale Sold out» مقابل OG metadata InStock — مستمر من الجولة 84 إلى 2026-11-20 بلا حسم، فيُربك قرار الشراء؛ ويضاف إليه أن اللوشن مسجل كجزء من باندل Carbamide Family وغير معروض منفرداً على ehepta.com بينما يُعرض منفرداً لدى Beseha.',replace('تتبنى زيرا: توحيد حالة التوفر بين وسم الصفحة والبيانات الوصفية ونظام المخزون قبل أي نشر، واختبار ظهورها في زحف طازج.\nتتجنب زيرا: ترك وسم «Sold out» متناقضاً مع بيانات التوفر؛ عند نفاد فعلي تعرض بديلاً واضحاً أو موعد توفر بدلاً من إشارة متضاربة.\nتختبر زيرا: توحيد السعر المعلن عبر قنواتها وصفحاتها، ومراجعة دورية لأي فرق في السعر أو التوفر لدى الموزعين.\nتختبر زيرا: عرض مكونات الباندل منفردة عند وجود طلب مسجل عليها، بدل اقتصارها على الباندل فقط، وقياس أثر ذلك على التحويل.\nتتبنى زيرا: قاعدة تحقق دورية من صفحات المنتج (وسم، بيانات وصفية، سعر، توفر) وسجلّ للتعارضات غير المحسومة حتى إغلاقها.','\n',char(10)),1795178418564,'','','','');
INSERT INTO competitor_ad_analyses VALUES(101,91,'هيبتا','باندلات Black Friday جاهزة بقيمة/خصم: روتينات كاملة للجسم والبشرة والشعر بأسعار مخفّضة مقابل السعر الأصلي، ضمن مجموعة باندلات موسّعة على الموقع.','غير مسجل في التسجيل — لا يوجد نص هوك أو إعلان موصوف؛ المسجل فقط أسماء الحزم وأسعار قبل/بعد.','صفحة مجموعة باندلات على الموقع (ehepta.com/collections/bundles) — فحص حي بالمتصفح؛ ليس فيديو مسجلاً ولا كرييتف إعلاني موصوف في التسجيل.','مجموعة /collections/bundles فيها 37 منتجاً. الحزم الثماني المؤكدة بنفس الأسعار ومتوفرة: Carbamide Family 546 بدل 700، Strawberry Skin 447 بدل 580، Beta Friday 495 بدل 660، Heels Friday 360 بدل 480، Honeymoon 436 بدل 545، Carbamide Lotion Offer 2 575 بدل 780، Face and Body 608 بدل 810، Hair Heroes 1,105 بدل 1,535. التعداد الكامل أضاف 29 حزمة كخط أساس موسّع، منها: Winter Bundle 510 بدل 680، Kids Bundle 444 بدل 600، Shower Party 520 بدل 710، Carbamide Lotion Offer 1 296 بدل 390، Mami Milk 375 بدل 450، Panthenol Light Lotion Bundle 359 بدل 460، Hepta Carnival 2,699 بدل 3,770 + 12 متغير Carnival + Hydra من 1,074 لـ3,670. لا تغيير سعري مسجل ولا منتج جديد مسجل.','غير مسجلة — لا يوجد تاريخ بدء أو مدة تشغيل في التسجيل؛ المسجل فقط تاريخ الرصد 2026-11-20 ~14:30–14:32 EET (جولة سوق 90)، وأن الحزم الثماني من الجولة 84 ما زالت بنفس الأسعار ومتوفرة.','مستنتج وليس أداءً مسجلاً: على الأرجح يعمل بسبب اتساع المجموعة (37 منتجاً) وتغطيتها استخدامات متعددة، ووضوح سعر قبل/بعد لكل حزمة، وتوفر الحزم الثماني واستقرار أسعارها، مع سياق موسم Black Friday.','الأوضح المسجل: رابط Black Friday المخصص /collections/black-friday-bundles يرجع 404، بينما الرابط الفعلي من قائمة الموقع هو /collections/bundles؛ فأي زيارة تستخدم الرابط المخصص تفشل. إضافة إلى ذلك، لا يوجد تغيير سعري أو منتج جديد مسجل، فالعرض استمرار/خط أساس موسّع وليس إطلاقاً جديداً مؤكداً.',replace('تبنَّ: اختبر باندل روتين جاهز واحد واضح بسعر قبل/بعد معلن، مع هدف اختبار قابل للقياس مثل الإضافة إلى السلة، بدون أي ادعاء علاجي.\nتجنّب: قبل أي حملة موسمية، افحص كل الروابط المعلنة حياً؛ رابط واحد يرجع 404 يضيّع زيارات الحملة.\nاختبر: قسّم الباندلات حسب الاستخدام (جسم، كعب، شعر، عائلة، أطفال) بدل قائمة واحدة عامة، وقارن أي تقسيم يرفع التحويل.\nتجنّب: لا تعرض تعداداً موسعاً كإطلاق جديد إلا بعد تأكيد أنه جديد فعلاً؛ وضّح ما هو مستمر وما هو جديد.\nاختبر: اختبر نقطة سعر واحدة لباندل روتين مقابل سعر الروتين المنفرد 799، مع إبراز التوفير بوضوح، واختبر سعراً واحداً في كل مرة.','\n',char(10)),1795178494589,'','','','');
INSERT INTO competitor_ad_analyses VALUES(102,92,'غير محدد من التسجيل','زبدة الشيا للبشرة تحديدًا — إشارة لغة بحث عن استخدام منتج زيرا الحالي (زبدة الشيا) للبشرة، وليست منتجًا جديدًا','غير مسجل — لا يوجد نص إعلان أو هوك مسجل، فقط اقتراح البحث «زبدة الشيا للبشرة»','SEARCH — مسح Google Egypt autocomplete (hl=ar, gl=eg)، 12 كلمة، 10 اقتراحات لكل كلمة','غير مسجل — لا يوجد عرض مسجل في الملاحظة','غير مسجلة — تاريخ الرصد المسجل فقط هو 2026-11-20 الساعة 14:50 EET، و«الأصلية» كانت ثابتة 4 مسحات متتالية حسب ملاحظة #34، دون تاريخ بدء أو مدة تشغيل مسجلة','لا يوجد إعلان مسجل للحكم على نجاحه؛ الإشارة المسجلة الوحيدة هي دخول «زبدة الشيا للبشرة» في المركز الثامن في «زبدة الشيا»، ما يشير إلى أن الباحثين يسألون عن زبدة الشيا للبشرة تحديدًا بلغة بحث محددة','إشارة مسح واحد فقط — تثبت أو تموت في المسحات القادمة قبل أي خطوة محتوى؛ وخروج «الأصلية» بعد 4 مسحات ثبات قد يكون مؤقتًا، ولا توجد أرقام أداء مسجلة',replace('راقب المسحات القادمة لتأكيد ثبات «زبدة الشيا للبشرة» قبل أي خطوة محتوى؛ لا تبنِ محتوى على إشارة مسح واحد.\nاختبر لغة «للبشرة» في عناوين وأسئلة AEO لمنتج زبدة الشيا الحالي بصياغة وصفية فقط، دون ادعاءات طبية ودون تقديمها كمنتج جديد.\nلا تتخلَّ عن زاوية «الأصلية» بناءً على خروجها في مسح واحد؛ كانت ثابتة 4 مسحات متتالية حسب ملاحظة #34، فاحتفظ بها تحت المراقبة.\nاختبر صياغة سؤال وإجابة مباشرة حول استخدام زبدة الشيا للبشرة، وقارن ظهورها في الاقتراحات اللاحقة قبل التوسع.\nتجنب المقارنة باسم براند والادعاءات الطبية؛ ركّز على الاستخدام ولغة البحث المسجلة فقط.','\n',char(10)),1795179676721,'','','','');
INSERT INTO competitor_ad_analyses VALUES(103,93,'غير محدد من التسجيل','غير مسجلة كزاوية إعلان؛ المسجل فقط اتجاه بحث: «سيلوليت جورجينا» — فضول مرتبط باسم مشهور (على الأرجح جورجينا رودريغيز) وليس منتجًا — و«سيلوليت رول امازون» — بحث عن أداة رولر للسيلوليت على أمازون.','غير مسجل نص هوك إعلاني؛ المسجل فقط اقتراحا البحث الجديدان: «سيلوليت جورجينا» في المركز 8 و«سيلوليت رول امازون» في المركز 10.','SEARCH — مسح Google Egypt autocomplete بتاريخ 2026-11-20 الساعة 15:09 EET (client=firefox, hl=ar, gl=eg)، وليس إعلان فيديو مسجلًا','غير مسجل — لا يوجد عرض منتج أو سعر أو خصم في التسجيل؛ «رول امازون» بحث عن أداة على أمازون وليس عرضًا مسجلًا','غير مسجلة — لا تاريخ بدء ولا مدة تشغيل مسجلة؛ المسجل فقط مقارنة مسح 15:09 EET بلقطة 14:50 EET في 2026-11-20، وهي إشارة مسح واحد تحتاج تأكيدًا في المسحات القادمة','لا يوجد دليل أداء مسجل يثبت نجاح إعلان؛ المسجل فقط أن اقتراحين جديدين دخلا قائمة «سيلوليت» بينما خرج «سيلوليت الافخاذ» و«سيلوليت الجسم»، وباقي الكلمات الـ11 بلا تغيير — ما يشير، كاستنتاج فقط، إلى اهتمام بحثي لحظي بالفضول حول المشاهير وبأداة الرولر، وليس إلى أداء إعلان','إشارة مسح واحد غير مؤكدة وقد تموت في المسح التالي؛ «جورجينا» اسم مشهور وليست منتجًا فلا تتحول مباشرة إلى عرض، و«رول امازون» بحث عن أداة على منصة خارجية، والتقلبات السابقة الموثقة (مثل «زبدة الشيا الاصلية» و«مخمرية») تظهر أن مثل هذه التغيرات قد تكون عابرة',replace('اختبر قبل أي إنفاق: راقب «سيلوليت جورجينا» و«سيلوليت رول امازون» في المسحات القادمة، ولا تعتبرهما اتجاهًا ثابتًا إلا إذا استمرا أو تقدما في الترتيب.\nتجنب استخدام اسم «جورجينا» أو أي اسم مشهور في إعلانات زيرا، واختبر بدلًا من ذلك محتوى فضول عام حول السيلوليت دون ادعاءات طبية أو مقارنات باسم براند.\nاختبر زاوية أداة الرولر كجزء من روتين عناية توضيحي فقط، دون ادعاء علاج السيلوليت، ووضّح طريقة الاستخدام والمنتج المكمل إن وجد.\nلا تنسخ مسار «رول امازون» كتوجيه للشراء من أمازون؛ اختبر صفحة/محتوى خاصًا بزيرا يشرح الرولر ويقيس الاهتمام بدلًا من تحويل البحث لمنصة خارجية.\nلا تفترض تراجع الاهتمام ب«سيلوليت الافخاذ» و«سيلوليت الجسم» من خروجهما في مسح واحد؛ عاملهما كتقلب مؤقت حتى تأكيد المسحات القادمة.','\n',char(10)),1795180849834,'','','','');
INSERT INTO competitor_ad_analyses VALUES(104,93,'غير محدد من التسجيل','لا توجد زاوية إعلان مسجلة؛ الزاوية الظاهرة من البحث فقط هي تحوّل نية البحث عن «سيلوليت» من موضع الجسم («سيلوليت الافخاذ» و«سيلوليت الجسم» خرجتا) إلى فضول مرتبط باسم مشهور («سيلوليت جورجينا»، على الأرجح جورجينا رودريغيز حسب التسجيل) وبحث عن أداة («سيلوليت رول امازون»).','لا يوجد هوك إعلان مسجل؛ الهوك الظاهر من الاقتراحات نفسها هو «سيلوليت جورجينا» (فضول/ترند اسم مشهور) و«سيلوليت رول امازون» (بحث عن أداة رولر للسيلوليت على أمازون).','SEARCH — مسح Google Egypt autocomplete (client=firefox, hl=ar, gl=eg)؛ ليس إعلان فيديو أو صورة مسجلاً','غير مسجل — لا يوجد عرض أو منتج أو سعر مذكور في الملاحظة','غير مسجلة — لا تاريخ بدء إعلان ولا مدة تشغيل مذكورة؛ المسجل فقط تاريخ رصد 2026-11-20 ومسح 15:09 EET مقابل لقطة 14:50 EET، وإشارة مسح واحد تحتاج تأكيدًا في المسحات التالية','مستنتج (وليس أداءً مسجلاً): دخول اقتراحين جديدين كليًا إلى المركزين 8 و10 في مسح واحد، مع بقاء باقي الكلمات الـ11 بلا تغيير، يشير إلى صعود مفاجئ في فضول البحث — اسم مشهور يولّد نقرات فضول، و«رول امازون» يدل على نية عملية للبحث عن أداة، وليس مجرد معلومة عامة.','الأوضح: إشارة مسح واحد غير مؤكدة — قد تثبت أو تموت في المسحات الجاية؛ ولا يوجد إعلان أو منتج أو عرض أو أداء مسجل يثبت نجاحًا، و«جورجينا» ليست منتجًا حسب التسجيل، و«رول امازون» يوجّه الطلب نحو أمازون وليس نحو براند محدد.',replace('اختبر فقط بعد تأكيد: راقب المسحات الجاية لـ«سيلوليت جورجينا» و«سيلوليت رول امازون» قبل أي خطوة أو إنفاق، ولا تتصرف على إشارة مسح واحد.\nاختبر محتوى تعليميًا عامًا يجيب عن فضول السيلوليت وأدوات الرولر من دون ادعاءات طبية ومن دون استخدام اسم مشهور أو اسم براند منافس.\nاختبر زاوية الأداة المكمّلة: محتوى/بحث حول الرولر كأداة ضمن روتين العناية، من دون وعد بنتيجة طبية ومن دون توجيه للشراء من أمازون.\nتجنب النسخ الأعمى: لا تبنِ منتجًا أو حملة على اسم «جورجينا»، ولا تفترض أن خروج «الافخاذ/الجسم» يعني اختفاء الطلب، فهو تغيير اقتراحات فقط.\nتتبّع استمرارية التقلبات المعروفة (عودة «زبدة الشيا الاصلية»، وتبديل ترتيب «مخمرية»، وبقاء «لمسة حرير») كمؤشر سياق قبل تفسير أي تغيير جديد.','\n',char(10)),1795180886569,'','','','');
INSERT INTO competitor_ad_analyses VALUES(105,94,'غير محدد من التسجيل','غير مسجلة كزاوية إعلان؛ المسجل فقط اهتمام بحثي بعبارتي «سيلوليت جورجينا» و«سيلوليت رول امازون»، و«سيلوليت جورجينا» ترند اسم مشهور وليست منتجاً حسب التسجيل','غير مسجل في التسجيل — لا يوجد هوك إعلان مذكور؛ العبارتان المسجلتان هما اقتراحا بحث «سيلوليت جورجينا» و«سيلوليت رول امازون» وليستا نص هوك','SEARCH — مسح Google Egypt autocomplete بتاريخ 2026-11-20 (client=firefox, hl=ar, gl=eg)؛ ليس إعلان فيديو مسجلاً','غير مسجل — لا يوجد عرض إعلاني مذكور في التسجيل؛ المسجل فقط أن فرصة #8 (رولر السيلوليت) تفضل «قيد الدراسة»','مدة تشغيل الإعلان غير مسجلة؛ المسجل هو رصد بحثي فقط: دخول العبارتين أعلى 10 في 15:09 EET في 2026-11-20 («سيلوليت جورجينا» مركز 8، «سيلوليت رول امازون» مركز 10) وخروجهما في مسح 15:30 EET — عمر مسح واحد في سلسلة فايرفوكس — مع استمرار وجودهما في المركزين 10–11 في سلسلة كروم في مسحات 19 نوفمبر 18:49 و22:50Z و20 نوفمبر 10:49 و14:09','لا يوجد دليل مسجل على أن هذا إعلان ناجح؛ المسجل هو إشارة طلب بحثي فقط: الرولر ما زال ظاهراً تحت حد أعلى 10 في كروم (10–11) رغم خروجه من أعلى 10 في فايرفوكس، والمجموعة الثابتة «سيلوليت الافخاذ» و«سيلوليت الجسم» عادت في 15:30 — أي أن الطلب الأساسي على السيلوليت مستمر، بينما اختراق 15:09 كان استثناءً قصيراً','الأوضح: تقلّب شديد وقصر العمر — خروج بعد مسح واحد من أعلى 10 في فايرفوكس، و«سيلوليت جورجينا» ترند اسم مشهور مش منتج وموته بعد مسح واحد متوقَّع، والإشارة ضعفت في فايرفوكس فلا يمكن الاعتماد على ذروة 15:09 كطلب مستقر',replace('لا تبنِ حملة زيرا على ترند «سيلوليت جورجينا» — اسم مشهور قصير العمر وموته بعد مسح واحد متوقَّع حسب ملاحظة #86؛ عامِله كإشارة مراقبة فقط لا كزاوية أساسية.\nأبقِ فرصة #8 (رولر السيلوليت) «قيد الدراسة» ولا تطلقها كطلب مؤكد — الإشارة ضعفت في فايرفوكس لكن الطلب ما زال ظاهراً تحت الحد في كروم (المركزان 10–11).\nلا تعتبر اختراق مسح واحد (15:09) طلباً مستقراً — مسح 15:30 أعاد المجموعة الثابتة «سيلوليت الافخاذ» و«سيلوليت الجسم»، فمسح 15:09 كان الاستثناء.\nراقب سلسلتي فايرفوكس (أعلى 10) وكروم (15 نتيجة) معاً قبل الحكم بموت عبارة — العبارة قد تكون معلّقة تحت الحد وتخترقه أحياناً.\nاختبر لزيرا صياغة حول عبارات المجموعة الثابتة المسجلة بدل ذروة الترند، دون ادعاءات طبية ودون مقارنة باسم براند، وقِس الاستمرارية عبر مسحات متتالية قبل التوسع.','\n',char(10)),1795182046197,'','','','');
INSERT INTO competitor_ad_analyses VALUES(106,95,'غير محدد من التسجيل','غير مسجلة في التسجيل — الملاحظة مسح بحث فقط عن عودة «يوريا ٣٠٪» كإشارة طلب (فرصة #1 الأصلية بصيغة «يوريا 30%»)، وليست وصفاً لزاوية إعلان','غير مسجل في التسجيل — لا يوجد نص إعلان أو هوك مذكور','مسح لغة بحث جوجل مصر 16:09 EET — اقتراحات الإكمال التلقائي (hl=ar, gl=eg)؛ وسم الأدلة: SEARCH — وليس فورمات إعلان مسجل','غير مسجل في التسجيل — لا يوجد عرض مذكور','غير مسجلة — تاريخ الرصد الوحيد المسجل هو 2026-11-20 الساعة 16:09 EET، ولا يوجد تاريخ بدء إعلان أو مدة تشغيل مذكورة','غير مثبت من التسجيل — لا يوجد إعلان أو أرقام أداء مسجلة لتقييم نجاحه؛ المستنتج فقط أن عودة «يوريا ٣٠٪» بعد خروج «يوريا الدم» قد تعكس عودة اهتمام بحثي بإشارة الفرصة #1، لكن التسجيل نفسه يشترط ثبوتها في المسحات الجاية قبل أي خطوة','ضعف الثبوت والاستقرار: الإشارة عودة بصيغة أرقام عربية مختلفة عن الصيغة اللاتينية الأصلية، والتغيير الوحيد ضمن 12 كلمة، مع اضطراب إكمال تلقائي موازٍ («يوريان تيمبر» بدل «يورياج تيمبر») — فلا يمكن الاعتماد عليها كطلب مؤكد من مسح واحد',replace('اختبر ثبوت «يوريا ٣٠٪» في المسحات الجاية قبل أي خطوة لزيرا — لا تبنِ قرار محتوى أو استهداف على مسح واحد.\nاختبر تغطية صيغتي الأرقام العربية («٣٠٪») واللاتينية («30%») في محتوى البحث/AEO لزيرا دون ادعاءات طبية.\nتجنب تصنيف تهجئة بديلة في الإكمال التلقائي كمنتج أو منافس جديد قبل التحقق من أنها نفس الاسم.\nتجنب استهداف أو محتوى الإشارات الطبية غير ذات الصلة مثل «يوريا الدم» التي خرجت من المسح.\nراقب استقرار باقي الكلمات الـ11 بلا تغيير كمؤشر ضبط — أي تغيير لاحق فيها يستحق فحصاً منفصلاً قبل الاستنتاج.','\n',char(10)),1795184409226,'','','','');
INSERT INTO competitor_ad_analyses VALUES(107,95,'غير محدد من التسجيل','غير مسجلة — لا يوجد إعلان موصوف في التسجيل؛ المسجل فقط عودة إشارة بحث «يوريا ٣٠٪» (أرقام عربية) كفرصة #1 سابقة','غير مسجل — لا يوجد هوك إعلاني مذكور في التسجيل','غير مسجل كفورمات إعلان — المصدر المسجل مسح لغة بحث جوجل مصر (اقتراحات الإكمال التلقائي hl=ar, gl=eg)، وليس إعلانًا','غير مسجل — لا يوجد عرض مذكور في التسجيل','غير مسجلة — تاريخ الرصد المسجل فقط هو 2026-11-20 في مسح 16:09 EET، ولا يوجد تاريخ بدء إعلان أو مدة تشغيل مذكورة','لا يوجد إعلان مسجل للحكم على نجاحه؛ المسجل فقط أن «يوريا ٣٠٪» دخلت مكان «يوريا الدم» غير ذات الصلة في مسح 16:09، وباقي الكلمات الـ11 بلا تغيير، وأنها عودة لإشارة فرصة #1 وتحتاج ثبوتًا','عدم الثبوت: الإشارة عودة بصيغة أرقام عربية لإشارة سابقة وليست فرصة جديدة، وتحتاج ثبوتًا في المسحات الجاية قبل أي خطوة، واضطراب الإكمال التلقائي في تهجئة العلامة يضعف الاعتماد على مسح واحد',replace('اختبر ثبوت «يوريا ٣٠٪» بصيغتي الأرقام العربية (٣٠٪) واللاتينية (30%) في المسحات الجاية قبل أي خطوة، ولا تعاملها كفرصة جديدة.\nتجنب الخلط مع «يوريا الدم» الطبية غير ذات الصلة، ولا تستخدم ادعاءات طبية في محتوى زيرا.\nتعامل مع «يوريان تيمبر» كتهجئة بديلة محتملة لنفس العلامة، ولا تبنِ عليها منتجًا جديدًا ولا تقارن باسم براند.\nلا تبنِ إعلانًا على اقتراح إكمال تلقائي واحد؛ انتظر ثبوت الإشارة في مسحات لاحقة قبل الاستثمار في زاوية أو محتوى.\nراقب تغير صيغ الأرقام العربية مقابل اللاتينية في لغة البحث المصرية عند صياغة عناوين AEO، دون نسخ أعمى.','\n',char(10)),1795184472337,'','','','');
INSERT INTO competitor_ad_analyses VALUES(108,96,'غير محدد من التسجيل','غير مسجلة كزاوية إعلان؛ المسجل فقط صياغة بحث «يوريا ٣٠٪» مقابل الثابت المسجل «يوريا الدم»، دون وصف زاوية إبداعية.','غير مسجل؛ لا نص هوك أو منطوق مذكور في التسجيل.','غير مسجل كفورمات إعلان؛ المصدر المسجل مسح لغة بحث جوجل مصر (فايرفوكس، hl=ar، gl=eg) في 16:29 EET مقارنة بمسح 16:09 EET + أرشيف 85 مسحة.','غير مسجل؛ لا عرض مذكور في التسجيل، والخلاصة المسجلة: لا فرصة منتج جديدة.','مدة تشغيل الإعلان غير مسجلة؛ المسجل فقط تاريخ الرصد 2026-11-20 وأن عبارة «يوريا ٣٠٪» دخلت أعلى 10 في مسح 16:09 EET وخرجت في مسح 16:29 EET بعد مسح واحد فقط، وظهرت في 5 مسحات من 85 مقابل «يوريا الدم» في 78 من 85.','لا يوجد دليل مسجل على أنه شغال/ناجح؛ المسجل عكسه: موت بعد ظهور واحد وتذبذب مثل «كريم urea للجسم»، ولا الصيغة العربية ولا اللاتينية مثبتة.','التذبذب وعدم الثبوت: خرجت «يوريا ٣٠٪» من أعلى 10 بعد مسح واحد فقط (16:09→16:29)، وظهرت في 5 مسحات فقط من 85، بينما «يوريا الدم» ثابت في 78 من 85 — فالاعتماد عليها اعتماد على صياغة غير مستقرة.',replace('أبقِ استبعاد «يوريا ٣٠٪» من كرييتف التيست لحين الثبوت كما في التفكير #70 — لا تبنِ اختباراً على ظهور واحد.\nلا تعتبر تذبذب «يوريا ٣٠٪» طلب منتج جديد؛ الخلاصة المسجلة: لا فرصة منتج جديدة، بل تذبذب صياغة فقط.\nاختبر الصياغة الثابتة المسجلة «يوريا الدم» كمرجع لغوي للمقارنة فقط، دون ادعاءات طبية أو وعود علاجية، مع الفصل بين مصطلح البحث ومصطلح المنتج.\nاشترط الثبوت عبر مسحات متكررة قبل اعتماد أي صيغة تركيز، بدلاً من نسخ صياغة ظهرت مرة واحدة.\nتجنب المقارنات باسم براند والادعاءات الطبية (AEO)، واختبر الصياغة العربية مقابل اللاتينية بمعايير محايدة عند توفر دليل ثبوت.','\n',char(10)),1795185669865,'','','','');
INSERT INTO competitor_ad_analyses VALUES(109,97,'غير محدد من التسجيل','غير مسجل — التسجيل مسح بحث (SEARCH) وليس وصف إعلان، فلا زاوية إعلانية مذكورة','غير مسجل — لا يوجد نص هوك أو محتوى إعلان في التسجيل','غير مسجل — المصدر مسح لغة بحث جوجل مصر (SEARCH)، وليس فورمات إعلان','غير مسجل — لا يوجد عرض مذكور في التسجيل','غير مسجلة — لا يوجد تاريخ بدء إعلان أو مدة تشغيل مذكورة؛ التواريخ المسجلة فقط هي تاريخ الرصد 2026-11-20 ومسحا 16:56 و17:30 EET (فايرفوكس) و14:09 و17:10 EET (كروم)','غير قابل للتحديد من التسجيل — لا يوجد إعلان مسجل ولا أرقام أداء؛ المسجل فقط هو ثبات أعلى 10 في مسح فايرفوكس 17:30 مقابل 16:56 في الكلمات الـ12، وصفر اقتراحات جديدة وصفر فرص منتج جديدة','غير مسجل كضعف إعلان — لا يوجد إعلان موصوف لتحديد ضعفه؛ أضعف نقطة موثقة في التسجيل نفسه هي خطر المقارنة عبر العملاء، إذ أظهر مسح كروم الأول فرقاً كاذباً من 12 دخولاً وتم تجاهله',replace('اعتمد سلسلة مسح واحدة (فايرفوكس في هذا التسجيل) للمقارنة، وتجنب مقارنة كروم بفايرفوكس لأنها أنتجت فرقاً كاذباً من 12 دخولاً — اختبر أي تغيير عبر نفس العميل قبل اتخاذ قرار.\nلا تبنِ محتوى أو منتجاً على «يوريا ٣٠٪» كصيغة عربية مثبتة؛ التسجيل يقوّي أنها متذبذبة وخرجت من أعلى 10 «يوريا» في مقارنة كروم-بكروم، بينما «كريم يوريا ٣٠ للجسم» ثابت في أعلى 10 «كريم يوريا للجسم».\nأبقِ «سيلوليت رول امازون» (فرصة #8) قيد الدراسة فقط؛ فهي في المركز 11 في سلسلة كروم، تحت حد أعلى 10، ولا قرار إنتاج أو محتوى من غير موافقة المالك.\nلا تعتبر تذبذب خانة «زبدة الشيا» بين «للبشرة» و«الاصلية» إشارة جديدة؛ هو نفس التذبذب الموثق في #92/#93.\nوثّق التاريخ والعميل ولغة البحث (hl=ar, gl=eg) عند كل مسح؛ فصفر تغييرات في أعلى 10 فايرفوكس بين 16:56 و17:30 لا يعني فرصة جديدة.','\n',char(10)),1795188034732,'','','','');
INSERT INTO competitor_ad_analyses VALUES(110,98,'أليجون (Alejon)','غير مسجلة في التسجيل — لا يصف التسجيل زاوية إعلانية؛ المسجل فقط منتج كريم اليوريا 200مل بسعر ثابت 380 EGP ومتوفر.','غير مسجل — لا يوجد نص هوك أو رسالة إعلانية مذكورة في التسجيل.','غير مسجل كفورمات إعلان — المسجل صفحات منتج/مجموعة على موقعي صيدليات الفؤاد وMai Pharmacy، وليس إعلان فيديو أو صورة موصوفاً.','غير مؤكد حياً — لا يوجد عرض مؤكد في الفحص الحي؛ عرض White Friday B2G2 الوارد من خط الأساس ما زال بلا تأكيد حي (ميتا 403، لا متجر رسمي، لا نتيجة بحث عام).','غير مسجلة كمدة تشغيل إعلان؛ المسجل فقط تواريخ رصد: خط الأساس 2026-11-18، والجولة 85 في 2026-11-20 06:20 EET، والجولة 91 في 2026-11-20 ~18:30 EET، مع ثبات السعر 380 EGP بينها — وهذه استمرارية رصد سعر/توفر وليست مدة تشغيل إعلان.','لا يوجد دليل أداء مسجل، فلا يمكن تأكيد أن إعلاناً يعمل؛ المسجل فقط يدل على استمرارية العرض التجاري: سعر ثابت 380 EGP وتوفر (InStock) في الفحص الحي، ومطابقة للجولة 85 وخط الأساس 2026-11-18، ما يقلل — كاستنتاج محدود — احتكاك الشراء المرتبط بتغير السعر أو نفاد المخزون، دون أي رقم أداء مسجل.','الأوضح: غموض التركيز المسجل — صفحة الفؤاد تصف العبوة بأنها يوريا 20% (+ لاكتيك + جلسرين + ألانتوين) مقابل تسمية 10% في قوائم جوميا (زحف قديم 208–233 يوم، غير طازج)؛ ويضاف إليه غياب قناة رسمية/متجر رسمي ظاهر في البحث وعدم تأكيد عرض White Friday B2G2 حياً، وعدم ظهور كريم الجسم 200مل ضمن 24 منتجاً في مجموعة Mai Pharmacy (غير مؤكد كحذف)، ولا منتج جديد مسجل.',replace('اختبر توحيد نسبة التركيز والمكونات حرفياً بين العبوة وصفحة المنتج والمتاجر قبل أي نشر، لتجنب الغموض المسجل في القوائم.\nتبنَّ تثبيت السعر والتوفر والتحقق منهما بفحص حي موثق قبل الترويج، لأن التغير غير المعلن يضعف الثقة.\nتجنب الإعلان عن عرض موسمي قبل تأكيده حياً على قناة رسمية قابلة للفتح والتحقق.\nاختبر وجود قناة رسمية واحدة واضحة للمنتج، بحيث لا يعتمد العميل على قوائم طرف ثالث فقط.\nتجنب الادعاءات الطبية وروتين علاجي غير موثق؛ وركز الاختبار على وضوح الاستخدام والمكونات والسعر والتوفر فقط.','\n',char(10)),1795192868183,'','','','');
INSERT INTO competitor_ad_analyses VALUES(111,99,'غير محدد من التسجيل','غير مسجلة؛ التسجيل مسح اقتراحات بحث وليس إعلاناً، ولا يذكر زاوية إعلانية.','غير مسجل؛ لا يوجد هوك إعلاني أو نص منطوق مذكور في التسجيل.','مسح اقتراحات بحث جوجل مصر (SEARCH_SCAN) عبر suggestqueries.google.com (hl=ar، gl=eg) بتاريخ 2026-11-20 18:49 EET لـ12 كلمة متتبعة — وليس إعلاناً مسجلاً بصيغة فيديو أو صورة','غير مسجل؛ لا يوجد عرض سعر أو منتج أو خصم مذكور في التسجيل، والملاحظة تنص على أنه لا فرصة منتج جديدة.','غير مسجلة؛ التواريخ المسجلة هي 2026-11-20 18:49 EET للمسح الحالي و18:32 EET للمسح السابق فقط، ولا يوجد تاريخ بدء إعلان أو مدة تشغيل مذكورة.','غير مثبت من التسجيل؛ لا توجد أرقام أداء أو نجاح إعلان مسجلة، والمسجل فقط ظهور 10 اقتراحات جديدة في مسح واحد (معظمها #10، و#5 و#8) — إشارات تثبت أو تموت في المسحات الجاية، ولا فرصة منتج جديدة مسجلة.','الأوضح أن الإشارات ضعيفة وغير مثبتة: مسح واحد فقط، ومعظم الاقتراحات الجديدة في المركز #10، والمسح السابق كان مخزناً بإزاحة فالمقارنة غير موثوقة بالكامل، وبعضها صياغات بديلة أو ترند باسم شخصية، والملاحظة نفسها تقول لا فرصة منتج جديدة ولا منتج أو مشكلة لا تحملها زيرا.',replace('اختبر صياغات البحث المسجلة كأسئلة/عناوين AEO فقط بعد تثبيتها في مسحات لاحقة: «جلد الوزة كريم» و«كريم ازالة سيلوليت» و«علاج السيلوليت عند النساء»، دون ادعاء نتيجة طبية.\nاختبر محتوى تعليمي يوضح الفرق بين تركيزات اليوريا المسجلة (10% و30% و25% في روتين KP) واستخدام كل تركيز في الروتين، دون ادعاء علاجي.\nتجنب بناء محتوى أو استهداف حول ترند الاسم الشخصي المسجل في «سيلوليت جورجينا»؛ راقبه فقط كمؤشر ترند وليس فرصة منتج.\nاختبر الصياغات البديلة المسجلة «زبدة الشيا الاصلية» و«ملح صخرى سيوة» كصياغات بحث عامة، وتجنب صياغة البحث التي تحمل اسم علامة أخرى.\nلا تعتمد على هذا المسح وحده: أعد التحقق في المسحات القادمة قبل أي اعتماد، خاصة أن المسح السابق 18:32 كان مخزناً بإزاحة، وأن معظم الجديد في المركز #10، وأن «مخمرية رجالي للجسم» لاحقة لصياغة موجودة وليست شريحة جديدة.','\n',char(10)),1795194126978,'','','','');
INSERT INTO competitor_ad_analyses VALUES(112,100,'غير محدد من التسجيل','علاج السيلوليت بالأعشاب — زاوية العلاج بالأعشاب / الطبيعي','غير مسجل كهوك إعلاني؛ المسجل فقط عبارة اقتراح البحث «علاج السيلوليت بالاعشاب»','غير مسجل كفورمات إعلان؛ المصدر المسجل مسح لغة بحث جوجل مصر (اقتراحات بحث)، وسم الأدلة SEARCH_LANGUAGE','غير مسجل؛ لا منتج محدد ولا عرض مذكور — طريقة علاج (أعشاب/طبيعي) وليست منتجاً محدداً','غير مسجلة؛ المسجل فقط تاريخ رصد 2026-11-20 ومسح 19:49 EET مقابل مسح 19:31 EET، وإشارة مسح واحد تثبت أو تموت في المسحات الجاية قبل أي خطوة','لا يوجد أداء مسجل يثبت نجاحه؛ المستنتج فقط: دخوله كاقتراح جديد رقم 10 في «علاج السيلوليت» يشير إلى اهتمام بحثي بزاوية طبيعية/أعشاب، لكنه إشارة واحدة غير مثبتة.','إشارة مسح واحد فقط غير مثبتة، بلا منتج أو عرض أو أداء مسجل؛ وزيرا لا تحمل خط أعشاب، فهي إشارة زاوية محتوى محتملة وليست فرصة منتج.',replace('انتظر المسحات الجاية لتأكيد بقاء الاقتراح ضمن أعلى 10 قبل أي خطوة؛ لا قرار من غير موافقة المالك.\nاختبرها كزاوية محتوى محتملة فقط: لماذا التركيبة العلمية بدل الأعشاب — من غير ادعاءات طبية ومن غير مقارنات باسم براند.\nلا تبنِ عليها منتج أعشاب ولا تنسخها كمنتج؛ زيرا لا تحمل خط أعشاب والمسجل طريقة علاج مش منتج محدد.\nلا تستخدم عبارة الاقتراح كهوك إعلاني مثبت؛ لم يسجل نص إعلان أو فورمات أو أداء.\nوثّق أي اختبار محتوى مقابل الاقتراح الأصلي، وتوقف عنه إذا ماتت الإشارة في المسحات التالية.','\n',char(10)),1795197646991,'','','','');
INSERT INTO competitor_ad_analyses VALUES(113,101,'غير محدد من التسجيل','تأطير ديموغرافي لغوي جديد: «علاج السيلوليت عند النساء» — إشارة لغة بحث فقط، وليس منتجاً أو مشكلة جديدة وفق التسجيل.','دخول اقتراح «علاج السيلوليت عند النساء» إلى أعلى 10 اقتراحات لبحث «علاج السيلوليت» في المرتبة 9 في مسح 20 نوفمبر 19:49 EET.','غير مسجل كفورمات إعلان؛ المسجل فقط إشارة لغة بحث (SEARCH_LANGUAGE) من مسح اقتراحات بحث جوجل مصر (hl=ar, gl=eg).','غير مسجل','غير مسجلة؛ لا يوجد تاريخ بدء أو مدة تشغيل مسجلة. التواريخ المسجلة فقط هي مسحا 19:31 و19:49 EET في 2026-11-20، وهي توقيت رصد لإشارة مسح واحد وليست مدة استمرارية.','لا يوجد دليل مسجل على نجاح إعلان أو أرقام أداء؛ المسجل فقط دخول الصياغة في المرتبة 9 ضمن أعلى 10 اقتراحات، وهو ما قد يعكس تطابق الصياغة مع لغة بحث المستخدمين — وهذا تفسير محتمل وليس أداءً مثبتاً، ويثبت أو يموت في المسحات الجاية.','إشارة مسح واحد غير مثبتة وقابلة للاختفاء، والتأطير لغة فقط وليس منتجاً أو مشكلة جديدة؛ كما خرجت صياغتا «علاج السيلوليت في الجسم» و«علاج السيلوليت في الفخذين» في نفس المسح، مما يظهر تقلب اقتراحات البحث.',replace('اختبر صياغة «عند النساء» كمتغير لغوي في محتوى زيرا (AEO/SEO) فقط بعد تأكيدها في مسحات لاحقة، دون ادعاءات طبية أو وعود علاجية.\nلا تبنِ حملة أو قرار منتج على إشارة مسح واحد؛ انتظر تثبيت الاقتراح قبل أي خطوة، ولا قرار من غير موافقة المالك.\nتجنب النسخ الأعمى للصياغة كزاوية إعلان؛ عاملها كإشارة لغة للاختبار وليس كدليل نجاح منافس.\nراقب الصياغات الخارجة من القائمة في نفس المسح قبل حذف أو تغيير صياغات قائمة، لأن التقلب في مسح واحد لا يثبت تراجعاً دائماً.\nاختبر الصياغة الديموغرافية مقابل الصياغة العامة في عناوين/أسئلة المحتوى، وقس الاستجابة اللغوية فقط دون مقارنات باسم براند.','\n',char(10)),1795197712056,'','','','');
INSERT INTO competitor_ad_analyses VALUES(114,102,'غير محدد من التسجيل','علاج جلد الوزة (KP) في منطقة البكيني — توسيع مشكلة معروفة لمنطقة جسم جديدة بصيغة علاج، وليست فرصة منتج جديدة حسب التسجيل','«علاج جلد الوزة في منطقة البكيني» — اقتراح جديد رقم 6 ضمن أعلى 10 اقتراحات «علاج جلد الوزة»','غير مسجل كإعلان أو فيديو؛ المسجل فقط اقتراح بحث في مسح لغة بحث جوجل مصر (وسم الأدلة: SEARCH_LANGUAGE)','غير مسجل','غير مسجلة — المسجل فقط تاريخ الرصد 2026-11-20 ومسحان في 19:31 و19:49 EET؛ لا يوجد تاريخ بدء أو مدة استمرارية مسجلة، وإشارة مسح واحد فقط','لا يوجد دليل أداء إعلان مسجل؛ المسجل فقط دخول الصيغة ضمن أعلى 10 اقتراحات بالمركز 6. المستنتج: التحديد بمنطقة جسم حساسة وصيغة علاج ذات نية واضحة قد يجعل الزاوية أوضح وأقرب للبحث عن حل من صيغة المشكلة العامة، لكن هذا استنتاج من لغة البحث وليس نتيجة أداء مسجلة','إشارة مسح واحد فقط تثبت أو تموت في المسحات الجاية، والجدة محدودة بصيغة العلاج لأن «جلد الوزة في البكيني» موجود أصلًا؛ ولا يوجد دليل أداء أو تمييز منتج مسجل، وروتين KP الحالي للجسم يغطيها أصلًا حسب التسجيل',replace('اختبار زاوية اللغة/المحتوى «علاج جلد الوزة في منطقة البكيني» ضمن روتين KP الحالي للجسم في زيرا، دون ادعاء منتج جديد أو ادعاءات طبية، ومقارنتها بصيغة الجسم العامة.\nعدم اتخاذ قرار قبل تأكيد الإشارة في المسحات الجاية؛ إشارة مسح واحد فقط، ولا قرار من غير موافقة المالك.\nتجنب النسخ الأعمى: الجديد المسجل هو صيغة العلاج فقط، لأن «جلد الوزة في البكيني» موجود أصلًا في اقتراحات «جلد الوزة».\nاختبار الصيغة الحرفية المسجلة في عنوان/سؤال شائع (AEO) بصياغة معلوماتية محايدة، وقياس الاهتمام قبل التوسع في المحتوى.','\n',char(10)),1795198241268,'','','','');
INSERT INTO competitor_ad_analyses VALUES(115,103,'غير محدد من التسجيل','غير مسجلة؛ لا يوجد إعلان مسجل في الملاحظة، والمسجل فقط اقتراحا بحث: «استخدامات ملح سيوة» كاستعلام معلوماتي عام، و«اباجورات ملح سيوة» كصيغة جمع مكررة من «اباجورة ملح سيوة».','غير مسجل؛ لا يوجد نص هوك أو منطوق إعلان مذكور في التسجيل.','غير مسجل كفورمات إعلان؛ المصدر المسجل هو مسح لغة بحث جوجل مصر (hl=ar, gl=eg) فقط.','غير مسجل؛ لا يوجد عرض منتج مسجل، والملاحظة المسجلة تنص على «لا فرصة منتج هنا»، وخرجت «ملح سيوة للبيع» من أعلى 10 في نفس المسح.','غير مسجلة كمدة تشغيل إعلان؛ المسجل فقط مسحان في 2026-11-20 الساعة 19:31 و19:49 EET، وإشارة مسح واحد تثبت أو تموت في المسحات الجاية.','غير قابل للتقييم من التسجيل؛ لا يوجد إعلان مسجل لقياس نجاحه، والمسجل إشارة بحث واحدة فقط، مع خروج الكلمة نفسها «ملح سيوة» و«ملح سيوة للبيع» من أعلى 10، فلا يصح استنتاج أن شيئًا يعمل.','ضعف الإشارة نفسها: إشارة مسح واحد غير مثبتة، و«اباجورات ملح سيوة» ليست إشارة جديدة فعليًا لأنها جمع مكرر من «اباجورة ملح سيوة» (رقم 5)، و«استخدامات ملح سيوة» استعلام معلوماتي عام، مع خروج الكلمة نفسها «ملح سيوة» و«ملح سيوة للبيع» من أعلى 10.',replace('تجنب اتخاذ قرار منتج أو استثمار بناءً على إشارة مسح واحد؛ انتظر المسحات الجاية لتثبيت الإشارة أو موتها، ولا قرار من غير موافقة المالك.\nاختبر محتوى معلوماتي (AEO) يجيب عن «استخدامات ملح سيوة» فقط، من غير ادعاءات طبية ومن غير عرض بيع أو مقارنة باسم براند.\nتجنب معاملة «اباجورات ملح سيوة» كطلب جديد مستقل؛ هي صيغة جمع مكررة من «اباجورة ملح سيوة» الموجودة أصلًا (رقم 5).\nلا تبنِ استهدافًا تجاريًا على هذا المسح؛ «ملح سيوة للبيع» خرجت من أعلى 10 في نفس المسح، والملاحظة المسجلة تنص على أنه لا فرصة منتج هنا.\nوثّق أي مسح لاحق بنفس معايير المسح المسجلة (hl=ar, gl=eg) قبل تغيير أي محتوى لزيرا.','\n',char(10)),1795198301322,'','','','');
INSERT INTO competitor_ad_analyses VALUES(116,104,'يورياج (Uriage) — منتج سيكا','الظهور في اقتراحات «يوريا» عبر اسم المنتج «سيكا» — ترقية إلى أعلى 10؛ لا زاوية إبداعية أو رسالة إعلانية مسجلة في الملاحظة','غير مسجل في التسجيل — لا نص إعلان أو هوك مذكور؛ الرصد اقتراح بحث فقط','SEARCH — اقتراح بحث جوجل مصر (hl=ar, gl=eg, client=firefox) لكلمة «يوريا»؛ ليس فيديو مسجلاً','غير مسجل في التسجيل — لا عرض مذكور','غير مسجلة — لا تاريخ بدء أو مدة تشغيل مذكورة؛ تاريخ الرصد المسجل فقط 2026-11-20، في مسحي 19:49 و20:09 EET، والثبات غير مثبت بعد','لا دليل أداء مسجل يثبت أنه شغال؛ المسجل فقط هو الترقية من المركز 7 في الجلب الموسّع (كروم، 15 اقتراحاً) في 19:49 إلى المركز 9 في أعلى 10 (فايرفوكس) في 20:09، ضمن حضور مسجَّل أصلاً لنفس العلامة في الكلمة نفسها (يورياج، مزيل عرق، غسول، صن بلوك) — وهذا كاستنتاج محتمل فقط يشير إلى طلب بحث قائم على اسم المنتج، لا إلى نجاح إعلان مثبت.','ضعف الإشارة نفسها: ليست ظهوراً أول مطلقاً، والمركز 9 متأخر في أعلى 10، وقائمة 19:49 كانت 9 اقتراحات فقط فالدخول لم يُزح غير «يوريا الدم» من المراكز الظاهرة، ولم يثبت بعد في المسحات القادمة، ولا يوجد محتوى إعلان أو عرض مسجل لتقييمه.',replace('تتبّع اقتراحات «يوريا» في عدة مسحات قادمة قبل اتخاذ أي خطوة؛ رصد واحد في المركز 9 لا يكفي للحكم على الثبات.\nاختبر وضوح أسماء منتجات زيرا القائمة في البحث بدل افتراض فرصة منتج جديدة؛ التسجيل ينفي وجود فرصة منتج جديدة هنا.\nقارن دائماً بين الجلب الموسّع وأعلى 10 قبل تفسير دخول أو خروج اقتراح؛ اختلاف عدد الاقتراحات قد يغيّر الصورة.\nتجنّب النسخ الأعمى لاسم منتج منافس أو أي ادعاء طبي؛ اختبر فقط صياغة اسم منتج زيرا وارتباطه بكلمة البحث ذات الصلة.','\n',char(10)),1795198819345,'','','','');
INSERT INTO competitor_ad_analyses VALUES(117,104,'يورياج (Uriage)','المسجل: ربط «يورياج سيكا» بكلمة البحث «يوريا» في اقتراحات جوجل، ضمن حضور مسجَّل أصلاً لنفس المنافس في الكلمة نفسها؛ لا زاوية إبداعية أو رسالة إعلانية مسجلة غير ذلك.','المسجل: نص الاقتراح نفسه «يورياج سيكا» في المركز 9 ضمن اقتراحات «يوريا»؛ لا نص إعلاني أو هوك إبداعي آخر مسجل.','SEARCH — اقتراح بحث في مسح لغة بحث جوجل مصر (hl=ar, gl=eg, client=firefox) لكلمة «يوريا»؛ ليس فيديو ولا إعلاناً مصوَّراً مسجلاً.','غير مسجل — لا عرض أو سعر أو خصم مذكور في الملاحظة.','غير مسجلة — المسجل فقط تاريخ الرصد 2026-11-20 ومسحا 19:49 و20:09 EET؛ لا تاريخ بدء ولا مدة تشغيل مذكورة.','المسجل فقط: دخول أعلى 10 اقتراحات «يوريا» في فايرفوكس بالمركز 9 في 20:09 EET على حساب خروج «يوريا الدم». المستنتج بحذر: ارتباط متزايد مؤقتاً بين اسم المنتج وبحث «يوريا» في تلك اللحظة، لكن بلا أرقام أداء مسجلة وبلا تأكيد استمرارية، فلا يمكن الجزم بالنجاح قبل المسحات التالية.','الأوضح: إشارة واحدة غير مؤكدة وليست ظهوراً أول مطلقاً — ترقية من المركز 7 في الجلب الموسَّع (كروم، 15 اقتراحاً) في 19:49 إلى المركز 9 في فايرفوكس في 20:09، وقائمة 19:49 كانت 9 اقتراحات فقط فلم يُزَح سوى «يوريا الدم»، ولا محتوى إعلاني أو عرض أو أرقام أداء مسجلة تدعمها؛ يثبت أو يموت في المسحات الجاية قبل أي خطوة.',replace('اختبر/راقب: لا تتحرك قبل تأكيد الثبات في المسحات التالية لفايرفوكس وكروم معاً، وافصل بين أعلى 10 والجلب الموسَّع (15 اقتراحاً) عند المقارنة.\nتجنب: لا تبنِ منتجاً أو حملة جديدة على هذه الإشارة وحدها، فالتسجيل يقول إنها ليست فرصة منتج جديدة.\nتبنَّ: راقب حضور زيرا الحالي في بحث «يوريا» ومصطلحات المكوِّن نفسها بمحتوى معلوماتي عام عن المكوِّن، دون ادعاءات طبية.\nاختبر: قارن اقتراحات «يوريا» عبر المتصفحات قبل أي استنتاج، لأن المركز المسجل يختلف بين فايرفوكس وكروم.\nتجنب: لا تنسخ نص اقتراح المنافس كهوك إعلاني لزيرا، ولا تقارن باسم براند.','\n',char(10)),1795198892589,'','','','');
INSERT INTO competitor_ad_analyses VALUES(118,105,'غير محدد من التسجيل','غير مسجلة في التسجيل — الملاحظة تصف اقتراحات إكمال تلقائي لبحث جوجل فقط، ولا تذكر زاوية إعلانية.','غير مسجل — لا يوجد نص هوك أو محتوى إعلاني مذكور في التسجيل.','اقتراحات إكمال تلقائي في بحث جوجل مصر (Google Egypt autocomplete، hl=ar، gl=eg) لكلمتي «يوريا» و«زبدة الشيا» — وليس إعلان فيديو مسجلاً','غير مسجل — لا يوجد عرض مذكور في التسجيل.','غير مسجلة — لا يوجد تاريخ بدء أو مدة تشغيل مذكورة؛ تاريخ الرصد المسجل فقط هو 2026-11-20، 20:29 EET، مع خروج «زبدة الشيا للبشرة» سابقًا في نفس اليوم وعودتها في هذا المسح، دون توقيت بدء محدد.','غير مثبت من التسجيل — لا توجد أرقام أداء أو محتوى إعلان مسجل؛ المسجل فقط هو دخول «يوريان تيمبر» أعلى 10 اقتراحات «يوريا» وعودة «زبدة الشيا للبشرة» لأعلى 10 اقتراحات «زبدة الشيا»، والتسجيل نفسه يصف ذلك بأنه متغير إملائي ودوران، وليس إشارة جديدة أو دليل نجاح.','الأوضح من التسجيل: لا يمكن الاعتماد على هذا الرصد وحده كإشارة تنافسية جديدة، لأنه — حسب التسجيل — متغير إملائي (يورياج مقابل يوريان) ودوران اقتراحات في نفس اليوم، ويحتاج إعادة فحص في المسحات التالية قبل أي استنتاج.',replace('اختبر تغطية المتغيرات الإملائية والصوتية الشائعة في محتوى البحث لزيرا، وراقبها عبر مسحات متعددة قبل اعتبارها إشارة جديدة.\nلا تغيّر استراتيجية المحتوى بناءً على مسح واحد: أعد فحص اقتراح «زبدة الشيا للبشرة» في مسحات لاحقة للتأكد من ثباته قبل الاستثمار فيه.\nاختبر محتوى يجيب عن نية «زبدة الشيا للبشرة» العامة بمعلومات استخدام واضحة وغير طبية، وقِس ظهوره في البحث بدل الادعاءات العلاجية.\nتتبع دوران اقتراحات البحث وسجّل الدخول والخروج مع التوقيت، لتفرّق بين الاتجاه الثابت والدوران المؤقت.\nتجنّب اعتبار كل تهجئة مختلفة منتجًا أو منافسًا جديدًا؛ ادمج المتغيرات الإملائية في تتبع واحد حتى يثبت العكس في مسحات متكررة.','\n',char(10)),1795200069238,'','','','');
INSERT INTO competitor_ad_analyses VALUES(119,106,'غير محدد من التسجيل','صياغة علاجية بديلة لنفس فئة كريم KP: «كريم علاج جلد الوزة» بدلاً من «كريم ضد جلد الوزة» — إشارة لغة بحث مسجلة، وليست زاوية إعلان موثقة.','مسجل كصياغة بحث فقط: «كريم علاج جلد الوزة» — لا يوجد نص هوك إعلاني مسجل في الملاحظة.','اقتراح إكمال تلقائي في بحث جوجل مصر (hl=ar, gl=eg) لكلمة «كريم جلد الوزة» — ليس إعلان فيديو مسجلاً.','غير مسجل — لا يوجد عرض مسجل في الملاحظة.','غير مسجلة — تاريخ الرصد الوحيد المسجل هو 2026-11-20 الساعة 20:29 EET؛ لا تاريخ بدء ولا مدة تشغيل مسجلة، والملاحظة تشترط الثبات في المسحات القادمة قبل أي خطوة محتوى.','لم يُسجل أداء إعلان؛ المسجل فقط دخول «كريم علاج جلد الوزة» أعلى 10 اقتراحات وخروج «كريم ضد جلد الوزة» في نفس المسح. مستنتج بحذر فقط: كلمة «علاج» قد تعكس نية بحث أكثر مباشرة من «ضد»، لكن هذا غير مثبت ويحتاج مسحات لاحقة.','إشارة لحظية من مسح واحد بلا استمرارية مثبتة، وليست منتجاً جديداً ولا إعلاناً موثقاً؛ الصياغة قد تختفي في المسح التالي، كما أن استخدام «علاج» كادعاء علاجي في محتوى زيرا مخاطرة طبية/تنظيمية.',replace('تتبع فقط: راقب «كريم علاج جلد الوزة» مقابل «كريم ضد جلد الوزة» في مسحات جوجل مصر القادمة، ولا تنشر محتوى مبنياً عليها قبل ثباتها في أكثر من مسح.\nاختبر كصياغة بحث/AEO فقط: اختبر عبارات محايدة مثل «روتين العناية بجلد الوزة» و«كريم روتين KP» في عناوين وأسئلة، دون ادعاء أن الكريم يعالج KP.\nتجنب النسخ الأعمى: لا تبنِ منتجاً جديداً ولا حملة على صياغة بحث واحدة؛ الملاحظة المسجلة تقول صراحة إنها إشارة لغة بحث لا فرصة منتج.\nاختبر نية البحث: قارن لاحقاً بين صياغات «علاج» و«ضد» و«روتين» من حيث وضوح النية، دون استخدام اسم براند منافس أو مقارنة ببراند.\nتجنب الادعاءات الطبية: عند أي اختبار محتوى، التزم بوصف روتين وعناية دون وعد علاجي.','\n',char(10)),1795200163890,'','','','');
INSERT INTO competitor_ad_analyses VALUES(120,107,'غير محدد من التسجيل','زاويتا بحث جديدتان مسجلتان في أعلى 10 اقتراحات «علاج السيلوليت»: «علاج السيلوليت عند النساء» — صياغة شريحة، و«علاج السيلوليت بالاعشاب» — زاوية علاج بديل بالأعشاب.','غير مسجل — لا يوجد نص إعلان أو هوك مسجل في التسجيل؛ المسجل فقط اقتراحا بحث.','غير مسجل كإعلان — المصدر المسجل: مسح Google Egypt autocomplete (hl=ar, gl=eg) لكلمة «علاج السيلوليت»؛ لا فورمات إعلاني مسجل، وليس فيديو مسجلاً.','غير مسجل — لا يوجد عرض مسجل في التسجيل.','غير مسجلة — لا تاريخ بدء إعلان ولا مدة تشغيل مسجلة؛ المسجل فقط تاريخ الرصد 2026-11-20 ومسح 20:29 EET، وأن الاقتراحين دخلا في هذا المسح، بينما خرج «علاج السيلوليت في الجسم» و«علاج السيلوليت في الفخذين» للمرة الثانية اليوم بعد عودتهما في مسح 20:09 EET.','لا يوجد دليل أداء مسجل ولا إعلان مسجل لتأكيد النجاح؛ المسجل فقط دخول الاقتراحين أعلى 10 في مسح 20:29 EET. المستنتج بحذر: صياغة «عند النساء» تطابق لغة بحث الشريحة، و«بالاعشاب» تطابق طلباً مسجلاً لبديل طبيعي، وهذا قد يفسر الظهور وليس أداءً مثبتاً.','الأوضح: الاقتراحان غير مثبتين — يثبتان أو يموتان في المسحات الجاية حسب التسجيل، و«بالاعشاب» زاوية علاج بديل بالأعشاب مش منتج تحمله زيرا ولا منتج مقترح، فلا فرصة منتج من غير قرار مالك؛ إضافة إلى غياب أي إعلان أو عرض أو دليل أداء مسجل يمكن البناء عليه.',replace('اختبر صياغة الشريحة «عند النساء» في أسئلة/محتوى بحثي (AEO) بصيغة استفسارية دون ادعاء طبي أو وعد علاجي، وقِس استمرارها في المسحات الجاية قبل التوسع.\nلا تبنِ عرضاً أو منتجاً حول «بالاعشاب» ولا تنسخ الزاوية كادعاء علاجي؛ تجنبها لحين قرار مالك صريح.\nراقب المسحات الجاية لتثبيت أو موت الاقتراحين، ولا تستثمر بناءً على ظهور واحد في مسح 20:29 EET.\nاحتفظ بصيغ الموضع الخارجة «في الجسم» و«في الفخذين» كمؤشر دوران لا كاختفاء نهائي، إذ عادتا في مسح 20:09 ثم خرجتا مجدداً.','\n',char(10)),1795200677486,'','','','');
INSERT INTO competitor_ad_analyses VALUES(121,108,'غير محدد من التسجيل','غير مسجلة — الملاحظة مسح لغة بحث وليست إعلاناً، فلا زاوية إعلانية موصوفة في التسجيل.','غير مسجل — لا نص هوك ولا محتوى إعلان مذكور في التسجيل.','مسح لغة بحث: Google Egypt autocomplete (hl=ar, gl=eg)، 12 كلمة متتبعة في مسح 20 نوفمبر 22:09 EET — ليس إعلان فيديو ولا نصاً إعلانياً مسجلاً.','غير مسجل — لا عرض مذكور في التسجيل.','غير مسجلة — المسجل فقط تاريخ رصد 2026-11-20 ومسحا 19:56 و22:09 EET في اليوم نفسه؛ لا تاريخ بدء إعلان ولا مدة تشغيل مذكورة.','غير مسجل — لا إعلان ولا أرقام أداء مسجلة؛ المسجل فقط عودة «كريم يوريا ٣٠ للجسم» و«كريم لاخفاء جلد الوزة» إلى أعلى 10، وهو إشارة طلب بحث فقط وليس دليل نجاح إعلان.','لا يوجد إعلان مسجل لتحليله، وكل الإشارات الجديدة من مسح واحد غير مثبتة، والمسح نفسه ينص على أنه «لا فرصة منتج جديدة من المسح ده»، إضافة إلى أن اختفاء الكلمة البذرة من القوائم الـ12 أثر صيغة رد API وليس خروجاً حقيقياً.',replace('اختبر كفرضية طلب مسجلة محتوى أو عرضاً حول يوريا 30% مقارنة بنسبة 25% الحالية لزيرا، دون أي ادعاء طبي أو فعالية علاجية.\nاختبر زاوية الإخفاء/المظهر المرتبطة بعبارة «كريم لاخفاء جلد الوزة» بعد عودتها إلى أعلى 10، بصياغة تجميلية غير طبية.\nلا تبنِ أي خطوة على إشارات المسح الواحد («سيلوليت جورجينا» و«مخمرية رجالي» و«علاج جلد الوزة في منطقة البكيني») قبل تأكيدها أو نفيها في مسحات لاحقة.\nاحتفظ بمراقبة الفرص المسجلة تحت أعلى 10، «علاج جلد الوزة والشعر تحت الجلد» و«سيلوليت رول امازون»، بدل إسقاطها من المتابعة.\nلا تحسب اختفاء الكلمة البذرة من القوائم الـ12 خروجاً؛ وثّق صيغة رد API (client=chrome) عند مقارنة المسحات.','\n',char(10)),1795206020231,'','','','');
INSERT INTO competitor_ad_analyses VALUES(122,108,'غير محدد من التسجيل','غير مسجلة كزاوية إعلان — المسجل فقط إشارات طلب بحث في مسح 20 نوفمبر 2026 22:09 EET: «كريم يوريا ٣٠ للجسم» دخل أعلى 10، و«كريم لاخفاء جلد الوزة» رجع لأعلى 10.','غير مسجل — لا يوجد نص إعلان أو هوك مسجل في الملاحظة.','غير مسجل كإعلان — الملاحظة مسح لغة بحث من Google Egypt autocomplete (hl=ar, gl=eg)، 12 كلمة متتبعة، وليست إعلاناً موصوفاً.','غير مسجل — لا يوجد عرض أو سعر أو حزمة مسجلة.','غير مسجلة — المسجل فقط مسحان في 2026-11-20: 19:56 EET و22:09 EET؛ لا يوجد تاريخ بدء إعلان أو مدة تشغيل مسجلة.','لا يوجد أداء إعلان مسجل لإثبات نجاح؛ المسجل فقط استمرار طلب البحث: يوريا 30% دخل أعلى 10 وكريم الإخفاء رجع لأعلى 10، و«علاج جلد الوزة والشعر تحت الجلد» (فرصة #3) و«سيلوليت رول امازون» (فرصة #8) ما زالا موجودين تحت أعلى 10.','لا يوجد إعلان مسجل لتقييم ضعفه؛ أضعف نقطة في التسجيل أن الإشارات الجديدة كلها من مسح واحد غير مؤكدة، ولا فرصة منتج جديدة من هذا المسح، واختفاء الكلمة البذرة «جلد الوزة» من الـ12 قائمة أثر منهجي في صيغة رد الـAPI (client=chrome) وليس خروجاً حقيقياً.',replace('راقب في المسحات التالية طلب «كريم يوريا ٣٠ للجسم» (فرصة #1) مقابل تركيز زيرا الحالي 25% قبل أي قرار منتج، وبدون ادعاءات طبية.\nاختبر محتوى AEO يجيب عن أسئلة البحث المسجلة حول إخفاء جلد الوزة والشعر تحت الجلد (فرصة #6 وفرصة #3)، دون ادعاء علاج أو مقارنة باسم براند.\nلا تتخذ خطوة على إشارات مسح واحد — «سيلوليت جورجينا» و«مخمرية رجالي» و«علاج جلد الوزة في منطقة البكيني» وإشارة سكراب ماركة منافسة — حتى تتكرر أو تموت في المسحات الجاية.\nلا تفسر اختفاء الكلمة البذرة «جلد الوزة» من القوائم كتراجع طلب؛ التسجيل يوضح أنه فرق صيغة رد API (client=chrome)، فاستبعد هذا الأثر عند المقارنة.\nاحتفظ بـ«سيلوليت رول امازون» (فرصة #8) تحت أعلى 10 كإشارة صيغة/قناة للمراقبة والاختبار لاحقاً فقط، دون نسخ أعمى.','\n',char(10)),1795206091468,'','','','');
INSERT INTO competitor_ad_analyses VALUES(123,109,'Soralone','المسجل: تموضع سعري منخفض لمنتجات يوريا لجلد الوزة؛ والاستنتاج: زاوية «قيمة مقابل سعر» عبر خصم ثابت وواضح، بدل رسالة منتج أو نتيجة جديدة — لا توجد رسالة إعلانية نصية مسجلة.','غير مسجل كنص هوك أو منطوق؛ العنصر المسجل الوحيد القريب من الهوك هو مرساة السعر: 145 بدل 295 (-51%).','غير مسجل كفيديو؛ التسجيل هو رصد حي لأسعار قوائم متاجر إلكترونية (Nefro Glow وe-majestic وSeif). البروفايل يذكر اعتماداً عاماً على ريلز صانعي محتوى وقمع واتساب، لكن لا يوجد وصف كرييتف أو فيديو في هذه الملاحظة.','جل يوريا 15% 100مل بـ145 بدل 295 (-51%) على Nefro Glow، مع ثبات كامل الخط على القناة نفسها (مثلاً سيكا 145/295، هيدرا 135/275، نانو سيكا سبراي 240/475)؛ وفي e-majestic هيدرا 138/275 ونانو سبراي 237.50/475؛ وأول رصد في سيف: كريم 60مل بـ130 بدل 200 (-35%) بلا خط أساس سابق.','غير مسجلة؛ لا تاريخ بدء ولا مدة تشغيل مذكورة. المسجل فقط: رصد حي في 2026-11-20 ~22:30 EET (جولة سوق 92)، وأن الأسعار مطابقة تماماً للجولتين 77 و87 دون تواريخهما.','استنتاج مرجّح وليس أداءً مسجلاً: مرساة سعرية قوية وواضحة (-51%) وثباتها عبر جولات وقنوات متعددة قد يبني توقعاً سعرياً مستقراً ويسهّل القرار، مع اتساع التوافر عبر قناة صيدلية جديدة؛ ولا توجد أرقام أداء مسجلة لدعم ذلك.','الأوضح: جمود سعري كامل في فترة White Friday حية على Nefro Glow — بلا تحرك أو حافز جديد مسجل وبلا منتج روتين جديد؛ والاعتماد الظاهر على الخصم وحده يجعل العرض قابلاً للتقليد، وحالة المخزون غير مؤكدة بسبب وسم «Out of stock» الظاهر كأثر عرض/زحف.',replace('اختبر لزيرا: تثبيت مرساة سعرية واضحة (سعر قبل/بعد) لفترة محددة وقياس أثرها على التحويل بدل تغيير السعر المتكرر.\nتبنَّ: توسيع التوافر عبر قناة بيع موثوقة إضافية كإثبات توافر، مع التحقق اليدوي من المخزون قبل الإعلان عنه.\nتجنب: ترك العرض ثابتاً تماماً خلال موسم تخفيضات دون حافز جديد؛ اختبر حزمة أو عرضاً محدوداً بدل خفض سعري إضافي.\nاختبر: رسالة قيمة غير سعرية قابلة للقياس (مثل حجم العبوة أو سهولة الروتين) لأن الخصم وحده سهل التقليد.\nتجنب: بناء أي رسالة على وسم مخزون أو سعر يظهر في الزحف فقط؛ تحقق من العرض فعلياً قبل النشر.','\n',char(10)),1795207301827,'','','','');
INSERT INTO competitor_ad_analyses VALUES(124,110,'غير محدد من التسجيل','نية بحث مسجلة عن «كريم يوريا للجسم» بصيغ الأرقام (١٠/10 و٢٠/20) وصيغة «الأفضل/الأحسن» والصيغة اللاتينية urea؛ وليس زاوية إعلانية إبداعية مسجلة.','غير مسجل — لا يوجد نص هوك إعلاني في التسجيل؛ المسجل فقط اقتراحات بحث داخلة: «كريم urea للجسم» و«كريم يوريا ١٠ للجسم» و«كريم يوريا 20 للجسم» و«احسن كريم يوريا للجسم».','مسح لغة بحث جوجل مصر (suggestqueries.google.com، hl=ar، gl=eg) — وليس إعلان فيديو أو صورة مسجلاً.','غير مسجل — لا يوجد عرض أو سعر أو خصم في التسجيل؛ المسجل أن كريم اليوريا منتج تحمله زيرا (25%).','غير مسجلة كمدة إعلان؛ المسجل فقط تاريخا مسح: 20 نوفمبر 2026 23:53 EET و21 نوفمبر 2026 00:09 EET، وظهور سابق للصيغة اللاتينية في مسح 20 نوفمبر 11:30 EET.','لا توجد أرقام أداء مسجلة فلا يمكن الحكم على نجاح إعلان؛ المسجل فقط استمرار نية البحث: 11 كلمة من 12 ثابتة تمامًا كمجموعة، وتحركت كلمة «كريم يوريا للجسم» وحدها بدخول 4 صيغ بحث وخروج 4، ما يشير (استنتاجًا من الثبات والدوران المسجلين) إلى اهتمام بحثي مستمر بصيغ الأرقام والأفضلية وليس إلى أداء إعلان.','الأوضح: لا فرصة منتج جديدة من هذا المسح — الداخلة الأربعة مجرد صيغ بحث بديلة لمنتج موجود؛ وعودة الصيغة اللاتينية غير مؤكدة وتحتاج مسحًا أو اثنين، والخارجة دوران لا موت مؤكد من مسح واحد.',replace('اختبر الصيغة اللاتينية «كريم urea للجسم» في عناوين البحث ووصف المنتج، لكن لا تعتمدها نهائيًا قبل مسح أو اثنين للتأكيد لأن اختبار موتها لم يُحسم بعد حسب التسجيل.\nغطِّ صيغ الأرقام البديلة ١٠/10 و٢٠/20 في المحتوى والبحث الداخلي بدل صيغة واحدة، لأن الداخلة المسجلة صيغ أرقام بديلة للموجود أصلًا.\nأضف مرادف «احسن كريم يوريا للجسم» بجانب «افضل كريم يوريا للجسم» في صياغة المحتوى، دون ادعاء تفوق طبي.\nتجنب الحكم بموت صيغة بحث من مسح واحد؛ الخارجة المسجلة وُصفت بأنها دوران حسب ملاحظة #39.\nلا تبنِ منتجًا جديدًا على هذا المسح؛ الداخلة صيغ بحث عن كريم يوريا الذي تحمله زيرا (25%)، فركّز على تغطية الصيغ لا على إطلاق جديد.','\n',char(10)),1795213222076,'','','','');
INSERT INTO competitor_ad_analyses VALUES(125,110,'غير محدد من التسجيل','غير مسجلة كزاوية إعلان؛ المسجل فقط نية بحث عن «كريم يوريا للجسم» بصيغ التركيز والأفضلية والصيغة اللاتينية urea','غير مسجل؛ لا يوجد نص هوك إعلاني في الملاحظة، وهي مسح اقتراحات بحث فقط','غير مسجل كفورمات إعلان؛ المصدر المسجل مسح لغة بحث جوجل مصر suggestqueries.google.com hl=ar gl=eg','غير مسجل؛ لا يوجد عرض سعر أو خصم أو حزمة مذكور، والمسجل فقط أن كريم يوريا منتج تحمله زيرا (25%)','غير مسجلة؛ لا تاريخ بدء إعلان ولا مدة تشغيل مذكورة، والتواريخ المسجلة تواريخ مسح فقط: 21 نوفمبر 00:09 EET مقارنة بـ 20 نوفمبر 23:53 EET، مع ظهور سابق للصيغة اللاتينية في 20 نوفمبر 11:30 EET','لا يوجد دليل أداء إعلان مسجل؛ المؤشر الوحيد المسجل هو ثبات 11 من 12 كلمة وحركة مقصورة على «كريم يوريا للجسم» بدخول 4 صيغ بحث بديلة، ما يشير — كاستنتاج من البحث فقط وليس أداء إعلان — إلى استمرار وتنوع الطلب البحثي على كريم اليوريا بتركيزات وصيغ مختلفة، لا إلى نجاح إعلان محدد','الأوضح من التسجيل: عدم الثبات — الصيغة اللاتينية عادت بعد تسجيل موتها في ملاحظة #35، والخارجة الأربعة دوران حسب ملاحظة #39 ولا يُحكم عليها من مسح واحد؛ ولا فرصة منتج جديدة مسجلة لأن الداخلة الأربع صيغ بحث عن منتج موجود أصلاً لدى زيرا',replace('اختبر صيغة urea اللاتينية بجانب يوريا العربية في عناوين ووصف زيرا، ولا تعتبرها ميتة إلا بعد مسح أو اثنين للتأكيد كما ورد في التسجيل.\nاختبر صيغ الأرقام البديلة 10 و٢٠ و١٠ و20 في البحث والوصف، لأنها ظهرت كصيغ بديلة للموجود أصلاً.\nاختبر مرادف «احسن كريم يوريا للجسم» بجانب «افضل» بدل افتراض صيغة بحث واحدة.\nتجنب الحكم على الخارجة الأربعة من مسح واحد؛ اعتبرها دوراناً حسب ملاحظة #39 حتى تأكيد مسح لاحق.\nلا تبنِ منتجاً جديداً على هذا المسح؛ ركّز على كريم اليوريا (25%) الذي تحمله زيرا أصلاً، ومن غير ادعاءات طبية أو مقارنات باسم براند.','\n',char(10)),1795213247868,'','','','');
INSERT INTO competitor_ad_analyses VALUES(126,111,'غير محدد من التسجيل','علاج جلد الوزة منطقة بمنطقة بدلاً من طرحه كمشكلة عامة، مع بروز «منطقة البكيني» كمنطقة بحث جديدة دخلت أعلى 10 اقتراحات «علاج جلد الوزة» لأول مرة، بعد الوجه (فرصة #4).','غير مسجل — لا يوجد نص إعلان أو هوك مسجل في الملاحظة؛ العبارة المسجلة الوحيدة هي عبارة البحث «علاج جلد الوزة في منطقة البكيني»','غير مسجل — المصدر مسح لغة بحث جوجل مصر (SEARCH)، وليس وصف إعلان بصيغة فيديو أو صورة أو نص','غير مسجل — لا يوجد عرض مسجل؛ الإشارة الموازية الوحيدة هي ارتباط كلمة «كريم» بالمشكلة في «جلد الوزة كريم»','غير مسجلة — لا يوجد تاريخ بدء إعلان ولا مدة تشغيل مذكورة؛ التواريخ المسجلة الوحيدة هي مسحا 00:31 و00:49 EET في 21 نوفمبر 2026، وهي تواريخ رصد بحث وليست مدة تشغيل','لا يوجد إعلان مسجل ولا أرقام أداء، فلا يمكن تأكيد نجاح إعلان؛ قوة الإشارة المسجلة فقط هي تحديد الباحثات للمنطقة بدقة — البكيني في أعلى 10 ومعها بين الفخذين والرجل والذراعين تحت أعلى 10 — ما يشير إلى طلب محدد حسب المنطقة وليس اهتماماً عاماً، إضافة إلى التصاق كلمة «كريم» بالمشكلة نفسها.','إشارة مسح واحد فقط لم تُثبت بعد وقد تختفي في المسحات التالية، وهي إشارة بحث وليست دليل أداء إعلان؛ كما لا تحدد منافساً ولا رسالة إعلان ولا عرضاً ولا صيغة',replace('اختبر محتوى/صفحات منفصلة لكل منطقة — البكيني، بين الفخذين (#11)، الرجل (#12)، الذراعين (#14) — بدل صفحة عامة واحدة، وقارن الاهتمام بكل منطقة قبل التوسع.\nاختبر صياغة «كريم» كصيغة منتج مرتبطة مباشرة بالمشكلة، بناءً على دخول «جلد الوزة كريم» أعلى 10 «جلد الوزة»، دون أي ادعاء طبي بفعالية العلاج.\nلا تبنِ حملة كاملة على إشارة مسح واحد؛ انتظر تأكيد بقاء «علاج جلد الوزة في منطقة البكيني» في أعلى 10 في المسحات التالية قبل أي خطوة كبيرة.\nاختبر عبارة «علاج جلد الوزة والشعر تحت الجلد» (#15) كحاجة مترابطة بصياغة تعليمية واستفسارية، دون ادعاءات طبية.\nتجنب نسخ عبارة منافس غير محدد أو ادعاءات علاجية؛ استخدم لغة البحث حرفياً في AEO/SEO كوصف لما تبحث عنه المستخدمة، واختبر الصياغة حسب المنطقة.','\n',char(10)),1795216269648,'','','','');
INSERT INTO competitor_ad_analyses VALUES(127,112,'إيفا — مذكورة صراحة في التسجيل كمنافس في إشارة «سكراب جسم ايفا» فقط؛ الإشارتان الأخريان بلا براند منافس مذكور','المسجل: ربط كلمة فئوية باسم قابل للبحث — «سيلوليت» باسم مشهورة، و«سكراب جسم» باسم منافس، و«مخمرية» بتخصيص رجالي بصيغة أطول «مخمرية رجالي للجسم». هذه زاوية مستنتجة من لغة البحث، وليست زاوية إعلان موصوف نصاً في التسجيل.','غير مسجل — لا يوجد نص هوك أو منطوق إعلان في التسجيل؛ المسجل فقط عبارات بحث دخلت أعلى 10: «سيلوليت جورجينا» و«سكراب جسم ايفا» و«مخمرية رجالي للجسم».','SEARCH — مسح لغة بحث جوجل مصر (hl=ar, gl=eg)؛ ليس إعلان فيديو أو صورة موصوفاً في التسجيل.','غير مسجل — لا يوجد عرض سعر أو خصم أو هدية أو عرض مذكور في التسجيل.','غير مسجلة — تاريخ الرصد 2026-11-21، ومسح 00:49 EET مقارنة بمسح 00:31 EET في اليوم نفسه؛ لا يوجد تاريخ بدء إعلان أو مدة تشغيل مسجلة، والفارق بين المسحين ليس مدة تشغيل.','مستنتج وليس مسجلاً بأرقام أداء: دخول 3 عبارات جديدة إلى أعلى 10 في مسح واحد يشير إلى أن ربط الاسم/التخصيص بالفئة يجعل عبارة البحث أكثر تحديداً وسهولة في التذكر والكتابة؛ لكن لا يوجد في التسجيل ما يثبت تحويلاً أو مبيعاً أو استمرارية، والتسجيل نفسه يقول إنها إشارات مسح واحد تثبت أو تموت في المسحات الجاية.','الأوضح: إشارة مسح واحد فقط بلا استمرارية أو أداء مسجل، وبلا محتوى إعلان أو عرض يربطها بنتيجة؛ والارتباط باسم مشهورة/براند لا تملكه زيرا، ولا يوجد منتج زيرا يحمل أياً من هذه الأسماء كما هو مسجل.',replace('اختبر صيغ بحث أطول وأوضح حول الاستخدام والفئة المستهدفة (مثل تخصيص منتج موجود فعلاً للرجال وللجسم) في عنوان/وصف زيرا، وقس ظهورها في مسحات قادمة قبل التوسع.\nلا تنسخ عبارات بحث تحمل اسم مشهورة أو براند منافس؛ ابنِ صيغة خاصة بزيرا حول الفئة والاستخدام العام دون ادعاء طبي ودون مقارنة باسم براند.\nأجّل أي استثمار كبير حتى تتأكد الإشارات الثلاث في مسحات جاية — اعتبرها فرضيات اختبار لا اتجاهاً مثبتاً.\nاختبر زاوية التخصيص للرجال على منتج مخمرية موجود لدى زيرا بصياغة واضحة عن الاستخدام، دون تغيير الاسم إلى صيغة لا يحملها المنتج.\nركّز وصف المنتج على الاستخدام والملمس والرائحة وتجربة الاستخدام، وتجنب أي ادعاء طبي حول السيلوليت أو نتائج علاجية.','\n',char(10)),1795216387054,'','','','');
INSERT INTO competitor_ad_analyses VALUES(128,113,'Veexia — Vee Allure Urea Hydro Cream 10%','تموضع مسجل لجلد الوزة (keratosis pilaris): بشرة جافة خشنة وملمس متكتل، عبر كريم يوريا 10% مع نياسيناميد وساليسيليك وجليكوليك ولاكتيك وشيا وبانثينول — كما هو موصوف في صفحة المنتج على Beseha','غير مسجل نص هوك إعلاني حرفي في التسجيل؛ المستنتج من التموضع المسجل فقط هو: يوريا 10% لملمس جلد الوزة الخشن المتكتل — وليس نصاً منقولاً من إعلان','غير مسجل؛ المسجل فقط بحث عام وصفحة منتج على Beseha، ولا يوجد وصف لإعلان فيديو أو صورة في التسجيل','غير مسجل؛ لم يظهر سعر حي في نتيجة البحث، ولا يوجد خصم أو عرض أو باقة مذكورة، والمسجل فقط عبوة 150 جم','غير مسجلة؛ تاريخ الرصد المسجل فقط هو 2026-11-21 نحو 01:00 EET في الجولة 98، ولا يوجد تاريخ بدء إعلان أو مدة تشغيل/استمرارية مذكورة','لا يوجد دليل أداء مسجل؛ الاستنتاج فقط وليس مسجلاً: التموضع الضيق والمحدد للملمس المتكتل مع ذكر تركيز 10% وتركيبة متعددة المكونات قد يجعل الرسالة أوضح وأسهل في الفهم من ادعاء ترطيب عام، لكن هذا لا يثبت نجاح الإعلان.','الأوضح من التسجيل: غياب السعر الحي وغياب أي إعلان ميتا أو قناة موثقة، والبراند غير مسجل في قائمة منافسي زيرا الـ33 ويحتاج جولة تعميق مستقلة قبل إضافته كمنافس رسمي أو تجاهله، فلا يمكن الحكم على قوة الإعلان أو استمراريته من صفحة منتج فقط.',replace('اختبر لزيرا تموضعاً ضيقاً واحداً للملمس الخشن المتكتل بدلاً من ادعاءات عامة، بصياغة تجميلية عن المظهر والترطيب والملمس دون ادعاء علاجي.\nاختبر إظهار التركيز والمكونات بوضوح في صفحة المنتج، مثل نسبة اليوريا، وقِس أثره على الفهم والثقة بدلاً من نسخه أعمى.\nتجنب أي قرار إنتاج أو محتوى عن منافس غير موثق قبل إكمال جولة تعميق مستقلة للسعر والتوفر والقنوات وإعلانات ميتا، وموافقة المالك.\nتبنَّ وضوح حجم العبوة والاستخدام المستهدف في صفحة المنتج، وتجنب ترك السعر غير ظاهر لأنه يضعف وضوح القرار.\nاختبر رسالة مشكلة/ملمس واحدة لكل إعلان بدلاً من سرد كل المكونات دفعة واحدة، ولا تعتبر الزاوية ناجحة دون دليل استمرارية مسجل.','\n',char(10)),1795216807423,'','','','');
INSERT INTO competitor_ad_analyses VALUES(129,113,'Vee Allure (Veexia)','تموضع صريح لجلد الوزة (keratosis pilaris) والجلد الجاف الخشن والملمس المتكتل، عبر كريم «Vee Allure Urea Hydro Cream 10%» بتركيبة مسجلة: يوريا 10% + نياسيناميد + ساليسيليك + جليكوليك + لاكتيك + شيا + بانثينول، بحجم 150 جم، معروض على Beseha.','غير مسجل في التسجيل — لا يوجد نص هوك إعلاني أو منطوق مذكور؛ المسجل فقط هو التموضع: الجلد الجاف الخشن والملمس المتكتل المرتبط بجلد الوزة.','غير مسجل كإعلان — المسجل هو صفحة منتج على Beseha واكتشاف عبر بحث عام، وليس وصف فورمات إعلاني (صورة/فيديو/كاروسيل).','غير مسجل — لم يظهر سعر حي في نتيجة البحث، ولا يوجد عرض أو خصم أو حزمة مذكورة في التسجيل.','غير مسجلة — تاريخ الرصد فقط هو 2026-11-21 ~01:00 EET خلال الجولة 98 (Eva)؛ لا تاريخ بدء إعلان ولا مدة تشغيل مذكورة.','لا توجد أرقام أداء مسجلة تثبت نجاحه؛ الاستنتاج المحتمل من التموضع المسجل فقط هو أن التخصيص لمشكلة ملمس محددة وواضحة، مع تركيبة مركبة موصوفة وحجم 150 جم، يجعله سهل الفهم والتمييز كحل موضعي مقترح، لكن ذلك استنتاج وليس أداءً مسجلاً.','الأوضح: غياب السعر الحي والتوفر والقنوات وإعلانات ميتا المسجلة، والبراند غير مسجل في قائمة منافسي زيرا الـ33؛ فلا يمكن تأكيد أن هذا إعلان ناجح أو مستمر، ويحتاج جولة تعميق مستقلة قبل إضافته كمنافس رسمي أو تجاهله.',replace('اختبر تموضع زيرا حول مشكلة ملمس محددة (جفاف/خشونة/تكتل) بصياغة وصفية غير طبية، وقس فهم الجمهور واستجابته قبل التوسع.\nاختبر عرض التركيبة المركبة كقيمة في صفحة المنتج (مكونات موضحة + طريقة استخدام)، دون وعود علاجية أو ادعاء علاج جلد الوزة.\nتجنب نسخ التموضع أو الصياغة حرفياً، وتجنب أي مقارنة باسم براند منافس أو ادعاء تفوق.\nقبل اعتبار أي منتج جديد منافساً رسمياً، وثّق في جولة تعميق مستقلة: السعر الحي والتوفر والقنوات والإعلانات النشطة.\nلا تتخذ قرار إنتاج أو محتوى بناءً على اكتشاف منتج وحده؛ اربط أي اختبار بموافقة المالك وبمعيار نجاح محدد مسبقاً.','\n',char(10)),1795216879353,'','','','');
INSERT INTO competitor_ad_analyses VALUES(130,114,'غير محدد من التسجيل','غير مسجلة كزاوية إعلان؛ المسجل هو معنى أولي لعبارتي بحث دخلتا أعلى 10 «زبدة الشيا»: «زبدة الشيا للوجة تجربتي» بحث عن تجربة استخدام الشيا للوجه، و«زبدة الشيا الافريقية» بحث عن نوع/مصدر الشيا. شيا زيرا متموضعة للجسم في روتين KP حسب الملاحظة، فزاوية الوجه محتملة كمحتوى مش فجوة منتج بعد، وتموضع زيرا من حيث المصدر غير مسجل.','غير مسجل — لا يوجد نص هوك أو إعلان مسجل في الملاحظة، وعبارتا البحث ليستا هوك إعلان.','غير مسجل كفورمات إعلان؛ المصدر المسجل هو مسح لغة بحث جوجل مصر (Google Egypt autocomplete، hl=ar، gl=eg، client=chrome) بتاريخ 2026-11-21 الساعة 01:33 EET، وليس إعلان فيديو أو صورة موصوفًا.','غير مسجل — لا يوجد عرض مسجل في الملاحظة.','غير مسجلة — لا يوجد تاريخ بدء إعلان أو مدة تشغيل مذكورة؛ التواريخ المسجلة فقط هي تاريخ الرصد 2026-11-21 ومسح 01:33 EET في 21 نوفمبر، مع مقارنة بمسح 23:12Z.','غير مثبت من التسجيل أن إعلانًا يعمل أو ناجح؛ المسجل فقط هو دخول «زبدة الشيا للوجة تجربتي» (#9) و«زبدة الشيا الافريقية» (#10) إلى أعلى 10 «زبدة الشيا» في مسح chrome، ما يشير — إن تأكد — إلى اهتمام بحثي بتجربة الوجه وبالمصدر/النوع الأفريقي، دون أي أرقام أداء مسجلة.','ضعف الإشارة نفسها: إشارة مسح واحد فقط وتحتاج تأكيدًا؛ جلب موازٍ بنفس التوقيت تقريبًا (client=firefox) لم يُظهر الاقتراحين الجديدين وأظهر «الخام» ما زالت موجودة، فخروج «زبدة الشيا الخام» من أعلى 10 دوران مش موت، ولا يجوز الاستنتاج قبل المسحات الجاية.',replace('اختبر — بعد التأكيد في مسحات جاية — محتوى حول تجربة الشيا للوجه كزاوية محتوى فقط، دون تغيير تموضع شيا زيرا للجسم في روتين KP ودون ادعاءات طبية، لأن الملاحظة تقول إنها زاوية محتملة مش فجوة منتج بعد.\nافحص تموضع شيا زيرا من حيث المصدر/النوع، لأن «الافريقية» بحث عن نوع/مصدر والتموضع الحالي غير مسجل؛ اختبر توضيح المصدر في المحتوى فقط إذا تأكدت الإشارة.\nلا تستنتج موت «زبدة الشيا الخام» ولا تبنِ قرارًا عليها قبل تأكيد المسحات الجاية، وتعامل مع خروجها كدوران محتمل.\nتابع الفرص المسجلة الحية تحت أعلى 10 في المراتب 11-15: «يوريا 30»/«يوريا ٣٠٪» (فرصة #1)، و«علاج جلد الوزة والشعر تحت الجلد» (فرصة #3)، و«سيلوليت رول امازون» (فرصة #8)، واختبرها كمحتوى دون نسخ أعمى ودون مقارنات باسم براند.\nلا تنسخ عبارتي البحث كهوك أو ادعاء، ولا تبنِ إعلانًا على مسح واحد؛ أعد القياس أولًا ثم اختبر زاوية واحدة قابلة للقياس في كل مرة.','\n',char(10)),1795218054288,'','','','');
INSERT INTO competitor_ad_analyses VALUES(131,115,'غير محدد من التسجيل','المسجل: اقتراحا بحث «زبدة الشيا للوجة تجربتي» (تجربة استخدام للوجه) و«زبدة الشيا الافريقية» (نوع/مصدر الشيا)؛ والملاحظة نفسها تصفهما بأنهما إشارة لغة/زاوية محتوى وليستا منتجاً جديداً لا تحمله زيرا.','غير مسجل كهوك إعلان؛ المسجل فقط عبارتا الاقتراح «زبدة الشيا للوجة تجربتي» و«زبدة الشيا الافريقية»، ولا يوجد نص هوك إعلاني منطوق مسجل.','غير مسجل كفورمات إعلان؛ المسجل فقط مسح اقتراحات بحث جوجل مصر (suggestqueries.google.com، hl=ar، gl=eg، client=chrome) بتاريخ 2026-11-21، وليس وصف إعلان فيديو أو صورة.','غير مسجل؛ لا يوجد عرض مسجل في الملاحظة، والملاحظة تنص على أنه لا فرصة منتج جديدة من هذا المسح.','غير مسجلة كمدة تشغيل إعلان؛ المسجل فقط تواريخ المسح في 2026-11-21: 01:11 و01:33 و01:50 EET، والاقتراحان ظهرا في مسح 01:33 وخرجا من أعلى 10 في مسح 01:50 بعد مسح واحد فقط.','لا يوجد دليل مسجل على أن الإشارة شغالة/ناجحة؛ المسجل عكس ذلك: الاقتراحان ماتا بعد مسح واحد، ومقابل خط الأساس الملفّي (01:11 EET) صفر داخل/خارج أعلى 10 في الكلمات الـ12 كلها، فلا يمكن الاستنتاج أنه إعلان ناجح.','الأوضح: إشارة ومضة لمسح واحد غير ثابتة — ماتت فوراً في المسح التالي باختبار الموت، بينما عاد «زبدة الشيا الخام» (#3) و«زبدة الشيا للبشرة» (#10)، فالاعتماد عليها كطلب ثابت سيكون مضللاً.',replace('اختبر إشارة المسح الواحد قبل اعتمادها: لا تبنِ محتوى أو منتجاً على اقتراح ظهر في مسح واحد فقط؛ أعد المسح للتأكيد (اختبار الموت) كما في تأكيد #114.\nاختبر «للوجة تجربتي» كزاوية محتوى عن تجربة استخدام للوجه فقط، دون ادعاء طبي ودون تقديمها كمنتج جديد.\nاختبر «الافريقية» كزاوية محتوى عن نوع/مصدر الشيا فقط، دون ادعاء منتج جديد.\nتجنب حذف مصطلحات ثابتة بعد غياب مسح واحد: غياب «الخام» و«للبشرة» في مسح 01:33 كان دوراناً حسب ملاحظة #39، وعادا في مسح 01:50 في المركزين #3 و#10.\nقارن أي مسح جديد بخط الأساس الملفّي (01:11 EET): صفر تغيير في أعلى 10 للكلمات الـ12 كلها يعني لا فرصة منتج جديدة من هذا المسح.','\n',char(10)),1795219570879,'','','','');
INSERT INTO competitor_ad_analyses VALUES(132,116,'غير محدد من التسجيل','غير مسجلة — التسجيل مسح اقتراحات بحث جوجل وليس وصف إعلان، ولا يذكر زاوية إعلانية','غير مسجل — لا يوجد نص هوك أو منطوق إعلان في التسجيل','غير مسجل كفورمات إعلان — المصدر المسجل مسح لغة بحث جوجل مصر (SEARCH)، 12 كلمة و10 اقتراحات لكل كلمة','غير مسجل — لا يوجد عرض مذكور في التسجيل','غير مسجلة — لا يوجد تاريخ بدء أو مدة تشغيل؛ تاريخ الرصد الوحيد المسجل هو 2026-11-21 02:29 EET','لا يمكن الاستنتاج أن إعلاناً يعمل — لا يوجد إعلان موصوف ولا أرقام أداء مسجلة؛ المسجل فقط خروج 3 عبارات بحث من أعلى 10 في مسح واحد، وقاعدة الدوران المسجلة تعتبر ذلك دوراناً لا موتاً وتتطلب غياباً متتالياً للحكم، والفرص الثلاث تظل قيد الدراسة','غياب أي دليل إعلاني قابل للتحليل: لا منافس ولا إبداع ولا عرض ولا أداء مسجل، والاعتماد على مسح واحد فقط لا يكفي للحكم على موت فرصة بحث',replace('لا تحكم على فرصة بحث من مسح واحد؛ اشترط غياباً متتالياً في المسحات التالية وفق قاعدة الدوران المسجلة (ملاحظة #41/#42) قبل إسقاطها.\nأبقِ العبارات الثلاث قيد الدراسة واختبرها في المسحات التالية: «علاج جلد الوزة في منطقة البكيني» (فرصة #9)، و«كريم لاخفاء جلد الوزة» (فرصة #6)، و«كريم يوريا ٣٠ للجسم» (فرصة #1) — دون ادعاءات طبية.\nتجاهل الاقتراح الأول عندما يكون صدى للاستعلام نفسه، ولا تسجله كإشارة جديدة.\nعامل صيغ الإملاء المختلفة للاسم نفسه، مثل «يوريان تيمبر» مقابل «يورياج تيمبر»، كمنتج واحد موجود أصلاً ولا تعتبرها فرصة منتج جديدة.\nاختبر محتوى زيرا بلغة البحث المسجلة نفسها بصيغة معلوماتية قابلة للقياس في البحث، بدل نسخ إعلان غير موصوف.','\n',char(10)),1795221638765,'','','','');
INSERT INTO competitor_ad_analyses VALUES(133,117,'بلاك لوتس (blacklotusegypt.com)','مستنتج من الأسعار المسجلة فقط: زاوية سعر/قيمة على منتجات العناية بالجسم الأساسية — تخفيض لوشن الجسم والمقشر — مع عرض موسمي وحيد وتوسّع في التوفر عبر الريتيل، ودون زاوية روتين متخصص مسجلة لـ KP/السيلوليت.','غير مسجل — لا يوجد نص هوك أو محتوى إعلان مذكور في التسجيل؛ التسجيل فحص موقع فقط.','غير مسجل كإعلان — فحص حي بالمتصفح لموقع blacklotusegypt.com (صفحات /routines و/shop وغيرها)؛ ليس فيديو مسجلاً.','المسجل: لوشن الجسم 250مل 300 EGP بدل 345 (-45) لكل الروائح؛ المقشر 290–310 EGP بدل 320؛ كريم الجسم 200مل 350 EGP؛ العرض الموسمي الوحيد Back to School Care 630 بدل 700 (-10%)؛ لا Black Friday/White Friday مسجل؛ لا حد شحن مجاني معلن.','غير مسجلة — لا تاريخ بدء إعلان ولا مدة تشغيل مذكورة؛ المسجل فقط تاريخ الرصد 2026-11-21 (فحص ~02:30–02:36 EET) وأساس مقارنة الأسعار 18 نوفمبر.','مستنتج وليس أداءً مسجلاً: التخفيض الواضح (-45 EGP على اللوشن) قد يخفض حاجز التجربة، والمنتجان المسجلان للسيلوليت IN STOCK، والتوسع إلى 5 فروع + 13 متجر بيع بالتجزئة يزيد التوفر والوصول؛ ولا أرقام أداء مسجلة.','الأوضح المسجل: فجوة في KP/جلد الوزة والسيلوليت — بحث «urea» و«keratosis» و«جلد الوزة» صفر نتائج، والسيلوليت منتجان منفردان فقط ولا روتين سيلوليت/KP، ولا Black Friday/White Friday ولا حد شحن مجاني معلن.',replace('اختبر حزمة/روتيناً مجمّعاً للعناية بالجسم لاهتمام السيلوليت وجلد الوزة بدل منتجات منفردة، مع وصف واضح للاستخدام دون ادعاء طبي.\nاختبر تخفيضاً سعرياً واضحاً ومحدداً على منتج بطل مثل اللوشن أو المقشر، مع إظهار السعر قبل/بعد.\nأعلن حد الشحن المجاني بوضوح إن وجد، وتجنّب ترك الشحن دون حد معلن.\nاختبر عرضاً موسمياً في توقيت ذروة المنافسة بدل الاعتماد على عرض موسمي وحيد.\nأظهر نقاط التوفر والريتيل بوضوح لبناء الثقة، دون توسيع التشكيلة بمنتجات خارج فضاء الأبطال.','\n',char(10)),1795221702067,'','','','');
INSERT INTO competitor_ad_analyses VALUES(134,118,'غير محدد من التسجيل','غير مسجلة كزاوية إعلان؛ المسجل فقط عبارة بحث عادت لأعلى 10: «علاج جلد الوزة في منطقة البكيني» في المركز 6 ضمن اقتراحات «علاج جلد الوزة».','غير مسجل؛ لا يوجد نص هوك أو إعلان في التسجيل.','غير مسجل كفورمات إعلان؛ المصدر المسجل مسح لغة بحث جوجل مصر (SEARCH) عبر suggestqueries.google.com، 12 كلمة و10 اقتراحات لكل كلمة.','غير مسجل؛ لا يوجد عرض مذكور في التسجيل.','غير مسجلة كمدة تشغيل إعلان؛ التواريخ المسجلة هي تواريخ مسح بحث فقط: 02:29 و02:32 و02:49 EET في 21 نوفمبر 2026، مع إشارة إلى مسحات 20 نوفمبر و01:50 EET لزبدة الشيا الخام.','لا يوجد دليل أداء إعلان مسجل؛ المسجل فقط أن العبارة عادت للمركز 6 بعد غياب مسح واحد، فالخروج كان دوراناً وفق القاعدة المسجلة (ملاحظة #41/#42)، وإشارة الفرصة #9 ما زالت حية.','لا يوجد إعلان مسجل لتقييم ضعفه؛ أضعف نقطة في الإشارة المسجلة هي تذبذبها كمدوِّرة معروفة، فخروج أو عودة مسح واحد لا يكفي وحده لقرار، والقرار المسجل يتطلب موافقة المالك.',replace('أبقِ الفرصة #9 «علاج جلد الوزة في منطقة البكيني» قيد الدراسة ولا تلغها بسبب خروج مسح واحد؛ عودتها للمركز 6 تؤكد الدوران حسب القاعدة المسجلة.\nلا تتخذ قراراً بشأن الفرصة #9 من غير موافقة المالك، كما هو مسجل.\nاختبر محتوى معلوماتياً حول العبارة الراجعة دون ادعاءات طبية ودون نسخ أعمى أو مقارنة باسم براند.\nلا تعتبر عودة «زبدة الشيا الخام» (المركز 7) إشارة منتج جديد؛ زيرا تحمل زبدة الشيا أصلاً و«الخام» صيغة بحث عن الشكل الخام.\nلا تعتبر خروج «علاج جلد الوزة في الوجه» و«زبدة الشيا للبشرة» في هذا المسح موتاً للطلب؛ المسجل أنهما مدوِّرتان معروفتان، وراقب المسحات التالية قبل أي استنتاج.','\n',char(10)),1795223459760,'','','','');
INSERT INTO competitor_ad_analyses VALUES(135,119,'غير محدد من التسجيل','مقارنة ودليل اختيار: «الأفضل» في كريم السيلوليت — نية مقارنة صريحة ظهرت في اقتراح البحث، وليست زاوية منتج أو مشكلة جديدة','«افضل كريم سيلوليت» — صيغة «الأفضل» كاقتراح بحث في المركز السابع تحت «كريم سيلوليت»','اقتراح إكمال تلقائي في بحث جوجل مصر (Google Egypt autocomplete, hl=ar, gl=eg) — ليس إعلان فيديو أو صورة مسجلاً في التسجيل','غير مسجل — لا يوجد عرض أو سعر أو منتج محدد مذكور في التسجيل','غير مسجلة — لا يوجد تاريخ بدء أو مدة تشغيل مذكورة؛ المسجل فقط تاريخ رصد 2026-11-21 الساعة 03:29 EET مقابل لقطة سابقة 03:15 EET في نفس اليوم','لا يوجد دليل أداء مسجل، والمستنتج فقط: دخول صيغة «الأفضل» للمركز السابع وحلولها محل «كريم سيلوليت الحمل» يشير إلى نية مقارنة نشطة لدى باحثات السيلوليت قد يخدمها محتوى دليل اختيار، لكنها إشارة مسح واحد لم تثبت بعد','إشارة مسح واحد فقط غير مثبتة، وصيغة عامة بلا براند أو منتج أو عرض أو محتوى إعلان مسجل؛ فلا يمكن الاستنتاج منها نجاح إعلان أو تفضيل منتج معين',replace('اختبار محتوى دليل اختيار/مقارنة معايير لكريم السيلوليت ضمن روتين زيرا الحالي لخدمة نية «الأفضل»، دون ادعاء طبي أو أن منتج زيرا هو الأفضل مطلقاً\nتتبع اقتراح «افضل كريم سيلوليت» في المسحات القادمة قبل توسيع الاستثمار؛ إشارة واحدة لا تكفي لاتخاذ قرار\nعدم إطلاق منتج جديد بناءً على هذه الإشارة، لأن التسجيل يوضح أن زيرا تحمل كريم سيلوليت ضمن روتين السيلوليت\nتجنب النسخ الأعمى لصيغة «الأفضل» والمقارنات باسم براند منافس، والالتزام بمعايير اختيار قابلة للاختبار (AEO)\nاختبار عناوين وأسئلة اختيار عملية بدل الادعاءات المطلقة، وقياس ما إذا كانت نية المقارنة تتحول لاهتمام فعلي بروتين زيرا','\n',char(10)),1795225254484,'','','','');
INSERT INTO competitor_ad_analyses VALUES(136,120,'غير محدد من التسجيل','استهداف نسائي محدد لعلاج السيلوليت — الصيغة المسجلة «عند النساء» مقابل الصيغة العامة «علاج السيلوليت»','«علاج السيلوليت عند النساء» — نص الاستعلام/الاقتراح المسجل نفسه؛ لا يوجد نص هوك إعلاني آخر مسجل','اقتراح بحث جوجل مصر (suggestqueries.google.com، hl=ar، gl=eg) — ليس فيديو ولا إعلان مصوّر مسجل','غير مسجل — لا يوجد عرض مذكور في التسجيل','غير مسجلة مدة تشغيل أو تاريخ بدء إعلان؛ المسجل فقط تواريخ الرصد: حكم موت في 20 نوفمبر بعد الخروج 4 مسحات متتالية (20:49–21:49 EET)، والغياب عن أعلى 10 في مسحات 00:49 و01:11 و01:50 و02:29 و03:29 و03:49 EET في 21 نوفمبر، ثم العودة للمرتبة #10 في مسح 04:09 EET في 21 نوفمبر 2026','لم يسجل أي رقم أداء أو نجاح إعلاني؛ المسجل فقط عودتها للمرتبة #10 في مسح 04:09 EET بعد غياب طويل، وحكم التسجيل بأن الاقتراح يدور ولا يموت، على نمط عودة «urea» في ملاحظة #42 — والاستنتاج المحتمل فقط هو طلب دوري متكرر على الصيغة النسائية المحددة، ويحتاج تثبتاً في المسحات القادمة قبل أي استنتاج','عدم الاستقرار هو الضعف الأوضح المسجل: خرجت 4 مسحات متتالية ثم 6 مسحات أخرى خارج أعلى 10، وعادت عند الحد الأدنى #10 فقط، وفي المسح نفسه خرج الاستعلام العام «علاج السيلوليت» من قائمته؛ ظهورها هش وقابل للاختفاء مجدداً',replace('لا تعلن موت صيغة بحث أو زاوية بعد 4-6 غيابات متتالية؛ انتظر مسحات لاحقة للتثبت من الدوران قبل إيقاف اختبار لزيرا.\nاختبر الصيغة النسائية المحددة «عند النساء» كمتغير لغوي واستهدافي منفصل عن الصيغة العامة، دون أي ادعاء طبي.\nتجنب الاستنتاج من ظهور واحد عند المرتبة #10؛ اعتبره إشارة دوران هشة وليس نجاحاً مثبتاً، وانتظر تثبتاً في المسحات القادمة.\nراقب الصيغة العامة والمتغيرات معاً في المسح نفسه، لأن خروج «علاج السيلوليت» تزامن مسجلاً مع دخول «علاج السيلوليت عند النساء».\nوثّق الرتبة والتوقيت (EET) لكل مسح بنفس منهجية الرصد قبل الحكم على الاستمرارية، وتجنب النسخ الأعمى أو المقارنة باسم براند.','\n',char(10)),1795227620979,'','','','');
INSERT INTO competitor_ad_analyses VALUES(137,120,'غير محدد من التسجيل','استهداف نسائي محدد: «علاج السيلوليت عند النساء» — صياغة بحث مخصصة للنساء بدل الصياغة العامة.','لا يوجد هوك إعلاني مسجل؛ العبارة المسجلة الوحيدة هي «علاج السيلوليت عند النساء»','اقتراح بحث في Google Suggest (suggestqueries.google.com، hl=ar، gl=eg) — ليس إعلان فيديو مسجلاً','غير مسجل — لا يوجد عرض مذكور في التسجيل','مدة تشغيل الإعلان غير مسجلة؛ المسجل فقط تواريخ الرصد: خروجها 4 مسحات متتالية 20:49–21:49 EET 20 نوفمبر 2026، وبقاؤها خارج أعلى 10 في مسحات 00:49 و01:11 و01:50 و02:29 و03:29 و03:49 EET 21 نوفمبر، ثم دخولها أعلى 10 في المرتبة #10 في مسح 04:09 EET 21 نوفمبر 2026','المسجل لا يثبت نجاح أداء؛ المستنتج بحذر فقط: عودتها بعد غياب طويل تشير إلى دوران في الاقتراحات وليس موت الطلب، والتخصيص «عند النساء» قد يطابق صياغة بحث مستخدمة — لكن التسجيل نفسه ينص على أن تثبت أو تموت في المسحات الجاية قبل أي استنتاج','الأوضح المسجل: هشاشة وعدم استقرار — المرتبة #10 وهي أدنى مرتبة في أعلى 10، بعد غياب عن 4 مسحات متتالية في 20 نوفمبر و6 مسحات أخرى في 21 نوفمبر حتى 03:49، ولم يثبت استمرارها بعد مسح 04:09',replace('اختبر لزيرا صياغة بحث مخصصة للنساء في محتوى البحث/AEO دون ادعاءات طبية، وقارنها بالصياغة العامة «علاج السيلوليت» بدل نسخ العبارة أعمى.\nلا تحكم بموت اقتراح أو كلمة بعد 4 مسحات فقط؛ اعتمد اختبار استمرارية أطول وراقب الدوران قبل الإيقاف.\nراقب المسحات التالية لـ«عند النساء» قبل أي استثمار؛ عودة واحدة في المرتبة #10 لا تكفي كدليل استمرارية.\nتجنب ادعاء علاج أو نتيجة طبية في محتوى زيرا، واكتفِ بوصف موضوعي ومعلومات عامة.\nتتبع تناوب «علاج السيلوليت» و«علاج السيلوليت عند النساء» — دخول إحداهما صاحبه خروج الأخرى في مسح 04:09 — لتجنب منافسة صيغك لبعضها.','\n',char(10)),1795227656121,'','','','');
INSERT INTO competitor_ad_analyses VALUES(138,121,'غير محدد من التسجيل','الأصالة والثقة: التمييز بين زبدة الشيا الأصلية والمغشوشة — «إزاي تعرفي الأصلية»؛ والمسجل يصفها بأنها زاوية ثقة/محتوى وليست فرصة منتج جديد، لأن زيرا تحمل سكراب زبدة الشيا أصلًا.','غير مسجل كهوك إعلان؛ العبارة المسجلة الوحيدة هي عبارة البحث «زبدة الشيا الاصلية» التي دخلت أعلى 10.','غير مسجل كإعلان؛ المصدر المسجل هو مسح لغة بحث جوجل مصر (suggestqueries.google.com، hl=ar، gl=eg) بوسم SEARCH_LANGUAGE، وليس فورمات إعلان فيديو أو صورة.','غير مسجل — لا يوجد عرض مذكور في التسجيل.','غير مسجلة؛ التاريخ المسجل الوحيد هو رصد واحد في 04:30 EET 21 نوفمبر 2026 (تاريخ الرصد: 2026-11-21)، ولا يوجد تاريخ بدء أو مدة تشغيل مذكورة.','لا يوجد دليل أداء إعلان مسجل؛ المسجل فقط هو دخول «زبدة الشيا الاصلية» المركز التاسع تحت «زبدة الشيا» وحلولها محل «زبدة الشيا للبشرة» التي خرجت من أعلى 10. والمستنتج من ذلك — وليس مسجلًا — أن الطلب يعكس قلق الباحثات من الغش وحاجة إلى إشارات ثقة وتمييز قبل الشراء.','إشارة مسح واحد فقط — كما هو مسجل، تثبت أو تموت في المسحات الجاية؛ فلا دليل على استمرارية الطلب أو على أداء إعلان، ولا منافس محدد ولا محتوى إعلان موصوف يمكن تقييمه.',replace('اختبري زاوية محتوى/ثقة «إزاي تعرفي الأصلية» حول سكراب زبدة الشيا الحالي لدى زيرا، بدل إطلاق منتج جديد — كما هو مسجل.\nاستهدفي نية البحث عن الأصالة في محتوى AEO/البحث بصياغة «زبدة الشيا الاصلية» دون ادعاءات طبية ودون مقارنة باسم براند.\nلا تستثمري بقوة قبل تأكيد الإشارة في مسحات قادمة؛ راقبي هل تبقى العبارة في أعلى 10 أم تخرج.\nتجنبي نسخ هوك أو عرض غير مسجل، وتجنبي الادعاء بأن منتج زيرا هو «الأصلي» الوحيد دون دليل مسجل.\nاختبري محتوى تعليميًا قصيرًا حول التمييز يعتمد فقط على معلومات موثقة عن منتج زيرا، وقيسي الاستجابة قبل التوسع فيه.','\n',char(10)),1795229096513,'','','','');
INSERT INTO angles VALUES(1,'KA-1 «العروسة»','فرحي قرب.. ودراعي لسه خشن؟','روتين جلد الوزة','عروسة فرحها قرب','مالك','Static','اتعملت','','من حزمة الستاتيك البيعية المعتمدة من المالك (V2/V4 — 2026-11-19): 1 Pain / 1 Problem / 1 Solution، واتنتجت كتصميمات فعلية 1080×1350.',1795096776145,1795096776145);
