PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "__drizzle_migrations" (
			id SERIAL PRIMARY KEY,
			hash text NOT NULL,
			created_at numeric
		);
CREATE TABLE tasks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  title TEXT NOT NULL,
  type TEXT NOT NULL,
  objective TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'New',
  evidence_tag TEXT NOT NULL DEFAULT 'UNKNOWN',
  assumptions TEXT NOT NULL DEFAULT '',
  confidence INTEGER NOT NULL DEFAULT 50,
  freshness TEXT NOT NULL DEFAULT '',
  stage INTEGER NOT NULL DEFAULT 1,
  notes TEXT NOT NULL DEFAULT '',
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);
CREATE TABLE approvals (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  title TEXT NOT NULL,
  action_type TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'Pending',
  created_at INTEGER NOT NULL,
  decided_at INTEGER
);
CREATE TABLE learnings (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  hypothesis TEXT NOT NULL,
  decision TEXT NOT NULL DEFAULT '',
  expected_outcome TEXT NOT NULL DEFAULT '',
  actual_outcome TEXT NOT NULL DEFAULT '',
  verdict TEXT NOT NULL DEFAULT 'Pending',
  created_at INTEGER NOT NULL
);
CREATE TABLE system_checks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  checked_at INTEGER NOT NULL,
  note TEXT NOT NULL DEFAULT '',
  tasks_count INTEGER NOT NULL DEFAULT 0,
  approvals_pending INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE work_items (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  title TEXT NOT NULL,
  source_type TEXT NOT NULL DEFAULT 'Manual',
  status TEXT NOT NULL DEFAULT 'New',
  stage INTEGER NOT NULL DEFAULT 1,
  owner_role TEXT NOT NULL DEFAULT 'Owner',
  priority TEXT NOT NULL DEFAULT 'Medium',
  due_date TEXT NOT NULL DEFAULT '',
  progress INTEGER NOT NULL DEFAULT 0,
  blocker TEXT NOT NULL DEFAULT '',
  next_action TEXT NOT NULL DEFAULT '',
  notes TEXT NOT NULL DEFAULT '',
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);
CREATE TABLE campaigns (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  platform TEXT NOT NULL DEFAULT 'Meta',
  objective TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'Draft',
  budget REAL NOT NULL DEFAULT 0,
  spent REAL NOT NULL DEFAULT 0,
  results TEXT NOT NULL DEFAULT '',
  period TEXT NOT NULL DEFAULT '',
  attribution TEXT NOT NULL DEFAULT '7-day click',
  weekly_orders INTEGER NOT NULL DEFAULT 0,
  notes TEXT NOT NULL DEFAULT '',
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);
CREATE TABLE creatives (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  title TEXT NOT NULL,
  cis_tag TEXT NOT NULL DEFAULT '',
  product TEXT NOT NULL DEFAULT '',
  angle TEXT NOT NULL DEFAULT '',
  hook TEXT NOT NULL DEFAULT '',
  format TEXT NOT NULL DEFAULT '',
  talent TEXT NOT NULL DEFAULT '',
  lever TEXT NOT NULL DEFAULT '',
  version INTEGER NOT NULL DEFAULT 1,
  status TEXT NOT NULL DEFAULT 'Concept Draft',
  perf_class TEXT NOT NULL DEFAULT 'Insufficient Evidence',
  notes TEXT NOT NULL DEFAULT '',
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
, `hook_rate` real DEFAULT 0 NOT NULL, `hold_rate` real DEFAULT 0 NOT NULL, `outbound_ctr` real DEFAULT 0 NOT NULL, `cvr` real DEFAULT 0 NOT NULL, `cpp` real DEFAULT 0 NOT NULL, `spend` real DEFAULT 0 NOT NULL, `orders_delivered` integer DEFAULT 0 NOT NULL, `why_note` text DEFAULT '' NOT NULL, `image_blob_key` text DEFAULT '' NOT NULL);
CREATE TABLE content_items (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  title TEXT NOT NULL,
  channel TEXT NOT NULL DEFAULT 'Instagram',
  pillar TEXT NOT NULL DEFAULT '',
  format TEXT NOT NULL DEFAULT 'Reel',
  status TEXT NOT NULL DEFAULT 'Idea',
  scheduled_date TEXT NOT NULL DEFAULT '',
  caption_draft TEXT NOT NULL DEFAULT '',
  innovation_bucket TEXT NOT NULL DEFAULT '70% Proven',
  depth_bucket TEXT NOT NULL DEFAULT '75% Deep Problem-Solving',
  source_idea TEXT NOT NULL DEFAULT '',
  notes TEXT NOT NULL DEFAULT '',
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);
CREATE TABLE competitors (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  category TEXT NOT NULL DEFAULT '',
  positioning TEXT NOT NULL DEFAULT '',
  offer TEXT NOT NULL DEFAULT '',
  price_note TEXT NOT NULL DEFAULT '',
  source_url TEXT NOT NULL DEFAULT '',
  notes TEXT NOT NULL DEFAULT '',
  created_at INTEGER NOT NULL
, website_url TEXT NOT NULL DEFAULT '', meta_page TEXT NOT NULL DEFAULT '', tiktok_handle TEXT NOT NULL DEFAULT '');
CREATE TABLE observations (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  title TEXT NOT NULL,
  source TEXT NOT NULL DEFAULT '',
  observed_date TEXT NOT NULL DEFAULT '',
  evidence_tag TEXT NOT NULL DEFAULT 'UNKNOWN',
  notes TEXT NOT NULL DEFAULT '',
  created_at INTEGER NOT NULL
);
CREATE TABLE customer_insights (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  theme TEXT NOT NULL,
  insight_type TEXT NOT NULL DEFAULT 'Objection',
  summary TEXT NOT NULL DEFAULT '',
  frequency TEXT NOT NULL DEFAULT '',
  notes TEXT NOT NULL DEFAULT '',
  created_at INTEGER NOT NULL
);
CREATE TABLE financial_snapshots (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  label TEXT NOT NULL,
  period TEXT NOT NULL DEFAULT '',
