, `breakeven_roas` real DEFAULT 0 NOT NULL);
CREATE TABLE experiments (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  hypothesis TEXT NOT NULL,
  creative_id TEXT NOT NULL DEFAULT '',
